(window.__KSHC_DATA=window.__KSHC_DATA||{})["courses3"]={"courses":[{"id":"HST.510+fall_2005","numbers":["HST.510"],"title":"Genomics, Computing, Economics, and Society","summary":"This course will focus on understanding aspects of modern technology displaying exponential growth curves and the impact on global quality of life through a weekly updated class project integrating knowledge and providing practical tools for political and business decision-making concerning new aspects of bioengineering, personalized medicine, genetically modified organisms, and stem cells. Interplays of economic, ethical, ecological, and biophysical modeling will be explored through multi-disciplinary teams of students, and individual brief reports.","departments":["Health Sciences and Technology"],"areas":["Health & Medicine","Science & Math","Social Sciences"],"topics":["Biology","Biomedicine","Economics","Functional Genomics","Genetics","Health and Medicine","Political Economy","Public Health","Science","Social Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2005","instructors":["Dr. George Church","Jeremy Zucker","Shawn Douglas","Alexander Wait"],"url":"https://ocw.mit.edu/courses/hst-510-genomics-computing-economics-and-society-fall-2005/","views":1851},{"id":"16.682+spring_2011","numbers":["16.682"],"title":"Technology in Transportation","summary":"This course provides an introduction to the transportation industry’s major technical challenges and considerations. For upper level undergraduates interested in learning about the transportation field in a broad but quantitative manner. Topics include road vehicle engineering, internal combustion engines, batteries and motors, electric and hybrid powertrains, urban and high speed rail transportation, water vessels, aircraft types and aerodynamics, radar, navigation, GPS, GIS. Students will complete a project on a subject of their choosing.","departments":["Aeronautics and Astronautics"],"areas":["Engineering"],"topics":["Aerospace Engineering","Engineering","Guidance and Control Systems","Mechanical Engineering","Propulsion Systems"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Problem Set Solutions","Problem Sets"],"term":"Spring 2011","instructors":["Prof. Sanjay Sarma"],"url":"https://ocw.mit.edu/courses/16-682-technology-in-transportation-spring-2011/","views":1851},{"id":"18.155+fall_2004","numbers":["18.155"],"title":"Differential Analysis","summary":"This is the first semester of a two-semester sequence on Differential Analysis. Topics include fundamental solutions for elliptic; hyperbolic and parabolic differential operators; method of characteristics; review of Lebesgue integration; distributions; fourier transform; homogeneous distributions; asymptotic methods.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Differential Equations","Mathematical Analysis","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Richard Melrose"],"url":"https://ocw.mit.edu/courses/18-155-differential-analysis-fall-2004/","views":1850},{"id":"20.441J+fall_2009","numbers":["20.441J","2.79J","3.96J","HST.522J"],"title":"Biomaterials-Tissue Interactions","summary":"This course covers the principles of materials science and cell biology underlying the design of medical implants, artificial organs, and matrices for tissue engineering. Methods for biomaterials surface characterization and analysis of protein adsorption on biomaterials. Molecular and cellular interactions with biomaterials are analyzed in terms of unit cell processes, such as matrix synthesis, degradation, and contraction. Mechanisms underlying wound healing and tissue remodeling following implantation in various organs. Tissue and organ regeneration. Design of implants and prostheses based on control of biomaterials-tissue interactions. Comparative analysis of intact, biodegradable, and bioreplaceable implants by reference to case studies. Criteria for restoration of physiological function for tissues and organs.","departments":["Biological Engineering","Health Sciences and Technology","Materials Science and Engineering","Mechanical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Biomaterials","Cell Biology","Cell and Tissue Engineering","Engineering","Science"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2009","instructors":["Prof. Ioannis Yannas","Prof. Myron Spector"],"url":"https://ocw.mit.edu/courses/20-441j-biomaterials-tissue-interactions-fall-2009/","views":1848},{"id":"11.486J+fall_2005","numbers":["11.486J","14.778J","17.184J"],"title":"Economic Institutions and Growth Policy Analysis","summary":"This course is designed for students particularly concerned with the practical problems of operating in large formal organizations, either from an operational or a research perspective. It will focus, as the title suggests, upon different forms of economic organizations and institutions in advanced and developing industrial societies and the theories (and theoretical perspectives) which might help us to understand them.","departments":["Economics","Political Science","Urban Studies and Planning"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Industrial Organization","Organizational Behavior","Public Administration","Public Economics","Public Policy","Social Science"],"levels":["Graduate"],"features":[],"term":"Fall 2005","instructors":["Prof. Michael Piore","Prof. Alice Amsden"],"url":"https://ocw.mit.edu/courses/11-486j-economic-institutions-and-growth-policy-analysis-fall-2005/","views":1846},{"id":"22.04J+fall_2025","numbers":["22.04J","STS.084J"],"title":"Social Problems of Nuclear Energy","summary":"This course examines nuclear power as a low‑carbon electricity source, balancing its potential role in addressing climate change against longstanding technical, economic, and social challenges. Topics include the ability of nuclear power to help mitigate climate change; challenges associated with ensuring nuclear safety; the effects of nuclear accidents; the management of nuclear waste; the linkages between nuclear power and nuclear weapons, the consequences of nuclear war; and political challenges to the safe and economic regulation of the nuclear industry. Students explore both fission and fusion technologies, emerging reactor designs, policy options, and the institutional and societal constraints shaping nuclear power’s future. Emphasis is placed on critical evaluation of tradeoffs, uncertainties, and value judgments involved in decisions about nuclear energy within an increasingly competitive renewable energy landscape.","departments":["Nuclear Science and Engineering","Science, Technology, and Society"],"areas":["Energy, Climate & Sustainability","Engineering"],"topics":["Energy","Engineering","Nuclear Energy","Nuclear Engineering"],"levels":["Undergraduate"],"features":["Instructor Insights","Lecture Videos","Readings","Written Assignments"],"term":"Fall 2025","instructors":["Prof. R. Scott Kemp"],"url":"https://ocw.mit.edu/courses/22-04j-social-problems-of-nuclear-energy-fall-2025/","views":1846},{"id":"21H.983+spring_2017","numbers":["21H.983"],"title":"Gender","summary":"This course examines the definition of gender in scientific, societal, and historical contexts. It explores how gender influences state formation and the work of the state, what role gender plays in imperialism and in the welfare state, the ever-present relationship between gender and war, and different states’ regulation of the body in gendered ways at different times. It investigates new directions in the study of gender as historians, anthropologists and others have taken on this fascinating set of problems.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["American History","Anthropology","Cultural Anthropology","European History","Gender Studies","History","Humanities","Social Anthropology","Social Science","Society"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2017","instructors":["Prof. Lerna Ekmekcioglu","Prof. Elizabeth A. Wood"],"url":"https://ocw.mit.edu/courses/21h-983-gender-spring-2017/","views":1845},{"id":"12.810+spring_2023","numbers":["12.810"],"title":"Dynamics of the Atmosphere","summary":"This course discusses the dynamics of the atmosphere, with emphasis on the large scale. Topics include internal gravity waves in the atmosphere; potential vorticity conservation and Rossby waves; baroclinic instability and extratropical storms; the general circulation including the role of eddies, isentropic coordinates and tracer transport.\n\nThis class builds on a previous version of 12.810 taught by Professor Alan Plumb.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Atmospheric Science","Earth Science","Geophysics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Projects","Readings"],"term":"Spring 2023","instructors":["Prof. Paul O'Gorman"],"url":"https://ocw.mit.edu/courses/12-810-dynamics-of-the-atmosphere-spring-2023/","views":1843},{"id":"20.110J+fall_2005","numbers":["20.110J","5.601J","2.772J"],"title":"Thermodynamics of Biomolecular Systems","summary":"This subject deals primarily with equilibrium properties of macroscopic and microscopic systems, basic thermodynamics, chemical equilibrium of reactions in gas and solution phase, and macromolecular interactions.","departments":["Biological Engineering","Chemistry","Mechanical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biomaterials","Chemistry","Engineering","Physical Chemistry","Physics","Science","Thermodynamics"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2005","instructors":["Prof. Kim Hamad-Schifferli","Prof. Linda Griffith","Prof. Moungi Bawendi","Prof. Robert Field"],"url":"https://ocw.mit.edu/courses/20-110j-thermodynamics-of-biomolecular-systems-fall-2005/","views":1840},{"id":"21A.104+spring_2016","numbers":["21A.104","21A.119"],"title":"Memory, Culture, Forgetting","summary":"This course introduces scholarly debates about the sociocultural practices through which individuals and societies create, sustain, recall, and erase memories. Emphasis is given to the history of knowledge, construction of memory, the role of authorities in shaping memory, and how societies decide on whose versions of memory are more “truthful” and “real.” Other topics include how memory works in the human brain, memory and trauma, amnesia, memory practices in the sciences, false memory, sites of memory, and the commodification of memory. Students taking the graduate version complete additional assignments.","departments":["Anthropology"],"areas":["Social Sciences"],"topics":["Anthropology","Biological Anthropology","Cultural Anthropology","Ethnography","Social Anthropology","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2016","instructors":["Prof. Manduhai Buyandelger"],"url":"https://ocw.mit.edu/courses/21a-104-memory-culture-forgetting-spring-2016/","views":1839},{"id":"6.973+spring_2006","numbers":["6.973"],"title":"Communication System Design","summary":"This course presents a top-down approach to communications system design. The course will cover communication theory, algorithms and implementation architectures for essential blocks in modern physical-layer communication systems (coders and decoders, filters, multi-tone modulation, synchronization sub-systems). The course is hands-on, with a project component serving as a vehicle for study of different communication techniques, architectures and implementations. This year, the project is focused on WLAN transceivers. At the end of the course, students will have gone through the complete WLAN System-On-a-Chip design process, from communication theory, through algorithm and architecture all the way to the synthesized standard-cell RTL chip representation.","departments":["Electrical Engineering and Computer Science"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Networks","Computer Science","Electrical Engineering","Engineering","Systems Design","Systems Engineering","Telecommunications"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2006","instructors":["Prof. Vladimir Stojanovic"],"url":"https://ocw.mit.edu/courses/6-973-communication-system-design-spring-2006/","views":1838},{"id":"21G.414+fall_2006","numbers":["21G.414"],"title":"German Culture, Media, and Society","summary":"The topic for Fall 2006 is short film and radio plays. This course investigates current trends and topics in German literary, theater, film, television, radio, and other media arts productions. Students analyze media texts in the context of their production, reception, and distribution as well as the public debates initiated by these works. The topic for Fall 2006 is German Short Film, a popular format that represents most recent trends in film production, and German Radio Art, a striving genre that includes experimental radio plays, sound art, and audio installations. Special attention will be given to the representation of German minorities, contrasted by their own artistic expressions reflecting changes in identity and a new political voice. Students have the opportunity to discuss course topics with a writer, filmmaker, and/or media artist from Germany. The course is taught in German.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","European and Russian Studies","Film and Video","Fine Arts","German","Humanities","Language","Media Studies","Social Science","Society","Visual Arts"],"levels":["Undergraduate"],"features":["Projects"],"term":"Fall 2006","instructors":["Dr. Kurt Fendt"],"url":"https://ocw.mit.edu/courses/21g-414-german-culture-media-and-society-fall-2006/","views":1834},{"id":"9.357+fall_2001","numbers":["9.357"],"title":"Special Topics in Vision Science","summary":"An advanced seminar on issues of current interest in human and machine vision. Topics vary from year to year. This year, the class will involve studying the perception of materials. Participants discuss current literature as well as their ongoing research. Topics are tackled from multiple standpoints, including optics, psychophysics, computer graphics and computer vision.","departments":["Brain and Cognitive Sciences"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Health & Medicine","Science & Math"],"topics":["Cognitive Science","Computer Science","Engineering","Graphics and Visualization","Health and Medicine","Science","Sensory-Neural Systems"],"levels":["Graduate"],"features":[],"term":"Fall 2001","instructors":["Prof. Edward Adelson"],"url":"https://ocw.mit.edu/courses/9-357-special-topics-in-vision-science-fall-2001/","views":1834},{"id":"6.5060+spring_2023","numbers":["6.5060"],"title":"Algorithm Engineering","summary":"This is a research-oriented course on algorithm engineering, which will cover both the theory and practice of algorithms and data structures. Students will learn about models of computation, algorithm design and analysis, and performance engineering of algorithm implementations. We will study the design and implementation of sequential, parallel, cache-efficient, external-memory, and write-efficient algorithms for fundamental problems in computing. Many of the principles of algorithm engineering will be illustrated in the context of parallel algorithms and graph problems.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Algorithms and Data Structures","Computer Science","Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Readings"],"term":"Spring 2023","instructors":["Prof. Charles Leiserson","Prof. Julian Shun"],"url":"https://ocw.mit.edu/courses/6-5060-algorithm-engineering-spring-2023/","views":1832},{"id":"22.55J+fall_2004","numbers":["22.55J","HST.560J"],"title":"Principles of Radiation Interactions","summary":"The central theme of this course is the interaction of radiation with biological material. The course is intended to provide a broad understanding of how different types of radiation deposit energy, including the creation and behavior of secondary radiations; of how radiation affects cells and why the different types of radiation have very different biological effects. Topics will include: the effects of radiation on biological systems including DNA damage; in vitro cell survival models; and in vivo mammalian systems. The course covers radiation therapy, radiation syndromes in humans and carcinogenesis. Environmental radiation sources on earth and in space, and aspects of radiation protection are also discussed. Examples from the current literature will be used to supplement lecture material.","departments":["Health Sciences and Technology","Nuclear Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Chemistry","Electromagnetism","Engineering","Nuclear Engineering","Nuclear Physics","Physical Chemistry","Physics","Radiological Engineering","Science"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Jeffrey Coderre"],"url":"https://ocw.mit.edu/courses/22-55j-principles-of-radiation-interactions-fall-2004/","views":1832},{"id":"21G.410+spring_2017","numbers":["21G.410"],"title":"Advanced German: Professional Communication","summary":"This course exposes students to current issues and language use in German technology, business, and international industrial relations, and discusses ramifications of these issues in a larger social and cultural context. We seek to prepare students who wish to work or study in a German-speaking country by focusing on specialized vocabulary and systematic training in speaking and writing skills to improve fluency and style and emphasizing communicative strategies that are crucial in a working environment. Discussion and analysis of newspaper and magazine articles, modern expository prose, and extensive use of online material are included. Taught in German.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["Economics","German","Humanities","International Development","Language","Social Science"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments"],"term":"Spring 2017","instructors":["Peter Weise"],"url":"https://ocw.mit.edu/courses/21g-410-advanced-german-professional-communication-spring-2017/","views":1831},{"id":"24.262+spring_2004","numbers":["24.262"],"title":"Feeling and Imagination in Art, Science, and Technology","summary":"This course is a seminar on creativity in art, science, and technology. We discuss how these pursuits are jointly dependent on affective as well as cognitive elements in human nature. We study feeling and imagination in relation to principles of idealization, consummation, and the aesthetic values that give meaning to science and technology as well as literature and the other arts. Readings in philosophy, psychology, and literature are part of the course.","departments":["Linguistics and Philosophy"],"areas":["Humanities","Science & Math","Social Sciences"],"topics":["Cognitive Science","Humanities","Literature","Philosophy","Psychology","Science","Social Science"],"levels":["Undergraduate"],"features":["Lecture Videos"],"term":"Spring 2004","instructors":["Prof. Irving Singer"],"url":"https://ocw.mit.edu/courses/24-262-feeling-and-imagination-in-art-science-and-technology-spring-2004/","views":1830},{"id":"11.701+fall_2011","numbers":["11.701"],"title":"Introduction to International Development Planning","summary":"This introductory survey course is intended to develop an understanding of key issues and dilemmas of planning in non-Western countries. The issues covered by the course include state intervention, governance, law and institutions in development, privatization, participatory planning, decentralization, poverty, urban-rural linkages, corruption and civil service reform, trade and outsourcing and labor standards, post-conflict development and the role of aid in development.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Developmental Economics","Economics","Global Poverty","International Development","Public Administration","Regional Planning","Regional Politics","Social Science","Society","The Developing World","Urban Studies"],"levels":["Graduate"],"features":["Presentation Assignments","Programming Assignments with Examples"],"term":"Fall 2011","instructors":["Prof. Balakrishnan Rajagopal"],"url":"https://ocw.mit.edu/courses/11-701-introduction-to-international-development-planning-fall-2011/","views":1830},{"id":"6.252J+spring_2003","numbers":["6.252J","15.084J"],"title":"Nonlinear Programming","summary":"6.252J is a course in the department’s “Communication, Control, and Signal Processing” concentration. This course provides a unified analytical and computational approach to nonlinear optimization problems. The topics covered in this course include: unconstrained optimization methods, constrained optimization methods, convex analysis, Lagrangian relaxation, nondifferentiable optimization, and applications in integer programming. There is also a comprehensive treatment of optimality conditions, Lagrange multiplier theory, and duality theory. Throughout the course, applications are drawn from control, communications, power systems, and resource allocation problems.","departments":["Electrical Engineering and Computer Science","Sloan School of Management"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Engineering","Systems Engineering","Systems Optimization","Theory of Computation"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2003","instructors":["Prof. Dimitri Bertsekas"],"url":"https://ocw.mit.edu/courses/6-252j-nonlinear-programming-spring-2003/","views":1830},{"id":"21L.449+spring_2002","numbers":["21L.449"],"title":"End of Nature","summary":"This subject offers a broad survey of texts (both literary and philosophical) drawn from the Western tradition and selected to trace the growth of ideas about nature and the natural environment of mankind. The term nature in this context has to do with the varying ways in which the physical world has been conceived as the habitation of mankind, a source of imperatives for the collective organization and conduct of human life. In this sense, nature is less the object of complex scientific investigation than the object of individual experience and direct observation. Using the term “nature” in this sense, we can say that modern reference to “the environment” owes much to three ideas about the relation of mankind to nature. In the first of these, which harks back to ancient medical theories and notions about weather, geographical nature was seen as a neutral agency affecting or transforming agent of mankind’s character and institutions. In the second, which derives from religious and classical sources in the Western tradition, the earth was designed as a fit environment for mankind or, at the least, as adequately suited for its abode, and civic or political life was taken to be consonant with the natural world. In the third, which also makes its appearance in the ancient world but becomes important only much later, nature and mankind are regarded as antagonists, and one must conquer the other or be subjugated by it.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Criticism","History","Humanities","Intellectual History","Literature","Philosophy"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2002","instructors":["Prof. Alvin Kibel"],"url":"https://ocw.mit.edu/courses/21l-449-end-of-nature-spring-2002/","views":1829},{"id":"6.637+spring_2003","numbers":["6.637"],"title":"Optical Signals, Devices, and Systems","summary":"6.637 covers the fundamentals of optical signals and modern optical devices and systems from a practical point of view. Its goal is to help students develop a thorough understanding of the underlying physical principles such that device and system design and performance can be predicted, analyzed, and understood.\n\nMost optical systems involve the use of one or more of the following: sources (e.g., lasers and light-emitting diodes), light modulation components (e.g., liquid-crystal light modulators), transmission media (e.g., free space or fibers), photodetectors (e.g., photodiodes, photomultiplier tubes), information storage devices (e.g., optical disk), processing systems (e.g., imaging and spatial filtering systems) and displays (LCOS microdisplays). These are the topics covered by this course.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering","Science & Math"],"topics":["Atomic, Molecular, Optical Physics","Electrical Engineering","Electronics","Engineering","Physics","Science","Signal Processing"],"levels":["Graduate"],"features":["Problem Sets"],"term":"Spring 2003","instructors":["Prof. Cardinal Warde"],"url":"https://ocw.mit.edu/courses/6-637-optical-signals-devices-and-systems-spring-2003/","views":1829},{"id":"RES.LL-001+spring_2007","numbers":["RES.LL-001"],"title":"Introduction to Radar Systems","summary":"This set of 10 lectures (about 11+ hours in duration) was excerpted from a three-day course developed at MIT Lincoln Laboratory to provide an understanding of radar systems concepts and technologies to military officers and DoD civilians involved in radar systems development, acquisition, and related fields. That three-day program consists of a mixture of lectures, demonstrations, laboratory sessions, and tours.\n\nOnline Publication","departments":[],"areas":["Engineering","Science & Math"],"topics":["Electrical Engineering","Electromagnetism","Electronics","Engineering","Physics","Science","Signal Processing"],"levels":["Undergraduate"],"features":[],"term":"Spring 2007","instructors":["Robert M. O'Donnell"],"url":"https://ocw.mit.edu/courses/res-ll-001-introduction-to-radar-systems-spring-2007/","views":1828},{"id":"15.232+fall_2013","numbers":["15.232"],"title":"Business Model Innovation: Global Health in Frontier Markets","summary":"This course explores successful approaches to delivering healthcare in challenging settings. We analyze organizations to find why some fall short while others grow in size and contribute to the health of the people they serve, and explore promising business models and social enterprise innovations.","departments":["Sloan School of Management"],"areas":["Business & Management","Health & Medicine"],"topics":["Business","Health Care Management","Health and Medicine","Management","Public Health"],"levels":["Graduate"],"features":["Instructor Insights","Lecture Notes","Presentation Assignments","Projects with Examples","Written Assignments with Examples"],"term":"Fall 2013","instructors":["Dr. Anjali Sastry"],"url":"https://ocw.mit.edu/courses/15-232-business-model-innovation-global-health-in-frontier-markets-fall-2013/","views":1826},{"id":"21G.110+spring_2004","numbers":["21G.110"],"title":"Chinese IV (Streamlined)","summary":"This is the second semester of the intermediate level sequence intended for students whose conversational ability exceeds their reading and writing skills. Focus is on reading and writing, as well as broadening conversational skills and control of standard pronunciation, for students with background in conversational Chinese. Lab work is required. On completing this course, students should be able to speak the language with standard pronunciation, to converse with some fluency on everyday topics, as well as on some specialized topics, to read edited, as well as authentic texts, in simplified or traditional characters with suitable fluency, and to be able to write composition on certain topics. The class consists of a combination of practice, reading, discussion, dictation, composition and feedback, net exploration via the web, and presentation. This course is conducted in Mandarin.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Chinese","Humanities","Language"],"levels":["Undergraduate"],"features":["Activity Assignments","Demonstration Audio"],"term":"Spring 2004","instructors":["Tong Chen"],"url":"https://ocw.mit.edu/courses/21g-110-chinese-iv-streamlined-spring-2004/","views":1824},{"id":"18.303+fall_2006","numbers":["18.303"],"title":"Linear Partial Differential Equations","summary":"This course covers the classical partial differential equations of applied mathematics: diffusion, Laplace/Poisson, and wave equations. It also includes methods and tools for solving these PDEs, such as separation of variables, Fourier series and transforms, eigenvalue problems, and Green’s functions.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Applied Mathematics","Differential Equations","Mathematics"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2006","instructors":["Dr. Matthew Hancock"],"url":"https://ocw.mit.edu/courses/18-303-linear-partial-differential-equations-fall-2006/","views":1823},{"id":"21M.542+january-iap_2010","numbers":["21M.542"],"title":"Interdisciplinary Approaches to Musical Time","summary":"This course is an interdisciplinary exploration of three broad topics concerning music in relation to time.\n\n• Music as Architecture: the creation of musical shapes in time;\n• Music as Memory: how musical understanding depends upon memory and reminiscence, with attention to analysis of musical structures; and\n• Time as the Substance of Music: how different disciplines such as philosophy and neuroscience view the temporal dimension of musical processes and/or performances.\n\nClassroom discussion of these topics is complemented by three weekend concerts with pre-concert forums, jointly presented by the Boston Chamber Music Society (BCMS) and MIT Music & Theater Arts.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities","Science & Math"],"topics":["Cognitive Science","Fine Arts","Humanities","Music","Music Theory","Philosophy","Science"],"levels":["Undergraduate"],"features":["Lecture Videos","Music Audio","Other Video","Presentation Assignments with Examples","Written Assignments with Examples"],"term":"January IAP 2010","instructors":["Dr. Martin Marks","Prof. Marcus A Thompson","Prof. Charles Shadle"],"url":"https://ocw.mit.edu/courses/21m-542-interdisciplinary-approaches-to-musical-time-january-iap-2010/","views":1821},{"id":"21L.310+fall_2006","numbers":["21L.310"],"title":"Bestsellers: Detective Fiction","summary":"This course focuses on works that caught the popular imagination in the past or present. It emphasizes texts that are related by genre, theme or style. The books studied in this course vary from semester to semester, and the topic for Fall 2006 is Detective Fictions.","departments":["Literature"],"areas":["Humanities"],"topics":["Creative Writing","Criticism","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2006","instructors":["Prof. Stephen Tapscott"],"url":"https://ocw.mit.edu/courses/21l-310-bestsellers-detective-fiction-fall-2006/","views":1818},{"id":"21L.430+fall_2010","numbers":["21L.430","WGS.492","CMS.920"],"title":"Popular Culture and Narrative: Literature, Comics, and Culture","summary":"In this course, we will investigate popular culture and narrative by focusing on the relationship between literary texts and comics. Several questions shape the syllabus and provide a framework for approaching the course materials: How do familiar aspects of comics trace their origins to literary texts and broader cultural concerns? How have classic comics gone on to influence literary fiction? In what ways do contemporary graphic narratives bring a new kind of seriousness of purpose to comics, blurring what’s left of the boundaries between the highbrow and the lowbrow? Readings and materials for the course range from the nineteenth century to the present, and include novels, short stories, essays, older and newer comics, and some older and newer films. Expectations include diligent reading, active participation, occasional discussion leading, and two papers.","departments":["Comparative Media Studies/Writing","Literature","Women's and Gender Studies"],"areas":["Humanities"],"topics":["Comparative Literature","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2010","instructors":["Prof. John Picker"],"url":"https://ocw.mit.edu/courses/21l-430-popular-culture-and-narrative-literature-comics-and-culture-fall-2010/","views":1818},{"id":"18.705+fall_2008","numbers":["18.705"],"title":"Commutative Algebra","summary":"In this course students will learn about Noetherian rings and modules, Hilbert basis theorem, Cayley-Hamilton theorem, integral dependence, Noether normalization, the Nullstellensatz, localization, primary decomposition, DVRs, filtrations, length, Artin rings, Hilbert polynomials, tensor products, and dimension theory.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics"],"levels":["Graduate"],"features":["Problem Sets"],"term":"Fall 2008","instructors":["Prof. Steven Kleiman"],"url":"https://ocw.mit.edu/courses/18-705-commutative-algebra-fall-2008/","views":1816},{"id":"21H.161+fall_2015","numbers":["21H.161"],"title":"The Middle East in the 20th Century","summary":"This course surveys the history of the Middle East, from the end of the 19th century to the present. It examines major political, social, intellectual and cultural issues and practices. It also focuses on important events, movements, and ideas that prevailed during the last century and affect its current realities.","departments":["History"],"areas":["Humanities"],"topics":["History","Humanities","Middle Eastern History","Modern History"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2015","instructors":["Prof. Abigail Jacobson"],"url":"https://ocw.mit.edu/courses/21h-161-the-middle-east-in-the-20th-century-fall-2015/","views":1816},{"id":"22.033+fall_2011","numbers":["22.033","22.33"],"title":"Nuclear Systems Design Project","summary":"This capstone course is a group design project involving integration of nuclear physics, particle transport, control, heat transfer, safety, instrumentation, materials, environmental impact, and economic optimization. It provides opportunities to synthesize knowledge acquired in nuclear and non-nuclear subjects and apply this knowledge to practical problems of current interest in nuclear applications design. Each year, the class takes on a different design project; this year, the project is a power plant design that ties together the creation of emission-free electricity with carbon sequestration and fossil fuel displacement. Students taking graduate version complete additional assignments.\n\nThis course is an elective subject in MIT’s undergraduate Energy Studies Minor. This Institute-wide program complements the deep expertise obtained in any major with a broad understanding of the interlinked realms of science, technology, and social sciences as they relate to energy and associated environmental challenges.","departments":["Nuclear Science and Engineering"],"areas":["Business & Management","Energy, Climate & Sustainability","Engineering","Science & Math"],"topics":["Business","Energy","Engineering","Hydrogen and Alternatives","Nuclear Energy","Nuclear Engineering","Nuclear Physics","Nuclear Systems, Policy, and Economics","Physics","Project Management","Renewables","Science","Systems Design","Systems Engineering"],"levels":["Undergraduate","Graduate"],"features":["Instructor Insights","Lecture Notes","Lecture Videos","Other Video","Projects with Examples","Written Assignments with Examples"],"term":"Fall 2011","instructors":["Prof. Michael Short"],"url":"https://ocw.mit.edu/courses/22-033-nuclear-systems-design-project-fall-2011/","views":1815},{"id":"RES.EC-003+spring_2022","numbers":["RES.EC-003"],"title":"D-Lab Student Showcases","summary":"Student projects in D-Lab classes are defined by community partners and social ventures around the world. We don’t always know what is needed, but our community partners do, and our students have technical knowledge and skills to contribute to that work.\n\nEach semester, through a selection of full-semester classes, our students form into teams to work on projects framed by community partners – NGOs, local nonprofits, and social entrepreneurs. At the end of each semester, students present their work to their peers, partners, and guests.","departments":["Edgerton Center"],"areas":["Education & Teaching","Energy, Climate & Sustainability","Engineering","Health & Medicine","Social Sciences"],"topics":["Energy","Engineering","Health and Medicine","Social Science","Society","Teaching and Education"],"levels":["Non-Credit"],"features":["Projects with Examples"],"term":"Spring 2022","instructors":["MIT D-Lab"],"url":"https://ocw.mit.edu/courses/res-ec-003-d-lab-student-showcases-spring-2022/","views":1814},{"id":"HST.934J+spring_2010","numbers":["HST.934J","STS.449J"],"title":"Introduction to Global Medicine: Bioscience, Technologies, Disparities, Strategies","summary":"This class provides a space for medical students and MD/PhD students, as well as HASTS (History, Anthropology, Science, Technology, and Society) PhD students to discuss social and ethical issues in the biosciences and biotechnologies as they are being developed. Discussions are with course faculty and with leading figures in developing technologies such as George Daley or George Church in stem cell or genomics research, Bruce Walker or Pardis Sabeti in setting up laboratories in Africa, Paul Farmer and Partners in Health colleagues in building local support systems and first world quality care in Haiti, Peru, and Rwanda, and Amy Farber in building patient-centered therapeutic-outcome research for critical but “orphan” diseases. Goals include stimulating students to think about applying their learning in Boston to countries around the world, including using the experiences they have had in their home countries or research experience abroad. Goals also include a mix of patient-doctor care perspectives from medical anthropology, and moving upstream in the research chain to questions of how to move discoveries from basic research through the pipelines into clinical and bedside care.","departments":["Health Sciences and Technology","Science, Technology, and Society"],"areas":["Engineering","Health & Medicine","Humanities"],"topics":["Biological Engineering","Biomedicine","Biotechnology","Engineering","Ethics","Health and Medicine","Humanities","Philosophy","Public Health"],"levels":["Graduate"],"features":[],"term":"Spring 2010","instructors":["Prof. Michael M.J. Fischer","Prof. Byron Good","Prof. Mary-Jo DelVecchio Good","Prof. David Jones"],"url":"https://ocw.mit.edu/courses/hst-934j-introduction-to-global-medicine-bioscience-technologies-disparities-strategies-spring-2010/","views":1810},{"id":"10.467+fall_2005","numbers":["10.467"],"title":"Polymer Science Laboratory","summary":"Experiments in this class are broadly aimed at acquainting students with the range of properties of polymers, methods of synthesis, and physical chemistry. Some examples of laboratory work include solution polymerization of acrylamide, bead polymerization of divinylbenzene, and interfacial polymerization of nylon 6,10. Evaluation of networks by tensile and swelling experiments, rheology of polymer solutions and suspensions, and physical properties of natural and silicone rubber are also covered.","departments":["Chemical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Chemical Engineering","Chemistry","Engineering","Materials Science and Engineering","Physical Chemistry","Polymeric Materials","Polymers","Science"],"levels":["Undergraduate"],"features":[],"term":"Fall 2005","instructors":["Mr. Harlan Breindel","Prof. Paula Hammond"],"url":"https://ocw.mit.edu/courses/10-467-polymer-science-laboratory-fall-2005/","views":1809},{"id":"8.322+spring_2003","numbers":["8.322"],"title":"Quantum Theory II","summary":"8.322 is the second semester of a two-semester subject on quantum theory, stressing principles. Topics covered include: time-dependent perturbation theory and applications to radiation, quantization of EM radiation field, adiabatic theorem and Berry’s phase, symmetries in QM, many-particle systems, scattering theory, relativistic quantum mechanics, and Dirac equation.","departments":["Physics"],"areas":["Science & Math"],"topics":["Physics","Quantum Mechanics","Science","Theoretical Physics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2003","instructors":["Prof. Washington Taylor"],"url":"https://ocw.mit.edu/courses/8-322-quantum-theory-ii-spring-2003/","views":1807},{"id":"6.933J+fall_2001","numbers":["6.933J","STS.420J"],"title":"The Structure of Engineering Revolutions","summary":"6.933J / STS.420J provides an integrated approach to engineering practice in the real world. Students of 6.933J / STS.420J research the life cycle of a major engineering project, new technology, or startup company from multiple perspectives: technical, economic, political, and cultural. Research involves interviewing inventors, reading laboratory notebooks, evaluating patents, and looking over the shoulders of engineers as they developed today’s technologies. This subject is for students who recognize that technical proficiency alone is only part of the formula for success in technology.","departments":["Electrical Engineering and Computer Science","Science, Technology, and Society"],"areas":["Business & Management","Engineering","Innovation & Entrepreneurship"],"topics":["Business","Engineering","Entrepreneurship","Innovation"],"levels":["Graduate"],"features":["Projects with Examples","Written Assignments"],"term":"Fall 2001","instructors":["Prof. David Mindell"],"url":"https://ocw.mit.edu/courses/6-933j-the-structure-of-engineering-revolutions-fall-2001/","views":1807},{"id":"IDS.900+fall_2005","numbers":["IDS.900","17.312J","STS.461J","IDS.900 (formerly ESD.85J)"],"title":"Integrating Doctoral Seminar on Emerging Technologies","summary":"This team-taught subject is for doctoral students working on emerging technologies at the interface of technology, policy and societal issues. It integrates concepts of research strategy and design from a variety of disciplines. The class addresses problem identification and formulation of research topics, the role of qualitative and quantitative research methods, and the use of various data collection techniques. Coursework focuses on students’ thesis proposals, faculty-student study panels, critical evaluation of research design, and ethical issues in conducting research and gathering data.","departments":["Institute for Data, Systems, and Society","Political Science","Science, Technology, and Society"],"areas":["Engineering"],"topics":["Engineering","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2005","instructors":["Prof. Daniel Hastings","Dr. Jason Black","Dr. Lawrence McCray"],"url":"https://ocw.mit.edu/courses/ids-900-integrating-doctoral-seminar-on-emerging-technologies-fall-2005/","views":1805},{"id":"21G.716+spring_2005","numbers":["21G.716"],"title":"Introduction to Contemporary Hispanic Literature","summary":"This course studies important twentieth century texts from Spain and Latin America. The readings include short stories, theatre, the novel and poetry. This subject is conducted in Spanish and all reading and writing for the course is also done in Spanish.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","International Literature","Language","Literature","Spanish"],"levels":["Undergraduate"],"features":["Projects with Examples"],"term":"Spring 2005","instructors":["Prof. Margery Resnick"],"url":"https://ocw.mit.edu/courses/21g-716-introduction-to-contemporary-hispanic-literature-spring-2005/","views":1804},{"id":"21G.228+spring_2007","numbers":["21G.228","21G.227"],"title":"Advanced Workshop in Writing for Social Sciences and Architecture (ELS)","summary":"This workshop is designed to help you write clearly, accurately and effectively in both an academic and a professional environment. In class, we analyze various forms of writing and address problems common to advanced speakers of English. We will often read one another’s work.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Academic Writing","English as a Second Language","Humanities","Language","Literature"],"levels":["Undergraduate"],"features":["Lecture Notes","Presentation Assignments","Written Assignments"],"term":"Spring 2007","instructors":["Patricia Brennecke"],"url":"https://ocw.mit.edu/courses/21g-228-advanced-workshop-in-writing-for-social-sciences-and-architecture-els-spring-2007/","views":1803},{"id":"11.014J+fall_2011","numbers":["11.014J","21H.232J"],"title":"American Urban History II","summary":"This is a seminar course that explores the history of selected features of the physical environment of urban America. Among the features considered are parks, cemeteries, tenements, suburbs, zoos, skyscrapers, department stores, supermarkets, and amusement parks. The course gives students experience in working with primary documentation sources through its selection of readings and class discussions. Students then have the opportunity to apply this experience by researching their own historical questions and writing a term paper.","departments":["History","Urban Studies and Planning"],"areas":["Humanities","Social Sciences"],"topics":["American History","History","Humanities","Public Administration","Social Science","Urban Studies"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2011","instructors":["Prof. Robert Fogelson"],"url":"https://ocw.mit.edu/courses/11-014j-american-urban-history-ii-fall-2011/","views":1803},{"id":"21A.801J+fall_2012","numbers":["21A.801J","EC.702J","STS.071J","EC.792J","21A.839J","STS.481J"],"title":"Cross-Cultural Investigations: Technology and Development","summary":"This course enhances cross-cultural understanding through the discussion of practical, ethical, and epistemological issues in conducting social science and applied research in foreign countries or unfamiliar communities. It includes a research practicum to help students develop interviewing, participant-observation, and other qualitative research skills, as well as critical discussion of case studies. The course is open to all interested students, but intended particularly for those planning to undertake exploratory research or applied work abroad. Students taking the graduate version complete additional assignments.","departments":["Anthropology","Edgerton Center","Science, Technology, and Society"],"areas":["Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Ethnography","Social Science"],"levels":["Undergraduate","Graduate"],"features":["Activity Assignments","Written Assignments"],"term":"Fall 2012","instructors":["Prof. Heather Paxson"],"url":"https://ocw.mit.edu/courses/21a-801j-cross-cultural-investigations-technology-and-development-fall-2012/","views":1802},{"id":"9.591J+fall_2004","numbers":["9.591J","24.945J"],"title":"Language Processing","summary":"This course is a seminar in real-time language comprehension. It considers models of sentence and discourse comprehension from the linguistic, psychology, and artificial intelligence literature, including symbolic and connectionist models. Topics include ambiguity resolution and linguistic complexity; the use of lexical, syntactic, semantic, pragmatic, contextual and prosodic information in language comprehension; the relationship between the computational resources available in working memory and the language processing mechanism; and the psychological reality of linguistic representations.","departments":["Brain and Cognitive Sciences","Linguistics and Philosophy"],"areas":["Humanities","Science & Math"],"topics":["Cognitive Science","Humanities","Linguistics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Presentation Assignments","Written Assignments"],"term":"Fall 2004","instructors":["Prof. Edward Gibson"],"url":"https://ocw.mit.edu/courses/9-591j-language-processing-fall-2004/","views":1802},{"id":"21T.122+spring_2009","numbers":["21T.122"],"title":"Introduction to Stagecraft","summary":"Offered in the spring and fall terms, Introduction to Stagecraft is a hands-on course that gets students working with the tools and techniques of theatrical production in a practical way. It is not a design course but one devoted to artisanship. Among the many remarkable final projects that have been proposed and presented at the end of the course have been a Renaissance hourglass blown in the MIT glass shop and set into a frame turned on our set shop lathe; a four harness loom built by a student who then wove cloth on it; a number of chain mail tunics and coifs; a wide variety of costume and furniture pieces and electrified period lighting fixtures.","departments":["Theater Arts"],"areas":["Art, Design & Architecture"],"topics":["Fine Arts","Performance Arts","Theatrical Design"],"levels":["Undergraduate"],"features":["Activity Assignments with Examples"],"term":"Spring 2009","instructors":["Karen Perlow","Leslie Cocuzzo Held","Michael Katz","Sara Brown"],"url":"https://ocw.mit.edu/courses/21m-606-introduction-to-stagecraft-spring-2009/","views":1800},{"id":"20.201+fall_2013","numbers":["20.201"],"title":"Mechanisms of Drug Actions","summary":"This course addresses the scientific basis for the development of new drugs. The first half of the semester begins with an overview of the drug discovery process, followed by fundamental principles of pharmacokinetics, pharmacodynamics, metabolism, and the mechanisms by which drugs cause therapeutic and toxic responses. The second half of the semester applies those principles to case studies and literature discussions of current problems with specific drugs, drug classes, and therapeutic targets.","departments":["Biological Engineering"],"areas":["Engineering","Health & Medicine","Science & Math"],"topics":["Biochemistry","Biological Engineering","Biology","Biomedicine","Engineering","Health and Medicine","Pharmacology and Toxicology","Science"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Instructor Insights","Lecture Notes","Problem Set Solutions","Problem Sets","Projects with Examples","Written Assignments"],"term":"Fall 2013","instructors":["Prof. Peter Dedon","Prof. Steven Tannenbaum","Dr. Mark Murcko","Dr. Charles Knutson"],"url":"https://ocw.mit.edu/courses/20-201-mechanisms-of-drug-actions-fall-2013/","views":1799},{"id":"15.879+spring_2014","numbers":["15.879"],"title":"Advanced Research Seminar in System Dynamics:","summary":"Doctoral-level advanced research seminar in system dynamics modeling with a focus on social, economic, and technical systems. The course covers classic works in dynamic modeling from various disciplines and current research problems and papers. Participants critique theories and models, often including replication, testing, and improvement of various models.","departments":["Sloan School of Management"],"areas":["Business & Management","Engineering"],"topics":["Business","Computational Modeling and Simulation","Engineering","Management","Operations Management","Organizational Behavior","Systems Engineering","Systems Optimization"],"levels":["Graduate"],"features":["Instructor Insights","Media Assignments with Examples","Tutorial Videos","Written Assignments"],"term":"Spring 2014","instructors":["Prof. Hazhir Rahmandad"],"url":"https://ocw.mit.edu/courses/15-879-research-seminar-in-system-dynamics-spring-2014/","views":1798},{"id":"21G.704+spring_2005","numbers":["21G.704"],"title":"Spanish IV","summary":"Course Sequences\n\nSpanish IV aims at developing and improving student’s oral and written communication through the continued study of the language, literature and culture of Spain, Latin America and Hispanic communities in the United States. It also seeks to improve students’ ability to read and appreciate literary and non-literary texts in Spanish, deepening this way students’ awareness and understanding of the cultural diversity of the Spanish-speaking world. The course is organized by themes based on contemporary social, political and cultural issues of Spanish-speaking societies such as: cultural identity, the changing roles of women and family, economic development and its effects on cultural heritage and environment, and the individual’s rights in the political system.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","Language","Spanish"],"levels":["Undergraduate"],"features":["Activity Assignments","Exams"],"term":"Spring 2005","instructors":["Margarita Ribas Groeger","Solivia Márquez"],"url":"https://ocw.mit.edu/courses/21g-704-spanish-iv-spring-2005/","views":1795},{"id":"1.77+spring_2006","numbers":["1.77"],"title":"Water Quality Control","summary":"The course material emphasizes mathematical models for predicting distribution and fate of effluents discharged into lakes, reservoirs, rivers, estuaries, and oceans. It also focuses on formulation and structure of models as well as analytical and simple numerical solution techniques. Also discussed are the role of element cycles, such as oxygen, nitrogen, and phosphorus, as water quality indicators; offshore outfalls and diffusion; salinity intrusion in estuaries; and thermal stratification, eutrophication, and sedimentation processes in lakes and reservoirs. This course is a core requirement for the Environmental MEng program.","departments":["Civil and Environmental Engineering"],"areas":["Engineering"],"topics":["Aquatic Sciences and Water Quality Control","Engineering","Environmental Engineering","Hydrodynamics and Coastal Engineering","Hydrology and Water Resource Systems"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Spring 2006","instructors":["Dr. Eric Adams"],"url":"https://ocw.mit.edu/courses/1-77-water-quality-control-spring-2006/","views":1795},{"id":"8.224+spring_2003","numbers":["8.224"],"title":"Exploring Black Holes: General Relativity & Astrophysics","summary":"Study of physical effects in the vicinity of a black hole as a basis for understanding general relativity, astrophysics, and elements of cosmology. Extension to current developments in theory and observation. Energy and momentum in flat spacetime; the metric; curvature of spacetime near rotating and nonrotating centers of attraction; trajectories and orbits of particles and light; elementary models of the Cosmos. Weekly meetings include an evening seminar and recitation. The last third of the semester is reserved for collaborative research projects on topics such as the Global Positioning System, solar system tests of relativity, descending into a black hole, gravitational lensing, gravitational waves, Gravity Probe B, and more advanced models of the Cosmos.","departments":["Physics"],"areas":["Science & Math"],"topics":["Astrophysics","Physics","Relativity","Science"],"levels":["Undergraduate"],"features":["Exams","Lecture Videos","Problem Sets"],"term":"Spring 2003","instructors":["Prof. Edmund Bertschinger","Prof. Edwin F. Taylor"],"url":"https://ocw.mit.edu/courses/8-224-exploring-black-holes-general-relativity-astrophysics-spring-2003/","views":1794},{"id":"11.401+fall_2003","numbers":["11.401"],"title":"Introduction to Housing, Community and Economic Development","summary":"As an introduction to the field of Housing, Community, and Economic Development (HCED), the course is structured to:\n\nAdvance student’s understanding of how public policy and private markets affect housing, economic development, the local economy, and neighborhood institutions;\n\nProvide an overview of techniques for framing public and private interventions to meet housing and community development agendas, broadly defined, of inner city and low income neighborhoods;\n\nReview and critique specific programs, policies and strategies that are (and have been) directed at local development and neighborhood regeneration issues;\n\nGive students an opportunity to reflect on their personal sense of the “housing, community, and economic development” process and the various roles that planners play in implementing the elements of that agenda.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Economics","Housing Development","Public Administration","Public Policy","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Fall 2003","instructors":["Prof. Langley Keyes"],"url":"https://ocw.mit.edu/courses/11-401-introduction-to-housing-community-and-economic-development-fall-2003/","views":1788},{"id":"12.S990+fall_2012","numbers":["12.S990"],"title":"Quantifying Uncertainty","summary":"The ability to quantify the uncertainty in our models of nature is fundamental to many inference problems in Science and Engineering. In this course, we study advanced methods to represent, sample, update and propagate uncertainty. This is a “hands on” course: Methodology will be coupled with applications. The course will include lectures, invited talks, discussions, reviews and projects and will meet once a week to discuss a method and its applications.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Algorithms and Data Structures","Applied Mathematics","Computational Modeling and Simulation","Computer Science","Engineering","Mathematics","Systems Engineering","Systems Optimization"],"levels":["Undergraduate","Graduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Fall 2012","instructors":["Dr. Sai Ravela"],"url":"https://ocw.mit.edu/courses/12-s990-quantifying-uncertainty-fall-2012/","views":1788},{"id":"21M.293+fall_2005","numbers":["21M.293"],"title":"Music of Africa","summary":"This course is an introduction to selected musical traditions of West Africa. A variety of musical practices and their cultural contexts will be explored through listening, reading, and written assignments, with an emphasis on class discussion. The course includes in-class instruction in West African drumming, song and dance, as well as lecture-demonstrations by guest artists.\n\nAfter an introductory unit, the course will be organized around four main geographical areas: Senegal, Mali, Ghana, and Nigeria. An in-depth study of music from these countries will be interspersed with brief overviews of Southern, Central, and East Africa.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["African History","Anthropology","Dance","Ethnography","Fine Arts","History","Humanities","Music","Music History","Performance Arts","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2005","instructors":["Prof. Patricia Tang"],"url":"https://ocw.mit.edu/courses/21m-293-music-of-africa-fall-2005/","views":1784},{"id":"11.123+spring_2014","numbers":["11.123"],"title":"Big Plans and Mega-Urban Landscapes","summary":"This course explores the physical, ecological, technological, political, economic, and cultural implications of big plans and mega-urban landscapes in a global context. It uses local and international case studies to understand the process of making major changes to urban landscape and city fabric, and to regional landscape systems. It includes lectures by leading practitioners. The assignments consider planning and design strategies across multiple scales and time frames.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Regional Planning","Social Science","Urban Planning","Urban Studies"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Spring 2014","instructors":["Kian Goh"],"url":"https://ocw.mit.edu/courses/11-123-big-plans-and-mega-urban-landscapes-spring-2014/","views":1783},{"id":"18.319+fall_2005","numbers":["18.319"],"title":"Geometric Combinatorics","summary":"This course offers an introduction to discrete and computational geometry. Emphasis is placed on teaching methods in combinatorial geometry. Many results presented are recent, and include open (as yet unsolved) problems.","departments":["Mathematics"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Algebra and Number Theory","Algorithms and Data Structures","Computer Science","Discrete Mathematics","Engineering","Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Problem Sets"],"term":"Fall 2005","instructors":["Dr. Csaba Toth"],"url":"https://ocw.mit.edu/courses/18-319-geometric-combinatorics-fall-2005/","views":1782},{"id":"11.491J+fall_2004","numbers":["11.491J","17.176J"],"title":"Economic Development, Policy Analysis, and Industrialization","summary":"This class analyzes the theoretical and historical reasons why governments in latecomer countries have intervened with a wide array of policies to foster industrial development at various turning points: the initiation of industrial activity; the diversification of the industrial base; the restructuring of major industrial institutions; and the entry into high-technology sectors.","departments":["Political Science","Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Developmental Economics","Economics","Industrial Organization","International Development","Public Administration","Public Economics","Public Policy","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. Alice Amsden"],"url":"https://ocw.mit.edu/courses/11-491j-economic-development-policy-analysis-and-industrialization-fall-2004/","views":1781},{"id":"MAS.965+fall_2003","numbers":["MAS.965"],"title":"Special Topics in Media Technology: Cooperative Machines","summary":"This course examines the issues, principles, and challenges toward building machines that cooperate with humans and with other machines. Philosophical, scientific, and theoretical insights into this subject will be covered, as well as how these ideas are manifest in both natural and artificial systems (e.g. software agents and robots).","departments":["Media Arts and Sciences"],"areas":["Art, Design & Architecture","Data Science, Analytics & Computer Technology","Engineering"],"topics":["Artificial Intelligence","Computer Science","Digital Media","Engineering","Fine Arts","Media Studies"],"levels":["Graduate"],"features":["Projects with Examples"],"term":"Fall 2003","instructors":["Prof. Cynthia Breazeal"],"url":"https://ocw.mit.edu/courses/mas-965-special-topics-in-media-technology-cooperative-machines-fall-2003/","views":1781},{"id":"21G.108+spring_2015","numbers":["21G.108","21G.158"],"title":"Chinese II (Streamlined)","summary":"This course, along with 21G.107 / 157 Chinese I (Streamlined) offered in the previous fall, form the elementary level of the streamlined sequence, which is intended for students who, when they began the sequence at beginning level, had basic conversational skills (gained, typically, from growing up in a Chinese speaking environment), but lacked a corresponding level of literacy. The focus of the course is on standard usage, on reading in both traditional and simplified characters, and on writing. The course is conducted entirely in Chinese.\n\nStreamlined I and II—each section is limited to 16 students for pedagogical purposes. Pre-registered students have priority. Continuing students get first priority, followed, in order, by students in 21G.076, declared concentrators and minors, sophomores, freshmen, juniors, seniors, and graduate students. Pre-registered students who did not show up for the first two days of class without warning will be eliminated. Students beginning their studies of Chinese language at MIT above the elementary level must contact the Chinese instructors for a placement test. No auditors allowed.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Chinese","Humanities","Language"],"levels":["Undergraduate"],"features":["Activity Assignments","Written Assignments"],"term":"Spring 2015","instructors":["Min-Min Liang"],"url":"https://ocw.mit.edu/courses/21g-108-chinese-ii-streamlined-spring-2015/","views":1780},{"id":"11.368+fall_2019","numbers":["11.368","11.148"],"title":"Environmental Justice Law and Policy","summary":"This seminar introduces students to basic principles of environmental justice and presents frameworks for analyzing and addressing inequalities in the distribution of environmental benefits and burdens from the perspectives of social science, public policy, and law.","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Humanities","Social Sciences"],"topics":["Environmental Policy","Humanities","Philosophy","Political Philosophy","Political Science","Public Administration","Social Science"],"levels":["Undergraduate","Graduate"],"features":["Written Assignments"],"term":"Fall 2019","instructors":["Prof. Justin Steil","Enjoli Hall"],"url":"https://ocw.mit.edu/courses/11-368-environmental-justice-law-and-policy-fall-2019/","views":1777},{"id":"16.852J+fall_2005","numbers":["16.852J","ESD.61J"],"title":"Integrating the Lean Enterprise","summary":"This class addresses some of the important issues involved with the planning, development, and implementation of lean enterprises. People, technology, process, and management dimensions of an effective lean manufacturing company are considered in a unified framework. Particular emphasis is placed on the integration of these dimensions across the entire enterprise, including product development, production, and the extended supply chain. Analysis tools as well as future trends and directions are explored. A team project is a key component of this subject.","departments":["Aeronautics and Astronautics","Engineering Systems Division"],"areas":["Business & Management","Engineering"],"topics":["Business","Engineering","Operations Management","Project Management","Supply Chain Management","Systems Engineering","Systems Optimization"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2005","instructors":["Prof. Deborah Nightingale"],"url":"https://ocw.mit.edu/courses/16-852j-integrating-the-lean-enterprise-fall-2005/","views":1777},{"id":"21L.460+spring_2005","numbers":["21L.460"],"title":"Medieval Literature: Dante, Boccaccio, Chaucer","summary":"The course explores the literary masterworks of three of the most celebrated authors of the Middle Ages in their original literary and historical contexts. The various themes they take up - the importance of writing in the vernacular; the discourse of love as a form of discipline practised upon the self; the personal and political aspirations of the self in society; the constitution of ideal forms of social organization; the role of religion in the life and works of lay authors - transformed the course of much of Western literature for the next five centuries. Readings will include the entire Divine Comedy, generous selections from the Decameron, and all of Troilus and Criseyde in the original Middle English, together with samplings from the Troubadour tradition and the dolce stil nuovo.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Criticism","History","Humanities","Literature","Medieval History"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2005","instructors":["Prof. James Cain"],"url":"https://ocw.mit.edu/courses/21l-460-medieval-literature-dante-boccaccio-chaucer-spring-2005/","views":1776},{"id":"21W.035+fall_2016","numbers":["21W.035"],"title":"Science Writing and New Media: Communicating Science to the Public","summary":"This course provides an introduction to writing about science (including medicine, technology, and engineering) for general readers. With a strong emphasis in background research, this course will help students build a foundation for strong science writing. Students will read works by accomplished science writers. Each assignment will focus on a different popular form, such as news articles, interviews, essays, and short features.","departments":["Comparative Media Studies/Writing"],"areas":["Humanities"],"topics":["Academic Writing","History","History of Science and Technology","Humanities","Literature","Nonfiction Prose","Periodic Literature","Technical Writing"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments"],"term":"Fall 2016","instructors":["Jared David Berezin"],"url":"https://ocw.mit.edu/courses/21w-035-science-writing-and-new-media-communicating-science-to-the-public-fall-2016/","views":1775},{"id":"HST.525J+fall_2005","numbers":["HST.525J","10.548J"],"title":"Tumor Pathophysiology and Transport Phenomena","summary":"Tumor pathophysiology plays a central role in the growth, invasion, metastasis and treatment of solid tumors. This class applies principles of transport phenomena to develop a systems-level, quantitative understanding of angiogenesis, blood flow and microcirculation, metabolism and microenvironment, transport and binding of small and large molecules, movement of cancer and immune cells, metastatic process, and treatment response.\n\nAdditional Faculty\n\nDr. Pat D’Amore\n\nDr. Dan Duda\n\nDr. Robert Langer\n\nProf. Robert Weinberg\n\nDr. Marsha Moses\n\nDr. Raghu Kalluri\n\nDr. Lance Munn","departments":["Chemical Engineering","Health Sciences and Technology"],"areas":["Engineering","Health & Medicine"],"topics":["Cancer","Chemical Engineering","Engineering","Health and Medicine","Pathology and Pathophysiology","Transport Processes"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2005","instructors":["Dr. Rakesh Jain"],"url":"https://ocw.mit.edu/courses/hst-525j-tumor-pathophysiology-and-transport-phenomena-fall-2005/","views":1774},{"id":"STS.464+spring_2005","numbers":["STS.464"],"title":"Cultural History of Technology","summary":"The subject of this course is the historical process by which the meaning of “technology” has been constructed. Although the word itself is traceable to the ancient Greek root teckhne (meaning art), it did not enter the English language until the 17th century, and did not acquire its current meaning until after World War I. The aim of the course, then, is to explore various sectors of industrializing 19th and 20th century Western society and culture with a view to explaining and assessing the emergence of technology as a pivotal word (and concept) in contemporary (especially Anglo-American) thought and expression.\n\nNote: In the interests of freshness and topicality we regard the STS.464 syllabus as sufficiently flexible to permit some — mostly minor — variations from year to year. One example of a different STS.464 syllabus can be found in STS.464 Technology and the Literary Imagination, Spring 2008.","departments":["Science, Technology, and Society"],"areas":["Humanities"],"topics":["History","History of Science and Technology","Humanities","Intellectual History"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2005","instructors":["Prof. Leo Marx","Prof. Rosalind Williams"],"url":"https://ocw.mit.edu/courses/sts-464-cultural-history-of-technology-spring-2005/","views":1769},{"id":"11.165+fall_2011","numbers":["11.165","11.477"],"title":"Infrastructure and Energy Technology Challenges","summary":"This seminar examines efforts in developing and advanced nations and regions to create, finance, and regulate infrastructure and energy technologies from a variety of methodological and disciplinary perspectives. It is conducted with intensive in-class discussions and debates.","departments":["Urban Studies and Planning"],"areas":["Data Science, Analytics & Computer Technology","Energy, Climate & Sustainability","Social Sciences"],"topics":["Developmental Economics","Economics","Energy","International Development","Public Administration","Public Policy","Science and Technology Policy","Security Studies","Social Science","Technology"],"levels":["Undergraduate","Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2011","instructors":["Prof. Karen R. Polenske","Prof. Apiwat Ratanawaraha"],"url":"https://ocw.mit.edu/courses/11-165-infrastructure-and-energy-technology-challenges-fall-2011/","views":1769},{"id":"6.701+spring_2010","numbers":["6.701","6.719"],"title":"Introduction to Nanoelectronics","summary":"Traditionally, progress in electronics has been driven by miniaturization. But as electronic devices approach the molecular scale, classical models for device behavior must be abandoned. To prepare for the next generation of electronic devices, this class teaches the theory of current, voltage and resistance from atoms up. To describe electrons at the nanoscale, we will begin with an introduction to the principles of quantum mechanics, including quantization, the wave-particle duality, wavefunctions and Schrödinger’s equation. Then we will consider the electronic properties of molecules, carbon nanotubes and crystals, including energy band formation and the origin of metals, insulators and semiconductors. Electron conduction will be taught beginning with ballistic transport and concluding with a derivation of Ohm’s law. We will then compare ballistic to bulk MOSFETs. The class will conclude with a discussion of possible fundamental limits to computation.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Energy, Climate & Sustainability","Engineering","Science & Math"],"topics":["Chemistry","Electrical Engineering","Electronics","Energy","Engineering","Nanotechnology","Physical Chemistry","Physics","Quantum Mechanics","Science","Technology"],"levels":["Undergraduate"],"features":["Exams","Open Textbooks","Problem Sets"],"term":"Spring 2010","instructors":["Prof. Marc  Baldo"],"url":"https://ocw.mit.edu/courses/6-701-introduction-to-nanoelectronics-spring-2010/","views":1767},{"id":"STS.050+spring_2011","numbers":["STS.050"],"title":"The History of MIT","summary":"This course examines the history of MIT through the lens of the broader history of science and technology, and vice versa. The course covers the founding of MIT in 1861 and goes through the present, including such topics as William Barton Rogers, educational philosophy, biographies of MIT students and professors, intellectual and organizational development, the role of science, changing laboratories and practices, and MIT’s relationship with Boston, the federal government, and industry. Assignments include short papers, presentations, and final paper. A number of classes are concurrent with the MIT150 Symposia.","departments":["Science, Technology, and Society"],"areas":["Education & Teaching","Humanities"],"topics":["American History","Higher Education","History","History of Science and Technology","Humanities","Modern History","Teaching and Education"],"levels":["Undergraduate"],"features":["Lecture Videos","Written Assignments"],"term":"Spring 2011","instructors":["Prof. David Mindell","Prof. Merritt Roe Smith"],"url":"https://ocw.mit.edu/courses/sts-050-the-history-of-mit-spring-2011/","views":1767},{"id":"3.45+spring_2004","numbers":["3.45"],"title":"Magnetic Materials","summary":"This course will cover the following topics:\n\nMagnetostatics\n\nOrigin of magnetism in materials\n\nMagnetic domains and domain walls\n\nMagnetic anisotropy\n\nReversible and irreversible magnetization processes\n\nHard and soft magnetic materials\n\nMagnetic recording\n\nSpecial topics include magnetism of thin films, surfaces and fine particles; transport in ferromagnets, magnetoresistive sensors, and amorphous magnetic materials.","departments":["Materials Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Electromagnetism","Engineering","Materials Science and Engineering","Physics","Science"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Problem Set Solutions","Problem Sets"],"term":"Spring 2004","instructors":["Dr. Robert O’Handley"],"url":"https://ocw.mit.edu/courses/3-45-magnetic-materials-spring-2004/","views":1766},{"id":"4.463+fall_2002","numbers":["4.463","4.442"],"title":"Building Technologies III: Building Structural Systems II","summary":"This course addresses advanced topics in structures, exterior envelopes and contemporary production technologies. It continues the exploration of structural elements and systems; expanding to include more complex determinant, indeterminate, long-span and high-rise systems. Some of the topics covered include reinforced concrete, steel and engineered wood design, and an introduction to tensile systems. The contemporary exterior envelope is discussed with an emphasis on the classification of systems, their performance attributes and advanced manufacturing technologies. This course is the second of two graduate structures courses, the first of which is 4.462. They offer an expanded version of the content presented in the undergraduate course, 4.440.","departments":["Architecture"],"areas":["Art, Design & Architecture","Engineering"],"topics":["Architectural Engineering","Architecture","Civil Engineering","Engineering","Fine Arts","Materials Science and Engineering","Structural Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Projects"],"term":"Fall 2002","instructors":["Prof. John Ochsendorf"],"url":"https://ocw.mit.edu/courses/4-463-building-technologies-iii-building-structural-systems-ii-fall-2002/","views":1765},{"id":"6.041+spring_2006","numbers":["6.041","6.431"],"title":"Probabilistic Systems Analysis and Applied  Probability","summary":"This course is offered both to undergraduates (6.041) and graduates (6.431), but the assignments differ. 6.041/6.431 introduces students to the modeling, quantification, and analysis of uncertainty. Topics covered include: formulation and solution in sample space, random variables, transform techniques, simple random processes and their probability distributions, Markov processes, limit theorems, and elements of statistical inference.","departments":["Electrical Engineering and Computer Science"],"areas":["Science & Math"],"topics":["Discrete Mathematics","Mathematics","Probability and Statistics"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets","Simulation Videos"],"term":"Spring 2006","instructors":["Prof. Munther Dahleh"],"url":"https://ocw.mit.edu/courses/6-041-probabilistic-systems-analysis-and-applied-probability-spring-2006/","views":1765},{"id":"21H.383+fall_2016","numbers":["21H.383","21H.982"],"title":"Technology and the Global Economy, 1000-2000","summary":"This seminar examines the global history of the last millennium, including technological change, commodity exchange, systems of production, and economic growth. Students engage with economic history, medieval and early modern origins of modern systems of production, consumption and global exchange. Topics include the long pre-history of modern economic development; medieval world systems; the age of discovery; the global crisis of the 17th century; demographic systems; global population movements; the industrial revolution; the rise of the modern consumer; colonialism and empire building; patterns of inequality, within and across states; the curse of natural resources fate of Africa; and the threat of climate change to modern economic systems. Students taking the graduate version complete additional assignments.","departments":["History"],"areas":["Humanities"],"topics":["African History","American History","History","Humanities","Medieval History","World History"],"levels":["Undergraduate","Graduate"],"features":["Written Assignments with Examples"],"term":"Fall 2016","instructors":["Prof. Anne McCants"],"url":"https://ocw.mit.edu/courses/21h-383-technology-and-the-global-economy-1000-2000-fall-2016/","views":1764},{"id":"6.642+fall_2008","numbers":["6.642"],"title":"Continuum Electromechanics","summary":"This course focuses on laws, approximations and relations of continuum electromechanics. Topics include mechanical and electromechanical transfer relations, statics and dynamics of electromechanical systems having a static equilibrium, electromechanical flows, and field coupling with thermal and molecular diffusion. Also covered are electrokinetics, streaming interactions, application to materials processing, magnetohydrodynamic and electrohydrodynamic pumps and generators, ferrohydrodynamics, physiochemical systems, heat transfer, continuum feedback control, electron beam devices, and plasma dynamics.\n\nAcknowledgements\n\nThe instructor would like to thank Xuancheng Shao and Anyang Hou for transcribing into LaTeX the problem set solutions and exam solutions, respectively.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering","Science & Math"],"topics":["Electrical Engineering","Electromagnetism","Engineering","Mechanical Engineering","Physics","Quantum Mechanics","Science"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2008","instructors":["Markus Zahn"],"url":"https://ocw.mit.edu/courses/6-642-continuum-electromechanics-fall-2008/","views":1763},{"id":"WGS.645+fall_2014","numbers":["WGS.645"],"title":"Gender, Health and Marginalization Through a Critical Feminist Lens","summary":"In the course we will use a feminist interdisciplinary lens and invite students to look critically at how practices like privatization, shrinking public “safety nets”, de-regulation, and the commodification of health services intersect inevitably with gender, race and class, for both men and women. We will draw on a blend of empirical studies, policy materials, films and guest speakers to examine specific health issues like menstrual health, corporate obstetrics, abortion, obesity, intersex, harassment and other forms of gendered violence, mental health and stress, parent-child attachment, as well as ethics and pharmaceuticals.\n\nThe Graduate Consortium in Women’s Studies (GCWS)\n\nThis course is part of the Graduate Consortium in Women’s Studies. The GCWS at MIT brings together scholars and teachers at nine degree-granting institutions in the Boston area who are devoted to graduate teaching and research in Women’s Studies and to advancing interdisciplinary Women’s Studies scholarship. Learn more about the GCWS.","departments":["Women's and Gender Studies"],"areas":["Health & Medicine","Social Sciences"],"topics":["Gender Studies","Health and Exercise Science","Health and Medicine","Mental Health","Public Health","Social Medicine","Society"],"levels":["Graduate"],"features":["Instructor Insights","Presentation Assignments","Written Assignments"],"term":"Fall 2014","instructors":["Prof. Chris Bobel","Prof. Silvia Dominguez","Norma Swenson"],"url":"https://ocw.mit.edu/courses/wgs-645-gender-health-and-marginalization-through-a-critical-feminist-lens-fall-2014/","views":1763},{"id":"RES.6-001+spring_2008","numbers":["RES.6-001"],"title":"Electromagnetic Fields and Energy","summary":"Published in 1989 by Prentice-Hall, this book is a useful resource for educators and self-learners alike. The text is aimed at those who have seen Maxwell’s equations in integral and differential form and who have been exposed to some integral theorems and differential operators. A hypertext version of this textbook can be found here. An accompanying set of video demonstrations is available below.\n\nThese video demonstrations convey electromagnetism concepts. The demonstrations are related to topics covered in the textbook. They were prepared by Markus Zahn, James R. Melcher, and Manuel L. Silva and were produced by the Department of Electrical Engineering and Computer Science at the Massachusetts Institute of Technology.\n\nThe purpose of these demonstrations is to make mathematical analysis of electromagnetism take on physical meaning. Based on relatively simple configurations and arrangements of equipment, they make a direct connection between what has been analytically derived and what is observed. They permit the student to observe physically what has been described symbolically. Often presented with a plot of theoretical predictions that are compared to measured data, these demonstrations give the opportunity to test the range of validity of the theory and present a quantitative approach to dealing with the physical world.\n\nThe short form of these videos contains the demonstrations only. The long form also presents theory, diagrams, and calculations in support of the demonstrations.\n\nThese videos are used in the courses 6.013/ESD.013J and 6.641.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering","Science & Math"],"topics":["Electrical Engineering","Electromagnetism","Engineering","Physics","Science"],"levels":["Undergraduate"],"features":["Lecture Videos","Open Textbooks","Problem Set Solutions","Problem Sets"],"term":"Spring 2008","instructors":["Hermann A. Haus","James R. Melcher","Markus Zahn","Manuel L. Silva"],"url":"https://ocw.mit.edu/courses/res-6-001-electromagnetic-fields-and-energy-spring-2008/","views":1762},{"id":"2.154+fall_2004","numbers":["2.154"],"title":"Maneuvering and Control of Surface and Underwater Vehicles (13.49)","summary":"This course is about maneuvering motions of surface and underwater vehicles. Topics covered include: derivation of equations of motion, hydrodynamic coefficients, memory effects, linear and nonlinear forms of the equations of motion, control surfaces modeling and design, engine, propulsor, and transmission systems modeling and simulation during maneuvering. The course also deals with stability of motion, principles of multivariable automatic control, optimal control, Kalman filtering, and loop transfer recovery. We will also explore applications chosen from autopilots for surface vehicles; towing in open seas; and remotely operated vehicles.\n\nThis course was originally offered in Course 13 (Department of Ocean Engineering) as 13.49. In 2005, ocean engineering subjects became part of Course 2 (Department of Mechanical Engineering), and this course was renumbered 2.154.","departments":["Mechanical Engineering"],"areas":["Engineering"],"topics":["Computational Modeling and Simulation","Dynamics and Control","Engineering","Fluid Mechanics","Hydrodynamics","Mechanical Design","Mechanical Engineering","Ocean Engineering","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Open Textbooks"],"term":"Fall 2004","instructors":["Prof. Michael Triantafyllou"],"url":"https://ocw.mit.edu/courses/2-154-maneuvering-and-control-of-surface-and-underwater-vehicles-13-49-fall-2004/","views":1759},{"id":"21L.703+spring_2005","numbers":["21L.703"],"title":"Studies in Drama: Theater and Science in a Time of War","summary":"This course explores the creation (and creativity) of the modern scientific and cultural world through study of western Europe in the 17th century, the age of Descartes and Newton, Shakespeare, Rembrandt and Molière. The class compares period thinking to present-day debates about the scientific method, art, religion, and society. This team-taught, interdisciplinary subject draws on a wide range of literary, dramatic, historical, and scientific texts and images, and involves theatrical experimentation as well as reading, writing, researching and conversing.","departments":["Literature"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Criticism","Drama","Fine Arts","History","Humanities","Intellectual History","Literature","Performance Arts","Theater"],"levels":["Undergraduate"],"features":["Projects with Examples"],"term":"Spring 2005","instructors":["Prof. Diana Henderson","Prof. Janet Sonenberg"],"url":"https://ocw.mit.edu/courses/21l-703-studies-in-drama-theater-and-science-in-a-time-of-war-spring-2005/","views":1756},{"id":"12.333+spring_2004","numbers":["12.333"],"title":"Atmospheric and Ocean Circulations","summary":"In this course, we will look at many important aspects of the circulation of the atmosphere and ocean, from length scales of meters to thousands of km and time scales ranging from seconds to years. We will assume familiarity with concepts covered in course 12.003 (Physics of the Fluid Earth). In the early stages of the present course, we will make somewhat greater use of math than did 12.003, but the math we will use is no more than that encountered in elementary electromagnetic field theory, for example. The focus of the course is on the physics of the phenomena which we will discuss.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Energy, Climate & Sustainability","Science & Math"],"topics":["Atmospheric Science","Climate Studies","Earth Science","Geophysics","Oceanography","Science"],"levels":["Undergraduate"],"features":["Lecture Notes"],"term":"Spring 2004","instructors":["Prof. R. Alan Plumb"],"url":"https://ocw.mit.edu/courses/12-333-atmospheric-and-ocean-circulations-spring-2004/","views":1755},{"id":"4.671+spring_2016","numbers":["4.671","4.670"],"title":"Nationalism, Internationalism, and Globalism in Modern Art","summary":"This course studies how international modernism interacted with the concept of “nation” and how contemporary discourses concerning globalism changes that dynamic. This course also looks at how art uses and critiques globalization on various levels.","departments":["Architecture"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Architecture","Art History","Comparative History","European History","Fine Arts","History","Humanities","World History"],"levels":["Undergraduate","Graduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Spring 2016","instructors":["Prof. Caroline Jones"],"url":"https://ocw.mit.edu/courses/4-671-nationalism-internationalism-and-globalism-in-modern-art-spring-2016/","views":1754},{"id":"14.16+spring_2016","numbers":["14.16"],"title":"Strategy and Information","summary":"This is an advanced course in game theory. We begin with a rigorous overview of the main equilibrium concepts for non-­cooperative games in both static and dynamic settings with either complete or incomplete information. We define and explore properties of iterated strict dominance, rationalizability, Nash equilibrium, subgame perfection, sequential, perfect and proper equilibria, the intuitive criterion, and iterated weak dominance. We discuss applications to auctions, bargaining, and repeated games. Then we introduce solution concepts for cooperative games and study non-­cooperative implementations. Other topics include matching theory and networks.","departments":["Economics"],"areas":["Social Sciences"],"topics":["Economics","Game Theory","Social Science"],"levels":["Undergraduate"],"features":["Exams","Lecture Notes"],"term":"Spring 2016","instructors":["Prof. Mihai Manea"],"url":"https://ocw.mit.edu/courses/14-16-strategy-and-information-spring-2016/","views":1753},{"id":"21L.704+spring_2003","numbers":["21L.704"],"title":"Studies in Poetry: Gender and Lyric -- Renaissance Men and Women Writing about Love","summary":"The core of this seminar will be the great sequences of English love sonnets written by William Shakespeare, Philip Sidney, Edmund Spenser, and Mary Wroth. These poems cover an enormous amount of aesthetic and psychological ground: ranging from the utterly subjective to the entirely public or conventional, from licit to forbidden desires, they might also serve as a manual of experimentation with the resources of sound, rhythm, and figuration in poetry. Around these sequences, we will develop several other contexts, using both Renaissance texts and modern accounts: the Petrarchan literary tradition (poems by Francis Petrarch and Sir Thomas Wyatt); the social, political, and ethical uses of love poetry (seduction, getting famous, influencing policy, elevating morals, compensating for failure); other accounts of ideal masculinity and femininity (conduct manuals, theories of gender and anatomy); and the other limits of the late sixteenth century vogue for love poetry: narrative poems, pornographic poems, poems that don’t work.","departments":["Literature"],"areas":["Humanities","Social Sciences"],"topics":["Criticism","Gender Studies","Humanities","International Literature","Literature","Poetry","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2003","instructors":["Prof. Mary Fuller"],"url":"https://ocw.mit.edu/courses/21l-704-studies-in-poetry-gender-and-lyric-renaissance-men-and-women-writing-about-love-spring-2003/","views":1753},{"id":"RES.18-015+spring_2024","numbers":["RES.18-015"],"title":"Topics in Fourier Analysis","summary":"The goal of these lectures is to provide an introduction to Fourier analysis. The first topic is Fourier series, in particular, the Gibbs phenomenon and the dependence of their convergence properties on the suitability method used. The second topic is the Fourier transform, first the L¹ theory and then, using Hermite functions, the L² theory. The third topic is L. Schwartz’s theory of tempered distributions. The fourth topic is the theory of weak convergence of probability measures and application to a derivation of the Lévy-Khinchine formula for the Fourier transform of infinitely divisible probability measures. The final topic is the elementary theory of singular integral operators, starting with the Hilbert transform and then using the method of rations to prove the Lᵖ boundedness of even Calderòn-Zygmund kernels.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Mathematical Analysis","Mathematics"],"levels":["Non-Credit"],"features":["Lecture Notes","Open Textbooks"],"term":"Spring 2024","instructors":["Prof. Daniel Stroock"],"url":"https://ocw.mit.edu/courses/res-18-015-topics-in-fourier-analysis-spring-2024/","views":1751},{"id":"20.181+fall_2006","numbers":["20.181"],"title":"Computation for Biological Engineers","summary":"This course covers the analytical, graphical, and numerical methods supporting the analysis and design of integrated biological systems. Topics include modularity and abstraction in biological systems, mathematical encoding of detailed physical problems, numerical methods for solving the dynamics of continuous and discrete chemical systems, statistics and probability in dynamic systems, applied local and global optimization, simple feedback and control analysis, statistics and probability in pattern recognition.\n\nAn official course Web site and Wiki is maintained on OpenWetWare: 20.181 Computation for Biological Engineers.","departments":["Biological Engineering"],"areas":["Business & Management","Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Computation and Systems Biology","Computational Science and Engineering","Engineering","Science","Systems Engineering","Systems Optimization"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2006","instructors":["Prof. Eric Alm","Prof. Andrew Endy"],"url":"https://ocw.mit.edu/courses/20-181-computation-for-biological-engineers-fall-2006/","views":1749},{"id":"RES.STP-001+january-iap_2011","numbers":["RES.STP-001"],"title":"Science Policy Bootcamp","summary":"The careers of MIT scientists and engineers are significantly determined by public policy decisions made in Washington by the government. However, their access to information on how this system works is limited. Meanwhile, we increasingly understand that science and technology-based innovation is deeply connected to society’s economic growth and its ability to generate societal wellbeing, so the public role of science is growing. This course will examine the public policy behind and the government’s role in the science and technology innovation system. Given the challenges to future federal science support, this seminar will aim to equip those planning careers in and around science and technology with a basic background for involvement in science policymaking.\n\nThis course is offered during MIT’s Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month. It features student-led discussion incorporated into the course structure as well as opportunities to interact with MIT students and faculty involved in aspects of science policy. The course has been offered since 2006 and has developed as a collaborative effort between the instructor and MIT students from the Science Policy Initiative.","departments":[],"areas":["Social Sciences"],"topics":["Public Administration","Science and Technology Policy","Social Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"January IAP 2011","instructors":["William Bonvillian"],"url":"https://ocw.mit.edu/courses/res-stp-001-science-policy-bootcamp-january-iap-2011/","views":1749},{"id":"11.949+fall_2003","numbers":["11.949"],"title":"Cities in Conflict: Theory and Practice","summary":"This course’s aims are two-fold:\n\n• to offer students the theoretical and practical tools to understand how and why cities become torn by ethnic, religious, racial, nationalist, and/or other forms of identity that end up leading to conflict, violence, inequality, and social injustice; and\n• to use this knowledge and insight in the search for solutions\n\nAs preparation, students will be required to become familiar with social and political theories of the city and the nation and their relationship to each other. They also will focus on the ways that racial, ethnic, religious, nationalist or other identities grow and manifest themselves in cities or other territorial levels of determination (including the regional or transnational). In the search for remedies, students will be encouraged to consider a variety of policymaking or design points of entry, ranging from the political- institutional (e.g. forms of democratic participation and citizenship) to spatial, infrastructural, and technological interventions.","departments":["Urban Studies and Planning"],"areas":["Humanities","Social Sciences"],"topics":["Humanities","Philosophy","Political Philosophy","Public Administration","Public Policy","Regional Politics","Social Justice","Social Science","Sociology","Urban Studies"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Fall 2003","instructors":["Prof. Diane Davis","Prof. Roger Petersen"],"url":"https://ocw.mit.edu/courses/11-949-cities-in-conflict-theory-and-practice-fall-2003/","views":1742},{"id":"4.105+fall_2012","numbers":["4.105"],"title":"Geometric Disciplines and Architecture Skills: Reciprocal Methodologies","summary":"This course is an intensive introduction to architectural design tools and process, and is taught through a series of short exercises. The conceptual basis of each exercise is in the interrogation of the geometric principles that lie at the core of each skill. Skills covered in this course range from techniques of hand drafting, to generation of 3D computer models, physical model-building, sketching, and diagramming. Weekly lectures and pin-ups address the conventions associated with modes of architectural representation and their capacity to convey ideas. This course is tailored and offered only to first-year M.Arch students.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architecture","Fine Arts"],"levels":["Graduate"],"features":["Activity Assignments","Design Assignments","Lecture Notes","Projects with Examples"],"term":"Fall 2012","instructors":["Brandon Clifford"],"url":"https://ocw.mit.edu/courses/4-105-geometric-disciplines-and-architecture-skills-reciprocal-methodologies-fall-2012/","views":1742},{"id":"16.881+summer_1998","numbers":["16.881"],"title":"Robust System Design","summary":"This course was created for the “product development” track of MIT’s System Design and Management Program (SDM) in conjunction with the Center for Innovation in Product Development. After taking this course, a student should be able to:\n\n• Formulate measures of performance of a system or quality characteristics. These quality characteristics are to be made robust to noise affecting the system.\n• Sythesize and select design concepts for robustness.\n• Identify noise factors whose variation may affect the quality characteristics.\n• Estimate the robustness of any given design (experimentally and analytically).\n• Formulate and implement methods to reduce the effects of noise (parameter design, active control, adjustment).\n• Select rational tolerances for a design.\n• Explain the role of robust design techniques within the wider context of the product development process.\n• Lead product development activities that include robust design techniques.","departments":["Aeronautics and Astronautics"],"areas":["Business & Management","Engineering","Science & Math"],"topics":["Computational Modeling and Simulation","Engineering","Mathematics","Probability and Statistics","Systems Design","Systems Engineering"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Summer 1998","instructors":["Prof. Daniel Frey"],"url":"https://ocw.mit.edu/courses/16-881-robust-system-design-summer-1998/","views":1742},{"id":"17.441+fall_2007","numbers":["17.441","17.442"],"title":"International Politics and Climate Change","summary":"This course examines the interconnections of international politics and climate change. Beginning with an analysis of the strategic and environmental legacies of the 20th Century, it explores the politicization of the natural environment, the role of science in this process, and the gradual shifts in political concerns to incorporate “nature”. Two general thrusts of climate-politics connections are pursued, namely those related to (a) conflict – focusing on threats to security due to environmental dislocations and (b) cooperation – focusing on the politics of international treaties that have contributed to emergent processes for global accord in response to evidence of climate change. The course concludes by addressing the question of: “What Next?”","departments":["Political Science"],"areas":["Business & Management","Energy, Climate & Sustainability","Engineering","Science & Math","Social Sciences"],"topics":["Business","Climate Studies","Earth Science","Engineering","Environmental Engineering","Environmental Management","Globalization","International Relations","Political Science","Science","Social Science","Sustainability"],"levels":["Undergraduate","Graduate"],"features":["Exams","Written Assignments"],"term":"Fall 2007","instructors":["Prof. Nazli Choucri"],"url":"https://ocw.mit.edu/courses/17-441-international-politics-and-climate-change-fall-2007/","views":1740},{"id":"14.662+spring_2015","numbers":["14.662"],"title":"Labor Economics II","summary":"This is a graduate course in labor economics. The course will focus on covering theory and evidence on inequality, wage structure, skill demands, employment, job loss, and early-life determinants of long-run outcomes. Particular areas of focus are: (1) wage determination, including the Roy model, equalizing wage differentials, and models of discrimination; (2) the roles played by supply, demand, institutions, technology and trade in the evolving distribution of income.","departments":["Economics"],"areas":["Social Sciences"],"topics":["Economics","Labor Economics","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2015","instructors":["Prof. David Autor","Prof. Heidi L Williams"],"url":"https://ocw.mit.edu/courses/14-662-labor-economics-ii-spring-2015/","views":1740},{"id":"8.231+fall_2006","numbers":["8.231"],"title":"Physics of Solids I","summary":"This course offers an introduction to the basic concepts of the quantum theory of solids.","departments":["Physics"],"areas":["Science & Math"],"topics":["Condensed Matter Physics","Physics","Science"],"levels":["Undergraduate"],"features":["Problem Sets"],"term":"Fall 2006","instructors":["Prof. Xiao-Gang Wen"],"url":"https://ocw.mit.edu/courses/8-231-physics-of-solids-i-fall-2006/","views":1740},{"id":"21L.715+fall_2007","numbers":["21L.715","WGS.493","CMS.871"],"title":"Media in Cultural Context: Popular Readerships","summary":"What is the history of popular reading in the Western world? How does widespread access to print relate to distinctions between highbrow and lowbrow culture, between good taste and bad judgment, and between men and women readers? This course will introduce students to the broad history of popular reading and to controversies about taste and gender that have characterized its development. Our grounding in historical material will help make sense of our main focus: recent developments in the theory and practice of reading, including fan-fiction, Oprah’s book club, comics, hypertext, mass-market romance fiction, mega-chain bookstores, and reader response theory.","departments":["Literature","Women's and Gender Studies"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Comparative Literature","Fine Arts","Gender Studies","History","Humanities","Intellectual History","Literature","Media Studies","Society","Women's Studies"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2007","instructors":["Prof. Sarah Brouillette"],"url":"https://ocw.mit.edu/courses/21l-715-media-in-cultural-context-popular-readerships-fall-2007/","views":1738},{"id":"6.542J+fall_2005","numbers":["6.542J","24.966J","HST.712J"],"title":"Laboratory on the Physiology, Acoustics, and Perception of Speech","summary":"The course focuses on experimental investigations of speech processes. Topics include: measurement of articulatory movements, measurements of pressures and airflows in speech production, computer-aided waveform analysis and spectral analysis of speech, synthesis of speech, perception and discrimination of speechlike sounds, speech prosody, models for speech recognition, speech disorders, and other topics.\n\n• Two 1-hour lectures per week\n• Two labs per week\n• Brief lab reports\n• Term project, with short term paper\n• No exams","departments":["Electrical Engineering and Computer Science","Health Sciences and Technology","Linguistics and Philosophy"],"areas":["Engineering","Health & Medicine","Humanities"],"topics":["Anatomy and Physiology","Electrical Engineering","Engineering","Health and Medicine","Humanities","Linguistics","Signal Processing","Speech Pathology"],"levels":["Graduate"],"features":["Projects"],"term":"Fall 2005","instructors":["Dr. Joseph S. Perkell","Prof. Kenneth Stevens","Dr. Stefanie Shattuck-Hufnagel"],"url":"https://ocw.mit.edu/courses/6-542j-laboratory-on-the-physiology-acoustics-and-perception-of-speech-fall-2005/","views":1737},{"id":"21W.031+spring_2017","numbers":["21W.031"],"title":"Science Writing and New Media: Explorations in Communicating about Science & Technology","summary":"Proficiency in communicating about science and technology comes from both knowledge and practice, and this course emphasizes both. Through a variety of reading and writing assignments, we will examine general principles of good writing, as well as principles associated specifically with scientific and technical writing. We will also explore the effects of new media as avenues for communicating about science.","departments":["Comparative Media Studies/Writing"],"areas":["Humanities"],"topics":["Academic Writing","Humanities","Literature","Technical Writing"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2017","instructors":["Dr. Janis Melvold"],"url":"https://ocw.mit.edu/courses/21w-031-science-writing-and-new-media-explorations-in-communicating-about-science-technology-spring-2017/","views":1737},{"id":"6.S898+fall_2019","numbers":["6.S898","12.S992"],"title":"Climate Change Seminar","summary":"This course provides a broad overview of issues related to climate change, with an emphasis on those aspects most relevant to computer scientists. Topics include climate science, climate models and simulations, decision-making under uncertainty, economics, mitigation strategies, adaptation strategies, geoengineering, policy-making, messaging, and politics.The course will culminate in a presentation of a research project which might include a paper, a blog, software etc.","departments":["Earth, Atmospheric, and Planetary Sciences","Electrical Engineering and Computer Science"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math"],"topics":["Climate Studies","Computational Modeling and Simulation","Earth Science","Engineering","Science","Systems Engineering"],"levels":["Graduate"],"features":["Projects with Examples"],"term":"Fall 2019","instructors":["Prof. Alan Edelman","Prof. John Fernandez","Prof. Ronald Rivest","Henri Drake"],"url":"https://ocw.mit.edu/courses/6-s898-climate-change-seminar-fall-2019/","views":1736},{"id":"21H.311+fall_2004","numbers":["21H.311"],"title":"The Renaissance, 1300-1600","summary":"The “Renaissance” as a phenomenon in European history is best understood as a series of social, political, and cultural responses to an intellectual trend which began in Italy in the fourteenth century. This intellectual tendency, known as humanism, or the studia humanitatis, was at the heart of developments in literature, the arts, the sciences, religion, and government for almost three hundred years. In this class, we will highlight the history of humanism, but we will also study religious reformations, high politics, the agrarian world, and European conquest and expansion abroad in the period.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","European History","History","Humanities","Intellectual History","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. Jeffrey S. Ravel"],"url":"https://ocw.mit.edu/courses/21h-311-the-renaissance-1300-1600-fall-2004/","views":1736},{"id":"22.05+fall_2009","numbers":["22.05"],"title":"Neutron Science and Reactor Physics","summary":"This course introduces fundamental properties of the neutron. It covers reactions induced by neutrons, nuclear fission, slowing down of neutrons in infinite media, diffusion theory, the few-group approximation, point kinetics, and fission-product poisoning. It emphasizes the nuclear physics bases of reactor design and its relationship to reactor engineering problems.","departments":["Nuclear Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Chemistry","Engineering","High Energy Physics","Nuclear Engineering","Nuclear Physics","Particle Physics","Physical Chemistry","Physics","Science"],"levels":["Undergraduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2009","instructors":["Prof. Benoit Forget"],"url":"https://ocw.mit.edu/courses/22-05-neutron-science-and-reactor-physics-fall-2009/","views":1735},{"id":"1.253J+spring_2004","numbers":["1.253J","11.543J","ESD.222J"],"title":"Transportation Policy and Environmental Limits","summary":"Through a combination of lectures, cases, and class discussions this subject examines the economic and political conflict between transportation and the environment. It investigates the role of government regulation, green business and transportation policy as facilitators of economic development and environmental sustainability. It analyzes a variety of international policy problems including government-business relations; the role of interest groups, non-governmental organizations, and the public and media in the regulation of the automobile; sustainable development; global warming; the politics of risk and siting of transport facilities; environmental justice; equity; and transportation and public health in the urban metropolis. It provides students with an opportunity to apply transportation and planning methods to developing policy alternatives in the context of environmental politics.","departments":["Civil and Environmental Engineering","Engineering Systems Division","Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math","Social Sciences"],"topics":["Civil Engineering","Earth Science","Engineering","Environmental Engineering","Environmental Policy","Environmental Science","Public Administration","Public Policy","Science","Social Science","Transportation Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2004","instructors":["Frederick Salvucci","Prof. Joseph Coughlin"],"url":"https://ocw.mit.edu/courses/1-253j-transportation-policy-and-environmental-limits-spring-2004/","views":1734},{"id":"6.945+spring_2009","numbers":["6.945"],"title":"Adventures in Advanced Symbolic Programming","summary":"This course covers concepts and techniques for the design and implementation of large software systems that can be adapted to uses not anticipated by the designer. Applications include compilers, computer-algebra systems, deductive systems, and some artificial intelligence applications. Topics include combinators, generic operations, pattern matching, pattern-directed invocation, rule systems, backtracking, dependencies, indeterminacy, memoization, constraint propagation, and incremental refinement. Substantial weekly programming assignments are an integral part of the subject.\n\nThere will be extensive programming assignments, using MIT/GNU Scheme. Students should have significant programming experience in Scheme, Common Lisp, Haskell, CAML or some other “functional” language.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Artificial Intelligence","Computer Science","Engineering","Programming Languages","Software Design and Engineering"],"levels":["Graduate"],"features":["Problem Sets","Projects"],"term":"Spring 2009","instructors":["Prof. Gerald Sussman"],"url":"https://ocw.mit.edu/courses/6-945-adventures-in-advanced-symbolic-programming-spring-2009/","views":1732},{"id":"WGS.S10+fall_2017","numbers":["WGS.S10"],"title":"History of Women in Science and Engineering","summary":"This course provides a basic overview of the history of women in science, technology, engineering, and mathematics (STEM). Students will learn about specific contributions of women across a variety of disciplines and will gain a broad perspective on how these contributions played a larger role in the advancement of human knowledge and technological achievement. The class will also grapple with how both historic and modern biases within the STEM disciplines, as well as in representations of women and girls in media and popular culture, can affect outcomes in these areas.","departments":["Women's and Gender Studies"],"areas":["Engineering","Humanities","Science & Math","Social Sciences"],"topics":["Engineering","Gender Studies","History","History of Science and Technology","Humanities","Science","Society","Women's Studies"],"levels":["Undergraduate"],"features":["Instructor Insights","Presentation Assignments","Written Assignments"],"term":"Fall 2017","instructors":["Maia Weinstock"],"url":"https://ocw.mit.edu/courses/wgs-s10-history-of-women-in-science-and-engineering-fall-2017/","views":1732},{"id":"21L.487+spring_2002","numbers":["21L.487"],"title":"Modern Poetry","summary":"This course considers some of the substantial early twentieth-century poetic voices in America. Authors vary, but may include Moore, Frost, Eliot, Stevens, and Pound.\n\nWe’ll read the major poems by the most important poets in English in the 20th century, emphazinig especially the period between post-WWI disillusionment and early WW II internationalism (ca. 1918-1940). Our special focus this term will be how the concept of “the Image” evolved during this period. The War had undercut beliefs in master-narratives of nationalism and empire, and the language-systems that supported them (religious transcendence, rationalism and formalism). Retrieving energies from the Symbolist movements of the preceding century, early 20th century poets began to rethink how images carry information, and in what ways the visual, visionary, and verbal image can take the place of transcendent beliefs. New theories of linguistics and anthropology helped to advance this interest in the artistic/religious image. So did Freud. So did Charlie Chaplin films.\n\nWe’ll read poems that pay attention both to this disillusionment and to the compensatory joyous attention to the image: to ideas of the poet-as-language-priest, aesthetic-experience-as-displaced-religious impulse, to poetry as faith, ritual, and form.","departments":["Literature"],"areas":["Humanities"],"topics":["American Literature","Criticism","Humanities","Literature","Poetry"],"levels":["Undergraduate"],"features":["Activity Assignments","Presentation Assignments","Written Assignments"],"term":"Spring 2002","instructors":["Prof. Stephen Tapscott"],"url":"https://ocw.mit.edu/courses/21l-487-modern-poetry-spring-2002/","views":1732},{"id":"24.946+fall_2004","numbers":["24.946"],"title":"Linguistic Theory and the Japanese Language","summary":"This course is a detailed examination of the grammar of Japanese and its structure which is significantly different from English, with special emphasis on problems of interest in the study of linguistic universals. Data from a broad group of languages is studied for comparison with Japanese. This course assumes familiarity with linguistic theory.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Japanese","Language","Linguistics"],"levels":["Undergraduate"],"features":["Lecture Notes","Presentation Assignments","Written Assignments"],"term":"Fall 2004","instructors":["Prof. Shigeru Miyagawa"],"url":"https://ocw.mit.edu/courses/24-946-linguistic-theory-and-the-japanese-language-fall-2004/","views":1730},{"id":"STS.350+spring_2004","numbers":["STS.350"],"title":"Social Study of Science and Technology","summary":"This course surveys canonical and recent theories and methods in science studies. We will organize our discussions around the concept of “reproduction,” referring variously to:\n\n• Scientific reproduction (how results are replicated in lab, field, disciplinary contexts)\n• Social reproduction (how social knowledge and relations are regenerated over time)\n• Biological reproduction (how organic substance is managed in the genetic age)\n• Electronic reproduction (how information is reassembled in techniques of transcription, simulation, computation).\n\nExamining intersections and disruptions of these genres of reproduction, we seek to map relations among our social, biological, and electronic lives.","departments":["Science, Technology, and Society"],"areas":["Humanities","Social Sciences"],"topics":["History","History of Science and Technology","Humanities","Philosophy","Social Science","Sociology"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2004","instructors":["Prof. Stefan Helmreich"],"url":"https://ocw.mit.edu/courses/sts-350-social-study-of-science-and-technology-spring-2004/","views":1730},{"id":"24.949+fall_2020","numbers":["24.949"],"title":"Language Acquisition I","summary":"This course focuses on the process by which native speakers of a language acquire the ability to speak and understand that language. It covers some of the major results in the study of first-language acquisition, concentrating on morpho-syntax, semantics, and pragmatics. The findings primarily come from English, but cross-linguistic differences in the phenomena of interest and corresponding differences in acquisition patterns are considered where appropriate. Of interest throughout is how these developmental data inform linguistic theory and/or learnability theory.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2020","instructors":["Prof. Athulya Aravind"],"url":"https://ocw.mit.edu/courses/24-949-language-acquisition-i-fall-2020/","views":1729},{"id":"STS.035+spring_2004","numbers":["STS.035"],"title":"The History of Computing","summary":"This course focuses on one particular aspect of the history of computing: the use of the computer as a scientific instrument. The electronic digital computer was invented to do science, and its applications range from physics to mathematics to biology to the humanities. What has been the impact of computing on the practice of science? Is the computer different from other scientific instruments? Is computer simulation a valid form of scientific experiment? Can computer models be viewed as surrogate theories? How does the computer change the way scientists approach the notions of proof, expertise, and discovery? No comprehensive history of scientific computing has yet been written. This seminar examines scientific articles, participants’ memoirs, and works by historians, sociologists, and anthropologists of science to provide multiple perspectives on the use of computers in diverse fields of physical, biological, and social sciences and the humanities. We explore how the computer transformed scientific practice, and how the culture of computing was influenced, in turn, by scientific applications.","departments":["Science, Technology, and Society"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Humanities"],"topics":["Computer Science","Engineering","History","History of Science and Technology","Humanities","Modern History"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2004","instructors":["Dr. Slava Gerovitch"],"url":"https://ocw.mit.edu/courses/sts-035-the-history-of-computing-spring-2004/","views":1729},{"id":"11.479J+spring_2007","numbers":["11.479J","1.851J"],"title":"Water and Sanitation Infrastructure in Developing Countries","summary":"This course deals with the principles of infrastructure planning in developing countries, with a focus on appropriate and sustainable technologies for water and sanitation. It also incorporates technical, socio-cultural, public health, and economic factors into the planning and design of water and sanitation systems. Upon completion, students will be able to plan simple, yet reliable, water supply and sanitation systems for developing countries that are compatible with local customs and available human and material resources. Graduate and upper division students from any department who are interested in international development at the grassroots level are encouraged to participate in this interdisciplinary subject.\n\nAcknowledgment\n\nThis course was jointly developed by Earthea Nance and Susan Murcott in Spring 2006.","departments":["Civil and Environmental Engineering","Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Engineering","Health & Medicine","Social Sciences"],"topics":["Aquatic Sciences and Water Quality Control","Engineering","Environmental Engineering","Environmental Management","Environmental Policy","Health and Medicine","Hydrology and Water Resource Systems","Public Administration","Public Health","Regional Planning","Social Science","Society","The Developing World","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Written Assignments"],"term":"Spring 2007","instructors":["Susan Murcott"],"url":"https://ocw.mit.edu/courses/11-479j-water-and-sanitation-infrastructure-in-developing-countries-spring-2007/","views":1728},{"id":"ESD.141+spring_2006","numbers":["ESD.141"],"title":"Technology Policy Negotiations","summary":"This course features a core framework for an interest-based, problem-solving approach to technology, logistics and other systems-oriented negotiations. A comprehensive approach to dispute resolution in organizations and complex engineered systems is also developed. The course builds key interactive skills, including communications skills, dealing with difficult people, negotiating over the “rules of game,” and cross-cultural negotiations. Assignments center on analysis of negotiated interactions and assessing dispute resolution systems.","departments":["Engineering Systems Division"],"areas":["Business & Management","Engineering","Social Sciences"],"topics":["Business","Engineering","Organizational Behavior","Public Administration","Science and Technology Policy","Social Science","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2006","instructors":["Prof. Joel Cutcher-Gershenfeld"],"url":"https://ocw.mit.edu/courses/esd-141-technology-policy-negotiations-spring-2006/","views":1726},{"id":"6.050J+spring_2008","numbers":["6.050J","2.110J"],"title":"Information and Entropy","summary":"This course explores the ultimate limits to communication and computation, with an emphasis on the physical nature of information and information processing. Topics include: information and computation, digital signals, codes and compression, applications such as biological representations of information, logic circuits, computer architectures, and algorithmic information, noise, probability, error correction, reversible and irreversible operations, physics of computation, and quantum computation. The concept of entropy is applied to channel capacity and to the second law of thermodynamics.","departments":["Electrical Engineering and Computer Science","Mechanical Engineering"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Computation","Computer Science","Electrical Engineering","Engineering","Mathematics","Signal Processing","Theory of Computation"],"levels":["Undergraduate"],"features":["Open Textbooks","Problem Set Solutions","Problem Sets","Programming Assignments"],"term":"Spring 2008","instructors":["Prof. Paul Penfield","Prof. Seth Lloyd"],"url":"https://ocw.mit.edu/courses/6-050j-information-and-entropy-spring-2008/","views":1725},{"id":"STS.069+fall_2002","numbers":["STS.069"],"title":"Technology in a  Dangerous World","summary":"Aim is to analyze important current events for what they reveal about the nature and working of our technological world. Starting point is connection between technology and terrorism. Subject also explores how a human-built world can foster insecurity and danger, and how human beings respond. Many invited guests help develop a strong interdisciplinary approach (science, engineering, social science, humanities). Topics include technological risk and remediation, sociotechnical systems, imagination of disaster, technology and identity, technology and religion, technology and education, and technology and trust. Written and oral assignments and a final project required. Service-learning proposals and web-based presentations, in addition to written work, may be considered for the final project by the instructor.","departments":["Science, Technology, and Society"],"areas":["Social Sciences"],"topics":["Public Administration","Science and Technology Policy","Security Studies","Social Science","Sociology"],"levels":["Undergraduate"],"features":["Projects with Examples","Workshop Videos","Written Assignments"],"term":"Fall 2002","instructors":["Prof. Rosalind Williams"],"url":"https://ocw.mit.edu/courses/sts-069-technology-in-a-dangerous-world-fall-2002/","views":1724},{"id":"4.303+fall_2003","numbers":["4.303"],"title":"Dialogue in Art, Architecture, and Urbanism","summary":"In this class we will examine how the idea of the city has been “translated” by artists, architects, and other diverse disciplines. We will consider how collaborations between artists and architects might provide opportunities for rethinking / redesigning urban spaces. The class will look specifically at planned cities like Brasilia, Las Vegas, Canberra, and Celebration and compare such tabula rasa designs with the redesign of recyclable urban spaces demonstrated in projects such as Ground Zero, Barcelona 2004, and Boston’s Rose Kennedy Greenway. While the course will involve some reading and discussion, coursework will focus largely on the students’ own projects / interventions that should evolve over the course of the semester. Of the two weekly class meetings, one will be a group discussion or lecture with the whole class and visiting guests, and the other will be an individual meeting between the student and the instructor to discuss his or her work for the class, including the final project.","departments":["Architecture"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Architecture","Environmental Design","Fine Arts","Social Science","Urban Studies","Visual Arts"],"levels":["Graduate"],"features":["Other Video","Projects with Examples"],"term":"Fall 2003","instructors":["Prof. Antonio Muntadas"],"url":"https://ocw.mit.edu/courses/4-303-dialogue-in-art-architecture-and-urbanism-fall-2003/","views":1721},{"id":"18.098+january-iap_2008","numbers":["18.098","6.099"],"title":"Street-Fighting Mathematics","summary":"This course teaches the art of guessing results and solving problems without doing a proof or an exact calculation. Techniques include extreme-cases reasoning, dimensional analysis, successive approximation, discretization, generalization, and pictorial analysis. Applications include mental calculation, solid geometry, musical intervals, logarithms, integration, infinite series, solitaire, and differential equations. (No epsilons or deltas are harmed by taking this course.) This course is offered during the Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month.","departments":["Electrical Engineering and Computer Science","Mathematics"],"areas":["Science & Math"],"topics":["Calculus","Computation","Mathematical Analysis","Mathematics"],"levels":["Undergraduate"],"features":["Open Textbooks","Problem Set Solutions","Problem Sets"],"term":"January IAP 2008","instructors":["Sanjoy Mahajan"],"url":"https://ocw.mit.edu/courses/18-098-street-fighting-mathematics-january-iap-2008/","views":1720},{"id":"18.369+spring_2008","numbers":["18.369"],"title":"Mathematical Methods in Nanophotonics","summary":"Find out what solid-state physics has brought to Electromagnetism in the last 20 years. This course surveys the physics and mathematics of nanophotonics—electromagnetic waves in media structured on the scale of the wavelength.\n\nTopics include computational methods combined with high-level algebraic techniques borrowed from solid-state quantum mechanics: linear algebra and eigensystems, group theory, Bloch’s theorem and conservation laws, perturbation methods, and coupled-mode theories, to understand surprising optical phenomena from band gaps to slow light to nonlinear filters.\n\nNote: An earlier version of this course was published on OCW as 18.325 Topics in Applied Mathematics: Mathematical Methods in Nanophotonics, Fall 2005.","departments":["Mathematics"],"areas":["Engineering","Science & Math"],"topics":["Applied Mathematics","Atomic, Molecular, Optical Physics","Engineering","Linear Algebra","Mathematics","Nanotechnology","Physics","Quantum Mechanics","Science"],"levels":["Graduate"],"features":["Exams","Problem Sets"],"term":"Spring 2008","instructors":["Prof. Steven G. Johnson"],"url":"https://ocw.mit.edu/courses/18-369-mathematical-methods-in-nanophotonics-spring-2008/","views":1719},{"id":"18.086+spring_2006","numbers":["18.086"],"title":"Mathematical Methods for Engineers II","summary":"This graduate-level course is a continuation of Mathematical Methods for Engineers I (18.085). Topics include numerical methods; initial-value problems; network flows; and optimization.","departments":["Mathematics"],"areas":["Engineering","Science & Math"],"topics":["Applied Mathematics","Computational Science and Engineering","Differential Equations","Engineering","Linear Algebra","Mathematics","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Videos","Problem Set Solutions","Problem Sets","Projects with Examples"],"term":"Spring 2006","instructors":["Prof. Gilbert Strang"],"url":"https://ocw.mit.edu/courses/18-086-mathematical-methods-for-engineers-ii-spring-2006/","views":1706},{"id":"21A.461+fall_2021","numbers":["21A.461"],"title":"What is Capitalism?","summary":"This course introduces academic debates on the nature of capitalism, drawing upon the ideas of scholars as diverse as Adam Smith and Karl Marx. It examines anthropological studies of how contemporary capitalism plays out in people’s daily lives in a range of geographic and social settings, and implications for how we understand capitalism today. Settings range from Wall Street investment banks to auto assembly plants, from family businesses to consumer shopping malls.","departments":["Anthropology"],"areas":["Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Ethnography","Social Anthropology","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Readings","Written Assignments"],"term":"Fall 2021","instructors":["Prof. Christine Walley"],"url":"https://ocw.mit.edu/courses/21a-461-what-is-capitalism-fall-2021/","views":1705},{"id":"2.067+spring_2004","numbers":["2.067"],"title":"Advanced Structural Dynamics and Acoustics (13.811)","summary":"This course begins with the foundations of 3D elasticity, fluid and elastic wave equations, elastic and plastic waves in rods and beams, waves in plates, and dynamics and acoustics of cylindrical shells. The course considers acoustic fluids effects such as radiation and scattering by submerged plates and shells, and interaction between structural elements. Finally, it covers the response of plates and shells to high-intensity loads, dynamic plasticity and fracture, and structural damage caused by implosive and impact loads.\n\nThis course was originally offered in Course 13 (Department of Ocean Engineering) as 13.811. In 2005, ocean engineering subjects became part of Course 2 (Department of Mechanical Engineering), and this course was renumbered 2.067.","departments":["Mechanical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Engineering","Fluid Mechanics","Mechanical Engineering","Ocean Engineering","Ocean Structures","Physics","Quantum Mechanics","Science","Solid Mechanics"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2004","instructors":["Dr. David Battle","Prof. Henrik Schmidt","Prof. Tomasz Wierzbicki"],"url":"https://ocw.mit.edu/courses/2-067-advanced-structural-dynamics-and-acoustics-13-811-spring-2004/","views":1704},{"id":"18.156+spring_2016","numbers":["18.156"],"title":"Differential Analysis II: Partial Differential Equations and Fourier Analysis","summary":"In this course, we study elliptic Partial Differential Equations (PDEs) with variable coefficients building up to the minimal surface equation. Then we study Fourier and harmonic analysis, emphasizing applications of Fourier analysis. We will see some applications in combinatorics / number theory, like the Gauss circle problem, but mostly focus on applications in PDE, like the Calderon-Zygmund inequality for the Laplacian, and the Strichartz inequality for the Schrodinger equation. In the last part of the course, we study solutions to the linear and the non-linear Schrodinger equation. All through the course, we work on the craft of proving estimates.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Differential Equations","Mathematical Analysis","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2016","instructors":["Prof. Lawrence D Guth"],"url":"https://ocw.mit.edu/courses/18-156-differential-analysis-ii-partial-differential-equations-and-fourier-analysis-spring-2016/","views":1704},{"id":"21H.245J+spring_2016","numbers":["21H.245J","17.57J","21G.086J"],"title":"Soviet and Post-Soviet Politics and Society, 1917 to the Present","summary":"This course explores the political and historical evolution of the Soviet state and society from the 1917 Revolution to the present. It covers the creation of a revolutionary regime, causes and nature of the Stalin revolution, post-Stalinist efforts to achieve political and social reform, and causes of the Soviet collapse. It also examines current developments in Russia in light of Soviet history.","departments":["Global Studies and Languages","History","Political Science"],"areas":["Humanities","Social Sciences"],"topics":["European History","European and Russian Studies","History","Humanities","Military History","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2016","instructors":["Prof. Elizabeth A. Wood"],"url":"https://ocw.mit.edu/courses/21h-245j-soviet-and-post-soviet-politics-and-society-1917-to-the-present-spring-2016/","views":1704},{"id":"17.20+fall_2020","numbers":["17.20"],"title":"Introduction to the American Political Process","summary":"This course provides a substantive overview of U.S. politics and an introduction to the discipline of political science. It surveys the institutional foundations of U.S. politics as well as the activities of political elites, organizations, and ordinary citizens. It explores the application of general political science concepts and analytic frameworks to specific episodes and phenomena in U.S. politics.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Written Assignments with Examples"],"term":"Fall 2020","instructors":["Prof. Asya Magazinnik","Zeyu Chris Peng"],"url":"https://ocw.mit.edu/courses/17-20-introduction-to-the-american-political-process-fall-2020/","views":1703},{"id":"18.156+spring_2004","numbers":["18.156"],"title":"Differential Analysis","summary":"The main goal of this course is to give the students a solid foundation in the theory of elliptic and parabolic linear partial differential equations. It is the second semester of a two-semester, graduate-level sequence on Differential Analysis.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Differential Equations","Mathematical Analysis","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes","Presentation Assignments"],"term":"Spring 2004","instructors":["Prof. Jeff Viaclovsky"],"url":"https://ocw.mit.edu/courses/18-156-differential-analysis-spring-2004/","views":1699},{"id":"MAS.878+fall_2003","numbers":["MAS.878","MAS.478"],"title":"Special Topics in Multimedia Production: Experiences in Interactive Art","summary":"This class deals with interactive art. Visiting artists will discuss their work from a theoretical and practical perspective. Discussions of the history of interactive digital art and contemporary issues in the field will take place. Students will develop an interactive art project for a final exhibition or submit a short paper.","departments":["Media Arts and Sciences"],"areas":["Art, Design & Architecture"],"topics":["Digital Media","Fine Arts","Media Studies"],"levels":["Graduate"],"features":[],"term":"Fall 2003","instructors":["Prof. Glorianna Davenport","Prof. Stephen Benton","Ali Mazalek"],"url":"https://ocw.mit.edu/courses/mas-878-special-topics-in-multimedia-production-experiences-in-interactive-art-fall-2003/","views":1699},{"id":"21H.326+spring_1998","numbers":["21H.326"],"title":"The Making of Russia in the Worlds of Byzantium, Mongolia, and Europe","summary":"Medieval and early modern Russia stood at the crossroads of Europe and Asia. In this course we will examine some of the native developments and foreign influences which most affected the course of Russian history. Particular topics include the rise of the Kievan State, the Mongol Yoke, the rise of Muscovy, Ivan the Terrible, Peter the Great, relations with Western Europe. How did foreigners perceive Russia? How did those living in the Russian lands perceive foreigners? What social relations were developing between nobility and peasantry, town and country, women and men? What were the relations of each of these groups to the state? How did state formation come about in Kievan and Muscovite Russia? What were the political, religious, economic, and social factors affecting relations between state and society? In examining these questions we will consider a variety of sources including contemporary accounts (both domestic and foreign), legal and political documents, historical monographs and interpretive essays.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Asian History","Cultural Anthropology","European History","European and Russian Studies","History","Humanities","Philosophy","Political Philosophy","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 1998","instructors":["Prof. Elizabeth A. Wood"],"url":"https://ocw.mit.edu/courses/21h-326-the-making-of-russia-in-the-worlds-of-byzantium-mongolia-and-europe-spring-1998/","views":1699},{"id":"11.S940+fall_2015","numbers":["11.S940"],"title":"Development, Planning, and Implementation: The Dialectic of Theory and Practice","summary":"This is an advanced seminar that will analyze the effectiveness of development and planning theories from the perspective of practitioners who implement projects and policies based on such theories. The ultimate goal is to create new planning sensibilities, which theorize from practice, not the other way around.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Public Administration","Regional Planning","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Fall 2015","instructors":["Prof. Bishwapriya Sanyal","Cauam Ferreira Cardoso"],"url":"https://ocw.mit.edu/courses/11-s940-development-planning-and-implementation-the-dialectic-of-theory-and-practice-fall-2015/","views":1698},{"id":"21A.112+spring_2008","numbers":["21A.112"],"title":"Seminar in Ethnography and Fieldwork","summary":"This advanced course in anthropology engages closely with discussions and debates about ethnographic research, ethics, and representation.","departments":["Anthropology"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Ethics","Ethnography","Humanities","Philosophy","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2008","instructors":["Prof. Stefan Helmreich"],"url":"https://ocw.mit.edu/courses/21a-112-seminar-in-ethnography-and-fieldwork-spring-2008/","views":1698},{"id":"2.068+spring_2003","numbers":["2.068"],"title":"Computational Ocean Acoustics (13.853)","summary":"This course examines wave equations for fluid and visco-elastic media, wave-theory formulations of acoustic source radiation and seismo-acoustic propagation in stratified ocean waveguides, and Wavenumber Integration and Normal Mode methods for propagation in plane-stratified media. Also covered are Seismo-Acoustic modeling of seabeds and ice covers, seismic interface and surface waves in a stratified seabed, Parabolic Equation and Coupled Mode approaches to propagation in range-dependent ocean waveguides, numerical modeling of target scattering and reverberation clutter in ocean waveguides, and ocean ambient noise modeling. Students develop propagation models using all the numerical approaches relevant to state-of-the-art acoustic research.\n\nThis course was originally offered in Course 13 (Department of Ocean Engineering) as 13.853. In 2005, ocean engineering subjects became part of Course 2 (Department of Mechanical Engineering), and this course was renumbered 2.068.","departments":["Mechanical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Computational Modeling and Simulation","Earth Science","Engineering","Fluid Mechanics","Geophysics","Hydrodynamics","Mechanical Engineering","Ocean Engineering","Physics","Quantum Mechanics","Science","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2003","instructors":["Prof. Henrik Schmidt"],"url":"https://ocw.mit.edu/courses/2-068-computational-ocean-acoustics-13-853-spring-2003/","views":1697},{"id":"24.209+spring_2004","numbers":["24.209"],"title":"Philosophy In Film and Other Media","summary":"This course examines works of film in relation to thematic issues of philosophical importance that also occur in other arts, particularly literature and opera. Emphasis is put on film’s ability to represent and express feeling as well as cognition. Both written and cinematic works by Sturges, Shaw, Cocteau, Hitchcock, Joyce, and Bergman, among others, are considered. There are no tests or quizzes, however students write two major papers on media/philosophical research topics of their choosing.","departments":["Linguistics and Philosophy"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Film and Video","Fine Arts","Humanities","Literature","Media Studies","Philosophy","Visual Arts"],"levels":["Undergraduate"],"features":["Lecture Videos","Written Assignments with Examples"],"term":"Spring 2004","instructors":["Prof. Irving Singer"],"url":"https://ocw.mit.edu/courses/24-209-philosophy-in-film-and-other-media-spring-2004/","views":1697},{"id":"14.472+spring_2004","numbers":["14.472"],"title":"Public Economics II","summary":"This course covers theory and evidence on government expenditure policy– topics include: The theory of public goods; Education; State and local public goods; Political economy; Redistribution and welfare policy; Social insurance programs such as social security and unemployment insurance; and Health care policy.","departments":["Economics"],"areas":["Social Sciences"],"topics":["Economics","Political Economy","Public Administration","Public Economics","Public Policy","Social Science","Social Welfare"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2004","instructors":["Prof. Jonathan Gruber","Prof. Peter Diamond"],"url":"https://ocw.mit.edu/courses/14-472-public-economics-ii-spring-2004/","views":1695},{"id":"6.432+spring_2004","numbers":["6.432"],"title":"Stochastic Processes, Detection, and Estimation","summary":"This course examines the fundamentals of detection and estimation for signal processing, communications, and control. Topics covered include: vector spaces of random variables; Bayesian and Neyman-Pearson hypothesis testing; Bayesian and nonrandom parameter estimation; minimum-variance unbiased estimators and the Cramer-Rao bounds; representations for stochastic processes, shaping and whitening filters, and Karhunen-Loeve expansions; and detection and estimation from waveform observations. Advanced topics include: linear prediction and spectral estimation, and Wiener and Kalman filters.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering","Science & Math"],"topics":["Applied Mathematics","Electrical Engineering","Engineering","Mathematics","Probability and Statistics","Signal Processing"],"levels":["Graduate"],"features":[],"term":"Spring 2004","instructors":["Prof. Gregory Wornell","Prof. Alan Willsky"],"url":"https://ocw.mit.edu/courses/6-432-stochastic-processes-detection-and-estimation-spring-2004/","views":1695},{"id":"18.315+spring_2005","numbers":["18.315"],"title":"Combinatorial Theory: Introduction to Graph Theory, Extremal and Enumerative Combinatorics","summary":"This course serves as an introduction to major topics of modern enumerative and algebraic combinatorics with emphasis on partition identities, young tableaux bijections, spanning trees in graphs, and random generation of combinatorial objects. There is some discussion of various applications and connections to other fields.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Discrete Mathematics","Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Problem Sets"],"term":"Spring 2005","instructors":["Prof. Igor Pak"],"url":"https://ocw.mit.edu/courses/18-315-combinatorial-theory-introduction-to-graph-theory-extremal-and-enumerative-combinatorics-spring-2005/","views":1694},{"id":"3.054+spring_2015","numbers":["3.054","3.36"],"title":"Cellular Solids: Structure, Properties and Applications","summary":"This course reviews the processing and structure of cellular materials as they are created from polymers, metals, ceramics, glasses, and composites, develops models for the mechanical behavior of cellular solids, and shows how the unique properties of honeycombs and foams are exploited in applications such as lightweight structural panels, energy absorption devices and thermal insulation. The applications of cellular solids in medicine include increased fracture risk due to trabecular bone loss in patients with osteoporosis, the development of metal foam coatings for orthopaedic implants, and designing porous scaffolds for tissue engineering that mimic the extracellular matrix. Modelling of cellular materials applied to natural materials and biomimicking is explored. Students taking the graduate version of the class are required to complete additional assignments.","departments":["Materials Science and Engineering"],"areas":["Engineering"],"topics":["Biological Engineering","Cell and Tissue Engineering","Engineering","Materials Science and Engineering","Mechanical Engineering"],"levels":["Undergraduate","Graduate"],"features":["Instructor Insights","Lecture Notes","Lecture Videos","Other Video","Projects with Examples"],"term":"Spring 2015","instructors":["Lorna Gibson"],"url":"https://ocw.mit.edu/courses/3-054-cellular-solids-structure-properties-and-applications-spring-2015/","views":1692},{"id":"2.18+spring_2015","numbers":["2.18","2.180"],"title":"Biomolecular Feedback Systems","summary":"This course focuses on feedback control mechanisms that living organisms implement at the molecular level to execute their functions, with emphasis on techniques to design novel systems with prescribed behaviors. Students will learn how biological functions can be understood and designed using notions from feedback control.","departments":["Mechanical Engineering"],"areas":["Business & Management","Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Computation and Systems Biology","Computational Biology","Dynamics and Control","Engineering","Mechanical Engineering","Molecular Biology","Science","Synthetic Biology","Systems Design","Systems Engineering"],"levels":["Undergraduate"],"features":["Problem Sets","Projects"],"term":"Spring 2015","instructors":["Domitilla Del Vecchio"],"url":"https://ocw.mit.edu/courses/2-18-biomolecular-feedback-systems-spring-2015/","views":1690},{"id":"17.200+fall_2016","numbers":["17.200"],"title":"Graduate Seminar in American Politics I: Political Behavior","summary":"This graduate-level course focuses on mass political behavior within the American political system. The goal of this course is to give an introduction to some of the major questions in the study of American political behavior, and how people have gone about answering them. The background goal is to help students practice reading work critically, and thinking through the difficulties of social science research, in preparation for individual research projects. The course examines political ideology, public opinion, voting behavior, media effects, racial attitudes, mass-elite relations, and opinion-policy linkages.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","Political Science","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2016","instructors":["Prof. Ariel White"],"url":"https://ocw.mit.edu/courses/17-200-graduate-seminar-in-american-politics-i-political-behavior-fall-2016/","views":1690},{"id":"17.436+fall_2004","numbers":["17.436"],"title":"Territorial Conflict","summary":"This graduate seminar introduces an emerging research program within International Relations on territorial conflict. While scholars have recognized that territory has been one of the most frequent issues over which states go to war, territorial conflicts have only recently become the subject of systematic study. This course will examine why territorial conflicts arise in the first place, why some of these conflicts escalate to high levels of violence and why other territorial disputes reach settlement, thereby reducing the likelihood of war. Readings in the course draw upon political geography and history as well as qualitative and quantitative approaches to political science.","departments":["Political Science"],"areas":["Humanities","Social Sciences"],"topics":["History","Humanities","International Relations","Military History","Military Studies","Political Science","Public Administration","Security Studies","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. M. Taylor Fravel"],"url":"https://ocw.mit.edu/courses/17-436-territorial-conflict-fall-2004/","views":1690},{"id":"2.24+spring_2002","numbers":["2.24"],"title":"Ocean Wave Interaction with Ships and Offshore Energy Systems (13.022)","summary":"The subject introduces the principles of ocean surface waves and their interactions with ships, offshore platforms and advanced marine vehicles. Surface wave theory is developed for linear and nonlinear deterministic and random waves excited by the environment, ships, or floating structures.\n\nFollowing the development of the physics and mathematics of surface waves, several applications from the field of naval architecture and offshore engineering are addressed. They include the ship Kelvin wave pattern and wave resistance, the interaction of surface waves with floating bodies, the seakeeping of ships high-speed vessels and offshore platforms, the evaluation of the drift forces and other nonlinear wave effects responsible for the slow-drift responses of compliant offshore platforms and their mooring systems designed for hydrocarbon recovery from large water depths.\n\nThis course was originally offered in Course 13 (Department of Ocean Engineering) as 13.022. In 2005, ocean engineering subjects became part of Course 2 (Department of Mechanical Engineering), and this course was renumbered 2.24.","departments":["Mechanical Engineering"],"areas":["Energy, Climate & Sustainability","Engineering"],"topics":["Civil Engineering","Energy","Engineering","Environmental Engineering","Fossil Fuels","Hydrodynamics","Hydrodynamics and Coastal Engineering","Mechanical Design","Mechanical Engineering","Ocean Engineering","Ocean Structures","Renewables","Structural Engineering"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Sets"],"term":"Spring 2002","instructors":["Prof. Paul D. Sclavounos"],"url":"https://ocw.mit.edu/courses/2-24-ocean-wave-interaction-with-ships-and-offshore-energy-systems-13-022-spring-2002/","views":1689},{"id":"21H.009+spring_2014","numbers":["21H.009"],"title":"The World: 1400-Present","summary":"This course surveys the increasing interaction between communities, as the barrier of distance succumbed to both curiosity and new transport technologies. It explores Western Europe and the United States’ rise to world dominance, as well as the great divergence in material, political, and technological development between Western Europe and East Asia post–1750, and its impact on the rest of the world. It examines a series of evolving relationships, including human beings and their physical environment; religious and political systems; and sub-groups within communities, sorted by race, class, and gender. It introduces historical and other interpretive methodologies using both primary and secondary source materials.","departments":["History"],"areas":["Humanities"],"topics":["History","Humanities","World History"],"levels":["Undergraduate"],"features":["Activity Assignments","Lecture Notes","Written Assignments"],"term":"Spring 2014","instructors":["Prof. Anne McCants","Prof. Jeffrey S. Ravel"],"url":"https://ocw.mit.edu/courses/21h-009-the-world-1400-present-spring-2014/","views":1689},{"id":"RES.9-010+fall_2025","numbers":["RES.9-010"],"title":"Brain and Cognitive Sciences Computational Tutorial: Optimizing the Full Stack for Generative Image and Video Models","summary":"This tutorial covers optimization strategies for diffusion models used in image and video generation; topics include architecture design, hardware efficiency, and inference techniques. Speaker: Sayak Paul, Hugging Face.\n\nThis tutorial is part of a seminar series led by graduate students and postdocs in the MIT Department of Brain and Cognitive Sciences (BCS) from 2015 to the present, featuring topics relevant to research on intelligence in neuroscience, cognitive science, and artificial intelligence. The tutorials are aimed at participants who have some computational background but are not experts on these topics.\n\nThis series was organized by Sol Markman and Ajani Stewart, graduate students in the Department of Brain and Cognitive Sciences.","departments":["Brain and Cognitive Sciences"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Artificial Intelligence","Cognitive Science","Computer Science","Engineering","Science"],"levels":["Non-Credit"],"features":["Tutorial Videos"],"term":"Fall 2025","instructors":[],"url":"https://ocw.mit.edu/courses/res-9-010-bcs-tutorials-optimizing-the-full-stack-for-generative-image-and-video-models-fall-2025/","views":1688},{"id":"RES.HSO-001","numbers":["RES.HSO-001"],"title":"MIT Haystack Observatory K–12 STEM Lesson Plans","summary":"At the MIT Haystack Observatory, researchers use several basic science concepts every day. Electromagnetic waves, optics, and molecular chemistry are just a few of the core topics that can be incorporated into the high school science curriculum by exploring the atmosphere and the universe with lessons focused around the research specialties at Haystack.\n\nThe original material presented here was developed by teachers, with the assistance of the staff at Haystack. All lesson plans have been successfully used in high school classrooms. These lessons have been prepared with specific attention to the goals and objectives of current science curricula. The object is to create lessons that will enhance your class, not require you to add substantial material.\n\nThe development of these educational materials at the Haystack Observatory was funded by the National Science Foundation under the Research Experiences for Teachers (RET) program.","departments":[],"areas":["Education & Teaching"],"topics":["Curriculum and Teaching","Teaching and Education"],"levels":["High School"],"features":["Activity Assignments","Lecture Notes","Projects"],"term":"","instructors":[],"url":"https://ocw.mit.edu/courses/res-hso-001-mit-haystack-observatory-k12-stem-lesson-plans/","views":1686},{"id":"2.996+fall_2003","numbers":["2.996"],"title":"Sailing Yacht Design (13.734)","summary":"This subject teaches students, having an initial interest in sailing design, how to design good yachts. Topics covered include hydrostatics, transverse stability, and the incorporation of the design spiral into one’s working methods. Computer aided design (CAD) is used to design the shapes of hulls, appendages and decks, and is an important part of this course. The capstone project in this course is the Final Design Project in which each student designs a sailing yacht, complete in all major respects.\n\nThe central material for this subject is the content of the book Principals of Yacht Design by Larssson and Eliasson (see further description in the syllabus). All the class lectures are based on the material in this book. The figures in the book which are shown in class (but not reproduced on this site), contain the essential material and their meaning is explained in detail during the lecture sessions. Mastery of the material in the book and completing a design project provides the desired and needed education.\n\nThis course was originally offered in Course 13 (Department of Ocean Engineering) as 13.734. In 2005, ocean engineering subjects became part of Course 2 (Department of Mechanical Engineering), and this course was renumbered 2.996.","departments":["Mechanical Engineering"],"areas":["Engineering"],"topics":["Engineering","Mechanical Design","Mechanical Engineering","Ocean Engineering"],"levels":["Graduate"],"features":["Exams","Problem Sets"],"term":"Fall 2003","instructors":["Prof. Jerome Milgram"],"url":"https://ocw.mit.edu/courses/2-996-sailing-yacht-design-13-734-fall-2003/","views":1682},{"id":"17.202+spring_2010","numbers":["17.202"],"title":"Graduate Seminar in American Politics II","summary":"This is the second in a sequence of two field seminars in American politics intended for graduate students in political science, in preparation for taking the general examination in American politics. The material covered in this semester focuses on American political institutions. The readings covered here are not comprehensive, but it is sufficiently broad to give students an introduction to major empirical questions and theoretical approaches that guide the study of American political institutions these days.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","Political Science","Social Science"],"levels":["Graduate"],"features":["Projects with Examples","Written Assignments with Examples"],"term":"Spring 2010","instructors":["Prof. Charles Stewart"],"url":"https://ocw.mit.edu/courses/17-202-graduate-seminar-in-american-politics-ii-spring-2010/","views":1681},{"id":"21G.011+fall_2006","numbers":["21G.011"],"title":"Topics in Indian Popular Culture: Spectacle, Masala, and Genre","summary":"This course aims to provide an overview of Indian popular culture over the last two decades, through a variety of material such as popular fiction, music, television and Bombay cinema. The class will explore major themes and their representations in relation to current social and political issues. In particular, students will examine the elements of the formulaic “masala movie”, music and melodrama, the ideas of nostalgia and incumbent change in youth culture, as well as shifting questions of gender and sexuality in popular fiction. During the course, students will look at some journalistic writing, advertising clips and political cartoons to understand the relation between the popular culture and the social imagery of a nation. This course is taught in English.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Asian Studies","Cultural Anthropology","Film and Video","Fine Arts","Humanities","International Literature","Literature","Media Studies","Social Science","Society","Visual Arts"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2006","instructors":["Arundhati Banerjee"],"url":"https://ocw.mit.edu/courses/21g-011-topics-in-indian-popular-culture-spectacle-masala-and-genre-fall-2006/","views":1681},{"id":"3.20+fall_2003","numbers":["3.20"],"title":"Materials at Equilibrium (SMA 5111)","summary":"Material covered in this course includes the following topics:\n\n• Laws of thermodynamics: general formulation and applications to mechanical, electromagnetic and electrochemical systems, solutions, and phase diagrams\n• Computation of phase diagrams\n• Statistical thermodynamics and relation between microscopic and macroscopic properties, including ensembles, gases, crystal lattices, phase transitions\n• Applications to phase stability and properties of mixtures\n• Computational modeling\n• Interfaces\n\nThis course was also taught as part of the Singapore-MIT Alliance (SMA) programme as course number SMA 5111 (Materials at Equilibrium).","departments":["Materials Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Engineering","Materials Science and Engineering","Physics","Science","Thermodynamics"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Problem Set Solutions","Problem Sets"],"term":"Fall 2003","instructors":["Prof. Gerbrand Ceder","Dr. Anton Van der Ven"],"url":"https://ocw.mit.edu/courses/3-20-materials-at-equilibrium-sma-5111-fall-2003/","views":1680},{"id":"RES.14-004+january-iap_2026","numbers":["RES.14-004"],"title":"Seven Questions About Tariffs That Everyone Should Know the Answer To","summary":"It is hard to predict what US tariffs will look like in a few months, or even in a few weeks from now. But there are many questions about tariffs that can be answered through a combination of theory and data. This lecture discusses seven such questions that everyone should know the answers to. This talk was given during MIT’s Independent Activities Period in January 2026.","departments":[],"areas":["Social Sciences"],"topics":["Economics","Financial Economics","Political Economy","Social Science"],"levels":["Non-Credit"],"features":["Lecture Notes","Lecture Videos"],"term":"January IAP 2026","instructors":["Prof. Arnaud Costinot"],"url":"https://ocw.mit.edu/courses/res-14-004-seven-questions-about-tariffs-that-everyone-should-know-the-answer-to-january-iap-2026/","views":1678},{"id":"21H.983J+fall_2020","numbers":["21H.983J","21H.109J","WGS.310J","WGS.303J"],"title":"Gender: Historical Perspectives","summary":"This course examines the definition of gender in scientific, societal, and historical contexts. It explores how gender influences state formation and the work of the state, what role gender plays in imperialism and in the welfare state, the ever-present relationship between gender and war, and different states’ regulation of the body in gendered ways at different times. It also investigates new directions in the study of gender as historians, anthropologists and others have taken on this fascinating set of problems. Students taking the graduate version complete additional assignments.","departments":["History","Women's and Gender Studies"],"areas":["Humanities","Social Sciences"],"topics":["American History","Anthropology","Cultural Anthropology","European History","Gender Studies","History","Humanities","Social Anthropology","Social Science","Society"],"levels":["Graduate","Undergraduate"],"features":["Activity Assignments","Written Assignments"],"term":"Fall 2020","instructors":["Prof. Lerna Ekmekcioglu","Prof. Elizabeth A. Wood"],"url":"https://ocw.mit.edu/courses/21h-983j-gender-historical-perspectives-fall-2020/","views":1676},{"id":"21T.131+fall_2011","numbers":["21T.131"],"title":"Script Analysis","summary":"This course focuses on reading a script theatrically with a view to mounting a coherent production. Through careful, intensive reading of a variety of plays from different periods and different aesthetics, a pattern emerges for discerning what options exist for interpretating a script.\n\nThe Fall 2005 version of this course contains alternate readings and assignments sections.","departments":["Theater Arts"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Criticism","Drama","Fine Arts","Humanities","Literature","Performance Arts","Theater"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2011","instructors":["Prof. Alan Brody"],"url":"https://ocw.mit.edu/courses/21m-710-script-analysis-fall-2011/","views":1675},{"id":"STS.049J+spring_2004","numbers":["STS.049J"],"title":"Technology and Gender in American History","summary":"This course centers on the changing relationships between men, women, and technology in American history. Topics include theories of gender, technologies of production and consumption, the gendering of public and private space, men’s and women’s roles in science and technology, the effects of industrialization on sexual divisions of labor, gender and identity at home and at work.","departments":["Science, Technology, and Society"],"areas":["Humanities","Social Sciences"],"topics":["American History","Anthropology","Gender Studies","History","History of Science and Technology","Humanities","Modern History","Social Anthropology","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2004","instructors":["Prof. Deborah Fitzgerald"],"url":"https://ocw.mit.edu/courses/sts-049j-technology-and-gender-in-american-history-spring-2004/","views":1675},{"id":"6.876J+spring_2003","numbers":["6.876J","18.426J"],"title":"Advanced Topics in Cryptography","summary":"The topics covered in this course include interactive proofs, zero-knowledge proofs, zero-knowledge proofs of knowledge, non-interactive zero-knowledge proofs, secure protocols, two-party secure computation, multiparty secure computation, and chosen-ciphertext security.","departments":["Electrical Engineering and Computer Science","Mathematics"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Cryptography","Engineering","Theory of Computation"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2003","instructors":["Prof. Silvio Micali"],"url":"https://ocw.mit.edu/courses/6-876j-advanced-topics-in-cryptography-spring-2003/","views":1674},{"id":"15.598+spring_2003","numbers":["15.598"],"title":"IT and Business Transformation","summary":"The purpose of this Proseminar in Information Technology and Business Transformation (ITBT) is to provide students with a view of IT-enabled transformation and the strategic issues in the management of IT. The seminar will bring in CIOs, CEOs, and experienced consultants and industry observers to provide their perspectives and tell their stories about the use and management of IT today. Their talks will deal with the new technology, the new applications, the issues of implementation, the changes in industries and companies, and the strategic management of IT. In addition, there will be several case discussions of issues to be decided by senior management, with students taking on the position of executives and consultants. There will also be frameworks presented and used to position all material and speakers. Finally, one session will consist of ITBT alumni discussing career opportunities and issues for students, particularly from MIT, with these interests. Students will gain a perspective of the strategic role of and issues in managing IT as manifested in e-business applications, as a driver and enabler of business transformation, and as an underlying infrastructure resource for all businesses.","departments":["Sloan School of Management"],"areas":["Business & Management"],"topics":["Business","Information Technology","Innovation","Management","Organizational Behavior"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2003","instructors":["Prof. Cyrus Gibson"],"url":"https://ocw.mit.edu/courses/15-598-it-and-business-transformation-spring-2003/","views":1674},{"id":"15.269+fall_2015","numbers":["15.269"],"title":"Leadership Stories: Literature, Ethics, and Authority","summary":"This course explores how we use story to articulate ethical norms. The syllabus consists of short fiction, novels, plays, feature films and some non-fiction. Major topics include leadership and authority, professionalism, the nature of ethical standards, social enterprise, and questions of gender, cultural and individual identity, and work / life balance. Materials vary from year to year, but past readings have included work by Robert Bolt, Michael Frayn, Timothy Mo, Wole Soyinka, H. D. Thoreau, and others; films have included Crouching Tiger, Hidden Dragon, Hotel Rwanda, The Descendants, Motorcycle Diaries, Three Kings, and others. Draws on various professions and national cultures, and is run as a series of moderated discussions, with students centrally engaged in the teaching process.","departments":["Sloan School of Management"],"areas":["Business & Management","Humanities"],"topics":["Business","Business Ethics","Comparative Literature","Ethics","Fiction","Humanities","Leadership","Literature","Management","Philosophy"],"levels":["Graduate"],"features":["Activity Assignments","Instructor Insights","Written Assignments"],"term":"Fall 2015","instructors":["Prof. Leigh Hafrey"],"url":"https://ocw.mit.edu/courses/15-269-leadership-stories-literature-ethics-and-authority-fall-2015/","views":1672},{"id":"ES.S41+spring_2012","numbers":["ES.S41"],"title":"Speak Italian With Your Mouth Full","summary":"The participants in this seminar will dive into learning basic conversational Italian, Italian culture, and the Mediterranean diet. Each class is based on the preparation of a delicious dish and on the bite-sized acquisition of parts of the Italian language and culture. A good diet is not based on recipes only, it is also rooted in healthy habits and in culture. At the end of the seminar the participants will be able to cook some healthy and tasty recipes and to understand and speak basic Italian.","departments":["Experimental Study Group"],"areas":["Humanities","Social Sciences"],"topics":["European and Russian Studies","Humanities","Italian","Language","Society"],"levels":["Undergraduate"],"features":["Activity Assignments","Instructor Insights","Lecture Videos"],"term":"Spring 2012","instructors":["Dr. Paola Rebusco","Graham Gordon Ramsay"],"url":"https://ocw.mit.edu/courses/es-s41-speak-italian-with-your-mouth-full-spring-2012/","views":1672},{"id":"ESD.932+spring_2006","numbers":["ESD.932"],"title":"Engineering Ethics","summary":"This course introduces the theory and the practice of engineering ethics using a multi-disciplinary and cross-cultural approach. Theory includes ethics and philosophy of engineering. Historical cases are taken primarily from the scholarly literatures on engineering ethics, and hypothetical cases are written by students. Each student will write a story by selecting an ancestor or mythic hero as a substitute for a character in a historical case. Students will compare these cases and recommend action.","departments":["Engineering Systems Division"],"areas":["Business & Management","Engineering","Humanities"],"topics":["Business","Business Ethics","Engineering","Ethics","Humanities","Philosophy"],"levels":["Graduate"],"features":["Lecture Audio"],"term":"Spring 2006","instructors":["Dr. Taft Broome"],"url":"https://ocw.mit.edu/courses/esd-932-engineering-ethics-spring-2006/","views":1670},{"id":"21L.005+fall_2016","numbers":["21L.005"],"title":"Introduction to Drama","summary":"This course is a study of the history of theater art and practice from its origins to the modern period, including its roles in non-western cultures. Special attention is given to the relationship between the literary and performative dimensions of drama, and the relationship between drama and its cultural context.","departments":["Literature"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Classics","Drama","Fine Arts","Humanities","International Literature","Literature","Performance Arts","Theater"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2016","instructors":["Dr. Anne Fleche"],"url":"https://ocw.mit.edu/courses/21l-005-introduction-to-drama-fall-2016/","views":1669},{"id":"9.52-A+spring_2003","numbers":["9.52-A"],"title":"Investigating the Neural Substrates of Remote Memory using fMRI","summary":"This course is an investigation to distinguish episodic memory, which is memory of personal events, from semantic memory, which is general knowledge independent of time and place.","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math"],"topics":["Biology","Cognitive Science","Neuroscience","Science"],"levels":["Undergraduate"],"features":[],"term":"Spring 2003","instructors":["Prof. Suzanne Corkin"],"url":"https://ocw.mit.edu/courses/9-52-a-investigating-the-neural-substrates-of-remote-memory-using-fmri-spring-2003/","views":1669},{"id":"21L.435+fall_2002","numbers":["21L.435","CMS.840"],"title":"Shakespeare, Film and Media","summary":"Filmed Shakespeare began in 1899, with Sir Herbert Beerbohm Tree performing the death scene from King John for the camera. Sarah Bernhardt, who had played Hamlet a number of times in her long career, filmed the duel scene for the Paris Exposition of 1900. In the era of silent film (1895-1929) several hundred Shakespeare films were made in England, France Germany and the United States, Even without the spoken word, Shakespeare was popular in the new medium. The first half-century of sound included many of the most highly regarded Shakespeare films, among them – Laurence Olivier’s Hamlet and Henry V, Orson Welles’ Othello and Chimes at Midnight, Kurosawa’s Throne of Blood, Polanski’s Macbeth and Zeffirelli’s Romeo and Juliet. We are now in the midst of an extremely rich and varied period for Shakespeare on film which began with the release of Kenneth Branagh’s Henry V in 1989 and includes such films as Richard Loncraine’s Richard III, Julie Taymor’s Titus, Zeffirelli and Almereyda’s Hamlet films, Baz Luhrmann’s William Shakespeare’s Romeo + Juliet, and Shakespeare in Love. The phenomenon of filmed Shakespeare raises many questions for literary and media studies about adaptation, authorship, the status of “classic” texts and their variant forms, the role of Shakespeare in youth and popular culture, and the transition from manuscript, book and stage to the modern medium of film and its recent digitally inflected forms.\n\nMost of our work will involve individual and group analysis of the “film text” – that is, of specific sequences in the films, aided by videotape, DVD, the Shakespeare Electronic Archive, and some of the software tools for video annoatation developed by the MIT Shakespeare Project under the MIT-Microsoft iCampus Initiative.\n\nWe will study the films as works of art in their own right, and try to understand the means – literary, dramatic, performative, cinematic – by which they engage audiences and create meaning. With Shakespeare film as example, we will discuss how stories cross time, culture and media, and reflect on the benefits as well as the limitations of such migration.\n\nThe class will be conducted as a structured discussion, punctuated by student presentations and “mini-lectures” by the instructor. Students will introduce discussions, prepare clips and examples, and the major “written” work will take the form of presentations to the class and multimedia annotations as well as conventional short essays.\n\nThe methodological bias of the class is close “reading” of both text and film. This is a class in which your insights will form a major part of the work and will be the basis of a large fraction of class discussion. You will need to read carefully, to watch and listen to the films carefully, and develop effective ways of conveying your ideas to the class.","departments":["Literature"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Criticism","Drama","Film and Video","Fine Arts","Humanities","Literature","Media Studies","Visual Arts"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2002","instructors":["Prof. Peter S. Donaldson"],"url":"https://ocw.mit.edu/courses/21l-435-shakespeare-film-and-media-fall-2002/","views":1667},{"id":"18.966+spring_2007","numbers":["18.966"],"title":"Geometry of Manifolds","summary":"This is a second-semester graduate course on the geometry of manifolds. The main emphasis is on the geometry of symplectic manifolds, but the material also includes long digressions into complex geometry and the geometry of 4-manifolds, with special emphasis on topological considerations.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Differential Equations","Linear Algebra","Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2007","instructors":["Prof. Denis Auroux"],"url":"https://ocw.mit.edu/courses/18-966-geometry-of-manifolds-spring-2007/","views":1666},{"id":"22.67J+fall_2023","numbers":["22.67J","8.670J"],"title":"Principles of Plasma Diagnostics","summary":"This course is an introduction to the physical processes used to measure the properties of plasmas. It will cover diagnostics suitable for a wide range of plasmas, including magnetically confined fusion plasmas and high-energy-density plasmas. Techniques include the measurements of magnetic and electric fields, particle flux, refractive index, emission and scattering of electromagnetic waves, and nuclear diagnostics.","departments":["Nuclear Science and Engineering","Physics"],"areas":["Science & Math"],"topics":["Nuclear Physics","Physics","Science"],"levels":["Graduate"],"features":["Lecture Videos","Problem Sets","Supplemental Exam Materials"],"term":"Fall 2023","instructors":["Prof. Jack D. Hare"],"url":"https://ocw.mit.edu/courses/22-67j-principles-of-plasma-diagnostics-fall-2023/","views":1666},{"id":"6.844+spring_2003","numbers":["6.844"],"title":"Computability Theory of and with Scheme","summary":"6.844 is a graduate introduction to programming theory, logic of programming, and computability, with the programming language Scheme used to crystallize computability constructions and as an object of study itself. Topics covered include: programming and computability theory based on a term-rewriting, “substitution” model of computation by Scheme programs with side-effects; computation as algebraic manipulation: Scheme evaluation as algebraic manipulation and term rewriting theory; paradoxes from self-application and introduction to formal programming semantics; undecidability of the Halting Problem for Scheme; properties of recursively enumerable sets, leading to Incompleteness Theorems for Scheme equivalences; logic for program specification and verification; and Hilbert’s Tenth Problem.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Computation","Computer Science","Engineering","Mathematics","Programming Languages","Theory of Computation"],"levels":["Graduate"],"features":["Problem Sets"],"term":"Spring 2003","instructors":["Prof. Albert R. Meyer"],"url":"https://ocw.mit.edu/courses/6-844-computability-theory-of-and-with-scheme-spring-2003/","views":1663},{"id":"18.306+fall_2009","numbers":["18.306"],"title":"Advanced Partial Differential Equations with Applications","summary":"The focus of the course is the concepts and techniques for solving the partial differential equations (PDE) that permeate various scientific disciplines. The emphasis is on nonlinear PDE. Applications include problems from fluid dynamics, electrical and mechanical engineering, materials science, quantum mechanics, etc.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Applied Mathematics","Differential Equations","Mathematical Analysis","Mathematics"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2009","instructors":["Prof. Rodolfo Rosales"],"url":"https://ocw.mit.edu/courses/18-306-advanced-partial-differential-equations-with-applications-fall-2009/","views":1661},{"id":"18.725+fall_2003","numbers":["18.725"],"title":"Algebraic Geometry","summary":"This course covers the fundamental notions and results about algebraic varieties over an algebraically closed field. It also analyzes the relations between complex algebraic varieties and complex analytic varieties.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2003","instructors":["Prof. Martin Olsson"],"url":"https://ocw.mit.edu/courses/18-725-algebraic-geometry-fall-2003/","views":1661},{"id":"15.361+fall_2017","numbers":["15.361"],"title":"Executing Strategy for Results","summary":"This course provides business students an alternative to the mechanistic view of strategy execution that reframes an organization as a complex network of teams continuously adjusting to market conditions and to other teams. The Flexible Execution Model is introduced consisting of seven elements that together shape how well an organization executes its strategy. Practical tools that help leaders achieve their organizations’ strategic priorities are discussed. The course also explores novel ways to use data including surveys, Glassdoor reviews, and other sources to measure strategy execution and identify what is and is not working.","departments":["Sloan School of Management"],"areas":["Business & Management","Innovation & Entrepreneurship"],"topics":["Business","Entrepreneurship","Leadership","Management"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2017","instructors":["Donald Sull"],"url":"https://ocw.mit.edu/courses/15-361-executing-strategy-for-results-fall-2017/","views":1661},{"id":"6.976+spring_2003","numbers":["6.976"],"title":"High Speed Communication Circuits and Systems","summary":"6.976 covers circuit and system level design issues of high speed communication systems, with primary focus being placed on wireless and broadband data link applications. Specific circuit topics include transmission lines, high speed and low noise amplifiers, VCO’s, and high speed digital circuits. Specific system topics include frequency synthesizers, clock and data recovery circuits, and GMSK transceivers. In addition to learning analysis skills for the above items, students will gain a significant amount of experience in simulating circuits in SPICE and systems in CppSim (a custom C++ simulator).","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Design and Engineering","Computer Networks","Computer Science","Digital Systems","Electrical Engineering","Engineering","Telecommunications"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets","Projects"],"term":"Spring 2003","instructors":["Prof. Michael Perrott"],"url":"https://ocw.mit.edu/courses/6-976-high-speed-communication-circuits-and-systems-spring-2003/","views":1660},{"id":"2.004+spring_2008","numbers":["2.004"],"title":"Dynamics and Control II","summary":"Upon successful completion of this course, students will be able to:\n\n• Create lumped parameter models (expressed as ODEs) of simple dynamic systems in the electrical and mechanical energy domains\n• Make quantitative estimates of model parameters from experimental measurements\n• Obtain the time-domain response of linear systems to initial conditions and/or common forcing functions (specifically; impulse, step and ramp input) by both analytical and computational methods\n• Obtain the frequency-domain response of linear systems to sinusoidal inputs\n• Compensate the transient response of dynamic systems using feedback techniques\n• Design, implement and test an active control system to achieve a desired performance measure\n\nMastery of these topics will be assessed via homework, quizzes/exams, and lab assignments.","departments":["Mechanical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Applied Mathematics","Dynamics and Control","Engineering","Mathematics","Mechanical Engineering"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2008","instructors":["Prof. Derek Rowell"],"url":"https://ocw.mit.edu/courses/2-004-dynamics-and-control-ii-spring-2008/","views":1658},{"id":"6.021J+fall_2004","numbers":["6.021J","2.791J","2.794J","6.521J","20.370J","20.470J","HST.541J"],"title":"Quantitative Physiology: Cells and Tissues","summary":"In this subject, we consider two basic topics in cellular biophysics, posed here as questions:\n\n• Which molecules are transported across cellular membranes, and what are the mechanisms of transport? How do cells maintain their compositions, volume, and membrane potential?\n• How are potentials generated across the membranes of cells? What do these potentials do?\n\nAlthough the questions posed are fundamentally biological questions, the methods for answering these questions are inherently multidisciplinary. As we will see throughout the course, the role of mathematical models is to express concepts precisely enough that precise conclusions can be drawn. In connection with all the topics covered, we will consider both theory and experiment. For the student, the educational value of examining the interplay between theory and experiment transcends the value of the specific knowledge gained in the subject matter.\n\nThis course is jointly offered through four departments, available to both undergraduates and graduates.","departments":["Biological Engineering","Electrical Engineering and Computer Science","Health Sciences and Technology","Mechanical Engineering"],"areas":["Health & Medicine","Science & Math"],"topics":["Anatomy and Physiology","Biology","Biophysics","Cell Biology","Health and Medicine","Molecular Biology","Science"],"levels":["Undergraduate"],"features":["Problem Sets","Projects"],"term":"Fall 2004","instructors":["Prof. Dennis Freeman"],"url":"https://ocw.mit.edu/courses/6-021j-quantitative-physiology-cells-and-tissues-fall-2004/","views":1657},{"id":"11.947+spring_2009","numbers":["11.947"],"title":"Urbanization and Development","summary":"The course examines the causes and effects of rapid urbanization in developing countries. Using case studies from the world’s four major developing regions, including (among others) Mexico City, Buenos Aires, Managua, Singapore, Hong Kong, Guangzhou, Kabul, Beirut, Cairo, Kinshasa, Cape Town and Johannesburg, it explores the economic and political dynamics that grease the wheels of contemporary patterns of growth. In addition to examining both local and transnational forces that drive contemporary urbanization, the course focuses on key issues that emerge in rapidly growing cities of the developing world, ranging from growing income inequality and socio-economic exclusion, environmental challenges, and rising violence. Class sessions are discussion-based and focus on a critical analysis of the arguments presented in the readings.","departments":["Urban Studies and Planning"],"areas":["Humanities","Social Sciences"],"topics":["Community Development","Humanities","Philosophy","Political Philosophy","Public Administration","Social Science","Society","Sociology","The Developing World","Urban Studies"],"levels":["Graduate"],"features":["Activity Assignments","Exam Solutions","Exams"],"term":"Spring 2009","instructors":["Dr. Daniel Esser"],"url":"https://ocw.mit.edu/courses/11-947-urbanization-and-development-spring-2009/","views":1657},{"id":"17.462+fall_2005","numbers":["17.462"],"title":"Innovation in Military Organizations","summary":"This seminar has three purposes. One, it inquires into the causes of military innovation by examining a number of the most outstanding historical cases. Two, it views military innovations through the lens of organization theory to develop generalizations about the innovation process within militaries. Three, it uses the empirical study of military innovations as a way to examine the strength and credibility of hypotheses that organization theorists have generated about innovation in non-military organizations.","departments":["Political Science"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["Business","History","Humanities","Innovation","Military History","Military Studies","Organizational Behavior","Public Administration","Security Studies","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2005","instructors":["Prof. Barry Posen","Prof. Harvey Sapolsky"],"url":"https://ocw.mit.edu/courses/17-462-innovation-in-military-organizations-fall-2005/","views":1655},{"id":"17.433+spring_2011","numbers":["17.433","17.434"],"title":"International Relations of East Asia","summary":"The aim of this course is to introduce and analyze the international relations of East Asia. With four great powers, three nuclear weapons states, and two of the world’s largest economies, East Asia is one of the most dynamic and consequential regions in world politics. This course will examine the sources of conflict and cooperation in both periods, assessing competing explanations for key events in East Asia’s international relations. Readings will be drawn from international relations theory, political science and history.","departments":["Political Science"],"areas":["Humanities","Social Sciences"],"topics":["Asian History","Asian Studies","History","Humanities","International Relations","Political Science","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2011","instructors":["Prof. M. Taylor Fravel"],"url":"https://ocw.mit.edu/courses/17-433-international-relations-of-east-asia-spring-2011/","views":1655},{"id":"18.745+fall_2020","numbers":["18.745"],"title":"Lie Groups and Lie Algebras I","summary":"This course is the first half of the year-long introductory graduate sequence 18.745/18.755 on Lie groups and Lie algebras. Topics include foundations of the theory of Lie groups and Lie algebras; theorems of Engel and Lie; the universal enveloping algebra, the Poincare-Birkhoff-Witt theorem; free Lie algebras; the Campbell-Hausdorff formula; classification and structure of finite dimensional complex simple Lie algebras; their finite dimensional representations; and the Weyl character formula.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes","Open Textbooks","Problem Sets"],"term":"Fall 2020","instructors":["Prof. Pavel Etingof"],"url":"https://ocw.mit.edu/courses/18-745-lie-groups-and-lie-algebras-i-fall-2020/","views":1654},{"id":"8.513+fall_2021","numbers":["8.513"],"title":"Modern Quantum Many-body Physics for Condensed Matter Systems","summary":"This graduate-level course covers the quantum effect in solids. It focuses on the concepts and physical pictures behind various phenomena that appear in interacting many-body systems.","departments":["Physics"],"areas":["Science & Math"],"topics":["Condensed Matter Physics","Physics","Quantum Mechanics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2021","instructors":["Prof. Xiao-Gang Wen"],"url":"https://ocw.mit.edu/courses/8-513-modern-quantum-many-body-physics-for-condensed-matter-systems-fall-2021/","views":1654},{"id":"4.367+spring_2006","numbers":["4.367"],"title":"Studio Seminar in Public Art","summary":"How do we define Public Art? This course focuses on the production of projects for public places. Public Art is a concept that is in constant discussion and revision, as much as the evolution and transformation of public spaces and cities are. Monuments are repositories of memory and historical presences with the expectation of being permanent. Public interventions are created not to impose and be temporary, but as forms intended to activate discourse and discussion. Considering the concept of a museum as a public device and how they are searching for new ways of avoiding generic identities, we will deal with the concept of the personal imaginary museum. It should be considered as a point of departure to propose a personal individual construction based on the concept of defining a personal imaginary museum - concept, program, collection, events, architecture, public diffusion, etc.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architecture","Art History","Fine Arts","Visual Arts"],"levels":["Graduate"],"features":["Lecture Videos","Projects with Examples"],"term":"Spring 2006","instructors":["Prof. Antonio Muntadas"],"url":"https://ocw.mit.edu/courses/4-367-studio-seminar-in-public-art-spring-2006/","views":1654},{"id":"18.S097+january-iap_2019","numbers":["18.S097"],"title":"Applied Category Theory","summary":"Category theory is a relatively new branch of mathematics that has transformed much of pure math research. The technical advance is that category theory provides a framework in which to organize formal systems and by which to translate between them, allowing one to transfer knowledge from one field to another. But this same organizational framework also has many compelling examples outside of pure math. In this course, we will give seven sketches on real-world applications of category theory.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Applied Mathematics","Mathematics","Topology and Geometry"],"levels":["Undergraduate"],"features":["Instructor Insights","Lecture Videos","Open Textbooks","Problem Sets"],"term":"January IAP 2019","instructors":["Dr. David I. Spivak","Dr. Brendan Fong"],"url":"https://ocw.mit.edu/courses/18-s097-applied-category-theory-january-iap-2019/","views":1653},{"id":"ES.S10+spring_2013","numbers":["ES.S10"],"title":"Drugs and the Brain","summary":"This class is a multidisciplinary introduction to pharmacology, neurotransmitters, drug mechanisms, and brain diseases from addiction to schizophrenia.\n\nFrom Abilify® to Zyrtec®, the world is full of fascinating drugs. If you are poisoned by sarin nerve gas, you may be able to save your life by huffing some BZ nerve gas. This class will explain that chemical curiosity, along with a host of other interesting tidbits of pharmacology. The structure of the class interleaves basic concepts with specific examples and entertaining tangents, so it is not loaded with boring abstract theory. In the first class you will learn what a neurotransmitter is, and you will immediately apply that knowledge when we discuss the mechanism of caffeine. The class is highly multidisciplinary, including topics such as patent law, medical ethics, history, and the physics of crack pipes.","departments":["Experimental Study Group"],"areas":["Health & Medicine","Science & Math"],"topics":["Biochemistry","Biology","Health and Medicine","Neurobiology","Pharmacology and Toxicology","Science"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Instructor Insights","Lecture Notes"],"term":"Spring 2013","instructors":["Zak Fallows"],"url":"https://ocw.mit.edu/courses/es-s10-drugs-and-the-brain-spring-2013/","views":1652},{"id":"11.360+fall_2006","numbers":["11.360"],"title":"Community Growth and Land Use Planning","summary":"This course combines a seminar format with fieldwork to examine strategies of planning and control for growth and land use, chiefly at the municipal level. Specific topics include growth and its local consequences; land use planning approaches; and implementation tools including innovative zoning and regulatory techniques, physical design, and natural systems integration. Projects are arranged with small teams serving municipal clients.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Public Administration","Public Policy","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Fall 2006","instructors":["Prof. Eran Ben-Joseph","Prof. Terry Szold"],"url":"https://ocw.mit.edu/courses/11-360-community-growth-and-land-use-planning-fall-2006/","views":1649},{"id":"21G.412+fall_2014","numbers":["21G.412"],"title":"Advanced German Literature & Culture: Madness, Murder, Mysteries","summary":"This course provides the opportunity to discuss, orally and in writing, cultural, ethical, and social issues on a stylistically sophisticated level. It explores representative and influential works from the nineteenth century to the present, through literary texts (prose, drama, poetry), radio plays, art, film, and architecture, as well as investigates topics such as the human and the machine, science and ethics, representation of memory, and issues of good and evil. Taught in German.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Comparative Literature","Criticism","German","Humanities","Language","Literature"],"levels":["Undergraduate"],"features":[],"term":"Fall 2014","instructors":["Peter Weise"],"url":"https://ocw.mit.edu/courses/21g-412-advanced-german-literature-culture-madness-murder-mysteries-fall-2014/","views":1646},{"id":"1.963+spring_2007","numbers":["1.963"],"title":"A Sustainable Transportation Plan for MIT","summary":"This seminar-style class will focus on evaluating and recommending alternative commuter and business-related transportation policies for the MIT campus. Emphasis will be placed on reducing transportation-related energy usage in a sustainable manner in response to President Hockfield’s “Walk the Talk” energy initiative. Students will explore the relative roles of MIT and the MBTA as transportation providers, as well as the efficiency and effectiveness of related subsidy policies currently in place for all modes of transportation.","departments":["Civil and Environmental Engineering"],"areas":["Energy, Climate & Sustainability","Science & Math","Social Sciences"],"topics":["Earth Science","Public Administration","Public Policy","Science","Social Science","Sustainability","Transportation Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Projects"],"term":"Spring 2007","instructors":["Frederick Salvucci","John Attanucci","Lawrence Brutti"],"url":"https://ocw.mit.edu/courses/1-963-a-sustainable-transportation-plan-for-mit-spring-2007/","views":1645},{"id":"21G.412+fall_2009","numbers":["21G.412"],"title":"Texts, Topics, and Times in German Literature","summary":"In diesem Kurs erhalten Sie einen Überblick über einige wichtige literarische Texte, Tendenzen und Themen aus der deutschsprachigen Literatur- und Kulturszene. Wir werden literarische Texte, Gedichte, Theaterstücke und Essays untersuchen, sowie andere ästhetische Formen besprechen, wie Film und Architektur. Da alle Texte gleichzeitig in ihrem spezifischen kulturellen Kontext gelesen werden, tragen sie zu einem Verständnis von verschiedenen historischen Aspekten bei. Unter anderen werden folgende Themen und Fragestellungen besprochen: Technologie und deren Einfluss auf die Gesellschaft, Fragen der Ethik bei wissenschaftlicher Arbeit, Konstruktion von nationaler Geschichte und kollektivem Gedächtnis.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","European and Russian Studies","German","Humanities","International Literature","Language","Literature","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2009","instructors":["Dagmar Jaeger"],"url":"https://ocw.mit.edu/courses/21g-412-texts-topics-and-times-in-german-literature-fall-2009/","views":1643},{"id":"11.489+fall_2005","numbers":["11.489"],"title":"The Growth and Spatial Structure of Cities","summary":"This course examines the economic, political, social, and spatial dynamics of urban growth and decline in cities and their key component areas (downtown, suburbs, etc.). Topics include impacts of industrialization, technology, politics, and social practices on cities. Students will examine the role of public and private sector activities, ranging from zoning and subsidies to infrastructure development and real estate investment, in affecting urban growth and decline. Readings are both theoretical and empirical, with considerable thought paid to comparative and historical differences.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Public Administration","Public Policy","Social Science","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Fall 2005","instructors":["Prof. Diane Davis"],"url":"https://ocw.mit.edu/courses/11-489-the-growth-and-spatial-structure-of-cities-fall-2005/","views":1639},{"id":"CMS.951+spring_2015","numbers":["CMS.951"],"title":"Workshop II: Qualitative Social Science Methods for Media Studies","summary":"This course focuses on a number of qualitative social science methods that can be productively used in media studies research including interviewing, participant observation, focus groups, cultural probes, visual sociology, and ethnography. The emphasis will primarily be on understanding and learning concrete techniques that can be evaluated for their usefulness in any given project and utilized as needed. Data organization and analysis will be addressed. Several advanced critical thematics will also be covered, including ethics, reciprocity, “studying up,” and risk. The course will be taught via a combination of lectures, class discussions, group exercises, and assignments. This course requires a willingness to work hands-on with learning various social science methods and a commitment to the preparation for such (including reading, discussion, and reflection).","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Anthropology","Communication","Ethnography","Fine Arts","Media Studies","Social Anthropology","Social Science","Sociology"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2015","instructors":["Prof. Ian Condry","Prof. T. L. Taylor"],"url":"https://ocw.mit.edu/courses/cms-951-workshop-ii-qualitative-social-science-methods-for-media-studies-spring-2015/","views":1639},{"id":"21M.113+fall_2002","numbers":["21M.113"],"title":"Developing Musical Structures","summary":"The goal of this class is practical: to interrogate, make explicit, and thus to develop the powerful musical intuitions that are at work as you make sense of the music all around you. Reflecting, we will ask how this knowledge develops in ordinary and extraordinary ways.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music Performance","Music Theory"],"levels":["Undergraduate"],"features":["Activity Assignments","Written Assignments"],"term":"Fall 2002","instructors":["Prof. Jeanne Bamberger"],"url":"https://ocw.mit.edu/courses/21m-113-developing-musical-structures-fall-2002/","views":1638},{"id":"12.335+fall_2014","numbers":["12.335","12.835"],"title":"Experimental Atmospheric Chemistry","summary":"This course provides an introduction to the atmospheric chemistry involved in climate change, air pollution and biogeochemical cycles using a combination of hands-on laboratory, field studies, and simple computer models. Lectures will be accompanied by field trips to collect air samples for the analysis of gases, aerosols and clouds by the students.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Atmospheric Science","Chemistry","Earth Science","Science"],"levels":["Undergraduate","Graduate"],"features":["Activity Assignments","Lecture Notes"],"term":"Fall 2014","instructors":["Prof. Ronald G Prinn","Prof. Shuhei Ono","Dr. Karin Ardon Dryer"],"url":"https://ocw.mit.edu/courses/12-335-experimental-atmospheric-chemistry-fall-2014/","views":1636},{"id":"4.493+spring_2005","numbers":["4.493"],"title":"Emergent Materials II","summary":"This course will focus on providing students with the tools needed to practice responsible architecture in a contemporary context. It will familiarize students with the materials currently used in responsible practice, as well as the material properties most relevant to assembly. The course will also introduce students to materials that are untested but hold promise for future usage. Finally, the course will challenge students to refine their understanding of responsible or sustainable design practice by looking at the evolution of those ideas within the field of architecture.","departments":["Architecture"],"areas":["Art, Design & Architecture","Engineering"],"topics":["Architectural Engineering","Architecture","Engineering","Fine Arts","Materials Science and Engineering"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2005","instructors":["Prof. John Fernandez"],"url":"https://ocw.mit.edu/courses/4-493-emergent-materials-ii-spring-2005/","views":1633},{"id":"15.322+fall_2003","numbers":["15.322"],"title":"Leading Organizations II","summary":"Through lectures, discussions, and class exercises, 15.322 analyzes the human processes underlying organizational behavior and change. The class makes students aware of the challenge of organizational change and equips them to better handle it. There are many psychological and sociological phenomena that regularly occur in organizations, though many of these forces are difficult to see. The aim is to increase the students’ understanding of these forces – in themselves and in others – so they become more visible and manageable. The prerequisite for this course is 15.321 Leading Organizations I.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Leadership","Management","Organizational Behavior","Social Science","Sociology"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2003","instructors":["Prof. John Van Maanen"],"url":"https://ocw.mit.edu/courses/15-322-leading-organizations-ii-fall-2003/","views":1632},{"id":"21W.016+fall_2016","numbers":["21W.016"],"title":"Writing and Rhetoric: Designing Meaning","summary":"This course takes rhetoric as a system for designing meaning that helps us understand complex situations and ideas, enlighten and persuade others to act, and thus reshape our world. We’ll study rhetoric systematically and empirically, both analyzing how it works on us as readers, and testing how we can make informed rhetorical choices as we design our own texts.","departments":["Comparative Media Studies/Writing"],"areas":["Humanities","Social Sciences"],"topics":["Communication","Criticism","Humanities","Literature","Nonfiction Prose","Philosophy","Political Philosophy","Rhetoric","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2016","instructors":["Dr. Suzanne T. Lane"],"url":"https://ocw.mit.edu/courses/21w-016-writing-and-rhetoric-designing-meaning-fall-2016/","views":1632},{"id":"21H.380J+fall_2013","numbers":["21H.380J","21A.419J","21H.980J","21A.411J"],"title":"People and Other Animals","summary":"This course is a historical exploration of the ways that people have interacted with their closest animal relatives, for example: hunting, domestication of livestock, exploitation of animal labor, scientific study of animals, display of exotic and performing animals, and pet-keeping. Themes include changing ideas about animal agency and intelligence, our moral obligations to animals, and the limits imposed on the use of animals. Students taking the graduate version complete additional assignments.","departments":["Anthropology","History"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","History","History of Science and Technology","Humanities","Intellectual History","Social Science"],"levels":["Undergraduate","Graduate"],"features":["Written Assignments"],"term":"Fall 2013","instructors":["Prof. Harriet Ritvo"],"url":"https://ocw.mit.edu/courses/21h-380j-people-and-other-animals-fall-2013/","views":1631},{"id":"11.373+fall_2004","numbers":["11.373"],"title":"Science, Politics, and Environmental Policy","summary":"This class examines the role of science in the US environmental policy-making process. It investigates the methods scientists use to learn about the natural world, the way scientific knowledge accumulates, the treatment of science by advocates and the media, and the role of science in legislative, administrative and judicial decision making. It also considers how other political systems use science in an effort to put the US approach in comparative perspective.","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Social Sciences"],"topics":["American Politics","Comparative Politics","Environmental Policy","Political Science","Public Administration","Public Policy","Science and Technology Policy","Social Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2004","instructors":["Prof. Judith Layzer"],"url":"https://ocw.mit.edu/courses/11-373-science-politics-and-environmental-policy-fall-2004/","views":1627},{"id":"3.003+spring_2010","numbers":["3.003"],"title":"Principles of Engineering Practice","summary":"This class introduces students to the interdisciplinary nature of 21st-century engineering projects with three threads of learning: a technical toolkit, a social science toolkit, and a methodology for problem-based learning. Students encounter the social, political, economic, and technological challenges of engineering practice by participating in real engineering projects with faculty and industry; this semester’s major project focuses on the engineering and economics of solar cells. Student teams will create prototypes and mixed media reports with exercises in project planning, analysis, design, optimization, demonstration, reporting and team building.","departments":["Materials Science and Engineering"],"areas":["Business & Management","Engineering"],"topics":["Business","Electrical Engineering","Electronic Materials","Engineering","Management","Materials Science and Engineering"],"levels":["Undergraduate"],"features":["Activity Assignments","Lecture Notes","Presentation Assignments","Projects with Examples","Written Assignments with Examples"],"term":"Spring 2010","instructors":["Prof. Lionel C. Kimerling"],"url":"https://ocw.mit.edu/courses/3-003-principles-of-engineering-practice-spring-2010/","views":1624},{"id":"21H.244J+fall_2019","numbers":["21H.244J","21G.085J"],"title":"Imperial and Revolutionary Russia: Culture and Politics, 1700-1917","summary":"This course analyzes Russia’s social, cultural, and political heritage in the 18th and 19th centuries, up to and including the Russian Revolution of 1917. It compares reforming and revolutionary impulses in the context of serfdom, the rise of the intelligentsia, and debates over capitalism, while focusing on historical and literary texts, especially the intersections between the two.","departments":["Global Studies and Languages","History"],"areas":["Humanities"],"topics":["Asian History","European History","History","Humanities"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2019","instructors":["Prof. Elizabeth A. Wood"],"url":"https://ocw.mit.edu/courses/21h-244j-imperial-and-revolutionary-russia-culture-and-politics-1700-1917-fall-2019/","views":1623},{"id":"HST.951J+spring_2003","numbers":["HST.951J","6.873J"],"title":"Medical Decision Support","summary":"This course presents the main concepts of decision analysis, artificial intelligence and predictive model construction and evaluation in the specific context of medical applications. It emphasizes the advantages and disadvantages of using these methods in real-world systems and provides hands-on experience. Its technical focus is on decision support, knowledge-based systems (qualitative and quantitative), learning systems (including logistic regression, classification trees, neural networks, rough sets), and techniques to evaluate the performance of such systems. It reviews computer-based diagnosis, planning and monitoring of therapeutic interventions. It also discusses implemented medical applications and the software tools used in their construction. Students produce a final project using the machine learning methods learned in the course, based on actual clinical data.\n\nLecturers\n\nProf. Stephan Dreiseitl\n\nProf. Ju Jan Kim\n\nProf. Bill Long\n\nProf. Marco Ramoni\n\nProf. Fred Resnic\n\nProf. David Wypij","departments":["Electrical Engineering and Computer Science","Health Sciences and Technology"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering","Health & Medicine"],"topics":["Artificial Intelligence","Biological Engineering","Biomedicine","Business","Computational Biology","Computer Science","Engineering","Health and Medicine","Information Technology"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Set Solutions","Problem Sets","Programming Assignments"],"term":"Spring 2003","instructors":["Prof. Isaac Kohane","Prof. Lucila Ohno-Machado","Prof. Peter Szolovits","Prof. Staal Vinterbo"],"url":"https://ocw.mit.edu/courses/hst-951j-medical-decision-support-spring-2003/","views":1623},{"id":"14.20+spring_2003","numbers":["14.20"],"title":"Industrial Organization and Public Policy","summary":"This is a course in industrial organization, the study of firms in markets. Industrial organization focuses on firm behavior in imperfectly competitive markets, which appear to be far more common than the perfectly competitive markets that were the focus of your basic microeconomics course. This field analyzes the acquisition and use of market power by firms, strategic interactions among firms, and the role of government competition policy. We will approach this subject from both theoretical and applied perspectives.","departments":["Economics"],"areas":["Social Sciences"],"topics":["Economics","Industrial Organization","Microeconomics","Public Administration","Public Policy","Social Science"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Problem Set Solutions","Problem Sets"],"term":"Spring 2003","instructors":["Prof. Nancy Rose"],"url":"https://ocw.mit.edu/courses/14-20-industrial-organization-and-public-policy-spring-2003/","views":1622},{"id":"21M.250+fall_2006","numbers":["21M.250"],"title":"Schubert to Debussy","summary":"This course is a survey of developments in Western musical style, 1815-1915. Students will study works by 35 composers, including the romantics: Schubert, Chopin, and Schumann; the post-romantics: Wagner, Verdi, and Brahms; the turn-of-the-centurians: Mahler, Debussy, and Ravel; and the Americans: Gottschalk, Beach, and Joplin. Score-reading ability is beneficial.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History"],"levels":["Undergraduate"],"features":["Activity Assignments"],"term":"Fall 2006","instructors":["Prof. Charles Shadle"],"url":"https://ocw.mit.edu/courses/21m-250-schubert-to-debussy-fall-2006/","views":1622},{"id":"21L.701+fall_2005","numbers":["21L.701"],"title":"Literary Interpretation: Literature and Photography: The Image","summary":"This course introduces the practice and theory of literary criticism. The seminar focuses on topics such as the history of critical methods and techniques, and the continuity of certain subjects in literary history. Instruction and practice in oral and written communication is a major component of the course. Other components include theory and use of figurative language and reading poetry.","departments":["Literature"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Comparative Literature","Criticism","Fine Arts","Humanities","Literature","Philosophy","Philosophy of Language","Photography","Poetry","Visual Arts"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2005","instructors":["Marja Roholl","Prof. Stephen Tapscott"],"url":"https://ocw.mit.edu/courses/21l-701-literary-interpretation-literature-and-photography-the-image-fall-2005/","views":1621},{"id":"PE.910+january-iap_2002","numbers":["PE.910"],"title":"Physical Intelligence","summary":"For all of the bodies attached to the many great minds that walk the Institute’s halls, in the work that goes on at MIT the body is present as an object of study, but is all but unrecognized as an important dimension of our intelligence and experience. Yet the body is the basis of our experience in the world; it is the very foundation on which cognitive intelligence is built. Using the MIT gymnastics gym as our laboratory, the Physical Intelligence activity will take an innovative, hands-on approach to explore the kinesthetic intelligence of the body as applicable to a wide range of disciplines. Via exercises, activities, readings and discussions designed to excavate our physical experience, we will not only develop balance, agility, flexibility and strength, but a deep appreciation for the inherent unity of mind and body that suggests physical intelligence as a powerful complement to cognitive intelligence.","departments":["Athletics, Physical Education and Recreation"],"areas":["Health & Medicine","Science & Math"],"topics":["Cognitive Science","Health and Medicine","Physical Education and Recreation","Science"],"levels":["Undergraduate"],"features":[],"term":"January IAP 2002","instructors":["Noah Riskin"],"url":"https://ocw.mit.edu/courses/pe-910-physical-intelligence-january-iap-2002/","views":1621},{"id":"21G.053+spring_2014","numbers":["21G.053"],"title":"Understanding Contemporary French Politics","summary":"This course examines the changes in contemporary French society through the study of political debates, reforms and institutions since 1958, and analyzes the deep influence of politics on cultural and social life, despite a decline in political participation. Public controversies and political cleavages, from the Algerian war to postcolonial issues, from the birth of the European Union to the recent financial crisis, and from the moral “revolution” of the seventies to the recognition of new families are revisited.\n\nThis course is taught in English.","departments":["Global Studies and Languages"],"areas":["Social Sciences"],"topics":["European and Russian Studies","Political Science","Social Justice","Social Science","Society","Sociology"],"levels":["Undergraduate"],"features":["Instructor Insights","Presentation Assignments","Written Assignments"],"term":"Spring 2014","instructors":["Prof. Bruno Perreau"],"url":"https://ocw.mit.edu/courses/21g-053-understanding-contemporary-french-politics-spring-2014/","views":1621},{"id":"21W.021+fall_2013","numbers":["21W.021"],"title":"Writing and Experience: MIT: Inside, Live","summary":"During this seminar, students will chronicle their MIT experiences and investigate MIT history and culture. Visits to the MIT archives and museum, along with relevant readings, will supplement students’ experiences as source material for discussion and writing.","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Creative Writing","Fine Arts","Humanities","Literature","Media Studies"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2013","instructors":["Lucy Marx"],"url":"https://ocw.mit.edu/courses/21w-021-writing-and-experience-mit-inside-live-fall-2013/","views":1621},{"id":"21G.321+spring_2024","numbers":["21G.321"],"title":"Childhood and Youth in French and Francophone Cultures","summary":"This course studies the transformation of childhood and youth since the 18th century in France and the development of sentimentality within the family in a francophone context. We will examine the personification of children as a source of inspiration for artistic creation and a political ideal aimed at protecting future generations, and consider various representations of childhood and youth in literature, movies, and songs.\n\nThe course is taught entirely in French.\n\nAbout the instructor: Bruno Perreau is the Cynthia L. Reed Professor of French Studies at MIT and Director of MIT’s Center of Excellence in French Studies. He is also an Affiliate Faculty at the Center for European Studies, Harvard University.\n\nPerreau recently published The Politics of Adoption: Gender and the Making of French Citizenship (MIT Press, 2014), Queer Theory: The French Response (Stanford University Press, 2016), Les Défis de la République (ed. with Joan W. Scott, Presses de Sciences Po, 2017), Qui a peur de la théorie queer ? (Presses de Sciences Po, 2018), and Sphères d’injustice. Pour un universalisme minoritaire (La Découverte, 2023).","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","French","Humanities","International Literature","Language","Literature","Social Science"],"levels":["Undergraduate"],"features":["Media Assignments","Readings","Written Assignments"],"term":"Spring 2024","instructors":["Prof. Bruno Perreau"],"url":"https://ocw.mit.edu/courses/21g-321-childhood-and-youth-in-french-and-francophone-cultures-spring-2024/","views":1620},{"id":"21T.1000+fall_2009","numbers":["21T.1000"],"title":"Foundations of Theater Practice","summary":"The goals of this class are two-fold: the first is to experience the creative processes and storytelling behind several of theater’s arts and to acquire the analytical skills necessary in assessing the meaning they transmit when they come together in production. Secondly, we will introduce you to these languages in a creative way by giving you hands-on experience in each. To that end, several Visiting Artists and MIT faculty in Theater Arts will guest lecture, lead workshops, and give you practical instruction in their individual art forms.","departments":["Theater Arts"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Criticism","Fine Arts","Humanities","Literature","Performance Arts","Theater"],"levels":["Undergraduate"],"features":["Image Gallery","Written Assignments"],"term":"Fall 2009","instructors":["Prof. Janet Sonenberg"],"url":"https://ocw.mit.edu/courses/21m-611-foundations-of-theater-practice-fall-2009/","views":1620},{"id":"12.445+fall_2010","numbers":["12.445"],"title":"Oral Communication in the Earth, Atmospheric, and Planetary Sciences","summary":"This course focuses on developing oral presentation skills through practice, self-evaluation, and in-class feedback. Topics include slide preparation, answering difficult questions, explaining technical details and presenting to a general audience.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Humanities","Social Sciences"],"topics":["Communication","Humanities","Literature","Rhetoric","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Presentation Assignments"],"term":"Fall 2010","instructors":["Prof. Alison Malcolm"],"url":"https://ocw.mit.edu/courses/12-445-oral-communication-in-the-earth-atmospheric-and-planetary-sciences-fall-2010/","views":1617},{"id":"22.091+spring_2008","numbers":["22.091","22.903"],"title":"Nuclear Reactor Safety","summary":"Problems in nuclear engineering often involve applying knowledge from many disciplines simultaneously in achieving satisfactory solutions. The course will focus on understanding the complete nuclear reactor system including the balance of plant, support systems and resulting interdependencies affecting the overall safety of the plant and regulatory oversight. Both the Seabrook and Pilgrim nuclear plant simulators will be used as part of the educational experience to provide as realistic as possible understanding of nuclear power systems short of being at the reactor.","departments":["Nuclear Science and Engineering"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math"],"topics":["Energy","Engineering","Nuclear Energy","Nuclear Engineering","Nuclear Physics","Nuclear Systems, Policy, and Economics","Physics","Science"],"levels":["Undergraduate","Graduate"],"features":["Exams","Lecture Notes","Lecture Videos","Problem Sets","Programming Assignments","Written Assignments"],"term":"Spring 2008","instructors":["Prof. Andrew Kadak"],"url":"https://ocw.mit.edu/courses/22-091-nuclear-reactor-safety-spring-2008/","views":1615},{"id":"14.452+fall_2016","numbers":["14.452"],"title":"Economic Growth","summary":"This half semester class will present an introduction to macroeconomic modeling, particularly economic growth. It will focus both on models of economic growth and their empirical applications, and try to shed light on the mechanics of economic growth, technological change and sources of income and growth differences across countries.","departments":["Economics"],"areas":["Social Sciences"],"topics":["Developmental Economics","Economics","Macroeconomics","Social Science"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2016","instructors":["Prof. Daron Acemoglu"],"url":"https://ocw.mit.edu/courses/14-452-economic-growth-fall-2016/","views":1612},{"id":"21L.002X+spring_2012","numbers":["21L.002X"],"title":"Foundations of World Culture II: World Literatures and Texts","summary":"This class continues our study of the foundational texts of human culture, focusing on early modernity until the recent past. In many ways, this includes several questions such as: Why did these works achieve the fame and influence they achieved? How do they present what it means to be a human being? How do they describe the role of a member of a family, community, tradition, social class, gender? How do they distinguish between proper and improper behavior? How do they characterize the members of other groups? However, in several ways, these texts are also iconoclastic, breaking with centuries of established tradition to shed light on previously unexplored subjects, such as the status of women in society or the legacy of the colonial expansion of European countries. They also question well-established social beliefs like religion, monarchical rule and human nature in general.","departments":["Literature"],"areas":["Humanities"],"topics":["Classics","Humanities","International Literature","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2012","instructors":["Dr. Ghenwa Hayek"],"url":"https://ocw.mit.edu/courses/21l-002x-foundations-of-world-culture-ii-world-literatures-and-texts-spring-2012/","views":1612},{"id":"2.29+spring_2003","numbers":["2.29"],"title":"Numerical Marine Hydrodynamics (13.024)","summary":"This course is an introduction to numerical methods: interpolation, differentiation, integration, and systems of linear equations. It covers the solution of differential equations by numerical integration, as well as partial differential equations of inviscid hydrodynamics: finite difference methods, boundary integral equation panel methods. Also addressed are introductory numerical lifting surface computations, fast Fourier transforms, the numerical representation of deterministic and random sea waves, as well as integral boundary layer equations and numerical solutions.\n\nThis course was originally offered in Course 13 (Department of Ocean Engineering) as 13.024. In 2005, ocean engineering subjects became part of Course 2 (Department of Mechanical Engineering), and this course was renumbered 2.29.","departments":["Mechanical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Differential Equations","Engineering","Fluid Mechanics","Hydrodynamics","Mathematical Analysis","Mathematics","Mechanical Engineering","Numerical Simulation","Ocean Engineering","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Programming Assignments"],"term":"Spring 2003","instructors":["Prof. Jerome Milgram"],"url":"https://ocw.mit.edu/courses/2-29-numerical-marine-hydrodynamics-13-024-spring-2003/","views":1611},{"id":"21G.017+fall_2002","numbers":["21G.017"],"title":"Germany and its European Context","summary":"This course focuses on main currents in contemporary German literary and visual culture. Taking Nietzsche’s thought as a point of departure, students will survey the dialectics of tradition and modernity in both Germany and other European countries, particularly the UK, France, Denmark, and Poland. Primary works are drawn from literature, cinema, art, and performance, including works by Peter Sloterdijk, Thomas Vinterberg, and Michel Houellebecq.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["Criticism","European and Russian Studies","Humanities","International Literature","Literature","Society"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2002","instructors":["Prof. Charity Scribner"],"url":"https://ocw.mit.edu/courses/21g-017-germany-and-its-european-context-fall-2002/","views":1609},{"id":"RES.CMS-001+spring_2021","numbers":["RES.CMS-001"],"title":"Media Literacy in the Age of Deepfakes","summary":"Media Literacy in the Age of Deepfakes aims to equip students with the critical skills to better understand the past and contemporary threat of misinformation. Students will learn about different ways to analyze emerging forms of misinformation such as “deepfake” videos as well as how new technologies can be used to create a more just and equitable society. This module consists of three interconnected sections. We begin by defining and contextualizing some key terms related to misinformation. We then focus on the proliferation of deepfakes within our media environment. Lastly, we explore synthetic media for the civic good, including AI-enabled projects geared towards satire, investigative documentary, and public history. In Event of Moon Disaster, an award-winning deepfake art installation about the “failed” Apollo 11 moon landing, serves as a central case study.\n\nThis learning module also includes a suite of educator resources that consists of a syllabus, bibliography, and design prompts. We encourage teachers to draw on and adapt these resources for the purposes of their own classes.\n\nVisit Media Literacy in the Age of Deepfakes to access the learning module and educator resources. A sample of some of these materials can be found on OCW.\n\nThis course was produced by the MIT Center for Advanced Virtuality, with support from the J-WEL: Abdul Latif Jameel World Education Lab.","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture","Data Science, Analytics & Computer Technology","Education & Teaching","Engineering"],"topics":["Artificial Intelligence","Computer Science","Engineering","Fine Arts","Media Studies","Teaching and Education"],"levels":["Non-Credit"],"features":[],"term":"Spring 2021","instructors":["Prof. Joshua Glick","Prof. D. Fox Harrell"],"url":"https://ocw.mit.edu/courses/res-cms-001-media-literacy-in-the-age-of-deepfakes-spring-2021/","views":1609},{"id":"4.663+spring_2014","numbers":["4.663"],"title":"History of Urban Form: Locating Capitalism: Producing Early Modern Cities and Objects","summary":"What was the early modern economy like, and how did monetization impact artistic production, consumption, and the afterlife of objects? This seminar-format class explores major topics and themes concerning interconnections between early modern artistic and architectural creation and the economy. We will approach capitalism not as an inevitable system, but rather as a particular historical formation. Core course themes: commodification, production, and consumption, using case studies of the impact of the mercantile economy on chapels; palaces; prints and paintings, and their replication; and other material objects, including coins.","departments":["Architecture"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Architectural History and Criticism","Architecture","Art History","Fine Arts","Historiography","History","Humanities","Modern History"],"levels":["Graduate"],"features":["Instructor Insights","Presentation Assignments","Written Assignments with Examples"],"term":"Spring 2014","instructors":["Lauren Jacobi"],"url":"https://ocw.mit.edu/courses/4-663-history-of-urban-form-locating-capitalism-producing-early-modern-cities-and-objects-spring-2014/","views":1607},{"id":"HST.590+fall_2005","numbers":["HST.590","HST.502"],"title":"Biomedical Engineering Seminar Series: Topics in Medical Ethics and Responsible Conduct in Research","summary":"This seminar based course explores techniques for recognizing, analyzing, and resolving ethical dilemmas facing healthcare professionals and biomedical researchers in today’s highly regulated environment. Guest lectures by practicing clinicians, technologists, researchers, and regulators will include case studies, interactive small group discussions, and role-playing simulations. Professional conduct topics will include authorship, conflict of interest, data acquisition and management, and the protection of human subjects and animals involved in research programs.","departments":["Health Sciences and Technology"],"areas":["Business & Management","Humanities"],"topics":["Business","Business Ethics","Ethics","Humanities","Philosophy"],"levels":["Graduate"],"features":[],"term":"Fall 2005","instructors":["Dr. Jonathan Rosen"],"url":"https://ocw.mit.edu/courses/hst-590-biomedical-engineering-seminar-series-topics-in-medical-ethics-and-responsible-conduct-in-research-fall-2005-spring-2006/","views":1606},{"id":"24.910+spring_2007","numbers":["24.910"],"title":"Topics in Linguistic Theory: Laboratory Phonology","summary":"The goal of this course is to prepare you to engage in experimental investigations of questions related to linguistic theory, focusing on phonetics and phonology.","departments":["Linguistics and Philosophy"],"areas":["Engineering","Humanities"],"topics":["Electrical Engineering","Engineering","Humanities","Linguistics","Phonology","Signal Processing"],"levels":["Undergraduate"],"features":["Activity Assignments with Examples","Lecture Notes","Media Assignments with Examples"],"term":"Spring 2007","instructors":["Prof. Edward Flemming"],"url":"https://ocw.mit.edu/courses/24-910-topics-in-linguistic-theory-laboratory-phonology-spring-2007/","views":1606},{"id":"RES.6-002+spring_2008","numbers":["RES.6-002"],"title":"Electromagnetic Field Theory: A Problem Solving Approach","summary":"This text is an introductory treatment on the junior level for a two-semester electrical engineering course starting from the Coulomb-Lorentz force law on a point charge. The theory is extended by the continuous superposition of solutions from previously developed simpler problems leading to the general integral and differential field laws. Often the same problem is solved by different methods so that the advantages and limitations of each approach becomes clear. Sample problems and their solutions are presented for each new concept with great emphasis placed on classical models of physical phenomena such as polarization, conduction, and magnetization. A large variety of related problems that reinforce the text material are included at the end of each chapter for exercise and homework.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering","Science & Math"],"topics":["Differential Equations","Electrical Engineering","Electromagnetism","Engineering","Mathematics","Physics","Science"],"levels":["Undergraduate"],"features":["Problem Set Solutions","Problem Sets"],"term":"Spring 2008","instructors":["Markus Zahn"],"url":"https://ocw.mit.edu/courses/res-6-002-electromagnetic-field-theory-a-problem-solving-approach-spring-2008/","views":1605},{"id":"6.450+fall_2009","numbers":["6.450"],"title":"Principles of Digital Communication I","summary":"The course serves as an introduction to the theory and practice behind many of today’s communications systems. 6.450 forms the first of a two-course sequence on digital communication. The second class, 6.451 Principles of Digital Communication II, is offered in the spring.\n\nTopics covered include: digital communications at the block diagram level, data compression, Lempel-Ziv algorithm, scalar and vector quantization, sampling and aliasing, the Nyquist criterion, PAM and QAM modulation, signal constellations, finite-energy waveform spaces, detection, and modeling and system design for wireless communication.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering"],"topics":["Digital Systems","Electrical Engineering","Engineering","Telecommunications"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2009","instructors":["Soheil Feizi-Khankandi","Prof. Muriel Médard"],"url":"https://ocw.mit.edu/courses/6-450-principles-of-digital-communication-i-fall-2009/","views":1603},{"id":"11.360+fall_2005","numbers":["11.360"],"title":"Community Growth and Land Use Planning","summary":"This course combines a seminar format with fieldwork to examine strategies of planning and control for growth and land use, chiefly at the municipal level. Specific topics include growth and its local consequences; land use planning approaches; and implementation tools including innovative zoning and regulatory techniques, physical design, and natural systems integration. Projects are arranged with small teams serving municipal clients.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Public Administration","Public Policy","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Projects"],"term":"Fall 2005","instructors":["Prof. Eran Ben-Joseph","Prof. Terry Szold"],"url":"https://ocw.mit.edu/courses/11-360-community-growth-and-land-use-planning-fall-2005/","views":1599},{"id":"8.592J+spring_2011","numbers":["8.592J","HST.452J"],"title":"Statistical Physics in Biology","summary":"Statistical Physics in Biology is a survey of problems at the interface of statistical physics and modern biology. Topics include: bioinformatic methods for extracting information content of DNA; gene finding, sequence comparison, and phylogenetic trees; physical interactions responsible for structure of biopolymers; DNA double helix, secondary structure of RNA, and elements of protein folding; considerations of force, motion, and packaging; protein motors, membranes. We also look at collective behavior of biological elements, cellular networks, neural networks, and evolution.","departments":["Health Sciences and Technology","Physics"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Biostatistics","Computation and Systems Biology","Engineering","Physics","Science"],"levels":["Graduate"],"features":["Instructor Insights","Lecture Notes","Problem Sets","Projects"],"term":"Spring 2011","instructors":["Prof. Mehran Kardar","Prof. Leonid Mirny"],"url":"https://ocw.mit.edu/courses/8-592j-statistical-physics-in-biology-spring-2011/","views":1599},{"id":"21L.430+fall_2015","numbers":["21L.430","CMS.920"],"title":"Popular Culture and Narrative: Use and Abuse of the Fairy Tale","summary":"This course takes a deep look at a big subject. We ask where Fairy Tales come from and we examine the structure of Fairy Tales. We’ll also look at how Fairy Tales are conditioned by oral transmission and inherited story-telling techniques.","departments":["Comparative Media Studies/Writing","Literature"],"areas":["Humanities"],"topics":["Fiction","Humanities","International Literature","Literature"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Fall 2015","instructors":["Dr. William Donaldson"],"url":"https://ocw.mit.edu/courses/21l-430-popular-culture-and-narrative-use-and-abuse-of-the-fairy-tale-fall-2015/","views":1598},{"id":"11.471+spring_2010","numbers":["11.471"],"title":"Targeting the Poor: Local Economic Development in Developing Countries","summary":"This course treats public-sector policies, programs, and projects that attempt to increase employment through development-promoting measures in the economic realm, through support and regulation. It discusses the types of initiatives, tasks, and environments that are most conducive to equitable outcomes, and emphasizes throughout the understandings gained about why certain initiatives work and others don’t.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Developmental Economics","Economics","Global Poverty","Regional Planning","Social Justice","Social Science","Society","Sociology","The Developing World","Urban Studies"],"levels":["Graduate"],"features":["Presentation Assignments","Projects with Examples","Written Assignments"],"term":"Spring 2010","instructors":["Prof. Judith Tendler","Karin Brandt"],"url":"https://ocw.mit.edu/courses/11-471-targeting-the-poor-local-economic-development-in-developing-countries-spring-2010/","views":1597},{"id":"21W.763J+spring_2014","numbers":["21W.763J","CMS.309","CMS.809"],"title":"Transmedia Storytelling: Modern Science Fiction","summary":"Transmedia narratives exist across multiple storytelling platforms, using the advantages of each to enhance the experience of the audience. No matter which medium nor how many, the heart of any successful transmedia project is a good story. In this class we will spend time on the basics of solid storytelling in speculative fiction before we move on to how to translate those elements into various media. We will then explore how different presentations in different media can complement and enhance our storytelling. While we will read scholarly articles and discuss ideas about transmedia, this is primarily a class in making speculative fiction transmedia projects. We will analyze the strengths and weaknesses of various mediums and consider how they complement each other, and how by using several different media we can give the audience a more complete, rewarding, and immersive experience.","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Creative Writing","Digital Media","Fiction","Film and Video","Fine Arts","Humanities","Literature","Media Studies","Photography","Visual Arts"],"levels":["Undergraduate"],"features":["Lecture Notes","Presentation Assignments with Examples","Projects with Examples","Written Assignments with Examples"],"term":"Spring 2014","instructors":["Shariann Lewitt"],"url":"https://ocw.mit.edu/courses/21w-763j-transmedia-storytelling-modern-science-fiction-spring-2014/","views":1597},{"id":"RES.ENV-008+spring_2025","numbers":["RES.ENV-008"],"title":"Climate, Environment, and Sustainability Infusion Fellowship (CESIF)","summary":"The MIT Environmental Solutions Initiative’s Climate, Environment, and Sustainability Infusion Fellowship (CESIF) launched in February 2023 to empower faculty across MIT to cross their disciplinary boundaries and embed topics of climate science, the environment, and sustainability (CES) into the regular undergraduate curriculum.\n\nBy infusing CES topics into regular undergraduate subjects, MIT students were introduced to the critical challenges facing society today and the pathways toward planetary sustainability tomorrow.\n\nThe fellowship had a duration of two years, continuing until the spring of 2025. It provided faculty with funding and opportunities to build community in a cohort of faculty and instructors across disciplines, to engage in monthly meetings to learn about innovative CES content knowledge and pedagogical methodologies, to work with CES area experts and speakers, to workshop new instructional material, to get feedback from peers and ESI staff and visiting experts, to work closely with peer fellows for additional accountability and feedback, and to have access to a shared online platform for instructional support.","departments":[],"areas":["Education & Teaching","Energy, Climate & Sustainability","Science & Math"],"topics":["Climate","Curriculum and Teaching","Earth Science","Energy","Environmental Science","Science","Teaching and Education"],"levels":["Non-Credit"],"features":["Laboratory Assignments","Open Textbooks","Problem Set Solutions","Problem Sets"],"term":"Spring 2025","instructors":["Dr. Christopher Rabe"],"url":"https://ocw.mit.edu/courses/res-env-008-climate-environment-and-sustainability-infusion-fellowship-cesif-spring-2025/","views":1595},{"id":"2.964+fall_2006","numbers":["2.964"],"title":"Economics of Marine Transportation Industries","summary":"This half-semester course studies the economics of the principal markets related to marine transportation, environment, and natural resources. Topics include structures of the markets and industries involved; competition; impacts of policies and regulations. The course analyzes the relationship among industries, markets, technologies, and national policies, and introduces the concepts of national income accounts, sustainability, and intergenerational equity and their relationship to current economic practice.","departments":["Mechanical Engineering"],"areas":["Social Sciences"],"topics":["Economics","Industrial Organization","Social Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2006","instructors":["Dr. Hauke Kite-Powell"],"url":"https://ocw.mit.edu/courses/2-964-economics-of-marine-transportation-industries-fall-2006/","views":1593},{"id":"1.978+january-iap_2007","numbers":["1.978"],"title":"From Nano to Macro: Introduction to Atomistic Modeling Techniques","summary":"The objective of this course is to introduce large-scale atomistic modeling techniques and highlight its importance for solving problems in modern engineering sciences. We demonstrate how atomistic modeling can be used to understand how materials fail under extreme loading, involving unfolding of proteins and propagation of cracks.\n\nThis course was featured in an MIT Tech Talk article.","departments":["Civil and Environmental Engineering"],"areas":["Engineering"],"topics":["Civil Engineering","Computational Modeling and Simulation","Engineering","Mechanical Engineering","Microtechnology","Nanotechnology","Structural Engineering","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets","Projects with Examples"],"term":"January IAP 2007","instructors":["Prof. Markus Buehler"],"url":"https://ocw.mit.edu/courses/1-978-from-nano-to-macro-introduction-to-atomistic-modeling-techniques-january-iap-2007/","views":1590},{"id":"21L.707+spring_2005","numbers":["21L.707"],"title":"Arthurian Literature and Celtic Colonization","summary":"The course examines the earliest emergence of stories about King Arthur and the Knights of the Round Table in the context of the first wave of British Imperialism and the expanded powers of the Catholic Church during the twelfth and thirteenth centuries. The morphology of Arthurian romance will be set off against original historical documents and chronicle sources for the English conquests in Brittany, Wales, Scotland, and Ireland to understand the ways in which these new attitudes towards Empire were being mythologized. Authors will include Bede, Geoffrey of Monmouth, Chrétien de Troyes, Marie de France, Gerald of Wales, together with some lesser known works like the Perilous Graveyard, the Knight with the Sword, and Perlesvaus, or the High History of the Holy Graal. Special attention will be paid to how the narrative material of the story gets transformed according to the particular religious and political agendas of each new author.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","European History","History","Humanities","International Literature","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2005","instructors":["Prof. James Cain"],"url":"https://ocw.mit.edu/courses/21l-707-arthurian-literature-and-celtic-colonization-spring-2005/","views":1588},{"id":"21L.019+spring_2017","numbers":["21L.019"],"title":"Introduction to European and Latin American Fiction: Great Books on the Page and on the Screen","summary":"This subject serves as a broad introduction to the field of European and Latin American fiction. It is designed to help students acquire a general understanding of major fictional modes. We will pay attention not only to the literary movements these works represent, but also to the subtle interplay of history, geography, language and cultural norms that gave rise to specific literary forms. The books we read in this course are compelling, and film versions of five of the works we read give variety to the course and time to think about the interplay of film and print.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Creative Writing","Fiction","Humanities","International Literature","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2017","instructors":["Prof. Margery Resnick"],"url":"https://ocw.mit.edu/courses/21l-019-introduction-to-european-and-latin-american-fiction-great-books-on-the-page-and-on-the-screen-spring-2017/","views":1581},{"id":"12.742+fall_2006","numbers":["12.742"],"title":"Marine Chemistry","summary":"This course is an introduction to chemical oceanography. It describes reservoir models and residence time, major ion composition of seawater, inputs to and outputs from the ocean via rivers, the atmosphere, and the sea floor. Biogeochemical cycling within the oceanic water column and sediments, emphasizing the roles played by the formation, transport, and alteration of oceanic particles and the effects that these processes have on seawater composition. Cycles of carbon, nitrogen, phosphorus, oxygen, and sulfur. Uptake of anthropogenic carbon dioxide by the ocean. Material presented through lectures and student-led presentation and discussion of recent papers.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Earth Science","Engineering","Geobiology","Geochemistry","Hydrodynamics","Ocean Engineering","Oceanography","Science"],"levels":["Graduate"],"features":["Lecture Audio","Lecture Notes","Problem Sets"],"term":"Fall 2006","instructors":["Dr. Dierdre Toole","Dr. Karen Casciotti","Dr. Meg Tivey","Dr. Scott Doney","Dr. William Martin"],"url":"https://ocw.mit.edu/courses/12-742-marine-chemistry-fall-2006/","views":1581},{"id":"CMS.362+spring_2016","numbers":["CMS.362","CMS.862"],"title":"Civic Media Codesign Studio","summary":"This course is a service-learning, project-based studio course that focuses on collaborative design of civic media. Students will work in diverse teams with community partners to create civic media projects grounded in real-world community needs. This course covers co-design and lean UX methods, and best practices for including communities in iterative stages of project ideation, design, prototyping, testing, launch, and stewardship. Students should have an interest in collaboration with community-based organizations.","departments":["Comparative Media Studies/Writing"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["Business","Business Ethics","Communication","Economics","Globalization","Humanities","Innovation","Leadership","Political Science","Project Management","Public Administration","Social Science","Society","Sociology","Urban Studies"],"levels":["Undergraduate"],"features":["Presentation Assignments with Examples"],"term":"Spring 2016","instructors":["Prof. Sasha Costanza-Chock","Evan Henshaw-Plath"],"url":"https://ocw.mit.edu/courses/cms-362-civic-media-codesign-studio-spring-2016/","views":1580},{"id":"17.418+fall_2011","numbers":["17.418"],"title":"Field Seminar: International Relations Theory","summary":"This seminar provides an overview of the field of international relations. Each week, a different approach to explaining international relations will be examined. By surveying major concepts and theories in the field, the seminar will also assist graduate students in preparing for the comprehensive examination and further study in the department’s more specialized offerings in international relations.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["International Relations","Political Science","Social Science"],"levels":["Graduate","Undergraduate"],"features":[],"term":"Fall 2011","instructors":["Prof. M. Taylor Fravel"],"url":"https://ocw.mit.edu/courses/17-418-field-seminar-international-relations-theory-fall-2011/","views":1580},{"id":"EC.S07+fall_2004","numbers":["EC.S07"],"title":"Photovoltaic Solar Energy Systems","summary":"This class will study the behavior of photovoltaic solar energy systems, focusing on the behavior of “stand-alone” systems. The design of stand-alone photovoltaic systems will be covered. This will include estimation of costs and benefits, taking into account any available government subsidies. Introduction to the hardware elements and their behavior will be included.","departments":["Edgerton Center"],"areas":["Engineering","Science & Math"],"topics":["Atomic, Molecular, Optical Physics","Chemical Engineering","Electric Power","Electrical Engineering","Electromagnetism","Electronic Materials","Engineering","Materials Science and Engineering","Physics","Science","Transport Processes"],"levels":["Undergraduate"],"features":["Activity Assignments","Lecture Notes","Written Assignments"],"term":"Fall 2004","instructors":["Prof. Louis Bucciarelli"],"url":"https://ocw.mit.edu/courses/ec-s07-photovoltaic-solar-energy-systems-fall-2004/","views":1579},{"id":"15.277+fall_2008","numbers":["15.277"],"title":"Special Seminar in Communications: Leadership and Personal Effectiveness Coaching","summary":"This course builds on the work done concurrently in 15.280 Communication for Managers and 15.311 Organizational Processes in the first semester of the MBA program. 15.280 is offered for 6 units and 15.277 provides an additional 3 units for a total of 9 units in Managerial Communication. 15.277 acts as a lab component to 15.280 and provides students additional opportunities to hone their communication skills through a variety of in-class exercises. Emphasis is on both individual and team communication.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Communication","Leadership","Management","Social Science"],"levels":["Graduate"],"features":["Activity Assignments"],"term":"Fall 2008","instructors":["Prof. Christine Kelly"],"url":"https://ocw.mit.edu/courses/15-277-special-seminar-in-communications-leadership-and-personal-effectiveness-coaching-fall-2008/","views":1579},{"id":"WGS.693+spring_2009","numbers":["WGS.693"],"title":"Gender, Race, and the Complexities of Science and Technology: A Problem-Based Learning Experiment","summary":"What can we learn about science and technology–and what can we do with that knowledge? Who are “we” in these questions?–whose knowledge and expertise gets made into public policy, new medicines, topics of cultural and political discourse, science education, and so on? How can expertise and lay knowledge about science and technology be reconciled in a democratic society? How can we make sense of the interactions of living and non-living, humans and non-humans, individual and collectivities in the production of scientific knowledge and technologies?\n\nThe course takes these questions as entry points into an ever-growing body of work to which feminist, anti-racist, and other critical analysts and activists have made significant contributions. The course also takes these questions as an invitation to practice challenging the barriers of expertise, gender, race, class, and place that restrict wider access to and understanding of the production of scientific knowledge and technologies. In that spirit, students participate in an innovative, problem-based learning (PBL) approach that allows them to shape their own directions of inquiry and develop their skills as investigators and prospective teachers. At the same time the PBL cases engage students’ critical faculties as they learn about existing analyses of gender, race, and the complexities of science and technology, guided by individualized bibliographies co-constructed with the instructors and by the projects of the other students. Students from all fields and levels of preparation are encouraged to join the course.","departments":["Women's and Gender Studies"],"areas":["Education & Teaching","Social Sciences"],"topics":["Gender Studies","Society","Teaching and Education","Women's Studies"],"levels":["Graduate"],"features":["Activity Assignments","Presentation Assignments","Written Assignments"],"term":"Spring 2009","instructors":["Prof. Peter Taylor","Prof. Anne Fausto-Sterling"],"url":"https://ocw.mit.edu/courses/wgs-693-gender-race-and-the-complexities-of-science-and-technology-a-problem-based-learning-experiment-spring-2009/","views":1577},{"id":"14.661+fall_2017","numbers":["14.661"],"title":"Labor Economics I","summary":"This course aims to acquaint students with traditional and contemporary topics in labor economics and to encourage the development of independent research interests. The class provides a systematic development of the theory of labor supply, labor demand, and human capital. Topics covered include wage and employment determination, immigration, unemployment, equalizing differences, among many others. There is a particular emphasis on the interaction between theoretical and empirical modeling.","departments":["Economics"],"areas":["Social Sciences"],"topics":["Economics","Labor Economics","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Projects"],"term":"Fall 2017","instructors":["Prof. Daron Acemoglu","Prof. Joshua Angrist"],"url":"https://ocw.mit.edu/courses/14-661-labor-economics-i-fall-2017/","views":1577},{"id":"RES.18-012+spring_2022","numbers":["RES.18-012"],"title":"Algebra II Student Notes","summary":"Algebra II is the second semester of a year-long introduction to modern algebra. The course focuses on group representations, rings, ideals, fields, polynomial rings, modules, factorization, integers in quadratic number fields, field extensions, and Galois theory.\n\nThese notes, which were created by students in a recent on-campus 18.702 Algebra II class, are offered here to supplement the materials included in OCW’s version of 18.702. They have not been checked for accuracy by the instructors of that class or by other MIT faculty members.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics"],"levels":["Undergraduate"],"features":["Lecture Notes"],"term":"Spring 2022","instructors":[],"url":"https://ocw.mit.edu/courses/res-18-012-algebra-ii-student-notes-spring-2022/","views":1576},{"id":"MAS.962+fall_2002","numbers":["MAS.962"],"title":"Special Topics in Media Technology: Computational Semantics","summary":"How do words get their meanings? How can word meanings be represented and used by machines? We will explore three families of approaches to these questions from a computational perspective. Relational / structural methods such as semantic networks represent the meaning of words in terms of their relations to other words. Knowledge of the world through perception and action leads to the notion of external grounding, a process by which word meanings are ‘attached’ to the world. How an agent theorizes about, and conceptualizes its world provides yet another foundation for word meanings. We will examine each of these perspectives, and consider ways to integrate them.","departments":["Media Arts and Sciences"],"areas":["Art, Design & Architecture","Humanities","Science & Math"],"topics":["Computation","Fine Arts","Humanities","Linguistics","Mathematics","Media Studies","Semantics"],"levels":["Graduate"],"features":[],"term":"Fall 2002","instructors":["Prof. Deb Roy"],"url":"https://ocw.mit.edu/courses/mas-962-special-topics-in-media-technology-computational-semantics-fall-2002/","views":1575},{"id":"24.964+fall_2004","numbers":["24.964"],"title":"Topics in Phonology","summary":"This course introduces students to the theory and practice of modeling phonology, with an empirical focus on modeling the discovery of static phonotactics, the discovery of alternations, learning in the midst of variation and exceptions, and the discovery of gradient patterns. This course is also intended to provide hands-on experience with various aspects of using and developing models, including preparing training data, running simulations, and interpreting their results.","departments":["Linguistics and Philosophy"],"areas":["Engineering","Humanities"],"topics":["Computational Modeling and Simulation","Engineering","Humanities","Linguistics","Phonology","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Adam Albright"],"url":"https://ocw.mit.edu/courses/24-964-topics-in-phonology-fall-2004/","views":1574},{"id":"9.16+spring_2002","numbers":["9.16","9.161"],"title":"Cellular Neurophysiology","summary":"This course includes:\n\n• Surveying the molecular and cellular mechanisms of neuronal communication.\n• Coversion channels in excitable membrane, synaptic transmission, and synaptic plasticity.\n• Correlation of the properties of ion channels and synaptic transmission with their physiological function such as learning and memory.\n• Discussion of the organizational principles for the formation of functional neural networks at synaptic and cellular levels.","departments":["Brain and Cognitive Sciences"],"areas":["Health & Medicine","Science & Math"],"topics":["Anatomy and Physiology","Biology","Cell Biology","Health and Medicine","Neurobiology","Neuroscience","Science"],"levels":["Undergraduate"],"features":["Problem Sets"],"term":"Spring 2002","instructors":["Prof. Guosong Liu"],"url":"https://ocw.mit.edu/courses/9-16-cellular-neurophysiology-spring-2002/","views":1573},{"id":"4.273+fall_2001","numbers":["4.273"],"title":"Introduction to Design Inquiry","summary":"Introduction to Design Inquiry explores the nature and exercise of design intelligence. It aims to open avenues for further research and, along them, to open vistas on the teaching of design and on more mindful professional design practices.\n\nWe see design as processes located in individuals and groups, shaped by the formation and experience of each individual and by the characteristics of the groups that play a role in the design process. People construct the worlds they inhabit out of what they know and have experienced. So also does the designer, but the designer’s worlds must be possible for others to inhabit and, therefore, to construct. Indeed the success of a design depends in large part on the degree to which these constructive processes yield similar results.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architecture","Fine Arts"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2001","instructors":["Prof. Edith Ackermann","Prof. William Porter"],"url":"https://ocw.mit.edu/courses/4-273-introduction-to-design-inquiry-fall-2001/","views":1572},{"id":"24.910+spring_2003","numbers":["24.910"],"title":"Topics in Linguistics Theory","summary":"I realize that “Modes of Assertion” is a rather cryptic title for the course. What we will explore are ways of modulating the force of an assertion. This will engage us in formal semantics and pragmatics, the theory of speech acts and performative utterances, and quite a bit of empirical work on a not-too-well understood complex of data.\n\n“He obviously made a big mistake.”\n\n“It is obvious that he made a big mistake.”\n\nIf you’re like me you didn’t feel much of a difference. But now see what happens when you embed the two sentences:\n\n“We have to fire him, because he obviously made a big mistake.”\n\n“We have to fire him, because it is obvious that he made a big mistake.”\n\nOne of the two examples is unremarkable, the other suggests that the reason he needs to be fired is not that he made a big mistake but the fact that it is obvious that he did.\n\nWe will try to understand what is going on here and look at related constructions not just in English but also German (with its famous discourse particles like ja) and Quechua and Tibetan (with their systems of evidentiality-marking, as recently studied in dissertations from Stanford and UCLA).","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics","Semantics"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2003","instructors":["Prof. Kai von Fintel"],"url":"https://ocw.mit.edu/courses/24-910-topics-in-linguistics-theory-spring-2003/","views":1572},{"id":"15.978+spring_2007","numbers":["15.978"],"title":"Leadership Tools and Teams: A Product Development Lab","summary":"In this class you will be creating a leadership development tool for students like yourselves in the leadership program at Sloan. This tool might be a coaching guide for second-year pilots, a leadership workbook for MBA students to use during their summer employment, a leadership assessment for club presidents or a workshop on networking. You will be free to choose the tool that you want to develop, but by the end of the class there must be a product that can be used at Sloan. In addition, the tools must link in some way to the leadership model used at Sloan.","departments":["Sloan School of Management"],"areas":["Business & Management"],"topics":["Business","Leadership","Management"],"levels":["Graduate"],"features":["Lecture Notes","Projects"],"term":"Spring 2007","instructors":["Prof. Deborah Ancona"],"url":"https://ocw.mit.edu/courses/15-978-leadership-tools-and-teams-a-product-development-lab-spring-2007/","views":1571},{"id":"HST.535+fall_2004","numbers":["HST.535"],"title":"Principles and Practice of Tissue Engineering","summary":"The principles and practice of tissue engineering (and regenerative medicine) are taught by faculty of the Harvard-MIT Division of Health Sciences and Technology (HST) and Tsinghua University, Beijing, China. The principles underlying strategies for employing selected cells, biomaterial scaffolds, soluble regulators or their genes, and mechanical loading and culture conditions, for the regeneration of tissues and organs in vitro and in vivo are addressed. Differentiated cell types and stem cells are compared and contrasted for this application, as are natural and synthetic scaffolds. Methodology for the preparation of cells and scaffolds in practice is described. The rationale for employing selected growth factors is covered and the techniques for incorporating their genes into the scaffolds are examined. Discussion also addresses the influence of environmental factors including mechanical loading and culture conditions (e.g., static versus dynamic). Methods for fabricating tissue-engineered products and devices for implantation are taught. Examples of tissue engineering-based procedures currently employed clinically are analyzed as case studies.\n\nArchived webcast lecture videos for the Fall 2008 version of this class can be found at the HST.535 Fall 2008 website.","departments":["Health Sciences and Technology"],"areas":["Engineering"],"topics":["Biological Engineering","Biomaterials","Cell and Tissue Engineering","Engineering"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2004","instructors":["Prof. Myron Spector","Prof. Fu-Zhai Cui"],"url":"https://ocw.mit.edu/courses/hst-535-principles-and-practice-of-tissue-engineering-fall-2004/","views":1566},{"id":"RES.STS-001+fall_2024","numbers":["RES.STS-001"],"title":"MIT Project on Embodied Education","summary":"The MIT Project on Embodied Education aims to close the gap between the growing body of research on movement and the learning process and the pedagogical strategies that educators use, finding ways to integrate physical activity and academic instruction at all levels—for example, teaching elementary school math through yoga, middle school physics through martial arts, high school science through swimming, and college history through dance.","departments":["Science, Technology, and Society"],"areas":["Education & Teaching"],"topics":["Curriculum and Teaching","Teaching and Education"],"levels":["Non-Credit"],"features":["Activity Assignments with Examples"],"term":"Fall 2024","instructors":["Prof. Jennifer Light"],"url":"https://ocw.mit.edu/courses/res-sts-001-mit-project-on-embodied-education-fall-2024/","views":1565},{"id":"6.895+fall_2004","numbers":["6.895"],"title":"Essential Coding Theory","summary":"This course introduces the theory of error-correcting codes to computer scientists. This theory, dating back to the works of Shannon and Hamming from the late 40’s, overflows with theorems, techniques, and notions of interest to theoretical computer scientists. The course will focus on results of asymptotic and algorithmic significance. Principal topics include:\n\n• Construction and existence results for error-correcting codes.\n• Limitations on the combinatorial performance of error-correcting codes.\n• Decoding algorithms.\n• Applications in computer science.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Algorithms and Data Structures","Computer Science","Engineering","Theory of Computation"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2004","instructors":["Prof. Madhu Sudan"],"url":"https://ocw.mit.edu/courses/6-895-essential-coding-theory-fall-2004/","views":1562},{"id":"IDS.410J+spring_2013","numbers":["IDS.410J","12.844J","IDS.410J (formerly ESD.864)"],"title":"Modeling and Assessment for Policy","summary":"IDS.410J Modeling and Assessment for Policy explores how scientific information and quantitative models can be used to inform policy decision-making. Students will develop an understanding of quantitative modeling techniques and their role in the policy process through case studies and interactive activities. The course addresses issues such as analysis of scientific assessment processes, uses of integrated assessment models, public perception of quantitative information, methods for dealing with uncertainties, and design choices in building policy-relevant models. Examples used in this class focus on models and information used in earth system governance.","departments":["Earth, Atmospheric, and Planetary Sciences","Institute for Data, Systems, and Society"],"areas":["Data Science, Analytics & Computer Technology","Energy, Climate & Sustainability","Engineering","Science & Math","Social Sciences"],"topics":["Atmospheric Science","Climate Studies","Computational Modeling and Simulation","Computer Science","Data Mining","Earth Science","Engineering","Environmental Engineering","Environmental Management","Environmental Policy","Environmental Science","Public Administration","Public Policy","Science","Science and Technology Policy","Social Science","Sustainability","Systems Engineering"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Instructor Insights","Lecture Notes","Projects with Examples","Written Assignments with Examples"],"term":"Spring 2013","instructors":["Prof. Noelle Selin"],"url":"https://ocw.mit.edu/courses/ids-410j-modeling-and-assessment-for-policy-spring-2013/","views":1561},{"id":"6.092+january-iap_2006","numbers":["6.092"],"title":"Java Preparation for 6.170","summary":"This course focuses on introducing the language, libraries, tools and concepts of Javaᵀᴹ. The course is specifically targeted at students who intend to take 6.170 in the following term and feel they would struggle because they lack the necessary background. Topics include: Object-oriented programming, primitives, arrays, objects, inheritance, interfaces, polymorphism, hashing, data structures, collections, nested classes, floating point precision, defensive programming, and depth-first search algorithm.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Engineering","Programming Languages","Software Design and Engineering"],"levels":["Undergraduate"],"features":["Lecture Notes","Projects"],"term":"January IAP 2006","instructors":["Corey McCaffrey","Justin Mazzola Paluska","Lucy Mendel","Ray He","Robert Toscano","Scott Ostler"],"url":"https://ocw.mit.edu/courses/6-092-java-preparation-for-6-170-january-iap-2006/","views":1559},{"id":"24.961+fall_2014","numbers":["24.961"],"title":"Introduction to Phonology","summary":"This course serves as an introduction to the current research questions in phonological theory. Topics include metrical and prosodic structure, features and their phonetic basis in speech, acquisition and parsing, phonological domains, morphology, and language change and reconstruction. Activities include problem solving, squibs, and data collection.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics","Phonology"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2014","instructors":["Prof. Michael Kenstowicz"],"url":"https://ocw.mit.edu/courses/24-961-introduction-to-phonology-fall-2014/","views":1558},{"id":"6.451+spring_2005","numbers":["6.451"],"title":"Principles of Digital Communication II","summary":"This course is the second of a two-term sequence with 6.450. The focus is on coding techniques for approaching the Shannon limit of additive white Gaussian noise (AWGN) channels, their performance analysis, and design principles. After a review of 6.450 and the Shannon limit for AWGN channels, the course begins by discussing small signal constellations, performance analysis and coding gain, and hard-decision and soft-decision decoding. It continues with binary linear block codes, Reed-Muller codes, finite fields, Reed-Solomon and BCH codes, binary linear convolutional codes, and the Viterbi algorithm.\n\nMore advanced topics include trellis representations of binary linear block codes and trellis-based decoding; codes on graphs; the sum-product and min-sum algorithms; the BCJR algorithm; turbo codes, LDPC codes and RA codes; and performance of LDPC codes with iterative decoding. Finally, the course addresses coding for the bandwidth-limited regime, including lattice codes, trellis-coded modulation, multilevel coding and shaping. If time permits, it covers equalization of linear Gaussian channels.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering"],"topics":["Digital Systems","Electrical Engineering","Engineering","Telecommunications"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Lecture Videos","Problem Set Solutions","Problem Sets"],"term":"Spring 2005","instructors":["Prof. David Forney"],"url":"https://ocw.mit.edu/courses/6-451-principles-of-digital-communication-ii-spring-2005/","views":1558},{"id":"21A.506+fall_2016","numbers":["21A.506"],"title":"The Anthropology of Politics: U.S. Presidential Election Edition","summary":"This course examines the birth and international expansion of an American industry of political marketing. It focuses attention on the cultural processes, sociopolitical contexts and moral utopias that shape the practice of political marketing in the U.S. and in different countries. By looking at the debates and expert practices at the core of the business of politics, the course explores how the “universal” concept of democracy is interpreted and reworked through space and time, while examining how different cultural groups experimenting with political marketing understand the role of citizens in a democracy.","departments":["Anthropology"],"areas":["Social Sciences"],"topics":["American Politics","Anthropology","Ethnography","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments with Examples"],"term":"Fall 2016","instructors":["Maria Vidart-Delgado"],"url":"https://ocw.mit.edu/courses/21a-506-the-anthropology-of-politics-u-s-presidential-election-edition-fall-2016/","views":1558},{"id":"RES.18-008+fall_2011","numbers":["RES.18-008"],"title":"Calculus Revisited: Complex Variables, Differential Equations, and Linear Algebra","summary":"Calculus Revisited is a series of videos and related resources that covers the materials normally found in freshman- and sophomore-level introductory mathematics courses. Complex Variables, Differential Equations, and Linear Algebra is the third course in the series, consisting of 20 Videos, 3 Study Guides, and a set of Supplementary Notes. Students should have mastered the first two courses in the series (Single Variable Calculus and Multivariable Calculus) before taking this course.\n\nThe series was first released in 1972, but equally valuable today for students who are learning these topics for the first time.\n\nAbout the Instructor\n\nHerb Gross has taught math as senior lecturer at MIT and was the founding math department chair at Bunker Hill Community College. He is the developer of the Mathematics As A Second Language website, providing arithmetic and algebra materials to elementary and middle school teachers.\n\nAcknowledgements\n\nFunding for this resource was provided by the Gabriella and Paul Rosenbaum Foundation.\n\nOther Resources by Herb Gross\n\nCalculus Revisited: Single Variable Calculus\n\nCalculus Revisited: Multivariable Calculus","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Calculus","Differential Equations","Linear Algebra","Mathematics"],"levels":["Undergraduate"],"features":["Lecture Notes","Lecture Videos","Problem Set Solutions","Problem Sets"],"term":"Fall 2011","instructors":["Prof. Herbert Gross"],"url":"https://ocw.mit.edu/courses/res-18-008-calculus-revisited-complex-variables-differential-equations-and-linear-algebra-fall-2011/","views":1556},{"id":"17.486+fall_2016","numbers":["17.486"],"title":"Japan and East Asian Security","summary":"This course explores Japan’s role in world orders, past, present, and future. It focuses on Japanese conceptions of security; rearmament debates; the relationship of domestic politics to foreign policy; the impact of Japanese technological and economic transformation at home and abroad; alternative trade and security regimes; Japan’s response to 9/11; and relations with Asian neighbors, Russia, and the alliance with the United States.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Asian Studies","Economics","International Relations","Military Studies","Political Economy","Political Science","Public Administration","Security Studies","Social Science","Society"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Fall 2016","instructors":["Prof. Richard J. Samuels"],"url":"https://ocw.mit.edu/courses/17-486-japan-and-east-asian-security-fall-2016/","views":1556},{"id":"15.342J+fall_2004","numbers":["15.342J","11.262J"],"title":"Organizations and Environments","summary":"The goal of this doctoral course is to familiarize students with major conceptual frameworks, debates, and developments in contemporary organization theory. This is an inter-disciplinary domain of inquiry drawing primarily from sociology, and secondarily from economics, psychology, anthropology, and political science. The course focuses on inter-organizational processes, and also addresses the economic, institutional and cultural contexts that organizations must face.\n\nThis is an introduction to a vast and multifaceted domain of inquiry. Due to time limitations, this course will touch lightly on many important topics, and neglect others entirely; its design resembles more a map than an encyclopedia. Also, given the focus on theoretical matters, methodological issues will move to the background. Empirical material will be used to illustrate how knowledge is produced from a particular standpoint and trying to answer particular questions, leaving the bulk of the discussion on quantitative and qualitative procedures to seminars such as 15.347, 15.348, and the like.","departments":["Sloan School of Management","Urban Studies and Planning"],"areas":["Business & Management","Social Sciences"],"topics":["Anthropology","Business","Economics","Organizational Behavior","Political Science","Psychology","Social Science","Sociology"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. Pablo Boczkowski"],"url":"https://ocw.mit.edu/courses/15-342j-organizations-and-environments-fall-2004/","views":1556},{"id":"11.S945+fall_2013","numbers":["11.S945"],"title":"Urbanizing China: A Reflective Dialogue","summary":"The course explores the interactions between state and market as instigators of China’s urbanization, and its consequences of land, housing, transportation, energy, environment, migration, finance, urban inequality. Themes include the de-synchronization of China’s urbanization, potential differences between China’s past and future development, and differentiators between China’s urbanization and those of other countries. This discussion-based course asks students to participate in the conversation with the course instructor and guest lecturers by drawing upon their experiences and academic or professional backgrounds.","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Social Sciences"],"topics":["Economics","Environmental Policy","Geography","Political Economy","Public Administration","Social Science","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Presentation Assignments","Projects","Written Assignments"],"term":"Fall 2013","instructors":["Prof. Jinhua Zhao"],"url":"https://ocw.mit.edu/courses/11-s945-urbanizing-china-a-reflective-dialogue-fall-2013/","views":1556},{"id":"RES.10-001+spring_2026","numbers":["RES.10-001"],"title":"Making Science and Engineering Pictures: A Practical Guide to Presenting Your Work","summary":"In this course you will learn the basics of photography and gain an intriguing new perspective into the visual world. We will begin with a gentle introduction to the tools, and after that, we start in earnest.\n\nAlthough we will emphasize photographing science and engineering, most of the material will easily apply to other kinds of macro photography. The course’s video tutorials will be accompanied by assignments using a camera, a flatbed scanner, and mobile devices. You will discover how subtle changes in lighting, composition, and background contribute to creating more effective images. You will also learn to think graphically and present your photographs for journal figures, covers, and grant submissions. We will also host interviews with notable image makers and art directors.\n\nIn 2026, Felice Frankel updated the course with a video where she discusses AI and its role in generating images. Felice brings our attention to the pitfalls and ethics of using generative AI models to document research and outlines the necessary guardrails to ensure the production of honest and communicative images.\n\nAbout the Instructor\n\nFelice Frankel is an award-winning science photographer and research scientist in the Department of Chemical Engineering at the Massachusetts Institute of Technology. Felice’s images have been internationally published in books, journals, and magazines, including The New York Times, Nature, Science, National Geographic, and Discover. She is a fellow of the American Association for the Advancement of Science, a Gugghenheim Fellow, has received awards and grants from NSF, NEA, the Alfred P. Sloan Foundation, and was a senior research fellow in Harvard University’s Faculty of Arts and Sciences.\n\nAcknowledgements\n\nThe production of these videos is supported by OpenCourseWare, MITx, the Center for Materials Science and Engineering and the following departments: Chemical Engineering, Materials Science and Engineering and Mechanical Engineering.","departments":["Chemical Engineering"],"areas":["Art, Design & Architecture","Data Science, Analytics & Computer Technology","Education & Teaching","Engineering","Health & Medicine","Science & Math"],"topics":["Artificial Intelligence","Biology","Chemistry","Computer Science","Engineering","Fine Arts","Graphic Design","Health and Medicine","Photography","Physics","Science","Teaching and Education","Visual Arts"],"levels":["Undergraduate"],"features":["Activity Assignments with Examples","Instructor Insights","Lecture Audio","Lecture Videos"],"term":"Spring 2026","instructors":["Felice C. Frankel"],"url":"https://ocw.mit.edu/courses/res-10-001-making-science-and-engineering-pictures-a-practical-guide-to-presenting-your-work-spring-2026/","views":1554},{"id":"11.309J+fall_2003","numbers":["11.309J","4.215J"],"title":"Sites in Sight: Photography as Inquiry","summary":"This course explores photography as a disciplined way of seeing, of investigating landscapes and expressing ideas. Readings, observations, and photographs form the basis of discussions on landscape, light, significant detail, place, poetics, narrative, and how photography can inform design and planning, among other issues.","departments":["Architecture","Urban Studies and Planning"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Architecture","Environmental Design","Fine Arts","Photography","Social Science","Urban Planning","Urban Studies","Visual Arts"],"levels":["Graduate"],"features":["Media Assignments with Examples","Written Assignments"],"term":"Fall 2003","instructors":["Prof. Anne Whiston Spirn"],"url":"https://ocw.mit.edu/courses/11-309j-sites-in-sight-photography-as-inquiry-fall-2003/","views":1554},{"id":"22.39+fall_2006","numbers":["22.39"],"title":"Integration of Reactor Design, Operations, and Safety","summary":"This course integrates studies of engineering sciences, reactor physics and safety assessment into nuclear power plant design. Topics include materials issues in plant design and operations, aspects of thermal design, fuel depletion and fission-product poisoning, and temperature effects on reactivity, safety considerations in regulations and operations, such as the evolution of the regulatory process, the concept of defense in depth, General Design Criteria, accident analysis, probabilistic risk assessment, and risk-informed regulations.","departments":["Nuclear Science and Engineering"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math"],"topics":["Energy","Engineering","Nuclear Energy","Nuclear Engineering","Nuclear Materials","Nuclear Physics","Nuclear Systems, Policy, and Economics","Physics","Science"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets","Written Assignments"],"term":"Fall 2006","instructors":["Prof. George Apostolakis","Prof. Neil Todreas","Prof. Ronald Ballinger","Prof. Andrew Kadak"],"url":"https://ocw.mit.edu/courses/22-39-integration-of-reactor-design-operations-and-safety-fall-2006/","views":1553},{"id":"11.310J+spring_2002","numbers":["11.310J","4.243J"],"title":"Media Technology and City Design and Development","summary":"This workshop explores the potential of media technology and the Internet to enhance communication and transform city design and community development in inner-city neighborhoods. The class introduces a variety of methods for describing or representing a place and its residents, for simulating actions and changes, for presenting visions of the future, and for engaging multiple actors in the process of envisioning change and guiding action. Students will engage two neighborhoods: the Mill Creek neighborhood of West Philadelphia, PA, and the Brightwood/Northend neighborhood of Springfield, MA. Students will meet real people working on real projects, put theory into practice, and reflect on insights gained in the process. Our hope is that student work will contribute to new initiatives in both communities.\n\nThe class Web site can be found here: Media Technology and City Design and Development. It is sponsored by the West Philadelphia Landscape Project and the Center for Reflective Community Practice.","departments":["Architecture","Urban Studies and Planning"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Communication","Community Development","Digital Media","Fine Arts","Media Studies","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Undergraduate"],"features":["Projects with Examples","Written Assignments with Examples"],"term":"Spring 2002","instructors":["Prof. Ceasar McDowell","Prof. Anne Whiston Spirn"],"url":"https://ocw.mit.edu/courses/11-310j-media-technology-and-city-design-and-development-spring-2002/","views":1550},{"id":"21G.503+fall_2019","numbers":["21G.503"],"title":"Japanese III","summary":"Students further develop their skills in Japanese speaking, listening, reading, and writing in this intermediate language course. This course involves continued vocabulary and kanji building.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","Japanese","Language"],"levels":["Undergraduate"],"features":["Exams","Instructor Insights","Written Assignments"],"term":"Fall 2019","instructors":["Dr. Takako Aikawa","Masami Ikeda-Lamm","Wakana Maekawa","Emiko Rafique"],"url":"https://ocw.mit.edu/courses/21g-503-japanese-iii-fall-2019/","views":1549},{"id":"4.163J+spring_2005","numbers":["4.163J","11.332J"],"title":"Urban Design Studio: Providence","summary":"This studio discusses in great detail the design of urban environments, specifically in Providence, RI. It will propose strategies for change in large areas of cities, to be developed over time, involving different actors. Fitting forms into natural, man-made, historical, and cultural contexts; enabling desirable activity patterns; conceptualizing built form; providing infrastructure and service systems; guiding the sensory character of development: all are topics covered in the studio. The course integrates architecture and planning students in joint work and requires individual designs and planning guidelines as a final product.","departments":["Architecture","Urban Studies and Planning"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Architectural Design","Architecture","Environmental Design","Fine Arts","Social Science","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Design Assignments","Projects with Examples"],"term":"Spring 2005","instructors":["Prof. Greg Morrow","Prof. Michael Dennis"],"url":"https://ocw.mit.edu/courses/4-163j-urban-design-studio-providence-spring-2005/","views":1549},{"id":"HST.723J+spring_2005","numbers":["HST.723J","9.285J"],"title":"Neural Coding and Perception of Sound","summary":"This course focuses on neural structures and mechanisms mediating the detection, localization and recognition of sounds. Discussions cover how acoustic signals are coded by auditory neurons, the impact of these codes on behavioral performance, and the circuitry and cellular mechanisms underlying signal transformations. Topics include temporal coding, neural maps and feature detectors, learning and plasticity, and feedback control. General principles are conveyed by theme discussions of auditory masking, sound localization, musical pitch, speech coding, and cochlear implants.","departments":["Brain and Cognitive Sciences","Health Sciences and Technology"],"areas":["Health & Medicine","Science & Math"],"topics":["Biology","Cognitive Science","Health and Medicine","Neurobiology","Neuroscience","Science","Sensory-Neural Systems"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2005","instructors":["Dr. Bertrand Delgutte","Prof. Jennifer R. Melcher","Prof. John Guinan","Prof. M. Christian Brown","Prof. Andrew Oxenham"],"url":"https://ocw.mit.edu/courses/hst-723j-neural-coding-and-perception-of-sound-spring-2005/","views":1547},{"id":"6.803+spring_2019","numbers":["6.803","6.833"],"title":"The Human Intelligence Enterprise","summary":"This course analyzes seminal work directed at the development of a computational understanding of human intelligence, such as work on learning, language, vision, event representation, commonsense reasoning, self reflection, story understanding, and analogy. It reviews visionary ideas of Turing, Minsky, and other influential thinkers and examines the implications of work on brain scanning, developmental psychology, and cognitive psychology. There is an emphasis on discussion and analysis of original papers; students taking the graduate version complete additional exercises and a substantial term project.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Artificial Intelligence","Cognitive Science","Computer Science","Engineering","Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2019","instructors":["Patrick Henry Winston"],"url":"https://ocw.mit.edu/courses/6-803-the-human-intelligence-enterprise-spring-2019/","views":1547},{"id":"4.184+spring_2002","numbers":["4.184"],"title":"Architectural Design Workshops: Computational Design for Housing","summary":"An intensive nine day remote collaborative workshop involving MIT and Miyagi University in Japan. The objective is to develop a small housing project using shape computation as a design methodology. Students will use and test new interactive software for designing, sharing applications with overseas partners, presenting projects on an Internet workspace, and critiquing design proposals through the web and other advanced digital technologies. Students will be expected to do most of their work in class.","departments":["Architecture"],"areas":["Art, Design & Architecture","Engineering","Social Sciences"],"topics":["Architectural Design","Architecture","Computational Science and Engineering","Engineering","Fine Arts","Housing Development","Social Science","Systems Engineering","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2002","instructors":["Gabriela Celani","Miranda McGill","Prof. Terry Knight"],"url":"https://ocw.mit.edu/courses/4-184-architectural-design-workshops-computational-design-for-housing-spring-2002/","views":1546},{"id":"8.902+fall_2004","numbers":["8.902"],"title":"Astrophysics II","summary":"This is the second course in a two-semester sequence on astrophysics. Topics include galactic dynamics, groups and clusters on galaxies, phenomenological cosmology, Newtonian cosmology, Roberston-Walker models, and galaxy formation.","departments":["Physics"],"areas":["Science & Math"],"topics":["Astrophysics","Physics","Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2004","instructors":["Prof. Paul Schechter"],"url":"https://ocw.mit.edu/courses/8-902-astrophysics-ii-fall-2004/","views":1546},{"id":"3.987+spring_2006","numbers":["3.987"],"title":"Human Origins and Evolution","summary":"This course examines the dynamic interrelations among physical and behavioral traits of humans, environment, and culture to provide an integrated framework for studying human biological evolution and modern diversity. Topics include issues in morphological evolution and adaptation; fossil and cultural evidence for human evolution from earliest times through the Pleistocene; evolution of tool use and social behavior; modern human variation and concepts of race. The class also studies stone artifacts and fossil specimens.","departments":["Materials Science and Engineering"],"areas":["Social Sciences"],"topics":["Anthropology","Archaeology","Biological Anthropology","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2006","instructors":["Dr. Harry Merrick"],"url":"https://ocw.mit.edu/courses/3-987-human-origins-and-evolution-spring-2006/","views":1545},{"id":"WGS.181+fall_2017","numbers":["WGS.181"],"title":"Queer Cinema and Visual Culture","summary":"This course analyzes mainstream, popular films produced in the post-World War II 20th century U.S. as cultural texts that shed light on ongoing historical struggles over gender identity and appropriate sexual behaviors. It traces the history of LGBTQ/queer film through the 20th and into the 21st century. It also examines the effect of the Hollywood Production Code and censorship of sexual themes and content, and the subsequent subversion of queer cultural production in embedded codes and metaphors. In addition, this course also considers the significance of these films as artifacts and examples of various aspects of queer theory.","departments":["Women's and Gender Studies"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["African American Studies","American History","Film and Video","Fine Arts","Gender Studies","History","Humanities","Society","Visual Arts"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2017","instructors":["Dr. K.J. Surkan"],"url":"https://ocw.mit.edu/courses/wgs-181-queer-cinema-and-visual-culture-fall-2017/","views":1543},{"id":"4.A21+fall_2006","numbers":["4.A21"],"title":"Stories Without Words: Photographing the First Year","summary":"The transition from high school and home to college and a new living environment can be a fascinating and interesting time, made all the more challenging and interesting by being at MIT. More than recording the first semester through a series of snapshots, this freshman seminar will attempt to teach photography as a method of seeing and a tool for better understanding new surroundings. Over the course of the semester, students will develop a body of work through a series of assignments, and then attempt to describe the conditions and emotions of their new environment in a cohesive final presentation.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Fine Arts","Photography","Visual Arts"],"levels":["Undergraduate"],"features":["Image Gallery","Lecture Notes","Media Assignments","Projects with Examples"],"term":"Fall 2006","instructors":["Mr. Keith McCluskey"],"url":"https://ocw.mit.edu/courses/4-a21-stories-without-words-photographing-the-first-year-fall-2006/","views":1542},{"id":"12.950+january-iap_2010","numbers":["12.950"],"title":"Parallel Programming for Multicore Machines Using OpenMP and MPI","summary":"This course introduces fundamentals of shared and distributed memory programming, teaches you how to code using openMP and MPI respectively, and provides hands-on experience of parallel computing geared towards numerical applications.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Engineering","Software Design and Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"January IAP 2010","instructors":["Dr. Constantinos Evangelinos"],"url":"https://ocw.mit.edu/courses/12-950-parallel-programming-for-multicore-machines-using-openmp-and-mpi-january-iap-2010/","views":1541},{"id":"11.360+fall_2003","numbers":["11.360"],"title":"Community Growth and Land Use Planning","summary":"This subject explores the techniques, processes, and personal and professional skills required to effectively manage growth and land use change. While primarily focused on the planning practice in the United States, the principles and techniques reviewed and presented may have international application. This course is not for bystanders; it is designed for those who wish to become actively involved or exposed to the planning discipline and profession as it is practiced today, and as it may need to be practiced in the future.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Public Administration","Public Policy","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Fall 2003","instructors":["Prof. Terry Szold"],"url":"https://ocw.mit.edu/courses/11-360-community-growth-and-land-use-planning-fall-2003/","views":1540},{"id":"21L.004+spring_2009","numbers":["21L.004"],"title":"Reading Poetry","summary":"“Reading Poetry” has several aims: primarily, to increase the ways you can become more engaged and curious readers of poetry; to increase your confidence as writers thinking about literary texts; and to provide you with the language for literary description. The course is not designed as a historical survey course but rather as an introductory approach to poetry from various directions – as public or private utterances; as arranged imaginative shapes; and as psychological worlds, for example. One perspective offered is that poetry offers intellectual, moral and linguistic pleasures as well as difficulties to our private lives as readers and to our public lives as writers. Expect to hear and read poems aloud and to memorize lines; the class format will be group discussion, occasional lecture.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Criticism","Humanities","Literature","Poetry"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2009","instructors":["Kim Vaeth"],"url":"https://ocw.mit.edu/courses/21l-004-reading-poetry-spring-2009/","views":1540},{"id":"21H.601+fall_2006","numbers":["21H.601"],"title":"Islam, the Middle East, and the West","summary":"This course aims to provide students with a general overview of basic themes and issues in Middle Eastern history from the rise of Islam to the present, with an emphasis on the encounters and exchanges between the “Middle East” (Southwest Asia and North Africa) and the “West” (Europe and the United States).","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["History","Humanities","Middle Eastern History","Middle Eastern Studies","Society","World History"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2006","instructors":["Dr. Mériam Belli"],"url":"https://ocw.mit.edu/courses/21h-601-islam-the-middle-east-and-the-west-fall-2006/","views":1538},{"id":"3.052+spring_2007","numbers":["3.052"],"title":"Nanomechanics of Materials and Biomaterials","summary":"This course focuses on the latest scientific developments and discoveries in the field of nanomechanics, the study of forces and motion on extremely tiny (10\\-9 m) areas of synthetic and biological materials and structures. At this level, mechanical properties are intimately related to chemistry, physics, and quantum mechanics. Most lectures will consist of a theoretical component that will then be compared to recent experimental data (case studies) in the literature. The course begins with a series of introductory lectures that describes the normal and lateral forces acting at the atomic scale. The following discussions include experimental techniques in high resolution force spectroscopy, atomistic aspects of adhesion, nanoindentation, molecular details of fracture, chemical force microscopy, elasticity of single macromolecular chains, intermolecular interactions in polymers, dynamic force spectroscopy, biomolecular bond strength measurements, and molecular motors.","departments":["Materials Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biomaterials","Chemistry","Classical Mechanics","Engineering","Materials Science and Engineering","Nanotechnology","Physical Chemistry","Physics","Quantum Mechanics","Science"],"levels":["Undergraduate"],"features":["Demonstration Videos","Exam Solutions","Exams","Lecture Notes","Simulation Videos","Written Assignments with Examples"],"term":"Spring 2007","instructors":["Prof. Christine Ortiz"],"url":"https://ocw.mit.edu/courses/3-052-nanomechanics-of-materials-and-biomaterials-spring-2007/","views":1538},{"id":"12.491+fall_2007","numbers":["12.491"],"title":"Biogeochemistry of Sulfur","summary":"This course is designed for advanced undergraduate and graduate students with an interest in using primary research literature to discuss and learn about current research around sulfur biogeochemistry and astrobiology.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Biochemistry","Biology","Earth Science","Geobiology","Geochemistry","Planetary Science","Science"],"levels":["Graduate"],"features":["Projects"],"term":"Fall 2007","instructors":["Prof. Roger Summons","Prof. Shuhei Ono"],"url":"https://ocw.mit.edu/courses/12-491-biogeochemistry-of-sulfur-fall-2007/","views":1537},{"id":"12.425+fall_2007","numbers":["12.425"],"title":"Extrasolar Planets: Physics and Detection Techniques","summary":"This course covers the basic principles of planet atmospheres and interiors applied to the study of extrasolar planets (exoplanets). We focus on fundamental physical processes related to observable exoplanet properties. We also provide a quantitative overview of detection techniques and an introduction to the feasibility of the search for Earth-like planets, biosignatures and habitable conditions on exoplanets.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Astrophysics","Atmospheric Science","Earth Science","Geophysics","Physics","Planetary Science","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2007","instructors":["Prof. Sara Seager"],"url":"https://ocw.mit.edu/courses/12-425-extrasolar-planets-physics-and-detection-techniques-fall-2007/","views":1536},{"id":"21L.003+fall_2015","numbers":["21L.003"],"title":"Reading Fiction: Imaginary Journeys","summary":"Great works of fiction often take us to far-off places; they sometimes conduct us on journeys toward a deeper understanding of what’s right next door. We’ll read, discuss, and interpret a range of short and short-ish works: The reading list will be chosen from among such texts as “Gilgamesh,” Homer’s Odyssey (excerpts), Bunyan’s The Pilgrim’s Progress (excerpts), Swift’s Gulliver’s Travels, Mary Shelley’s Frankenstein, Conrad’s Heart of Darkness, Saleh’s Season of Migration to the North, Woolf’s To the Lighthouse, John Cheever’s “The Swimmer,” Coetzee’s The Life and Times of Michael K, Irving’s “Rip Van Winkle,” Toni Morrison’s Jazz, H. G. Wells’ The Time Machine, Twain’s The Adventures of Huckleberry Finn, Beckett’s How It Is, Calvino’s Invisible Cities, Forster’s A Passage to India. As a CI-H class, this subject will involve substantial practice in argumentative writing and oral communication.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2015","instructors":["Prof. James Buzard"],"url":"https://ocw.mit.edu/courses/21l-003-reading-fiction-imaginary-journeys-fall-2015/","views":1536},{"id":"MAS.965+fall_2004","numbers":["MAS.965"],"title":"Social Visualization","summary":"Millions of people are on-line today and the number is rapidly growing - yet this virtual crowd is often invisible. In this course we will examine ways of visualizing people, their activities and their interactions. Students will study the cognitive and cultural basis for social visualization through readings drawn from sociology, psychology and interface design and they will explore new ways of depicting virtual crowds and mapping electronic spaces through a series of design exercises.","departments":["Media Arts and Sciences"],"areas":["Art, Design & Architecture","Data Science, Analytics & Computer Technology","Engineering","Social Sciences"],"topics":["Anthropology","Computer Science","Engineering","Fine Arts","Graphics and Visualization","Media Studies","Social Anthropology","Social Science"],"levels":["Graduate"],"features":["Projects with Examples"],"term":"Fall 2004","instructors":["Prof. Judith Donath"],"url":"https://ocw.mit.edu/courses/mas-965-social-visualization-fall-2004/","views":1534},{"id":"18.304+spring_2015","numbers":["18.304"],"title":"Undergraduate Seminar in Discrete Mathematics","summary":"This course is a student-presented seminar in combinatorics, graph theory, and discrete mathematics in general. Instruction and practice in written and oral communication is emphasized, with participants reading and presenting papers from recent mathematics literature and writing a final paper in a related topic.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Applied Mathematics","Discrete Mathematics","Mathematics"],"levels":["Undergraduate"],"features":["Instructor Insights","Problem Sets","Projects with Examples","Written Assignments"],"term":"Spring 2015","instructors":["Dr. Omer Tamuz"],"url":"https://ocw.mit.edu/courses/18-304-undergraduate-seminar-in-discrete-mathematics-spring-2015/","views":1533},{"id":"4.144+spring_2006","numbers":["4.144"],"title":"Architectural Design, Level II: New Orleans Studio","summary":"The project for this studio is to design a demonstration project for a site near the French Quarter in New Orleans. The objectives of the project are the following:\n\n• To design more intense housing, community, educational and commercial facilities in four to six story buildings.\n• To explore the “space between” buildings as a way of designing and shaping objects.\n• To design at three scales - dwelling, cluster and overall.\n• To design dwellings where the owners may be able to help build and gain a skill for employment.\n• To provide/design facilities that can help the residents to gain education and skills.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architecture","Environmental Design","Fine Arts"],"levels":["Graduate"],"features":["Design Assignments","Projects with Examples"],"term":"Spring 2006","instructors":["Prof. Jan Wampler"],"url":"https://ocw.mit.edu/courses/4-144-architectural-design-level-ii-new-orleans-studio-spring-2006/","views":1532},{"id":"15.565J+spring_2002","numbers":["15.565J","15.578J","IDS.345J (formerly ESD.565J)"],"title":"Integrating eSystems & Global Information Systems","summary":"The strategic importance of information technology is now widely accepted. It has also become increasingly clear that the identification of strategic applications alone does not result in success for an organization. A careful coordination of strategic applications, information technologies, and organizational structures must be made to attain success. This course addresses strategic, technological, and organizational connectivity issues to support effective and meaningful integration of information and systems. This course is especially relevant to those who wish to effectively exploit information technology and create new business processes and opportunities.","departments":["Institute for Data, Systems, and Society","Sloan School of Management"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering"],"topics":["Business","Computer Science","Data Mining","Electrical Engineering","Engineering","Information Technology","Organizational Behavior","Telecommunications"],"levels":["Undergraduate","Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Projects","Written Assignments with Examples"],"term":"Spring 2002","instructors":["Prof. Stuart Madnick"],"url":"https://ocw.mit.edu/courses/15-565j-integrating-esystems-global-information-systems-spring-2002/","views":1531},{"id":"9.916-A+spring_2003","numbers":["9.916-A"],"title":"Probability and Causality in Human Cognition","summary":"Probability theory captures a number of essential characteristics of human cognition, including aspects of perception, reasoning, belief revision, and learning. Expressions of degree of belief were used in language long before people began codifying the laws of probability theory. This course explores the history and debates over codifying the laws of probability, how probability theory applies to specific cognitive processes, how it relates to the human understanding of causality, and how new computational approaches to causal modeling provide a framework for understanding human probabilistic reasoning.\n\nThis class is suitable for advanced undergraduates or graduate students specializing in cognitive science, artificial intelligence, and related fields.","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math"],"topics":["Cognitive Science","Mathematics","Probability and Statistics","Science"],"levels":["Graduate"],"features":[],"term":"Spring 2003","instructors":["Prof. Joshua Tenenbaum"],"url":"https://ocw.mit.edu/courses/9-916-a-probability-and-causality-in-human-cognition-spring-2003/","views":1531},{"id":"21G.714+spring_2003","numbers":["21G.714"],"title":"Spanish for Bilingual Students","summary":"Spanish for Bilingual Students is an intermediate course designed principally for heritage learners, but which includes other students interested in specific content areas, such as US Latino immigration, identity, ethnicity, education and representation in the media. Linguistic goals include vocabulary acquisition, improvement in writing, and enhancement of formal communicative skills.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","Language","Literature","Spanish"],"levels":["Undergraduate"],"features":["Activity Assignments","Projects with Examples","Written Assignments"],"term":"Spring 2003","instructors":["Douglas Morgenstern"],"url":"https://ocw.mit.edu/courses/21g-714-spanish-for-bilingual-students-spring-2003/","views":1531},{"id":"21L.016+spring_2009","numbers":["21L.016"],"title":"Learning from the Past: Drama, Science, Performance","summary":"This class explores the creation (and creativity) of the modern scientific and cultural world through study of western Europe in the 17th century, the age of Descartes and Newton, Shakespeare, Milton and Ford. It compares period thinking to present-day debates about the scientific method, art, religion, and society. This team-taught, interdisciplinary subject draws on a wide range of literary, dramatic, historical, and scientific texts and images, and involves theatrical experimentation as well as reading, writing, researching and conversing.\n\nThe primary theme of the class is to explore how England in the mid-seventeenth century became “a world turned upside down” by the new ideas and upheavals in religion, politics, and philosophy, ideas that would shape our modern world. Paying special attention to the “theatricality” of the new models and perspectives afforded by scientific experimentation, the class will read plays by Shakespeare, Tate, Brecht, Ford, Churchill, and Kushner, as well as primary and secondary texts from a wide range of disciplines. Students will also compose and perform in scenes based on that material.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Drama","European History","History","History of Science and Technology","Humanities","International Literature","Literature"],"levels":["Undergraduate"],"features":["Image Gallery","Presentation Assignments","Projects with Examples","Written Assignments"],"term":"Spring 2009","instructors":["Prof. Diana Henderson","Prof. Janet Sonenberg"],"url":"https://ocw.mit.edu/courses/21l-016-learning-from-the-past-drama-science-performance-spring-2009/","views":1529},{"id":"21G.341+spring_2014","numbers":["21G.341"],"title":"Contemporary French Film and Social Issues","summary":"This course covers issues in contemporary French society as expressed through movies made in the 2000s. Topics include France’s national self-image, the women’s movement, sexuality and gender, family life and class structure, post-colonialism and immigration, and American cultural imperialism. Films by Lelouch, Audiard, Doillon, Denis, Klapisch, Resnais, Rouan, Balasko, Collard, Dridi, Kassovitz, and others. Readings from French periodicals. Films shown with English subtitles. Taught in French.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["European and Russian Studies","Film and Video","Fine Arts","French","Humanities","International Literature","Language","Literature","Society","Visual Arts"],"levels":["Undergraduate"],"features":["Instructor Insights","Presentation Assignments","Written Assignments"],"term":"Spring 2014","instructors":["Catherine E Clark"],"url":"https://ocw.mit.edu/courses/21g-341-contemporary-french-film-and-social-issues-spring-2014/","views":1528},{"id":"STS.462+spring_2006","numbers":["STS.462"],"title":"Social and Political Implications of Technology","summary":"This course is a graduate reading seminar, in which historical and contemporary studies are used to explore the interaction of technology with social and political values. Emphasis is on how technological devices, structures, and systems influence the organization of society and the behavior of its members. Examples are drawn from the technologies of war, transportation, communication, production, and reproduction.","departments":["Science, Technology, and Society"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","History","History of Science and Technology","Humanities","Political Science","Social Science","Sociology"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Spring 2006","instructors":["Prof. David Mindell","Prof. Merritt Roe Smith"],"url":"https://ocw.mit.edu/courses/sts-462-social-and-political-implications-of-technology-spring-2006/","views":1528},{"id":"12.480+fall_2006","numbers":["12.480"],"title":"Thermodynamics for Geoscientists","summary":"In this course, principles of thermodynamics are used to infer the physical conditions of formation and modification of igneous and metamorphic rocks. The course includes phase equilibria of homogeneous and heterogeneous systems and thermodynamic modeling of non-ideal crystalline solutions. It also surveys the processes that lead to the formation of metamorphic and igneous rocks in the major tectonic environments in the Earth’s crust and mantle.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geology","Geophysics","Physics","Science","Thermodynamics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2006","instructors":["Prof. Timothy Grove"],"url":"https://ocw.mit.edu/courses/12-480-thermodynamics-for-geoscientists-fall-2006/","views":1528},{"id":"RES.7-009+fall_2022","numbers":["RES.7-009"],"title":"7.InT: Inclusive Teaching Module","summary":"The Inclusive Teaching Module is both a standalone online resource for those looking to explore materials related to inclusive teaching as well as an integral part of a blended workshop available to use at your own institution. If you are looking to facilitate a blended workshop using this material, please download the Facilitation Guide and Appendix files to get started!\n\nAs part of the Open Learning Library (OLL), this course is free to use. You have the option to sign up and enroll if you want to track your progress, or you can view and use all the materials without enrolling. Resources on OLL allow learners to learn at their own pace while receiving immediate feedback through interactive content and exercises.","departments":["Biology"],"areas":["Education & Teaching"],"topics":["Curriculum and Teaching","Teaching and Education"],"levels":["Non-Credit"],"features":["Instructor Insights","Multiple Assignment Types with Solutions","Readings","Videos"],"term":"Fall 2022","instructors":["Dr. Darcy G. Gordon","Prof. Catherine Drennan"],"url":"https://ocw.mit.edu/courses/res-7-009-7-int-inclusive-teaching-module-fall-2022/","views":1526},{"id":"21H.007J+fall_2012","numbers":["21H.007J","21L.014J"],"title":"Empire: Introduction to Ancient and Medieval Studies","summary":"This course is an investigation of the Roman empire of Augustus, the Frankish empire of Charlemagne, and the English empire in the age of the Hundred Years War. Students examine different types of evidence, read across a variety of disciplines, and develop skills to identify continuities and changes in ancient and medieval societies. Each term this course is different, looking at different materials from a variety of domains to explore ancient and mideveal studies. This version is a capture of the course as it was taught in 2012, and does not reflect how it is taught currently.","departments":["History","Literature"],"areas":["Humanities"],"topics":["Ancient History","European History","History","Humanities"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2012","instructors":["Prof. Arthur Bahr","Prof. William Broadhead","Prof. Eric J Goldberg"],"url":"https://ocw.mit.edu/courses/21h-007j-empire-introduction-to-ancient-and-medieval-studies-fall-2012/","views":1525},{"id":"9.201+spring_2000","numbers":["9.201"],"title":"Advanced Animal Behavior","summary":"The course includes survey and special topics designed for graduate students in the brain and cognitive sciences. It emphasizes ethological studies of natural behavior patterns and their analysis in laboratory work, with contributions from field biology (mammology, primatology), sociobiology, and comparative psychology. It stresses mammalian behavior but also includes major contributions from studies of other vertebrates and of invertebrates. It covers some applications of animal-behavior knowledge to neuropsychology and behavioral pharmacology.","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math","Social Sciences"],"topics":["Cognitive Science","Psychology","Science","Social Science"],"levels":["Graduate"],"features":["Activity Assignments","Presentation Assignments","Written Assignments"],"term":"Spring 2000","instructors":["Prof. Gerald E. Schneider"],"url":"https://ocw.mit.edu/courses/9-201-advanced-animal-behavior-spring-2000/","views":1520},{"id":"21T.423+fall_2004","numbers":["21T.423"],"title":"Theater Arts Topics","summary":"Directed practice in acting, directing, or design on a sustained theater piece, either one-act or full length, from pre-rehearsal preparation to workshop production.","departments":["Theater Arts"],"areas":["Art, Design & Architecture"],"topics":["Fine Arts","Performance Arts","Theater","Theatrical Design"],"levels":["Undergraduate"],"features":["Image Gallery"],"term":"Fall 2004","instructors":["Prof. Janet Sonenberg"],"url":"https://ocw.mit.edu/courses/21m-873-theater-arts-topics-fall-2004-january-iap-2005/","views":1520},{"id":"14.462+spring_2004","numbers":["14.462"],"title":"Advanced Macroeconomics II","summary":"14.462 is the second semester of the second-year Ph.D. macroeconomics sequence.\n\nThe course is intended to introduce the students, not only to particular areas of current research, but also to some very useful analytical tools. It covers a selection of topics that varies from year to year. Recent topics include:\n\n• Growth and Fluctuations\n• Heterogeneity and Incomplete Markets\n• Optimal Fiscal Policy\n• Time Inconsistency\n• Reputation\n• Coordination Games and Macroeconomic Complementarities\n• Information","departments":["Economics"],"areas":["Social Sciences"],"topics":["Economics","Industrial Organization","Macroeconomics","Social Science"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2004","instructors":["Prof. George-Marios Angeletos","Prof. Gilles Saint-Paul"],"url":"https://ocw.mit.edu/courses/14-462-advanced-macroeconomics-ii-spring-2004/","views":1519},{"id":"6.270+january-iap_2005","numbers":["6.270"],"title":"Autonomous Robot Design Competition","summary":"6.270 is a hands-on, learn-by-doing class, in which participants design and build a robot that will play in a competition at the end of January. The goal for the students is to design a machine that will be able to navigate its way around the playing surface, recognize other opponents, and manipulate game objects. Unlike the machines in Design and Manufacturing I (2.007), 6.270 robots are totally autonomous, so once a round begins, there is no human intervention.\n\nThe goal of 6.270 is to teach students about robotic design by giving them the hardware, software, and information they need to design, build, and debug their own robot. The subject includes concepts and applications that are related to various MIT classes (e.g. 6.001, 6.002, 6.004, and 2.007), though there are no formal prerequisites for 6.270.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Artificial Intelligence","Computer Design and Engineering","Computer Science","Electrical Engineering","Engineering","Robotics and Control Systems"],"levels":["Undergraduate"],"features":["Competition Videos","Design Assignments with Examples","Lecture Notes","Problem Sets"],"term":"January IAP 2005","instructors":["No Faculty","Michael Thilmont"],"url":"https://ocw.mit.edu/courses/6-270-autonomous-robot-design-competition-january-iap-2005/","views":1518},{"id":"RES.CMS-501+spring_2020","numbers":["RES.CMS-501"],"title":"Envisioning the Graduate of the Future","summary":"Communities have always wrestled with the multiple purposes of education: to train young people for careers, vocations, and college; to prepare them for their roles as citizens; to develop habits of reflective, ethical adults; and to create a common experience in a pluralistic society while meeting the needs of individual learners. As the world changes and grows more complex, returning to these important questions of purpose can help guide schools in their growth and strategic change.\n\nTo ensure our schools are effective, we need to routinely reimagine what the high school graduate of the future will need to know and be able to do. The artifact that communicates these ideas is called a graduate profile. Making explicit the capabilities, competencies, knowledge, and attitudes for secondary school graduates, and inviting key stakeholders like students and community members to be engaged in the process, can help you and your school to focus your vision of success and drive school innovation efforts.\n\nThis course is part of the Open Learning Library, which is free to use. You have the option to sign up and enroll in the course if you want to track your progress, or you can view and use all the materials without enrolling.","departments":["Comparative Media Studies/Writing"],"areas":["Education & Teaching"],"topics":["Curriculum and Teaching","Teaching and Education"],"levels":["Non-Credit"],"features":["Instructor Insights"],"term":"Spring 2020","instructors":["Prof. Justin Reich","Elizabeth Huttner-Loan","Alyssa Napier"],"url":"https://ocw.mit.edu/courses/res-cms-501-envisioning-the-graduate-of-the-future-spring-2020/","views":1518},{"id":"CMS.701+spring_2015","numbers":["CMS.701","CMS.901"],"title":"Current Debates in Media","summary":"This class addresses important, current debates in media with in-depth discussion of popular perceptions and policy implications. Students will engage in the critical study of the economic, political, social, and cultural significance of media, and learn to identify, analyze, and understand the complex relations among media texts, policies, institutions, industries, and infrastructures. This class offers the opportunity to discuss, in stimulating and challenging ways, topics such as ideology, propaganda, net neutrality, big data, digital hacktivism, digital rebellion, media violence, gamification, collective intelligence, participatory culture, intellectual property, artificial intelligence, etc., from historical, transcultural, and multiple methodological perspectives.","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Communication","Fine Arts","Gender Studies","Humanities","Media Studies","Philosophy","Political Science","Public Administration","Public Policy","Social Science","Society"],"levels":["Undergraduate"],"features":["Instructor Insights","Lecture Audio","Lecture Notes","Presentation Assignments","Written Assignments"],"term":"Spring 2015","instructors":["Dr. Gabrielle Trépanier-Jobin"],"url":"https://ocw.mit.edu/courses/cms-701-current-debates-in-media-spring-2015/","views":1517},{"id":"3.071+fall_2015","numbers":["3.071"],"title":"Amorphous Materials","summary":"This course discusses the fundamental material science behind amorphous solids, or non-crystalline materials. It covers formation of amorphous solids; amorphous structures and their electrical and optical properties; and characterization methods and technical applications.","departments":["Materials Science and Engineering"],"areas":["Engineering"],"topics":["Engineering","Materials Science and Engineering","Polymeric Materials"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Sets"],"term":"Fall 2015","instructors":["Prof. Juejun Hu"],"url":"https://ocw.mit.edu/courses/3-071-amorphous-materials-fall-2015/","views":1516},{"id":"6.551J+fall_2004","numbers":["6.551J","HST.714J"],"title":"Acoustics of Speech and Hearing","summary":"The Acoustics of Speech and Hearing is an H-Level graduate course that reviews the physical processes involved in the production, propagation and reception of human speech. Particular attention is paid to how the acoustics and mechanics of the speech and auditory system define what sounds we are capable of producing and what sounds we can sense. Areas of discussion include:\n\nthe acoustic cues used in determining the direction of a sound source,\n\nthe acoustic and mechanical mechanisms involved in speech production and\n\nthe acoustic and mechanical mechanism used to transduce and analyze sounds in the ear.","departments":["Electrical Engineering and Computer Science","Health Sciences and Technology"],"areas":["Engineering","Health & Medicine","Science & Math"],"topics":["Anatomy and Physiology","Biology","Biophysics","Electrical Engineering","Engineering","Health and Medicine","Science","Signal Processing"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Christopher Shera","Prof. John Rosowski","Prof. Kenneth Stevens","Prof. Louis Braida"],"url":"https://ocw.mit.edu/courses/6-551j-acoustics-of-speech-and-hearing-fall-2004/","views":1514},{"id":"3.53+spring_2001","numbers":["3.53"],"title":"Electrochemical Processing of Materials","summary":"This course covers a variety of topics concerning superconducting magnets, including thermodynamic and transport properties of aqueous and nonaqueous electrolytes, the electrode/electrolyte interface, and the kinetics of electrode processes. It also covers electrochemical characterization with regards to d.c. techniques (controlled potential, controlled current) and a.c. techniques (voltametry and impedance spectroscopy). Applications of the following will also be discussed: electrowinning, electrorefining, electroplating, and electrosynthesis, as well as electrochemical power sources (batteries and fuel cells).","departments":["Materials Science and Engineering"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math"],"topics":["Chemical Engineering","Electricity","Electromagnetism","Energy","Engineering","Fuel Cells","Materials Science and Engineering","Physics","Science"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Problem Set Solutions","Problem Sets"],"term":"Spring 2001","instructors":["Prof. Donald Sadoway"],"url":"https://ocw.mit.edu/courses/3-53-electrochemical-processing-of-materials-spring-2001/","views":1514},{"id":"HST.950J+spring_2003","numbers":["HST.950J","6.872J"],"title":"Medical Computing","summary":"The focus of the course is on medical science and practice in the age of automation and the genome, both present and future.\n\nIt ncludes an analysis of the computational needs of clinical medicine, a review systems and approaches that have been used to support those needs, and an examination of new technologies.","departments":["Electrical Engineering and Computer Science","Health Sciences and Technology"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering","Health & Medicine"],"topics":["Biological Engineering","Biomedical Instrumentation","Biomedicine","Business","Computational Biology","Computer Science","Data Mining","Engineering","Health and Medicine","Information Technology"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2003","instructors":["Prof. Isaac Kohane","Prof. Lucila Ohno-Machado","Prof. Peter Szolovits"],"url":"https://ocw.mit.edu/courses/hst-950j-medical-computing-spring-2003/","views":1514},{"id":"PE.210+spring_2007","numbers":["PE.210"],"title":"SCUBA","summary":"This course will thoroughly educate the successful student with the knowledge and skills necessary to be a certified beginning SCUBA diver. The prerequisite for the course is passing the MIT SCUBA swim test and demonstrating a “comfort level” in the water. At the end of the class, students will attempt to pass the certification exam to become certified divers. The class is taught in two parts each week: a classroom session and a pool session. The classroom sessions along with the reading material will provide the student with the knowledge necessary to pass the written exam. At the pool, the water skills are taught in progressions that build on the previous skills, making the difficult skills seem easy.","departments":["Athletics, Physical Education and Recreation"],"areas":["Health & Medicine"],"topics":["Health and Medicine","Physical Education and Recreation"],"levels":["Undergraduate"],"features":["Demonstration Videos","Lecture Videos"],"term":"Spring 2007","instructors":["Prof. Halston Taylor"],"url":"https://ocw.mit.edu/courses/pe-210-scuba-spring-2007/","views":1514},{"id":"6.838+fall_2002","numbers":["6.838"],"title":"Algorithms for Computer Animation","summary":"Animation is a compelling and effective form of expression; it engages viewers and makes difficult concepts easier to grasp. Today’s animation industry creates films, special effects, and games with stunning visual detail and quality. This graduate class will investigate the algorithms that make these animations possible: keyframing, inverse kinematics, physical simulation, optimization, optimal control, motion capture, and data-driven methods. Our study will also reveal the shortcomings of these sophisticated tools. The students will propose improvements and explore new methods for computer animation in semester-long research projects. The course should appeal to both students with general interest in computer graphics and students interested in new applications of machine learning, robotics, biomechanics, physics, applied mathematics and scientific computing.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Algorithms and Data Structures","Computer Science","Engineering","Graphics and Visualization","Programming Languages"],"levels":["Graduate"],"features":[],"term":"Fall 2002","instructors":["Prof. Jovan Popovic"],"url":"https://ocw.mit.edu/courses/6-838-algorithms-for-computer-animation-fall-2002/","views":1511},{"id":"21G.114+spring_2005","numbers":["21G.114"],"title":"Chinese VI (Streamlined)","summary":"This course is a sequel to 21G.113 Chinese V (Streamlined). It is designed to further help students develop sophisticated conversational, reading and writing skills by combining authentic reading and audio-visual material with their own explorations of Chinese speaking societies, using the human, literary, and electronic resources available at MIT, in the Boston area and on the web. Some special features of Chinese societies, cultures and customs will be introduced. The class consists of readings, discussion, student presentations and network exploration. The course is conducted in Mandarin.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Chinese","Humanities","Language"],"levels":["Undergraduate"],"features":["Activity Assignments","Written Assignments"],"term":"Spring 2005","instructors":["Jin Zhang"],"url":"https://ocw.mit.edu/courses/21g-114-chinese-vi-streamlined-spring-2005/","views":1511},{"id":"14.147+spring_2005","numbers":["14.147"],"title":"Topics in Game Theory","summary":"This course/workshop aims to provide an invigorating intellectual environment for graduate students and junior faculty who are interested in economic theory. We will discuss research ideas and explore topics in game theory and more broadly in economic theory.","departments":["Economics"],"areas":["Social Sciences"],"topics":["Economics","Game Theory","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2005","instructors":["Prof. Muhamet Yildiz"],"url":"https://ocw.mit.edu/courses/14-147-topics-in-game-theory-spring-2005/","views":1511},{"id":"21G.325J+fall_2011","numbers":["21G.325J","WGS.233J"],"title":"New Culture of Gender: Queer France","summary":"This course addresses the place of contemporary queer identities in French discourse and discusses the new generation of queer authors and their principal concerns. Class discussions and readings will introduce students to the main classical references of queer subcultures, from Proust and Vivien to Hocquenghem and Wittig. Throughout the course, students will examines current debates on post-colonial and globalized queer identities through essays, songs, movies, and novels. Authors covered include Didier Eribon, Anne Garréta, Abdellah Taïa, Anne Scott, and Nina Bouraoui. This class is taught in French.","departments":["Global Studies and Languages","Women's and Gender Studies"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Fine Arts","French","Gender Studies","Humanities","International Literature","Language","Literature","Media Studies","Social Anthropology","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2011","instructors":["Prof. Bruno Perreau"],"url":"https://ocw.mit.edu/courses/21g-325j-new-culture-of-gender-queer-france-fall-2011/","views":1510},{"id":"STS.S28+fall_2005","numbers":["STS.S28"],"title":"Godzilla and the Bullet Train: Technology and Culture in Modern Japan","summary":"This course explores how and why Japan, a late-comer to modernization, emerged as an industrial power and the world’s second-richest nation, notwithstanding its recent difficulties. We are particularly concerned with the historical development of technology in Japan especially after 1945, giving particular attention to the interplays between business, ideology, technology, and culture. We will discuss key historical phenomena that symbolize modern Japan as a technological power in the world; specific examples to be discussed in class include kamikaze aircraft, the Shinkansen high-speed bullet train, Godzilla, and anime.","departments":["Science, Technology, and Society"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Asian Studies","Fine Arts","Media Studies","Society"],"levels":["Undergraduate"],"features":["Activity Assignments","Written Assignments with Examples"],"term":"Fall 2005","instructors":["Dr. Takashi Nishiyama"],"url":"https://ocw.mit.edu/courses/sts-s28-godzilla-and-the-bullet-train-technology-and-culture-in-modern-japan-fall-2005/","views":1509},{"id":"1.206J+spring_2003","numbers":["1.206J","16.77J","ESD.215J"],"title":"Airline Schedule Planning","summary":"Explores a variety of models and optimization techniques for the solution of airline schedule planning and operations problems. Schedule design, fleet assignment, aircraft maintenance routing, crew scheduling, passenger mix, and other topics are covered. Recent models and algorithms addressing issues of model integration, robustness, and operations recovery are introduced. Modeling and solution techniques designed specifically for large-scale problems, and state-of-the-art applications of these techniques to airline problems are detailed.","departments":["Aeronautics and Astronautics","Civil and Environmental Engineering","Engineering Systems Division"],"areas":["Business & Management","Engineering","Social Sciences"],"topics":["Engineering","Social Science","Systems Engineering","Systems Optimization","Transportation Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2003","instructors":["Prof. Cynthia Barnhart"],"url":"https://ocw.mit.edu/courses/1-206j-airline-schedule-planning-spring-2003/","views":1504},{"id":"2.997+spring_2004","numbers":["2.997"],"title":"Decision Making in Large Scale Systems","summary":"This course is an introduction to the theory and application of large-scale dynamic programming. Topics include Markov decision processes, dynamic programming algorithms, simulation-based algorithms, theory and algorithms for value function approximation, and policy search methods. The course examines games and applications in areas such as dynamic resource allocation, finance and queueing networks.","departments":["Mechanical Engineering"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering","Social Sciences"],"topics":["Algorithms and Data Structures","Computational Modeling and Simulation","Computer Science","Engineering","Game Theory","Social Science","Systems Engineering","Systems Optimization"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Projects with Examples"],"term":"Spring 2004","instructors":["Prof. Daniela Pucci De Farias"],"url":"https://ocw.mit.edu/courses/2-997-decision-making-in-large-scale-systems-spring-2004/","views":1503},{"id":"4.S67+fall_2016","numbers":["4.S67"],"title":"Landscape Experience: Seminar in Land/Art","summary":"This seminar explores “land” as a genre, theme, and medium of art and architecture of the last five decades. Focusing largely on work within the boundaries of the United States, the course seeks to understand how the use of land in art and architecture is bound into complicated entanglements of property and power, the inheritances of non-U.S. traditions, and the violence of colonial ambitions. The term “landscape” is variously deployed in the service of a range of political and philosophical positions.","departments":["Architecture"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Architectural Design","Architectural History and Criticism","Architecture","Fine Arts","History","Humanities"],"levels":["Graduate"],"features":["Instructor Insights"],"term":"Fall 2016","instructors":["Dr. Rebecca K. Uchill","Prof. Caroline Jones"],"url":"https://ocw.mit.edu/courses/4-s67-landscape-experience-seminar-in-land-art-fall-2016/","views":1503},{"id":"11.360+fall_2010","numbers":["11.360"],"title":"Community Growth and Land Use Planning","summary":"This subject explores the techniques, processes, and personal and professional skills required to effectively manage growth and land use change. While primarily focused on the planning practice in the United States, the principles and techniques reviewed and presented may have international application. This course is not for bystanders; it is designed for those who wish to become actively involved or exposed to the planning discipline and profession as it is practiced today, and as it may need to be practiced in the future.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Public Administration","Public Policy","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Presentation Assignments","Projects with Examples","Written Assignments"],"term":"Fall 2010","instructors":["Prof. Terry Szold","Annis Sengupta"],"url":"https://ocw.mit.edu/courses/11-360-community-growth-and-land-use-planning-fall-2010/","views":1502},{"id":"21L.488+spring_2008","numbers":["21L.488"],"title":"Contemporary Literature: Literature, Development, and Human Rights","summary":"Central to our era is the gradual movement of all the world’s regions toward a uniform standard of economic and political development. In this class we will read a variety of recent narratives that partake of, dissent from, or contribute to this story, ranging from novels and poems to World Bank and IMF statements and National Geographic reports. We will seek to understand the many motives and voices – sometimes congruent, sometimes clashing – that are currently engaged in producing accounts of people in the developing world: their hardships, laughter, and courage, and how they help themselves and are helped by outsiders who may or may not have philanthropic motives. Readings will include literature by J. G. Ballard, Jamaica Kincaid, Rohinton Mistry, and John le Carré, as well as policy documents, newspaper and magazine articles, and the Web sites of a variety of trade and development commissions and organizations.","departments":["Literature"],"areas":["Humanities","Social Sciences"],"topics":["Criticism","Humanities","Literature","Philosophy","Political Philosophy","Social Justice","Social Science","Society","Sociology","The Developing World"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2008","instructors":["Prof. Sarah Brouillette"],"url":"https://ocw.mit.edu/courses/21l-488-contemporary-literature-literature-development-and-human-rights-spring-2008/","views":1502},{"id":"12.746+spring_2005","numbers":["12.746"],"title":"Marine Organic Geochemistry","summary":"This class is designed to provide the student with a global to molecular-level perspective of organic matter cycling in the oceans and marine sediments. Topics include: Organic matter (C,N,P) composition, reactivity and budgets within, and fluxes through, major ocean reservoirs; microbial recycling pathways for organic matter; models of organic matter degradation and preservation; role of anoxia in organic matter burial; relationships between dissolved and particulate (sinking and suspended) organic matter; methods for characterization of sedimentary organic matter; and application of biological markers as tools in oceanography. Both structural and isotopic aspects are covered.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Chemistry","Earth Science","Geobiology","Geochemistry","Oceanography","Organic Chemistry","Science"],"levels":["Graduate"],"features":["Lecture Notes","Projects"],"term":"Spring 2005","instructors":["Prof. Daniel Repeta","Prof. Timothy Eglinton"],"url":"https://ocw.mit.edu/courses/12-746-marine-organic-geochemistry-spring-2005/","views":1502},{"id":"21G.717+fall_2004","numbers":["21G.717"],"title":"Introduction to Spanish Culture","summary":"This course has several purposes. The major concern will be the examination of Spanish culture including Spain’s history, architecture, art, literature and film, to determine if there is a uniquely Spanish manner of seeing and understanding the world - one which emerges as clearly distinct from our own and that of other Western European nations.","departments":["Global Studies and Languages"],"areas":["Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Ethnography","European and Russian Studies","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. Margery Resnick"],"url":"https://ocw.mit.edu/courses/21g-717-introduction-to-spanish-culture-fall-2004/","views":1501},{"id":"3.21+spring_2006","numbers":["3.21"],"title":"Kinetic Processes in Materials","summary":"This course presents a unified treatment of phenomenological and atomistic kinetic processes in materials. It provides the foundation for the advanced understanding of processing, microstructural evolution, and behavior for a broad spectrum of materials. The course emphasizes analysis and development of rigorous comprehension of fundamentals. Topics include: irreversible thermodynamics; diffusion; nucleation; phase transformations; fluid and heat transport; morphological instabilities; gas-solid, liquid-solid, and solid-solid reactions.","departments":["Materials Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Chemistry","Engineering","Materials Science and Engineering","Physical Chemistry","Physics","Science","Thermodynamics"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2006","instructors":["Prof. Kenneth Russell","Prof. Samuel Allen"],"url":"https://ocw.mit.edu/courses/3-21-kinetic-processes-in-materials-spring-2006/","views":1500},{"id":"17.561+fall_2020","numbers":["17.561"],"title":"European Politics","summary":"This course examines similarities and differences in politics and political economy in Britain, Germany, Denmark, and Sweden. In particular, the course focuses on the structure of political power within the state, and on important institutions that form the link between state and society, especially political parties and interest organizations.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Economics","International Relations","Political Economy","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2020","instructors":["Prof. Kathleen Thelen"],"url":"https://ocw.mit.edu/courses/17-561-european-politics-fall-2020/","views":1499},{"id":"9.68+spring_2013","numbers":["9.68"],"title":"Affect: Neurobiological, Psychological and Sociocultural Counterparts of \"Feelings\"","summary":"This course studies the relations of affect to cognition and behavior, feeling to thinking and acting, and values to beliefs and practices. These connections will be considered at the psychological level of organization and in terms of their neurobiological and sociocultural counterparts.","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math","Social Sciences"],"topics":["Biology","Cognitive Science","Neurobiology","Neuroscience","Psychology","Science","Social Science"],"levels":["Undergraduate"],"features":["Instructor Insights","Lecture Notes","Written Assignments"],"term":"Spring 2013","instructors":["Stephan L. Chorover"],"url":"https://ocw.mit.edu/courses/9-68-affect-neurobiological-psychological-and-sociocultural-counterparts-of-feelings-spring-2013/","views":1497},{"id":"21L.310+fall_2018","numbers":["21L.310"],"title":"Bestsellers: Out for the Count","summary":"This class uses a range of literary texts to trace the growth of the vampire trope from its first appearance in English-language fiction in the early years of the nineteenth century. Centering on classic works by Lord Byron, John Polidori, Sheridan le Fanu, Bram Stoker, and others, we learn about the formation of the modern literary canon, the folklore of the undead, and the creation of one of the most prolific popular culture genres—vampire fiction—which reached its first apotheosis in Stoker’s masterwork, Dracula.","departments":["Literature"],"areas":["Humanities"],"topics":["Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2018","instructors":["Dr. William Donaldson"],"url":"https://ocw.mit.edu/courses/21l-310-bestsellers-out-for-the-count-fall-2018/","views":1497},{"id":"14.09+january-iap_2016","numbers":["14.09"],"title":"Financial Crises","summary":"This course is an introduction to the economic theories of financial crises. It focuses on amplification mechanisms that exacerbate crises, such as leverage, fire sales, bank runs, interconnections, and complexity. It also analyzes the different perspectives on the origins of crises, such as mistaken beliefs and moral hazard, and discusses the optimal regulation of the financial system. The course draws upon examples from financial crises around the world, especially the recent subprime financial crisis.\n\n14.09 is offered during the Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month.","departments":["Economics"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Finance","Financial Economics","Social Science"],"levels":["Undergraduate"],"features":["Exams","Lecture Notes"],"term":"January IAP 2016","instructors":["Prof. Alp Simsek"],"url":"https://ocw.mit.edu/courses/14-09-financial-crises-january-iap-2016/","views":1497},{"id":"4.155B+fall_2004","numbers":["4.155B"],"title":"Architectural Design, Level III: A Student Center for MIT","summary":"This studio will investigate the social, programmatic, tectonic and phenomenological performance and character of a student gathering place on the MIT campus. Whether it is simply for socializing or for more specific events, the student gathering place will serve as a refuge from the vigorous educational environment of the Institute, and it will reinforce a critical sense of “place” through the almost logical organization of its program. The place will foster a casual discovery of “being”: a reflection upon the student’s own existence based upon participation in group events and an intellectual attitude toward acting. To create a space that inspires, rather than imposes: such a discovery is the foremost challenge of this studio.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architecture","Environmental Design","Fine Arts"],"levels":["Graduate"],"features":["Design Assignments","Image Gallery","Projects with Examples"],"term":"Fall 2004","instructors":["Prof. Fernando Domeyko"],"url":"https://ocw.mit.edu/courses/4-155b-architectural-design-level-iii-a-student-center-for-mit-fall-2004/","views":1496},{"id":"RES.18-009+fall_2015","numbers":["RES.18-009"],"title":"Learn Differential Equations: Up Close with Gilbert Strang and Cleve Moler","summary":"Learn Differential Equations: Up Close with Gilbert Strang and Cleve Moler is an in-depth series of videos about differential equations and the MATLAB® ODE suite. These videos are suitable for students and life-long learners to enjoy.\n\nAbout the Instructors\n\nGilbert Strang is the MathWorks Professor of Mathematics at MIT. His research focuses on mathematical analysis, linear algebra and PDEs. He has written textbooks on linear algebra, computational science, finite elements, wavelets, GPS, and calculus.\n\nCleve Moler is chief mathematician, chairman, and cofounder of MathWorks. He was a professor of math and computer science for almost 20 years at the University of Michigan, Stanford University, and the University of New Mexico.\n\nThese videos were produced by The MathWorks® and are also available on The MathWorks website.","departments":["Mathematics"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Applied Mathematics","Computer Science","Differential Equations","Engineering","Linear Algebra","Mathematics","Programming Languages"],"levels":["Undergraduate"],"features":["Lecture Videos"],"term":"Fall 2015","instructors":["Prof. Gilbert Strang","Dr. Cleve Moler"],"url":"https://ocw.mit.edu/courses/res-18-009-learn-differential-equations-up-close-with-gilbert-strang-and-cleve-moler-fall-2015/","views":1496},{"id":"21A.240+spring_2004","numbers":["21A.240"],"title":"Race and Science","summary":"This course examines one of the most enduring and influential forms of identity and experience in the Americas and Europe, and in particular the ways race and racism have been created, justified, or contested in scientific practice and discourse. Drawing on classical and contemporary readings from Du Bois to Gould to Gilroy, we ask whether the logic of race might be changing in the world of genomics and informatics, and with that changed logic, how we can respond today to new configurations of race, science, technology, and inequality. Considered are the rise of evolutionary racism; debates about eugenics in the early twentieth century; Nazi notions of “racial hygiene”; nation-building projects and race in Latin America; and the movement in modern biology from race to populations to genes and genomes.","departments":["Anthropology"],"areas":["Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Ethnography","Social Justice","Social Science","Sociology"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2004","instructors":["Prof. Stefan Helmreich"],"url":"https://ocw.mit.edu/courses/21a-240-race-and-science-spring-2004/","views":1495},{"id":"11.479+spring_2005","numbers":["11.479"],"title":"Water and Sanitation Infrastructure Planning in Developing Countries","summary":"This course examines the policy and planning for the provision of water supply and sanitation services in developing countries. It reviews available technologies, but emphasizes the planning and policy process, including economic, social, environmental, and health issues. The course incorporates considerations of financing, pricing, institutional structure, consumer demand, and community participation in the planning process. And it evaluates policies and projects in case studies from Asia, Africa, Latin America, and Central and Eastern Europe.","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Engineering","Health & Medicine","Social Sciences"],"topics":["Aquatic Sciences and Water Quality Control","Engineering","Environmental Engineering","Environmental Management","Environmental Policy","Health and Medicine","Hydrology and Water Resource Systems","Public Administration","Public Health","Regional Planning","Social Science","Society","The Developing World","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Spring 2005","instructors":["Prof. Jennifer Davis"],"url":"https://ocw.mit.edu/courses/11-479-water-and-sanitation-infrastructure-planning-in-developing-countries-spring-2005/","views":1494},{"id":"12.864+spring_2005","numbers":["12.864"],"title":"Inference from Data and Models","summary":"This course covers the fundamental methods used for exploring the information content of observations related to kinematical and dynamical models.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Applied Mathematics","Classical Mechanics","Differential Equations","Engineering","Fluid Mechanics","Mathematics","Mechanical Engineering","Physics","Probability and Statistics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Programming Assignments"],"term":"Spring 2005","instructors":["Carl Wunsch"],"url":"https://ocw.mit.edu/courses/12-864-inference-from-data-and-models-spring-2005/","views":1492},{"id":"21L.715+spring_2007","numbers":["21L.715","CMS.871"],"title":"Media in Cultural Context","summary":"This course explores the international trade in television text, considering the ways in which ‘foreign’ programs find places within ‘domestic’ schedules. Looking at the life television texts maintain outside of their home market, this course examines questions of globalization and national cultures of production and reception. Students will be introduced to a range of positions about the nature of international textual trade, including economic arguments about the structuring of international markets and ethnographic studies about the role imported content plays in the formation of hybrid national identities. Students will be encouraged to consider the role American content is made to play in non-American markets.","departments":["Comparative Media Studies/Writing","Literature"],"areas":["Art, Design & Architecture","Business & Management","Humanities","Social Sciences"],"topics":["Anthropology","Business","Criticism","Cultural Anthropology","Fine Arts","Globalization","Humanities","Literature","Media Studies","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2007","instructors":["Dr. Joshua Green"],"url":"https://ocw.mit.edu/courses/21l-715-media-in-cultural-context-spring-2007/","views":1492},{"id":"MAS.961+fall_2004","numbers":["MAS.961"],"title":"Seminar on Deep Engagement","summary":"Innovation in expression, as realized in media, tangible objects, performance and more, generates new questions and new potentials for human engagement. When and how does expression engage us deeply? Many personal stories confirm the hypothesis that once we experience deep engagement, it is a state we long for, remember, and want to repeat. This class will explore what underlying principles and innovative methods can ensure the development of higher-quality “deep engagement” products (artifacts, experiences, environments, performances, etc.) that appeal to a broad audience and that have lasting value over the long term.","departments":["Media Arts and Sciences"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Communication","Fine Arts","Media Studies","Psychology","Social Science"],"levels":["Graduate"],"features":["Problem Set Solutions","Problem Sets","Projects with Examples"],"term":"Fall 2004","instructors":["Prof. Cynthia Breazeal","Prof. Glorianna Davenport"],"url":"https://ocw.mit.edu/courses/mas-961-seminar-on-deep-engagement-fall-2004/","views":1488},{"id":"11.423+spring_2004","numbers":["11.423"],"title":"Information and Communication Technologies in Community Development","summary":"This practicum subject integrates theory and practice through the design, implementation, and evaluation of a comprehensive community information infrastructure that promotes democratic involvement and informs community development projects. Students work with Lawrence Community Works, Inc. to involve constituents and generate solutions to an important planning problem in the City of Lawrence, Massachusetts. Final project presentations take place in a public forum, and serve to inform future development of the information infrastructure. Subject begins with an overview of the digital divide, e-government, public participation GIS, and neighborhood information systems. Subject includes a reflection component and a deliberate investigation of race, class, and gender dynamics.","departments":["Urban Studies and Planning"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Communication","Community Development","Information Technology","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Activity Assignments","Lecture Notes","Presentation Assignments"],"term":"Spring 2004","instructors":["Prof. Langley Keyes","Prof. Lorlene Hoyt"],"url":"https://ocw.mit.edu/courses/11-423-information-and-communication-technologies-in-community-development-spring-2004/","views":1487},{"id":"24.942+spring_2003","numbers":["24.942"],"title":"Grammar of a Less Familiar Language","summary":"This course is designed to allow participants to engage in the exploration of the grammatical structure of a language that is unknown to them (and typically to the instructors as well). In some ways it simulates traditional field methods research. In terms of format, we work in both group and individual meetings with the consultant. Each student identifies some grammatical construction (e.g. wh questions, agreement, palatalization, interrogative intonation) to focus their research: they elicit and share data and write a report on the material gathered that is to be turned in at the end of the term. Ideally, we can put together a volume of grammatical sketches.\n\nThe first three to four weeks of the term, our group meetings will explore the basic phonology, morphology and surface syntax for a first pass overview of the language, looking for interesting areas to be explored in more detail later. During this period individual sessions can review material from the general session as well as explore new areas. At roughly the fifth meeting, individual students (typically two to three per session) guide the group elicitations to explore their research topic.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2003","instructors":["Prof. Michael Kenstowicz","Prof. Norvin W. Richards"],"url":"https://ocw.mit.edu/courses/24-942-grammar-of-a-less-familiar-language-spring-2003/","views":1486},{"id":"21L.012+fall_2007","numbers":["21L.012"],"title":"Forms of Western Narrative","summary":"This course examines some leading examples of major genres of storytelling in the Western tradition, among them epic (Homer’s Odyssey), romance (from the Arthurian tradition), and novel (Cervantes’s Don Quixote). We will be asking why people tell (and have always told) stories, how they tell them, why they might tell them the way they do, and what difference it makes how they tell them. We’ll combine an investigation of the changing formal properties of narratives with consideration of the historical, cultural, and technological factors that have influenced how tales got told. In keeping with its CI-H and HASS-D label, this course will involve substantial attention to students’ writing and speaking abilities.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Criticism","Fiction","Humanities","International Literature","Literature"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2007","instructors":["Prof. James Buzard"],"url":"https://ocw.mit.edu/courses/21l-012-forms-of-western-narrative-fall-2007/","views":1485},{"id":"20.011J+spring_2004","numbers":["20.011J","2.772J"],"title":"Statistical Thermodynamics of Biomolecular Systems (BE.011J)","summary":"This course provides an introduction to the physical chemistry of biological systems. Topics include: connection of macroscopic thermodynamic properties to microscopic molecular properties using statistical mechanics, chemical potentials, equilibrium states, binding cooperativity, behavior of macromolecules in solution and at interfaces, and solvation. Example problems include protein structure, genomic analysis, single molecule biomechanics, and biomaterials.","departments":["Biological Engineering","Mechanical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Biomaterials","Biophysics","Biostatistics","Chemistry","Computation and Systems Biology","Engineering","Physical Chemistry","Physics","Science","Thermodynamics"],"levels":["Undergraduate"],"features":["Exams","Problem Sets"],"term":"Spring 2004","instructors":["Prof. Kim Hamad-Schifferli","Prof. Linda Griffith"],"url":"https://ocw.mit.edu/courses/20-011j-statistical-thermodynamics-of-biomolecular-systems-be-011j-spring-2004/","views":1484},{"id":"15.348+spring_2004","numbers":["15.348"],"title":"Doctoral Seminar in Research Methods II","summary":"A large proportion of contemporary research on organizations, strategy and management relies on quantitative research methods. This course is designed to provide an introduction to some of the most commonly used quantitative techniques, including logit/probit models, count models, event history models, and pooled cross-section techniques.","departments":["Sloan School of Management"],"areas":["Science & Math","Social Sciences"],"topics":["Mathematics","Probability and Statistics","Social Science"],"levels":["Graduate"],"features":["Activity Assignments"],"term":"Spring 2004","instructors":["Prof. Jesper B. Sorensen"],"url":"https://ocw.mit.edu/courses/15-348-doctoral-seminar-in-research-methods-ii-spring-2004/","views":1483},{"id":"6.S095+january-iap_2018","numbers":["6.S095"],"title":"Programming for the Puzzled","summary":"This class builds a bridge between the recreational world of algorithmic puzzles (puzzles that can be solved by algorithms) and the pragmatic world of computer programming, teaching students to program while solving puzzles. Python syntax and semantics required to understand the code are explained as needed for each puzzle.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Algorithms and Data Structures","Computer Science","Engineering","Programming Languages"],"levels":["Undergraduate"],"features":["Lecture Videos","Programming Assignments with Examples"],"term":"January IAP 2018","instructors":["Prof. Srini Devadas"],"url":"https://ocw.mit.edu/courses/6-s095-programming-for-the-puzzled-january-iap-2018/","views":1483},{"id":"21H.105+fall_2002","numbers":["21H.105"],"title":"American Classics","summary":"“What then is the American, this new man?” asked J. Hector St-John de Crèvecoeur in his Letters from an American Farmer in 1782. This subject takes Crèvecoeur’s question as the starting point for an examination of the changing meanings of national identity in the American past. We will consider a diverse collection of classic texts in American history to see how Americans have defined themselves and their nation in politics, literature, art, and popular culture. As a communications-intensive subject, students will be expected to engage intensively with the material through frequent oral and written exercises.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["American History","Anthropology","Classics","Cultural Anthropology","History","Humanities","Literature","Social Anthropology","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2002","instructors":["Prof. Christopher Capozzola","Louise Harrison Lepera"],"url":"https://ocw.mit.edu/courses/21h-105-american-classics-fall-2002/","views":1482},{"id":"12.090+fall_2006","numbers":["12.090"],"title":"Introduction to Fluid Motions, Sediment Transport, and Current-Generated Sedimentary Structures","summary":"This course begins by introducing students to aspects of fluid dynamics relevant to transport and deposition of particulate sedimentary materials. Emphasis is on the structure of turbulent shear flows and the forces exerted by fluid motions on bed of loosed sediment. With fluid dynamics as background, the course deals with sediment movement as bed load and suspended load, and with the geometry, kinematics, and dynamics of ripple and dune bed forms. The course concludes with basic material on the styles of current-generated primary sedimentary structures, with emphasis on cross stratification.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Earth Science","Engineering","Fluid Mechanics","Geology","Geophysics","Hydrodynamics","Mechanical Engineering","Ocean Engineering","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Open Textbooks","Projects","Written Assignments"],"term":"Fall 2006","instructors":["Prof. John Southard"],"url":"https://ocw.mit.edu/courses/12-090-introduction-to-fluid-motions-sediment-transport-and-current-generated-sedimentary-structures-fall-2006/","views":1482},{"id":"6.883+fall_2005","numbers":["6.883"],"title":"Program Analysis","summary":"6.883 is a graduate seminar that investigates a variety of program analysis techniques that address software engineering tasks. Static analysis topics include abstract interpretation (dataflow), type systems, model checking, decision procedures (SAT, BDDs), theorem-proving. Dynamic analysis topics include testing, fault isolation (debugging), model inference, and visualization. While the course focuses on the design and implementation of programming tools, the material will be useful to anyone who wishes to improve his or her programming or understand the state of the art. Students are expected to read classic and current technical papers, actively participate in class discussion, perform small exercises that provide experience with a variety of tools, and complete a team research project.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Algorithms and Data Structures","Computer Science","Engineering","Software Design and Engineering"],"levels":["Graduate"],"features":["Projects with Examples"],"term":"Fall 2005","instructors":["Prof. Michael Ernst"],"url":"https://ocw.mit.edu/courses/6-883-program-analysis-fall-2005/","views":1482},{"id":"12.802+spring_2004","numbers":["12.802"],"title":"Wave Motions in the Ocean and Atmosphere","summary":"This course is an introduction to basic ideas of geophysical wave motion in rotating, stratified, and rotating-stratified fluids. Subject begins with general wave concepts of phase and group velocity. It also covers the dynamics and kinematics of gravity waves with a focus on dispersion, energy flux, initial value problems, etc. Also addressed are subject foundation used to study internal and inertial waves, Kelvin, Poincare, and Rossby waves in homogeneous and stratified fluids. Laplace tidal equations are applied to equatorial waves. Other topics include: resonant interactions, potential vorticity, wave-mean flow interactions, and instability.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Atmospheric Science","Earth Science","Engineering","Environmental Engineering","Fluid Mechanics","Geophysics","Hydrodynamics","Hydrodynamics and Coastal Engineering","Mechanical Engineering","Ocean Engineering","Oceanography","Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2004","instructors":["Prof. Glenn Flierl"],"url":"https://ocw.mit.edu/courses/12-802-wave-motions-in-the-ocean-and-atmosphere-spring-2004/","views":1479},{"id":"24.902+fall_2003","numbers":["24.902"],"title":"Language and its Structure II: Syntax","summary":"This course will acquaint you with some of the important results and ideas of the last half - century of research in syntax. We will explore a large number of issues and a large amount of data so that you can learn something of what this field is all about. From time to time, we will discuss related work in language acquisition and processing. The class will emphasize ideas and arguments for these ideas in addition to the the details of particular analyses. At the same time, you will learn the mechanics of one particular approach (sometimes called Principles and Parameters syntax).\n\nMost of all, the course tries to show why the study of syntax is exciting, and why its results are important to researchers in other language sciences. The class assumes some familiarity with basic concepts of theoretical linguistics, of the sort you could acquire in 24.900.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics","Philosophy","Philosophy of Language","Syntax"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2003","instructors":["Prof. David Pesetsky"],"url":"https://ocw.mit.edu/courses/24-902-language-and-its-structure-ii-syntax-fall-2003/","views":1476},{"id":"18.354J+spring_2015","numbers":["18.354J","1.062J","12.207J"],"title":"Nonlinear Dynamics II: Continuum Systems","summary":"This course introduces the basic ideas for understanding the dynamics of continuum systems, by studying specific examples from a range of different fields. Our goal will be to explain the general principles, and also to illustrate them via important physical effects. A parallel goal of this course is to give you an introduction to mathematical modeling.","departments":["Civil and Environmental Engineering","Earth, Atmospheric, and Planetary Sciences","Mathematics"],"areas":["Science & Math"],"topics":["Applied Mathematics","Classical Mechanics","Mathematics","Physics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Projects"],"term":"Spring 2015","instructors":["Prof. Jörn Dunkel"],"url":"https://ocw.mit.edu/courses/18-354j-nonlinear-dynamics-ii-continuum-systems-spring-2015/","views":1475},{"id":"15.099+fall_2003","numbers":["15.099"],"title":"Readings in Optimization","summary":"In keeping with the tradition of the last twenty-some years, the Readings in Optimization seminar will focus on an advanced topic of interest to a portion of the MIT optimization community: randomized methods for deterministic optimization. In contrast to conventional optimization algorithms whose iterates are computed and analyzed deterministically, randomized methods rely on stochastic processes and random number/vector generation as part of the algorithm and/or its analysis. In the seminar, we will study some very recent papers on this topic, many by MIT faculty, as well as some older papers from the existing literature that are only now receiving attention.","departments":["Sloan School of Management"],"areas":["Business & Management","Engineering","Science & Math"],"topics":["Applied Mathematics","Engineering","Mathematics","Systems Engineering","Systems Optimization"],"levels":["Graduate"],"features":["Lecture Notes","Presentation Assignments with Examples"],"term":"Fall 2003","instructors":["Prof. Robert Freund"],"url":"https://ocw.mit.edu/courses/15-099-readings-in-optimization-fall-2003/","views":1472},{"id":"RES.3-004+fall_2017","numbers":["RES.3-004"],"title":"Visualizing Materials Science","summary":"This resource is a collection of student tutorial videos that explore various materials science and engineering topics using visualizations in the Wolfram Mathematica programming system.","departments":["Materials Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Applied Mathematics","Computation","Engineering","Materials Science and Engineering","Mathematics"],"levels":["Undergraduate"],"features":["Projects with Examples","Tutorial Videos"],"term":"Fall 2017","instructors":["Prof. W. Craig Carter"],"url":"https://ocw.mit.edu/courses/res-3-004-visualizing-materials-science-fall-2017/","views":1471},{"id":"STS.014+spring_2006","numbers":["STS.014"],"title":"Principles and Practice of Science Communication","summary":"This course helps in developing skills as science communicators through projects and analysis of theoretical principles. Case studies explore the emergence of popular science communication over the past two centuries and consider the relationships among authors, audiences and media. Project topics are identified early in the term and students work with MIT Museum staff. Projects may include physical exhibits, practical demonstrations, or scripts for public programs.","departments":["Science, Technology, and Society"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Communication","Fine Arts","Media Studies","Social Science"],"levels":["Undergraduate"],"features":["Activity Assignments"],"term":"Spring 2006","instructors":["Prof. John Durant"],"url":"https://ocw.mit.edu/courses/sts-014-principles-and-practice-of-science-communication-spring-2006/","views":1470},{"id":"21G.716+fall_2007","numbers":["21G.716"],"title":"Introduction to Contemporary Hispanic Literature","summary":"This course studies representative twentieth and twenty-first-century texts and films from Hispanic America and Spain. Emphasis is on developing strategies for analyzing the genres of the novel, the short story, the poem, the fictional film, and the theatrical script. The novels read this semester are Magali García Ramis’s Felices días, Tío Sergio (1986, Puerto Rico) and Javier Cercas’s Soldados de Salamina (2001, Spain). We will study Lorca’s play “La casa de Bernarda Alba” (1936, Spain), films from Spain, México, and Cuba, poems by Darío (Nicaragua), Machado (Spain), Lorca (Spain), Hernández (Spain), Vallejo (Perú), Cernuda (Spain), and Luis Palés Matos (Puerto Rico), and short stories from México (by an exiled Spanish writer), Chile, Argentina, and Cuba. Thematic emphasis is on the Spanish Civil War, changing attitudes toward gender, the Spanish-speaking Caribbean, and the history of race in the Americas.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","International Literature","Language","Literature","Spanish"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2007","instructors":["Prof. Elizabeth Garrels"],"url":"https://ocw.mit.edu/courses/21g-716-introduction-to-contemporary-hispanic-literature-fall-2007/","views":1469},{"id":"21H.402+fall_2005","numbers":["21H.402"],"title":"The Making of a Roman Emperor","summary":"Focusing on the emperors Augustus and Nero, this course investigates the ways in which Roman emperors used art, architecture, coinage and other media to create and project an image of themselves, the ways in which the surviving literary sources from the Roman period reinforced or subverted that image, and the ways in which both phenomena have contributed to post-classical perceptions of Roman emperors. Material studied will include the art, architecture, and coinage of Augustan and Neronian Rome, the works of Suetonius and Tacitus, and modern representations of the emperors such as those found in I, Claudius and Quo Vadis.","departments":["History"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Ancient History","Art History","European History","Fine Arts","History","Humanities","Media Studies"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2005","instructors":["Prof. William Broadhead"],"url":"https://ocw.mit.edu/courses/21h-402-the-making-of-a-roman-emperor-fall-2005/","views":1467},{"id":"4.638+fall_2002","numbers":["4.638"],"title":"Drawings & Numbers: Five Centuries of Digital Design","summary":"The aim of this course is to highlight some technical aspects of the classical tradition in architecture that have so far received only sporadic attention. It is well known that quantification has always been an essential component of classical design: proportional systems in particular have been keenly investigated. But the actual technical tools whereby quantitative precision was conceived, represented, transmitted, and implemented in pre-modern architecture remain mostly unexplored. By showing that a dialectical relationship between architectural theory and data-processing technologies was as crucial in the past as it is today, this course hopes to promote a more historically aware understanding of the current computer-induced transformations in architectural design.","departments":["Architecture"],"areas":["Art, Design & Architecture","Science & Math"],"topics":["Applied Mathematics","Architectural Engineering","Architectural History and Criticism","Architecture","Fine Arts","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2002","instructors":["Leonardo Diaz Borioli","Prof. Mario Carpo"],"url":"https://ocw.mit.edu/courses/4-638-drawings-numbers-five-centuries-of-digital-design-fall-2002/","views":1466},{"id":"15.969+fall_2004","numbers":["15.969"],"title":"Dynamic Leadership: Using Improvisation in Business","summary":"The first two weeks of this course are an overview of performing improvisation with introductory and advanced exercises in the techniques of improvisation. The final four weeks focus on applying these concepts in business situations to practice and mastering these improvisation tools in leadership learning.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Communication","Innovation","Leadership","Management","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Lecture Videos","Presentation Assignments"],"term":"Fall 2004","instructors":["Prof. Lakshmi Balachandra"],"url":"https://ocw.mit.edu/courses/15-969-dynamic-leadership-using-improvisation-in-business-fall-2004/","views":1466},{"id":"11.483+fall_2011","numbers":["11.483"],"title":"Housing and Land Use in Rapidly Urbanizing Regions","summary":"A truly inter-disciplinary course, Housing and Land Use in Rapidly Urbanizing Regions reviews how law, economics, sociology, political science, and planning conceptualize urban land and property rights and uses cases to discuss what these different lenses illuminate and obscure. It also looks at how the social sciences might be informed by how design, cartography, and visual studies conceptualize space’s physicality. This year’s topics include land trusts for affordable housing, mixed-use in public space, and critical cartography.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Housing Development","Political Science","Public Administration","Regional Planning","Social Science","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2011","instructors":["Prof. Annette M. Kim"],"url":"https://ocw.mit.edu/courses/11-483-housing-and-land-use-in-rapidly-urbanizing-regions-fall-2011/","views":1466},{"id":"21M.303+spring_2009","numbers":["21M.303"],"title":"Writing in Tonal Forms I","summary":"Written and analytic exercises based on 18th- and 19th-century small forms and harmonic practice found in music such as the chorale preludes of Bach; minuets and trios of Haydn, Mozart, and Beethoven; and the songs and character pieces of Schubert and Schumann. Musicianship laboratory is required.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History","Music Performance","Music Theory"],"levels":["Undergraduate"],"features":["Activity Assignments with Examples","Demonstration Audio","Music Audio","Workshop Videos"],"term":"Spring 2009","instructors":["Prof. Peter Child"],"url":"https://ocw.mit.edu/courses/21m-303-writing-in-tonal-forms-i-spring-2009/","views":1465},{"id":"3.37+fall_2002","numbers":["3.37"],"title":"Welding and Joining Processes","summary":"Discusses a wide variety of processes and materials from the viewpoint of their fundamental physical and chemical properties. Specific topics: cold welding, adhesive bonding, diffusion bonding, soldering, brazing, flames, arcs, high-energy density heat sources, solidification, cracking resistance, shielding methods, and electric contacts. Emphasis on underlying science of a given process rather than a detailed description of the technique or equipment.\n\nThis course meets with the first half of 3.371J in the Fall Term.","departments":["Materials Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Chemistry","Engineering","Materials Science and Engineering","Physics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Written Assignments"],"term":"Fall 2002","instructors":["Prof. Thomas Eagar"],"url":"https://ocw.mit.edu/courses/3-37-welding-and-joining-processes-fall-2002/","views":1462},{"id":"11.467J+spring_2005","numbers":["11.467J","4.257J","17.550J"],"title":"Property Rights in Transition","summary":"This course examines the theories and policy debates over who can own real property, how to communicate and enforce property rights, and the range of liberties that they confer. It explores alternative economic, political, and sociological perspectives of property rights and their policy and planning implications.","departments":["Architecture","Political Science","Urban Studies and Planning"],"areas":["Art, Design & Architecture","Business & Management","Humanities","Social Sciences"],"topics":["Business","Humanities","Legal Studies","Philosophy","Political Philosophy","Public Administration","Public Policy","Real Estate","Social Justice","Social Science","Sociology","Urban Studies"],"levels":["Graduate"],"features":["Projects with Examples"],"term":"Spring 2005","instructors":["Prof. Annette M. Kim"],"url":"https://ocw.mit.edu/courses/11-467j-property-rights-in-transition-spring-2005/","views":1460},{"id":"21M.295+fall_2014","numbers":["21M.295"],"title":"American Popular Music","summary":"This course surveys the development of popular music in the United States and in a cross-cultural milieu relative to the history and sociology of the last two hundred years. It examines the ethnic mixture that characterizes modern music, how it reflects many rich traditions and styles, and provides a background for understanding the musical vocabulary of current popular music styles.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History","Music Theory"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments"],"term":"Fall 2014","instructors":["Teresa M. Neff"],"url":"https://ocw.mit.edu/courses/21m-295-american-popular-music-fall-2014/","views":1456},{"id":"2.58J+spring_2006","numbers":["2.58J","10.74J"],"title":"Radiative Transfer","summary":"This course investigates the principles of thermal radiation and their applications to engineering heat and photon transfer problems. Topics include quantum and classical models of radiative properties of materials, electromagnetic wave theory for thermal radiation, radiative transfer in absorbing, emitting, and scattering media, and coherent laser radiation. Applications cover laser-material interactions, imaging, infrared instrumentation, global warming, semiconductor manufacturing, combustion, furnaces, and high temperature processing.","departments":["Chemical Engineering","Mechanical Engineering"],"areas":["Data Science, Analytics & Computer Technology","Energy, Climate & Sustainability","Engineering","Science & Math"],"topics":["Chemical Engineering","Climate","Combustion","Electromagnetism","Energy","Engineering","Particle Physics","Physics","Science","Technology","Thermodynamics","Transport Processes"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2006","instructors":["Prof. Gang Chen"],"url":"https://ocw.mit.edu/courses/2-58j-radiative-transfer-spring-2006/","views":1456},{"id":"12.811+spring_2011","numbers":["12.811"],"title":"Tropical Meteorology","summary":"This course describes the large-scale circulation systems of the tropical atmosphere and analyses the dynamics of such systems. Topics include: Radiative-convective equilibrium; the Hadley and walker circulation; monsoons; tropical boundary layers; theory of the response of the tropical atmosphere to localized sea-surface temperature anomalies; intraseasonal oscillations; equatorial waves; El Niño/Southern Oscillation; easterly waves; and tropical cyclones.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math"],"topics":["Atmospheric Science","Climate Studies","Earth Science","Engineering","Geophysics","Hydrodynamics","Ocean Engineering","Physics","Science","Thermodynamics"],"levels":["Graduate"],"features":["Lecture Notes","Projects"],"term":"Spring 2011","instructors":["Prof. Kerry Emanuel","Allison Wing"],"url":"https://ocw.mit.edu/courses/12-811-tropical-meteorology-spring-2011/","views":1455},{"id":"21L.471+spring_2002","numbers":["21L.471"],"title":"Major English Novels: Reading Romantic Fiction","summary":"Though the era of British Romanticism (ca. 1790-1830) is sometimes exclusively associated with the poetry of these years, this period was just as importantly a time of great innovation in British prose fiction. Romantic novelists pioneered or revolutionized several genres, including social/philosophical problem novels, tales of sentiment and sensibility, and the historical novel. Writing in the years of the French Revolution, the Napoleonic wars, and the early industrial revolution, these writers conveyed a spirit of chaos and upheaval even in stories whose settings are seemingly farthest removed from those cataclysmic historical events. In this year’s offering of “Major English Novels,” we will read of plagues, wars, hysterics, monsters and more in novels by authors including William Godwin, Maria Edgeworth, Jane Austen, Mary Shelley, and Walter Scott. In the final weeks of the semester, we will read one major novel of the Victorian era, Charles Dickens’s Great Expectations, in light of these earlier texts. There will be two essay assignments, one 5-7 pages and one 8-10 pages in length, and required presentations.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2002","instructors":["Prof. Noel Jackson"],"url":"https://ocw.mit.edu/courses/21l-471-major-english-novels-reading-romantic-fiction-spring-2002/","views":1454},{"id":"20.400J+spring_2006","numbers":["20.400J","7.548J"],"title":"Perspectives in Biological Engineering","summary":"This seminar-format course provides an in-depth presentation and discussion of how engineering and biological approaches can be combined to solve problems in science and technology, emphasizing integration of biological information and methodologies with engineering analysis, synthesis, and design. Emphasis is placed on molecular mechanisms underlying cellular processes, including signal transduction, gene expression networks, and functional responses.","departments":["Biological Engineering","Biology"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Computation and Systems Biology","Engineering","Science"],"levels":["Graduate"],"features":[],"term":"Spring 2006","instructors":["Prof. Douglas Lauffenburger","Prof. Peter Dedon"],"url":"https://ocw.mit.edu/courses/20-400j-perspectives-in-biological-engineering-spring-2006/","views":1453},{"id":"1.84J+fall_2013","numbers":["1.84J","10.817J","12.807J"],"title":"Atmospheric Chemistry","summary":"This course provides a detailed overview of the chemical transformations that control the abundances of key trace species in the Earth’s atmosphere. Emphasizes the effects of human activity on air quality and climate. Topics include photochemistry, kinetics, and thermodynamics important to the chemistry of the atmosphere; stratospheric ozone depletion; oxidation chemistry of the troposphere; photochemical smog; aerosol chemistry; and sources and sinks of greenhouse gases and other climate forcers.","departments":["Chemical Engineering","Civil and Environmental Engineering","Earth, Atmospheric, and Planetary Sciences"],"areas":["Energy, Climate & Sustainability","Science & Math"],"topics":["Atmospheric Science","Climate","Earth Science","Energy","Science"],"levels":["Graduate"],"features":["Instructor Insights","Lecture Notes","Problem Sets"],"term":"Fall 2013","instructors":["Prof. Jesse Kroll"],"url":"https://ocw.mit.edu/courses/1-84j-atmospheric-chemistry-fall-2013/","views":1450},{"id":"15.996+fall_2004","numbers":["15.996"],"title":"Cross-Cultural Leadership","summary":"Cross Cultural Leadership is a collaborative research seminar that examines what constitutes “effective” leadership across cultures. It is collaborative because the students are expected to provide some of the content. The weekly readings target particular aspects of cultural differentiation. Working within those topics, students are asked to describe aspects of leadership in particular cultures based on their research and/or personal experiences. The goal of the course is to help prepare students for business assignments outside of their native countries.\n\nCourse deliverables include: active participation in the class, contribution of class content on a weekly basis and an end of course paper that explores some aspect of leadership across cultures.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Anthropology","Business","Cultural Anthropology","Leadership","Social Science"],"levels":["Graduate"],"features":["Activity Assignments","Lecture Notes"],"term":"Fall 2004","instructors":["Pat Bentley"],"url":"https://ocw.mit.edu/courses/15-996-cross-cultural-leadership-fall-2004/","views":1450},{"id":"17.40+fall_2017","numbers":["17.40"],"title":"American Foreign Policy: Past, Present, and Future","summary":"This course explores the reasons for America’s past wars and interventions. It covers the consequences of American policies, and evaluates these consequences for the U.S. and the world. History covered includes World Wars I and II, the Korean and Indochina wars, the Cuban Missile Crisis and current conflicts, including those in in Iraq and Afghanistan, and against Al Qaeda.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","International Relations","Military Studies","Political Science","Public Administration","Public Policy","Social Science"],"levels":["Undergraduate"],"features":["Exams","Lecture Notes","Presentation Assignments","Written Assignments"],"term":"Fall 2017","instructors":["Prof. Stephen Van Evera"],"url":"https://ocw.mit.edu/courses/17-40-american-foreign-policy-past-present-and-future-fall-2017/","views":1446},{"id":"21L.701+spring_2009","numbers":["21L.701"],"title":"Literary Interpretation: Literature and Urban Experience","summary":"Alienation, overcrowding, sensory overload, homelessness, criminality, violence, loneliness, sprawl, blight. How have the realities of city living influenced literature’s formal and thematic techniques? How useful is it to think of literature as its own kind of “map” of urban space? Are cities too grand, heterogeneous, and shifting to be captured by writers? In this seminar we will seek answers to these questions in key city literature, and in theoretical works that endeavor to understand the culture of cities.","departments":["Literature"],"areas":["Humanities","Social Sciences"],"topics":["Comparative Literature","Criticism","Humanities","Literature","Philosophy","Social Science","Urban Studies"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Spring 2009","instructors":["Prof. Sarah Brouillette"],"url":"https://ocw.mit.edu/courses/21l-701-literary-interpretation-literature-and-urban-experience-spring-2009/","views":1446},{"id":"4.123+fall_2003","numbers":["4.123"],"title":"Architectural Design, Level I: Perceptions and Processes","summary":"This studio explores the notion of in-between by engaging several relationships; the relationship between intervention and perception, between representation and notation and between the fixed and the temporal. In the Exactitude in Science, Jorge Luis Borges tells the perverse tale of the one to one scale map, where the desire for precision and power leads to the escalating production of larger and more accurate maps of the territory. For Jean Baudrillard, “The territory no longer precedes the map nor survives it. …it is the map that precedes the territory… and thus, it would be the territory whose shreds are slowly rotting across the map.” The map or the territory, left to ruin-shredding across the ‘other’, beautifully captures the tension between reality and representation. Mediating between collective desire and territorial surface, maps filter, create, frame, scale, orient, and project. A map has agency. It is not merely representational but operational, the experience and discursive potential of this process lies in the reciprocity between the representation and the real. It is in-between these specific sets of relationships that this studio positions itself.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architecture","Environmental Design","Fine Arts"],"levels":["Graduate"],"features":["Design Assignments with Examples"],"term":"Fall 2003","instructors":["Prof. Meejin Yoon"],"url":"https://ocw.mit.edu/courses/4-123-architectural-design-level-i-perceptions-and-processes-fall-2003/","views":1444},{"id":"4.322+fall_2003","numbers":["4.322"],"title":"Introduction to Sculpture","summary":"This class introduces fundamental issues in sculpture such as site, context, process, psychology and aesthetics of the object, and the object’s relation to the body. During the semester Introduction to Sculpture will explore issues of interpretation and audience interaction. As a significant component to this class introductions to a variety of materials and techniques both traditional (wood, metal, plaster) as well as non-traditional (fabric, latex, found objects, rubber, etc.) will be emphasized.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architecture","Environmental Design","Fine Arts","Visual Arts"],"levels":["Undergraduate"],"features":["Activity Assignments","Projects with Examples"],"term":"Fall 2003","instructors":["Prof. Sanjit Sethi"],"url":"https://ocw.mit.edu/courses/4-322-introduction-to-sculpture-fall-2003/","views":1444},{"id":"24.947+spring_2013","numbers":["24.947"],"title":"Language Disorders in Children","summary":"This seminar focuses on reading and discussion of current linguistic theory, first language acquisition and language disorders in young children. It also focuses on development of a principled understanding of language disorders at the phonological, morphological and syntactic levels, examining ways in which these disorders confront theories of language and acquisition.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Language","Linguistics"],"levels":["Graduate"],"features":["Instructor Insights","Lecture Notes","Written Assignments"],"term":"Spring 2013","instructors":["Prof. Suzanne Flynn"],"url":"https://ocw.mit.edu/courses/24-947-language-disorders-in-children-spring-2013/","views":1443},{"id":"RES.16-9960+spring_2026","numbers":["RES.16-9960"],"title":"The Engineering Student’s Guide to Effective Technical Communication","summary":"Effective communication of technical content is essential to a student’s success before and after graduation. This course consists of short workshop videos specially adapted for the OCW format, with accompanying activities designed to help you develop specific communication skills. It is designed for you to pick and choose the topics that are relevant to you and to access them in any order.\n\nThis course is produced by the MIT Department of Aeronautics and Astronautics Communication Lab. Course materials and presentations were developed and presented by the Communication Lab Fellows, who are graduate students in AeroAstro with specialized training in effective technical communication. The Fellows provide technical communication support in the department and beyond.","departments":["Aeronautics and Astronautics"],"areas":["Engineering","Humanities"],"topics":["Aerospace Engineering","Engineering","Humanities","Literature","Technical Writing"],"levels":[],"features":["Activity Assignments","Editable Files","Lecture Videos"],"term":"Spring 2026","instructors":["MIT AeroAstro Communication Lab","Evan Kramer","Nicholas Rober","Annika Thomas"],"url":"https://ocw.mit.edu/courses/res-16-9960-the-engineering-students-guide-to-effective-technical-communication-spring-2026/","views":1443},{"id":"15.223+fall_2011","numbers":["15.223"],"title":"Global Markets, National Politics and the Competitive Advantage of Firms","summary":"This course examines opportunities and risks firms face in today’s global market. It provides conceptual tools for analyzing how governments and social institutions influence economic competition among firms embedded in different national settings. Public policies and institutions that shape competitive outcomes are examined through cases and analytical readings on different companies and industries operating in both developed and emerging markets.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Globalization","Industrial Organization","International Economics","Public Administration","Public Policy","Social Science"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Projects","Written Assignments"],"term":"Fall 2011","instructors":["Prof. Simon Johnson"],"url":"https://ocw.mit.edu/courses/15-223-global-markets-national-politics-and-the-competitive-advantage-of-firms-fall-2011/","views":1442},{"id":"21H.101+fall_2010","numbers":["21H.101"],"title":"American History to 1865","summary":"This course provides a basic history of American social, economic, and political development from the colonial period through the Civil War. It examines the colonial heritages of Spanish and British America; the American Revolution and its impact; the establishment and growth of the new nation; and the Civil War, its background, character, and impact. Readings include writings of the period by J. Winthrop, T. Paine, T. Jefferson, J. Madison, W. H. Garrison, G. Fitzhugh, H. B. Stowe, and A. Lincoln.","departments":["History"],"areas":["Humanities"],"topics":["American History","History","Humanities"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2010","instructors":["Prof. Pauline Maier"],"url":"https://ocw.mit.edu/courses/21h-101-american-history-to-1865-fall-2010/","views":1441},{"id":"21A.260+fall_2005","numbers":["21A.260"],"title":"Culture, Embodiment and the Senses","summary":"Culture, Embodiment, and the Senses will provide an historical and cross-cultural analysis of the politics of sensory experience. The subject will address western philosophical debates about mind, brain, emotion, and the body and the historical value placed upon sight, reason, and rationality, versus smell, taste, and touch as acceptable modes of knowing and knowledge production. We will assess cultural traditions that challenge scientific interpretations of experience arising from western philosophical and physiological models. The class will examine how sensory experience lies beyond the realm of individual physiological or psychological responses and occurs within a culturally elaborated field of social relations. Finally, we will debate how discourse about the senses is a product of particular modes of knowledge production that are themselves contested fields of power relations.","departments":["Anthropology"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Humanities","Philosophy","Political Philosophy","Psychology","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Fall 2005","instructors":["Prof. Erica James"],"url":"https://ocw.mit.edu/courses/21a-260-culture-embodiment-and-the-senses-fall-2005/","views":1441},{"id":"21G.802+spring_2012","numbers":["21G.802","21G.852"],"title":"Portuguese II","summary":"This course is a continuation of 21G.801. It focuses on expanding communication skills and further development of linguistic competency using a variety of authentic sources, such as the Internet, audio, video, and printed materials, to help develop cultural awareness and linguistic proficiency. This course is conducted entirely in Portuguese.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","Language","Portuguese"],"levels":["Undergraduate","Graduate"],"features":["Activity Assignments"],"term":"Spring 2012","instructors":["Dr. Nilma Dominique"],"url":"https://ocw.mit.edu/courses/21g-802-portuguese-ii-spring-2012/","views":1441},{"id":"15.389A+fall_2010","numbers":["15.389A"],"title":"Global Entrepreneurship Lab: Asia-Pacific","summary":"15.389A Global Entrepreneurship Lab: Asia-Pacific enables teams of students to work with the top management of global start-ups and gain experience in running, and consulting to, a new enterprise outside the United States. The focus is on start-ups operating in emerging markets throughout the world, with a special focus on the Asia-Pacific region. The course combines an internship in a growing firm with in-class discussions of the issues and policies that affect the climate for innovation and start-up success around the world.\n\nSpecial Features\n\n15.389A is part of a two-section course and includes materials that cover entrepreneurship in the Asia-Pacific region. 15.389B Global Entrepreneurship Lab: Latin America, the Middle East, and Africa is also available on OpenCourseWare and covers topics pertinent to these additional regions.","departments":["Sloan School of Management"],"areas":["Business & Management","Innovation & Entrepreneurship","Social Sciences"],"topics":["Asian Studies","Business","Entrepreneurship","Finance","Globalization","Society"],"levels":["Graduate"],"features":["Lecture Notes","Projects","Written Assignments"],"term":"Fall 2010","instructors":["Prof. Yasheng Huang","Prof. Simon Johnson","Michellana Jester"],"url":"https://ocw.mit.edu/courses/15-389a-global-entrepreneurship-lab-asia-pacific-fall-2010/","views":1439},{"id":"21G.109+fall_2005","numbers":["21G.109"],"title":"Chinese III (Streamlined)","summary":"This course is the intermediate level of the streamlined curriculum, which is intended for students who, when they began streamlined I, had some background in the language, whether it be comprehension with limited speaking ability or quite fluent speaking ability. The focus of the course is on standard pronunciation and usage, on reading in both complex and simplified characters, and on writing. It is presupposed that students in Chinese III have already learned the pinyin system of representing pronunciation sufficiently well to be able to read texts in pinyin accurately. (If not, there are pinyin tutorials to assist you to learn the system.)","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Chinese","Humanities","Language"],"levels":["Undergraduate"],"features":["Activity Assignments"],"term":"Fall 2005","instructors":["Jin Zhang"],"url":"https://ocw.mit.edu/courses/21g-109-chinese-iii-streamlined-fall-2005/","views":1437},{"id":"11.006+fall_2016","numbers":["11.006"],"title":"Poverty and Economic Security","summary":"This course explores the evolution of poverty and economic security in the United States, within a global context. It examines the impact of recent economic restructuring and globalization, and reviews the current debate about the fate of the middle class, sources of increasing inequality, and approaches to advancing economic opportunity and security. In this class, students will study the topic of poverty and economic security through the lens of the lived experience of Americans: individuals, families, and households; exploring the history, geography, and forces shaping the likelihood of being poor in America.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Global Poverty","Social Justice","Social Science","Society","Sociology","Urban Studies"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2016","instructors":["Prof. Amy Glasmeier"],"url":"https://ocw.mit.edu/courses/11-006-poverty-and-economic-security-fall-2016/","views":1435},{"id":"2.882+spring_2005","numbers":["2.882"],"title":"System Design and Analysis based on AD and Complexity Theories","summary":"This course studies what makes a good design and how one develops a good design. Students consider how the design of engineered systems (such as hardware, software, materials, and manufacturing systems) differ from the “design” of natural systems such as biological systems; discuss complexity and how one makes use of complexity theory to improve design; and discover how one uses axiomatic design theory (AD theory) in design of many different kinds of engineered systems. Questions are analyzed using Axiomatic Design Theory and Complexity Theory. Case studies are presented including the design of machines, tribological systems, materials, manufacturing systems, and recent inventions. Implications of AD and complexity theories on biological systems discussed.","departments":["Mechanical Engineering"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Engineering","Nanotechnology","Systems Design","Systems Engineering","Theory of Computation"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2005","instructors":["Prof. Nam Suh","Dr. Taesik Lee"],"url":"https://ocw.mit.edu/courses/2-882-system-design-and-analysis-based-on-ad-and-complexity-theories-spring-2005/","views":1433},{"id":"21G.346+fall_2014","numbers":["21G.346"],"title":"Topics in Modern French Literature and Culture: Global Paris","summary":"This course investigates Paris’s oversized status as a global capital by looking at the events, transformations, cultures, and arts for which the city is known to help us better understand Paris and its place in French and global cultures today. Taught in French.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Criticism","French","Humanities","International Literature","Language","Literature"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2014","instructors":["Catherine E Clark"],"url":"https://ocw.mit.edu/courses/21g-346-topics-in-modern-french-literature-and-culture-global-paris-fall-2014/","views":1433},{"id":"6.111+fall_2002","numbers":["6.111"],"title":"Introductory Digital Systems Laboratory","summary":"6.111 consists of lectures and labs on digital logic, flipflops, PALs, counters, timing, synchronization, finite-state machines, and microprogrammed systems. Students are expected to design and implement a final project of their choice: games, music, digital filters, graphics, etc. The course requires extensive use of VHDL for describing and implementing digital logic designs. 6.111 is worth 12 Engineering Design Points.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Design and Engineering","Computer Science","Digital Systems","Electrical Engineering","Electronics","Engineering"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets","Projects with Examples"],"term":"Fall 2002","instructors":["Prof. Don Troxel","Prof. James L. Kirtley"],"url":"https://ocw.mit.edu/courses/6-111-introductory-digital-systems-laboratory-fall-2002/","views":1432},{"id":"21G.322J+fall_2016","numbers":["21G.322J","21H.242J"],"title":"Frenchness in an Era of Globalization","summary":"This course approaches the question of what constitutes Frenchness in today’s era of globalization through issues of memory, belonging, and cultural production. It explores the role of timeless traditions – common technologies, an internationally-spoken language, monuments open to the world, and foods such as wine and cheese – that remain quintessentially French. The course also covers recent scandals about France’s role in the world, such as its colonial identity and Dominique Strauss-Kahn’s New York debacle.\n\nTaught in French.","departments":["Global Studies and Languages","History"],"areas":["Humanities"],"topics":["French","Humanities","International Literature","Language","Literature"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2016","instructors":["Catherine E Clark"],"url":"https://ocw.mit.edu/courses/21g-322j-frenchness-in-an-era-of-globalization-fall-2016/","views":1431},{"id":"18.726+spring_2009","numbers":["18.726"],"title":"Algebraic Geometry","summary":"This course provides an introduction to the language of schemes, properties of morphisms, and sheaf cohomology. Together with 18.725 Algebraic Geometry, students gain an understanding of the basic notions and techniques of modern algebraic geometry.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2009","instructors":["Prof. Kiran Kedlaya"],"url":"https://ocw.mit.edu/courses/18-726-algebraic-geometry-spring-2009/","views":1430},{"id":"21A.429J+fall_2016","numbers":["21A.429J","STS.320J"],"title":"Environmental Conflict","summary":"This course explores the complex interrelationships among humans and natural environments, focusing on non-western parts of the world in addition to Europe and the United States. It uses environmental conflict to draw attention to competing understandings and uses of “nature” as well as the local, national and transnational power relationships in which environmental interactions are embedded. In addition to utilizing a range of theoretical perspectives, this subject draws upon a series of ethnographic case studies of environmental conflicts in various parts of the world.","departments":["Anthropology","Science, Technology, and Society"],"areas":["Science & Math","Social Sciences"],"topics":["Anthropology","Biology","Earth Science","Ecology","Environmental Science","Ethnography","Science","Social Science","Sociology"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2016","instructors":["Prof. Christine Walley"],"url":"https://ocw.mit.edu/courses/21a-429j-environmental-conflict-fall-2016/","views":1427},{"id":"21L.705+spring_2008","numbers":["21L.705"],"title":"Major Authors: John Milton","summary":"In 1667, John Milton published what he intended both as the crowning achievement of a poetic career and a justification of God’s ways to man: an epic poem which retold and reimagined the Biblical story of creation, temptation, and original sin. Even in a hostile political climate, Paradise Lost was almost immediately recognized as a classic, and one fate of a classic is to be rewritten, both by admirers and by antagonists. In this seminar, we will read Paradise Lost alongside works of 20th century fantasy and science fiction which rethink both Milton’s text and its source.\n\nStudents should come to the seminar having read Paradise Lost straight through at least once; this can be accomplished by taking the IAP subject, Reading Paradise Lost (21L.995), or independently. Twentieth century authors will include C. S. Lewis (Perelandra, The Lion, the Witch and the Wardrobe) and Philip Pullman (His Dark Materials), as well as assorted criticism. Each week, one class meeting will focus on Milton, and the other on one of the modern novels.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Criticism","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2008","instructors":["Prof. Mary Fuller"],"url":"https://ocw.mit.edu/courses/21l-705-major-authors-john-milton-spring-2008/","views":1426},{"id":"17.408+fall_2013","numbers":["17.408"],"title":"Chinese Foreign Policy","summary":"This course explores the leading theoretical and methodological approaches to studying China’s interaction with the international system since 1949. Readings include books and articles that integrate the study of China’s foreign policy with the field of international relations.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["International Relations","Political Science","Social Science"],"levels":["Graduate"],"features":["Instructor Insights","Written Assignments with Examples"],"term":"Fall 2013","instructors":["Prof. M. Taylor Fravel"],"url":"https://ocw.mit.edu/courses/17-408-chinese-foreign-policy-fall-2013/","views":1424},{"id":"17.THT+fall_2004","numbers":["17.THT"],"title":"Thesis Research Design Seminar","summary":"This seminar is for students who plan to write a senior thesis in Political Science, and is required of all MIT Political Science majors. Seminar participants will develop their research topics, review relevant research and scholarship, frame their research questions and arguments, choose an appropriate methodology for analysis, draft the introductory and methodology sections of their theses, and write a complete prospectus of the project.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Political Science","Social Science"],"levels":["Undergraduate"],"features":[],"term":"Fall 2004","instructors":["Prof. Roger Petersen"],"url":"https://ocw.mit.edu/courses/17-tht-thesis-research-design-seminar-fall-2004/","views":1424},{"id":"2.081J+spring_2007","numbers":["2.081J","16.230J"],"title":"Plates and Shells","summary":"This course explores the following topics: derivation of elastic and plastic stress-strain relations for plate and shell elements; the bending and buckling of rectangular plates; nonlinear geometric effects; post-buckling and ultimate strength of cold formed sections and typical stiffened panels used in naval architecture; the general theory of elastic shells and axisymmetric shells; buckling, crushing and bending strength of cylindrical shells with application to offshore structures; and the application to crashworthiness of vehicles and explosive and impact loading of structures. The class is taught during the first half of term.","departments":["Aeronautics and Astronautics","Mechanical Engineering"],"areas":["Engineering"],"topics":["Aerospace Engineering","Engineering","Fluid Mechanics","Mechanical Engineering","Ocean Engineering","Ocean Structures","Solid Mechanics","Structural Mechanics"],"levels":["Graduate"],"features":["Exams","Problem Sets"],"term":"Spring 2007","instructors":["Prof. Tomasz Wierzbicki"],"url":"https://ocw.mit.edu/courses/2-081j-plates-and-shells-spring-2007/","views":1423},{"id":"11.946J+summer_2004","numbers":["11.946J","4.185J"],"title":"Beijing Urban Design Studio","summary":"The Beijing Urban Design Studio is a joint program between the MIT and Tsinghua University Schools of Architecture and Planning. The goal of the studio is to foster international cooperation through the undertaking of a joint urban design and planning initiative in the city of Beijing involving important, often controversial, sites and projects. Since 1995, almost 250 MIT and Tsinghua University students and faculty have participated in this annual studio, making it one of the most successful and enduring international academic programs between China and the US. It has received the Irwin Sizer Award from MIT for outstanding innovation in education. The studio takes place over five weeks in June and July including several weeks in residence at Tsinghua University and two brief study tours to locations and projects that inform the work. It will include 18-20 MIT and 10-15 Tsinghua Architecture and Planning students. The Beijing City Planning Institute, responsible for strategic planning in the city, participates in the studio as the client.","departments":["Architecture","Urban Studies and Planning"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Architecture","Economics","Environmental Design","Fine Arts","International Development","International Relations","Political Science","Social Science","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Image Gallery","Projects with Examples"],"term":"Summer 2004","instructors":["Prof. Dennis Frenchman","Prof. Jan Wampler","Kenneth Kruckemeyer","Prof. Paul Lukez"],"url":"https://ocw.mit.edu/courses/11-946j-beijing-urban-design-studio-summer-2004/","views":1422},{"id":"12.108+fall_2004","numbers":["12.108"],"title":"Structure of Earth Materials","summary":"This course provides a comprehensive introduction to crystalline structure, crystal chemistry, and bonding in rock-forming minerals. It introduces the theory relating crystal structure and crystal symmetry to physical properties such as refractive index, elastic modulus, and seismic velocity. It surveys the distribution of silicate, oxide, and metallic minerals in the interiors and on the surfaces of planets, and discusses the processes that led to their formation. It also addresses why diamonds are hard and why micas split into thin sheets.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Chemistry","Earth Science","Engineering","Geology","Mechanical Engineering","Physical Chemistry","Planetary Science","Science","Solid Mechanics"],"levels":["Undergraduate"],"features":["Image Gallery","Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. J. Evans","Prof. Timothy Grove"],"url":"https://ocw.mit.edu/courses/12-108-structure-of-earth-materials-fall-2004/","views":1421},{"id":"21M.250+spring_2014","numbers":["21M.250"],"title":"Beethoven to Mahler","summary":"This course surveys Romantic musical genres including song, choral music, opera, piano sonata, character cycle, concerto, symphony, and symphonic poem, including the composers Beethoven, Schubert, Berlioz, Chopin, Brahms, Wagner, Verdi, Tchaikovsky, and Mahler. Written essays and oral presentations are based on live performances as well as listening and reading assignments.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History"],"levels":["Undergraduate"],"features":["Instructor Insights","Lecture Notes","Written Assignments"],"term":"Spring 2014","instructors":["Teresa M. Neff"],"url":"https://ocw.mit.edu/courses/21m-250-beethoven-to-mahler-spring-2014/","views":1420},{"id":"21T.224+spring_2004","numbers":["21T.224"],"title":"Technical Design: Scenery, Mechanisms, and Special Effects","summary":"This class looks at the special structural and practical needs of theatrical scenery and effects and how they can be constructed. We map the technical design process from initial meetings to realization on stage. The class emphasizes safety, budgeting, and problem solving. Ten 1-3 page Tech notes are required as well as a final project. Work includes actual production assignments as well as paper design projects.","departments":["Theater Arts"],"areas":["Art, Design & Architecture","Engineering"],"topics":["Engineering","Fine Arts","Mechanical Design","Mechanical Engineering","Performance Arts","Theatrical Design"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2004","instructors":["Michael Katz"],"url":"https://ocw.mit.edu/courses/21m-735-technical-design-scenery-mechanisms-and-special-effects-spring-2004/","views":1420},{"id":"17.407+fall_2005","numbers":["17.407","17.408"],"title":"Chinese Foreign Policy","summary":"This lecture course provides students with a comprehensive introduction to the international relations of the People’s Republic of China. China’s foreign relations during the Cold War as well as contemporary diplomatic, security and economic issues will be examined to identify and explain China’s foreign policy goals and their implementation since 1949. Throughout, this course will investigate the sources of conflict and cooperation in China’s behavior, assessing competing explanations for key events and policies. Readings will be drawn from political science, history, and international relations theory.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Asian Studies","International Relations","Political Science","Public Administration","Public Policy","Social Science","Society"],"levels":["Undergraduate"],"features":[],"term":"Fall 2005","instructors":["Prof. M. Taylor Fravel"],"url":"https://ocw.mit.edu/courses/17-407-chinese-foreign-policy-fall-2005/","views":1418},{"id":"6.781J+spring_2006","numbers":["6.781J","2.391J"],"title":"Submicrometer and Nanometer Technology","summary":"This course surveys techniques to fabricate and analyze submicron and nanometer structures, with applications. Optical and electron microscopy is reviewed. Additional topics that are covered include: surface characterization, preparation, and measurement techniques, resist technology, optical projection, interferometric, X-ray, ion, and electron lithography; Aqueous, ion, and plasma etching techniques; lift-off and electroplating; and ion implantation. Applications in microelectronics, microphotonics, information storage, and nanotechnology will also be explored.\n\nAcknowledgements\n\nThe Instructors would like to thank Bob Barsotti, Bryan Cord, and Ben Wunsch for their work on the Atomic Force Microscope video. They would also like to thank Bryan Cord for creating each video.","departments":["Electrical Engineering and Computer Science","Mechanical Engineering"],"areas":["Engineering"],"topics":["Electrical Engineering","Engineering","Mechanical Engineering","Microtechnology","Nanotechnology"],"levels":["Graduate"],"features":["Demonstration Videos","Problem Sets"],"term":"Spring 2006","instructors":["Prof. George Barbastathis","Prof. Henry Smith","Prof. Karl Berggren"],"url":"https://ocw.mit.edu/courses/6-781j-submicrometer-and-nanometer-technology-spring-2006/","views":1418},{"id":"14.124+spring_2017","numbers":["14.124"],"title":"Microeconomic Theory IV","summary":"The topic of the class is information and contract theory. The purpose is to give an introduction to some of the main subjects in this field: decision making under uncertainty, risk sharing, moral hazard, adverse selection, mechanism design, and incomplete contracting.","departments":["Economics"],"areas":["Social Sciences"],"topics":["Economics","Microeconomics","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2017","instructors":["Prof. Bengt Holmstrom"],"url":"https://ocw.mit.edu/courses/14-124-microeconomic-theory-iv-spring-2017/","views":1417},{"id":"2.672+spring_2009","numbers":["2.672"],"title":"Project Laboratory","summary":"This is an engineering laboratory subject for mechanical engineering juniors and seniors. Major emphasis is on interplay between analytical and experimental methods in solution of research and development problems. Communication (written and oral) of results is also a strong component of the course. Groups of two or three students work together on three projects during the term.","departments":["Mechanical Engineering"],"areas":["Engineering"],"topics":["Engineering","Mechanical Engineering"],"levels":["Undergraduate"],"features":["Image Gallery"],"term":"Spring 2009","instructors":["Prof. Douglas Hart","Prof. Wai Cheng"],"url":"https://ocw.mit.edu/courses/2-672-project-laboratory-spring-2009/","views":1417},{"id":"ESD.933+spring_2005","numbers":["ESD.933"],"title":"Technology Policy Negotiations and Dispute Resolution","summary":"Technology Policy Negotiations and its prequel, ESD.932, Technology Policy Organizations, form a sequence on Organizational Processes in Technology Policy. This course provides a core framework for an interest-based approach to negotiations, along with a systems approach to dispute resolution in organizations. Core interactive skills are developed, including communication skills, negotiating over the “rules of game,” and cross-cultural negotiations. Key assignments center on ethical debates in technology policy, regional economic development challenges, and assessment of organizational dispute resolution systems.","departments":["Engineering Systems Division"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Communication","Organizational Behavior","Public Administration","Science and Technology Policy","Social Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2005","instructors":["Prof. Joel Cutcher-Gershenfeld"],"url":"https://ocw.mit.edu/courses/esd-933-technology-policy-negotiations-and-dispute-resolution-spring-2005/","views":1416},{"id":"21H.001+fall_2013","numbers":["21H.001"],"title":"How to Stage a Revolution","summary":"This course explores fundamental questions about the causes and nature of revolutions by looking at how people overthrow their rulers and establish new governments. Considers a set of major political transformations throughout the world and across centuries to understand the meaning of revolution and evaluate its impact. Examines how revolutionaries have attempted to establish their ideals and realize their goals. Asks whether radical upheavals require bloodshed, violence, or even terror. Seeks to explain why some revolutions succeed and others fail. Materials include the writings of revolutionaries, declarations and constitutions, music, films, art, novels, memoirs, and newspapers.","departments":["History"],"areas":["Humanities"],"topics":["American History","History","Humanities","Middle Eastern History","Modern History"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2013","instructors":["Prof. Malick Ghachem","Prof. Jeffrey S. Ravel","Prof. Craig Wilder"],"url":"https://ocw.mit.edu/courses/21h-001-how-to-stage-a-revolution-fall-2013/","views":1414},{"id":"6.035+spring_2010","numbers":["6.035"],"title":"Computer Language Engineering","summary":"This course analyzes issues associated with the implementation of higher-level programming languages. Topics covered include: fundamental concepts, functions, and structures of compilers, the interaction of theory and practice, and using tools in building software. The course includes a multi-person project on compiler design and implementation.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Engineering","Programming Languages","Software Design and Engineering"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Projects"],"term":"Spring 2010","instructors":["Prof. Saman Amarasinghe","Prof. Martin Rinard"],"url":"https://ocw.mit.edu/courses/6-035-computer-language-engineering-spring-2010/","views":1413},{"id":"16.72+fall_2006","numbers":["16.72"],"title":"Air Traffic Control","summary":"This course introduces the various aspects of present and future Air Traffic Control systems. Among the topics in the present system that we will discuss are the systems-analysis approach to problems of capacity and safety, surveillance, including the National Airspace System and Automated Terminal Radar Systems, navigation subsystem technology, aircraft guidance and control, communications, collision avoidance systems and sequencing and spacing in terminal areas. The class will then talk about future directions and development and have a critical discussion of past proposals and of probable future problem areas.","departments":["Aeronautics and Astronautics"],"areas":["Engineering","Social Sciences"],"topics":["Aerospace Engineering","Engineering","Guidance and Control Systems","Social Science","Transportation Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2006","instructors":["Prof. John Hansman"],"url":"https://ocw.mit.edu/courses/16-72-air-traffic-control-fall-2006/","views":1410},{"id":"17.410+spring_2006","numbers":["17.410","17.411"],"title":"Globalization, Migration, and International Relations","summary":"Tracing the evolution of international interactions, this course examines the dimensions of globalization in terms of scale and scope. It is divided into three parts; together they are intended to provide theoretical, empirical, and policy perspectives on source and consequences of globalization, focusing on emergent structures and processes, and on the implications of flows of goods and services across national boundaries – with special attention to the issue of migration, on the assumption that people matter and matter a lot. An important concern addressed pertains to the dilemmas of international policies that are shaped by the macro-level consequences of micro-level behavior. 17.411 fulfills undergraduate public policy requirement in the major and minor. Graduate students are expected to explore the subject in greater depth through reading and individual research.","departments":["Political Science"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Globalization","International Relations","Political Economy","Political Science","Public Administration","Public Policy","Social Science"],"levels":["Graduate"],"features":[],"term":"Spring 2006","instructors":["Prof. Nazli Choucri"],"url":"https://ocw.mit.edu/courses/17-410-globalization-migration-and-international-relations-spring-2006/","views":1409},{"id":"21L.460+spring_2004","numbers":["21L.460","WGS.514"],"title":"Medieval Literature: Medieval Women Writers","summary":"This survey provides a general introduction to medieval European literature (from Late Antiquity to the Fifteenth Century) from the perspective of women writers from a variety of cultures, social backgrounds, and historical timeperiods. Though much of the class will be devoted to exploring the evolution of a new literary tradition by and for women from its earliest emergence in the West, wider historical and cultural movements will also be addressed: the Fall of the Roman Empire, the growth of religious communities, the shift from orality to literacy, the culture of chivalry and courtly love, the emergence of scholasticism and universities, changes in devotional practices, the persecution of heretics, the rise of nationalism and class consciousness. Authors will include some of the most famous women of the period: Hildegard of Bingen, Heloise of Paris, Marie de France, Christine de Pizan, Joan of Arc, Margery Kempe, along with many interesting and intriguing though lesser known figures.","departments":["Literature","Women's and Gender Studies"],"areas":["Humanities","Social Sciences"],"topics":["Criticism","History","Humanities","International Literature","Literature","Medieval History","Society","Women's Studies"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Spring 2004","instructors":["Prof. James Cain"],"url":"https://ocw.mit.edu/courses/21l-460-medieval-literature-medieval-women-writers-spring-2004/","views":1409},{"id":"STS.002+fall_2003","numbers":["STS.002"],"title":"Toward the Scientific Revolution","summary":"This subject traces the evolution of ideas about nature, and how best to study and explain natural phenomena, beginning in ancient times and continuing through the Middle Ages and the Renaissance. A central theme of the subject is the intertwining of conceptual and institutional relations within diverse areas of inquiry: cosmology, natural history, physics, mathematics, and medicine.","departments":["Science, Technology, and Society"],"areas":["Humanities"],"topics":["History","History of Science and Technology","Humanities","Intellectual History"],"levels":["Undergraduate"],"features":[],"term":"Fall 2003","instructors":["Prof. David Kaiser"],"url":"https://ocw.mit.edu/courses/sts-002-toward-the-scientific-revolution-fall-2003/","views":1408},{"id":"21T.220+spring_2005","numbers":["21T.220"],"title":"Design for the Theater: Scenery","summary":"This course will examine theory of scenic design as currently practiced, as well as historical traditions for use of performance space and audience/performer engagement. Four play scripts and one opera or dance theater piece will be designed after in-depth analysis; emphasis will be on the social, political and cultural milieu at the time of their creation, and now.","departments":["Theater Arts"],"areas":["Art, Design & Architecture"],"topics":["Fine Arts","Performance Arts","Theatrical Design"],"levels":["Undergraduate"],"features":["Image Gallery","Written Assignments"],"term":"Spring 2005","instructors":["William Fregosi"],"url":"https://ocw.mit.edu/courses/21m-734-design-for-the-theater-scenery-spring-2005/","views":1406},{"id":"15.389B+fall_2010","numbers":["15.389B"],"title":"Global Entrepreneurship Lab: Latin America, the Middle East, and Africa","summary":"15.389B Global Entrepreneurship Lab: Latin America, the Middle East, and Africa enables teams of students to work with the top management of global start-ups and gain experience in running, and consulting to, a new enterprise outside the United States. The focus is on start-ups operating in emerging markets throughout the world, with a special focus on Latin America, the Middle East, and Africa. The course combines an internship in a growing firm with in-class discussions of the issues and policies that affect the climate for innovation and start-up success around the world.\n\nSpecial Features\n\n15.389B is part of a two-section course and includes materials that cover entrepreneurship in Latin America, the Middle East, and Africa. 15.389A Global Entrepreneurship Lab: Asia-Pacific is also available on OpenCourseWare and covers topics pertinent to these additional regions.","departments":["Sloan School of Management"],"areas":["Business & Management","Innovation & Entrepreneurship","Social Sciences"],"topics":["Business","Economics","Entrepreneurship","Globalization","Industrial Organization","Social Science"],"levels":["Graduate"],"features":["Projects","Written Assignments"],"term":"Fall 2010","instructors":["Prof. Simon Johnson","Prof. Yasheng Huang","Michellana Jester"],"url":"https://ocw.mit.edu/courses/15-389b-global-entrepreneurship-lab-latin-america-the-middle-east-and-africa-fall-2010/","views":1406},{"id":"17.20+spring_2004","numbers":["17.20"],"title":"Introduction to the American Political Process","summary":"This class introduces students to innovative as well as classic approaches to studying U.S. government. The writing assignments will help you explore, through a variety of lenses, statis and change in the American political system over the last three decades. In the end each student will have a solid grounding in our national political institutions and processes, sharper reading and writing skills, and insight into approaching politics critically and analytically.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2004","instructors":["Prof. Adam Berinsky"],"url":"https://ocw.mit.edu/courses/17-20-introduction-to-the-american-political-process-spring-2004/","views":1404},{"id":"STS.036+spring_2008","numbers":["STS.036"],"title":"Technology and Nature in American History","summary":"This course considers how the visual and material world of “nature” has been reshaped by industrial practices, ideologies, and institutions, particularly in nineteenth- and twentieth-century America. Topics include land-use patterns; the changing shape of cities and farms; the redesign of water systems; the construction of roads, dams, bridges, irrigation systems; the creation of national parks; ideas about wilderness; and the role of nature in an industrial world. From small farms to suburbia, Walden Pond to Yosemite, we will ask how technological and natural forces have interacted, and whether there is a place for nature in a technological world.\n\nAcknowledgement\n\nThis class is based on one originally designed and taught by Prof. Deborah Fitzgerald. Her Fall 2004 version can be viewed by following the link under Archived Courses on the right side of this page.","departments":["Science, Technology, and Society"],"areas":["Engineering","Humanities","Social Sciences"],"topics":["American History","Civil Engineering","Engineering","History","History of Science and Technology","Humanities","Social Science","Urban Planning","Urban Studies"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Spring 2008","instructors":["Jamie Pietruska"],"url":"https://ocw.mit.edu/courses/sts-036-technology-and-nature-in-american-history-spring-2008/","views":1403},{"id":"WGS.S10+spring_2014","numbers":["WGS.S10"],"title":"Gender, Power, Leadership, and the Workplace","summary":"This course will provide students with an analytic framework to understand the roles that gender, race, and class play in defining and determining access to leadership and power in the U.S., especially in the context of the workplace. We will explore women and men in leadership positions within the corporate, political and non-profit sectors, with attention to the roles of women of color and immigrant women within this context. We will also look at specific policies such as affirmative action, parental leave, child-care policy, and working-time policies and the role they play–or could play–in achieving parity. We will further investigate ways in which these policies address gender, racial, and class inequities, and think critically about mechanisms for change. The course will be highly interactive, and will combine texts, theater, videos and visual arts.","departments":["Women's and Gender Studies"],"areas":["Business & Management","Social Sciences"],"topics":["American Politics","Business","Gender Studies","Leadership","Political Science","Public Administration","Public Policy","Social Science","Social Welfare","Society","Women's Studies"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments with Examples"],"term":"Spring 2014","instructors":["Dr. Mindy Fried"],"url":"https://ocw.mit.edu/courses/wgs-s10-gender-power-leadership-and-the-workplace-spring-2014/","views":1401},{"id":"12.810+spring_2008","numbers":["12.810"],"title":"Dynamics of the Atmosphere","summary":"This course begins with a study of the role of dynamics in the general physics of the atmosphere, the consideration of the differences between modeling and approximation, and the observed large-scale phenomenology of the atmosphere. Only then are the basic equations derived in rigorous manner. The equations are then applied to important problems and methodologies in meteorology and climate, with discussions of the history of the topics where appropriate. Problems include the Hadley circulation and its role in the general circulation, atmospheric waves including gravity and Rossby waves and their interaction with the mean flow, with specific applications to the stratospheric quasi-biennial oscillation, tides, the super-rotation of Venus’ atmosphere, the generation of atmospheric turbulence, and stationary waves among other problems. The quasi-geostrophic approximation is derived, and the resulting equations are used to examine the hydrodynamic stability of the circulation with applications ranging from convective adjustment to climate.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Atmospheric Science","Earth Science","Engineering","Geophysics","Hydrodynamics","Ocean Engineering","Planetary Science","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2008","instructors":["Prof. Richard Lindzen"],"url":"https://ocw.mit.edu/courses/12-810-dynamics-of-the-atmosphere-spring-2008/","views":1400},{"id":"22.251+fall_2009","numbers":["22.251"],"title":"Systems Analysis of the Nuclear Fuel Cycle","summary":"This course provides an in-depth technical and policy analysis of various options for the nuclear fuel cycle. Topics include uranium supply, enrichment fuel fabrication, in-core physics and fuel management of uranium, thorium and other fuel types, reprocessing and waste disposal. Also covered are the principles of fuel cycle economics and the applied reactor physics of both contemporary and proposed thermal and fast reactors. Nonproliferation aspects, disposal of excess weapons plutonium, and transmutation of actinides and selected fission products in spent fuel are examined. Several state-of-the-art computer programs are provided for student use in problem sets and term papers.","departments":["Nuclear Science and Engineering"],"areas":["Engineering","Social Sciences"],"topics":["Engineering","Nuclear Engineering","Nuclear Materials","Nuclear Systems, Policy, and Economics","Public Administration","Science and Technology Policy","Social Science","Systems Engineering"],"levels":["Graduate"],"features":["Problem Sets"],"term":"Fall 2009","instructors":["Prof. Mujid S. Kazimi","Dr. Edward E. Pilat"],"url":"https://ocw.mit.edu/courses/22-251-systems-analysis-of-the-nuclear-fuel-cycle-fall-2009/","views":1399},{"id":"21A.336+spring_2004","numbers":["21A.336"],"title":"Marketing, Microchips and McDonalds: Debating Globalization","summary":"Everyday we are bombarded with the word “global” and encouraged to see globalization as the quintessential transformation of our age. But what exactly does “globalization” mean? How is it affecting the lives of people around the world, not only in economic, but social and cultural terms? How do contemporary changes compare with those from other historical periods? Are such changes positive, negative or simply inevitable? And, finally, how does the concept of the “global” itself shape our perceptions in ways that both help us understand the contemporary world and potentially distort it? This course begins by offering a brief overview of historical “world systems,” including those centered in Asia as well as Europe. It explores the nature of contemporary transformations, including those in economics, media & information technologies, population flows, and consumer habits, not through abstractions but by focusing on the daily lives of people in various parts of the world. This course considers such topics as the day-to-day impact of computers in Silicon Valley and among Tibetan refugees; the dilemmas of factory workers in the US and rural Java; the attractions of Bombay cinema in Nigeria, the making of rap music in Japan, and the cultural complexities of immigrant life in France. This course seeks not only to understand the various forms globalization takes, but to understand its very different impacts world-wide.","departments":["Anthropology"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["Anthropology","Business","Cultural Anthropology","Globalization","History","Humanities","Social Anthropology","Social Science","World History"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2004","instructors":["Prof. Christine Walley"],"url":"https://ocw.mit.edu/courses/21a-336-marketing-microchips-and-mcdonalds-debating-globalization-spring-2004/","views":1398},{"id":"21A.525+fall_2025","numbers":["21A.525"],"title":"Oceans and Us","summary":"This course explores how people have understood and encountered the ocean, cross-culturally, as a site of danger, pleasure, travel, food-procurement, commerce, and tourism. Topics include imperial voyaging, piracy, the invention of seaside vacations, the politics of fishing, the culture of onboard living in surface and submarine ships, the rise of undersea entertainment and documentary, regimes of managing maritime spaces and species, and the emergence of the ocean as an object of global ecological concern, particularly around climate change and sea level rise.","departments":["Anthropology"],"areas":["Energy, Climate & Sustainability","Science & Math","Social Sciences"],"topics":["Anthropology","Climate Studies","Cultural Anthropology","Earth Science","Environmental Science","Oceanography","Science","Social Anthropology","Social Science"],"levels":["Undergraduate"],"features":["Readings","Written Assignments"],"term":"Fall 2025","instructors":["Prof. Stefan Helmreich"],"url":"https://ocw.mit.edu/courses/21a-525-oceans-and-us-fall-2025/","views":1398},{"id":"21A.245J+fall_2005","numbers":["21A.245J","17.045J"],"title":"Power: Interpersonal, Organizational and Global Dimensions","summary":"Using examples from anthropology and sociology alongside classical and contemporary social theory, this course explores the nature of dominant and subordinate relationships, types of legitimate authority, and practices of resistance. The course also examines how we are influenced in subtle ways by the people around us, who makes controlling decisions in the family, how people get ahead at work, and whether democracies, in fact, reflect the “will of the people.”","departments":["Anthropology","Political Science"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["Anthropology","Business","Humanities","Organizational Behavior","Philosophy","Political Philosophy","Social Anthropology","Social Science","Sociology"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets","Written Assignments"],"term":"Fall 2005","instructors":["Prof. Susan S. Silbey"],"url":"https://ocw.mit.edu/courses/21a-245j-power-interpersonal-organizational-and-global-dimensions-fall-2005/","views":1396},{"id":"1.225J+fall_2002","numbers":["1.225J","ESD.205J"],"title":"Transportation Flow Systems","summary":"Design, operation, and management of traffic flows over complex transportation networks are the foci of this course. It covers two major topics: traffic flow modeling and traffic flow operations. Sub-topics include deterministic and probabilistic models, elements of queuing theory, and traffic assignment. Concepts are illustrated through various applications and case studies. This is a half-term subject offered during the second half of the semester.","departments":["Civil and Environmental Engineering","Engineering Systems Division"],"areas":["Engineering","Social Sciences"],"topics":["Civil Engineering","Computational Modeling and Simulation","Engineering","Social Science","Systems Engineering","Transportation Engineering","Transportation Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2002","instructors":["Prof. Ismail Chabini","Prof. Amedeo R. Odoni"],"url":"https://ocw.mit.edu/courses/1-225j-transportation-flow-systems-fall-2002/","views":1396},{"id":"1.463J+fall_2009","numbers":["1.463J","11.342J","ESD.53J"],"title":"The Impact of Globalization on the Built Environment","summary":"The course is designed to provide a better understanding of the built environment, globalization, the current financial crisis and the impact of these factors on the rapidly changing and evolving international architecture, engineering, construction fields.\n\nWe will, hopefully, obtain a better understanding of how these forces of globalization and the current financial crisis are having an impact on the built environment and how they will affect firms and your future career opportunities. We will also identify, review and discuss best practices and lessons that can be learned from recent events.\n\nWe will explore the “international built environment” in detail, examining how it functions and asking what are the managerial, entrepreneurial and professional opportunities, challenges and risks in it, especially growing crossover and multi-disciplinary opportunities; and we will seek to understand what makes this “built environment” so different from other sectors.","departments":["Civil and Environmental Engineering","Engineering Systems Division","Urban Studies and Planning"],"areas":["Business & Management","Engineering","Social Sciences"],"topics":["Business","Civil Engineering","Engineering","Globalization"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2009","instructors":["Mr. Derish M. Wolff","Prof. Fred Moavenzadeh"],"url":"https://ocw.mit.edu/courses/1-463j-the-impact-of-globalization-on-the-built-environment-fall-2009/","views":1393},{"id":"8.851+spring_2013","numbers":["8.851"],"title":"Effective Field Theory","summary":"Effective field theory is a fundamental framework to describe physical systems with quantum field theory. Part I of this course covers common tools used in effective theories. Part II is an in depth study of the Soft-Collinear Effective Theory (SCET), an effective theory for hard interactions in collider physics.","departments":["Physics"],"areas":["Science & Math"],"topics":["Particle Physics","Physics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Lecture Videos","Problem Sets","Projects"],"term":"Spring 2013","instructors":["Prof. Iain Stewart"],"url":"https://ocw.mit.edu/courses/8-851-effective-field-theory-spring-2013/","views":1391},{"id":"6.774+fall_2004","numbers":["6.774"],"title":"Physics of Microfabrication: Front End Processing","summary":"This course is offered to graduates and focuses on understanding the fundamental principles of the “front-end” processes used in the fabrication of devices for silicon integrated circuits. This includes advanced physical models and practical aspects of major processes, such as oxidation, diffusion, ion implantation, and epitaxy. Other topics covered include: high performance MOS and bipolar devices including ultra-thin gate oxides, implant-damage enhanced diffusion, advanced metrology, and new materials such as Silicon Germanium (SiGe).","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering","Science & Math"],"topics":["Condensed Matter Physics","Electronic Materials","Engineering","Materials Science and Engineering","Mechanical Engineering","Microtechnology","Nanotechnology","Physics","Science"],"levels":["Graduate"],"features":["Lecture Audio"],"term":"Fall 2004","instructors":["Prof. Judy Hoyt","Prof. L. Rafael Reif"],"url":"https://ocw.mit.edu/courses/6-774-physics-of-microfabrication-front-end-processing-fall-2004/","views":1391},{"id":"6.302+spring_2007","numbers":["6.302"],"title":"Feedback Systems","summary":"This course provides an introduction to the design of feedback systems. Topics covered include: properties and advantages of feedback systems, time-domain and frequency-domain performance measures, stability and degree of stability, root locus method, Nyquist criterion, frequency-domain design, compensation techniques, application to a wide variety of physical systems, internal and external compensation of operational amplifiers, modeling and compensation of power converter systems, and phase lock loops.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering"],"topics":["Electrical Engineering","Electronics","Engineering","Robotics and Control Systems"],"levels":["Graduate"],"features":["Exams","Problem Sets"],"term":"Spring 2007","instructors":["James Roberge","Prof. Joel Dawson","Dr. Kent Lundberg"],"url":"https://ocw.mit.edu/courses/6-302-feedback-systems-spring-2007/","views":1389},{"id":"21L.476+spring_2005","numbers":["21L.476"],"title":"Romantic Poetry","summary":"This course examines readings of the major British Romantic poets (Blake, Wordsworth, Coleridge, Byron, Scott, Shelley, and Keats) and important fiction writers (Mary Shelley and Walter Scott). Attention is also given to literary and historical contexts.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Fiction","Humanities","Literature","Poetry"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2005","instructors":["Prof. Noel Jackson"],"url":"https://ocw.mit.edu/courses/21l-476-romantic-poetry-spring-2005/","views":1389},{"id":"12.002+fall_2008","numbers":["12.002"],"title":"Physics and Chemistry of the Terrestrial Planets","summary":"This course introduces the structure, composition, and physical processes governing the terrestrial planets, including their formation and basic orbital properties. Topics include plate tectonics, earthquakes, seismic waves, rheology, impact cratering, gravity and magnetic fields, heat flux, thermal structure, mantle convection, deep interiors, planetary magnetism, and core dynamics. Suitable for majors and non-majors seeking general background in geophysics and planetary structure.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geophysics","Planetary Science","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2008","instructors":["Prof. Benjamin Weiss","Prof. Leigh Royden"],"url":"https://ocw.mit.edu/courses/12-002-physics-and-chemistry-of-the-terrestrial-planets-fall-2008/","views":1388},{"id":"RES.21G-108+spring_2024","numbers":["RES.21G-108"],"title":"Project-Based Language Learning for Chinese II (Streamlined)","summary":"This is the student project for the Spring 2024 MIT course 21G.108 Chinese II (Streamlined). In the project, Chinese heritage language students explore various topics, including the meaning of their Chinese names. Based on their discoveries, each student creates an online book.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Chinese","Humanities","Language"],"levels":["Undergraduate"],"features":["Activity Assignments","Instructor Insights"],"term":"Spring 2024","instructors":["Min-Min Liang"],"url":"https://ocw.mit.edu/courses/res-21g-108-project-based-language-learning-for-chinese-streamlined-ii-spring-2024/","views":1388},{"id":"21G.025+spring_2019","numbers":["21G.025"],"title":"Africa and the Politics of Knowledge","summary":"This course considers how, despite its immense diversity, Africa continues to hold purchase as both a geographical entity and meaningful knowledge category. It examines the relationship between articulations of “Africa” and projects like European imperialism, developments in the biological sciences, African de-colonization and state-building, and the imagining of the planet’s future. Readings in anthropology and history are organized around five themes: space and place, race, representation, self-determination, and time.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["African History","Anthropology","Comparative Politics","Cultural Anthropology","History","Humanities","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2019","instructors":["Prof. M. Amah Edoh"],"url":"https://ocw.mit.edu/courses/21g-025-africa-and-the-politics-of-knowledge-spring-2019/","views":1387},{"id":"3.A08+fall_2005","numbers":["3.A08"],"title":"Attraction and Repulsion: The Magic of Magnets","summary":"This Freshman Advising Seminar surveys the many applications of magnets and magnetism. To the Chinese and Greeks of ancient times, the attractive and repulsive forces between magnets must have seemed magical indeed. Through the ages, miraculous curative powers have been attributed to magnets, and magnets have been used by illusionists to produce “magical” effects. Magnets guided ships in the Age of Exploration and generated the electrical industry in the 19th century. Today they store information and entertainment on disks and tapes, and produce sound in speakers, images on TV screens, rotation in motors, and levitation in high-speed trains. Students visit various MIT projects related to magnets (including superconducting electromagnets) and read about and discuss the history, legends, pseudoscience, science, and technology of types of magnets, including applications in medicine. Several short written reports and at least one oral presentation will be required of each participant.","departments":["Materials Science and Engineering"],"areas":["Humanities","Science & Math"],"topics":["Electromagnetism","History","History of Science and Technology","Humanities","Physics","Science"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments with Examples"],"term":"Fall 2005","instructors":["Dr. James Livingston"],"url":"https://ocw.mit.edu/courses/3-a08-attraction-and-repulsion-the-magic-of-magnets-fall-2005/","views":1386},{"id":"21L.708+spring_2003","numbers":["21L.708","CMS.910"],"title":"Technologies of Humanism","summary":"This course explores the properties of non-sequential, multi-linear, and interactive forms of narratives as they have evolved from print to digital media. Works covered in this course range from the Talmud, classics of non-linear novels, experimental literature, early sound and film experiments to recent multi-linear and interactive films and games. The study of the structural properties of narratives that experiment with digression, multiple points of view, disruptions of time, space, and of storyline is complemented by theoretical texts about authorship/readership, plot/story, properties of digital media and hypertext. Questions that will be addressed in this course include: How can we define ‘non-sequentiality/multi-linearity’, ‘interactivity’, ‘narrative’. To what extend are these aspects determined by the text, the reader, the digital format? What are the roles of the reader and the author? What kinds of narratives are especially suited for a non-linear/interactive format? Are there stories that can only be told in a digital format? What can we learn from early non-digital examples of non-linear and interactive story telling?","departments":["Literature"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Criticism","Digital Media","Fiction","Fine Arts","Humanities","Literature","Media Studies"],"levels":["Undergraduate"],"features":["Projects","Written Assignments"],"term":"Spring 2003","instructors":["Dr. Kurt Fendt"],"url":"https://ocw.mit.edu/courses/21l-708-technologies-of-humanism-spring-2003/","views":1385},{"id":"21G.315+fall_2011","numbers":["21G.315"],"title":"Cross-Cultural Perspectives on Contemporary French Society","summary":"This course is an intermediate subject designed to help students gradually build an in-depth understanding of France. The course focuses on French attitudes and values regarding education, work, family and institutions, and deals with the differing notions that underlie interpersonal interactions and communication styles, such as politeness, friendship and formality. Using a Web comparative, cross-cultural approach, students explore a variety of French and American materials, then analyze and compare them using questionnaires, opinion polls, news reports (in different media), as well as a variety of historical, anthropological and literary texts. Throughout the course, attention is given to the development of relevant linguistics skills. This course is recommended for students planning to study and work in France and is taught in French.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","French","Humanities","International Literature","Language","Literature","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2011","instructors":["Sabine Levet"],"url":"https://ocw.mit.edu/courses/21g-315-cross-cultural-perspectives-on-contemporary-french-society-fall-2011/","views":1384},{"id":"12.103+fall_2005","numbers":["12.103"],"title":"Strange Bedfellows: Science and Environmental Policy","summary":"12.103 explores the role of scientific knowledge, discovery, method, and argument in environmental policymaking from both idealistic and realistic perspectives. The course will use case studies of science-intensive environmental controversies to study how science was used and abused in the policymaking process. Case studies include: global warming, biodiversity loss, and nuclear waste disposal siting. Subject includes intensive practice in the writing and presentation of “position statements” on environmental science issues.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math","Social Sciences"],"topics":["Earth Science","Engineering","Environmental Engineering","Environmental Management","Environmental Policy","Environmental Science","Public Administration","Science","Social Science"],"levels":["Undergraduate"],"features":["Presentation Assignments with Examples","Written Assignments with Examples"],"term":"Fall 2005","instructors":["Prof. Stephen M. Meyer","Prof. Kip Hodges"],"url":"https://ocw.mit.edu/courses/12-103-strange-bedfellows-science-and-environmental-policy-fall-2005/","views":1384},{"id":"6.345+spring_2003","numbers":["6.345"],"title":"Automatic Speech Recognition","summary":"6.345 introduces students to the rapidly developing field of automatic speech recognition. Its content is divided into three parts. Part I deals with background material in the acoustic theory of speech production, acoustic-phonetics, and signal representation. Part II describes algorithmic aspects of speech recognition systems including pattern classification, search algorithms, stochastic modelling, and language modelling techniques. Part III compares and contrasts the various approaches to speech recognition, and describes advanced techniques used for acoustic-phonetic modelling, robust speech recognition, speaker adaptation, processing paralinguistic information, speech understanding, and multimodal processing.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering","Humanities"],"topics":["Electrical Engineering","Engineering","Humanities","Linguistics","Signal Processing"],"levels":["Graduate"],"features":["Demonstration Audio","Lecture Notes"],"term":"Spring 2003","instructors":["Dr. James Glass","Prof. Victor Zue"],"url":"https://ocw.mit.edu/courses/6-345-automatic-speech-recognition-spring-2003/","views":1382},{"id":"24.951+fall_2003","numbers":["24.951"],"title":"Introduction to Syntax","summary":"This course is concerned with the concepts and principles which have been of central significance in the recent development of syntactic theory, with special focus on the “Government and Binding” (GB) / “Principles and Parameters” (P&P) / “Minimalist Program” (MP) approach.\n\nIt is the first of a series of two courses (24.951 is taught during the Fall and 24.952 is taught in the Spring). This course deals mostly with phrase structure, argument structure and its syntactic expression, including “A-movement”. Though other issues (e.g. wh-movement, antecedent-contained deletion, extraposition) may be mentioned during the semester, the course will not systematically investigate these topics in class until 24.952.\n\nThe goal of the course is to understand why certain problems have been treated in certain ways. Thus, on many occasions a variety of approaches will be discussed, and the (recent) historical development of these approaches are emphasized.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics","Syntax"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2003","instructors":["Prof. Idan Landau","Prof. Michel DeGraff"],"url":"https://ocw.mit.edu/courses/24-951-introduction-to-syntax-fall-2003/","views":1382},{"id":"22.615+spring_2007","numbers":["22.615"],"title":"MHD Theory of Fusion Systems","summary":"This course discusses MHD equilibria in cylindrical, toroidal, and noncircular tokamaks. It covers derivation of the basic MHD model from the Boltzmann equation, use of MHD equilibrium theory in poloidal field design, MHD stability theory including the Energy Principle, interchange instability, ballooning modes, second region of stability, and external kink modes. Emphasis is on discovering configurations capable of achieving good confinement at high beta.","departments":["Nuclear Science and Engineering"],"areas":["Science & Math"],"topics":["Chemistry","Electromagnetism","High Energy Physics","Nuclear Physics","Physical Chemistry","Physics","Science"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Spring 2007","instructors":["Prof. Jeffrey Freidberg"],"url":"https://ocw.mit.edu/courses/22-615-mhd-theory-of-fusion-systems-spring-2007/","views":1382},{"id":"12.091+january-iap_2006","numbers":["12.091"],"title":"Medical Geology/Geochemistry: An Exposure","summary":"This course introduces students to the basic concepts of Medical Geology/Geochemistry. Medical Geology/Geochemistry is the study of the interaction between abundances of elements and isotopes and the health of humans and plants.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Health & Medicine","Science & Math"],"topics":["Biochemistry","Biology","Biomedicine","Cellular and Molecular Medicine","Earth Science","Geochemistry","Health and Medicine","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"January IAP 2006","instructors":["Dr. Ila Pillalamarri"],"url":"https://ocw.mit.edu/courses/12-091-medical-geology-geochemistry-an-exposure-january-iap-2006/","views":1382},{"id":"21G.347+fall_2013","numbers":["21G.347"],"title":"Contemporary Short French Fiction: Social and Literary Trends since 1990","summary":"Students in this course will examine short stories and short novels published in France during the past 20 years, with emphasis on texts related to the dominant social and cultural trends. Themes include the legacy of France’s colonial experience, the re-examination of its wartime past, memory and the Holocaust, the specter of AIDS, changing gender relationships, new families, the quest for personal identity, and immigration narratives. This course is taught in French.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Fiction","French","Humanities","International Literature","Language","Literature"],"levels":["Undergraduate"],"features":[],"term":"Fall 2013","instructors":["Prof. Bruno Perreau"],"url":"https://ocw.mit.edu/courses/21g-347-contemporary-short-french-fiction-social-and-literary-trends-since-1990-fall-2013/","views":1381},{"id":"ESD.72+spring_2007","numbers":["ESD.72","1.155","2.963","3.577","6.938","10.816","16.862","22.82"],"title":"Engineering Risk-Benefit Analysis","summary":"ERBA (ESD.72) emphasizes three methodologies - reliability and probabilistic risk assessment (RPRA), decision analysis (DA), and cost-benefit analysis (CBA). In this class, the issues of interest are: the risks associated with large engineering projects such as nuclear power reactors, the International Space Station, and critical infrastructures; the development of new products; the design of processes and operations with environmental externalities; and infrastructure renewal projects.","departments":["Aeronautics and Astronautics","Chemical Engineering","Civil and Environmental Engineering","Electrical Engineering and Computer Science","Engineering Systems Division","Materials Science and Engineering","Mechanical Engineering","Nuclear Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Applied Mathematics","Computational Modeling and Simulation","Engineering","Mathematics","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2007","instructors":["Prof. George Apostolakis"],"url":"https://ocw.mit.edu/courses/esd-72-engineering-risk-benefit-analysis-spring-2007/","views":1381},{"id":"11.941+fall_2003","numbers":["11.941"],"title":"Use of Joint Fact Finding in Science Intensive Policy Disputes, Part I","summary":"11.941 and 11.942 make up a one-year seminar. The goal of this seminar is to explore the role of science and scientists in ecosystems and natural resources management focusing on joint fact finding as a new approach to environmental policy-making. Increasingly scientists and science organizations are confronting a conundrum: Why is science often ignored in important societal decisions even as the call for decisions based on sound science escalates? One reason is that decision-making is often driven by a variety of nonscientific, adversarial, and stakeholder dynamics. Thus, even though science helps inform choices, it is only one of many values and interests considered by each stakeholder. In response to this emerging challenge, scientists, and science agencies such as the U.S. Geological Survey, are embarking upon research that explores the problems of incorporating science into value-laden societal decisions. This research includes designing experiments that will assess the appropriateness of using the new and emerging approach of Joint Fact Finding to address some of the Nation’s most contentious environmental conflicts. In the first few sessions we will examine the problems of using science in environmental disputes. In following sessions, students will analyze and discuss cases that involved or that should have involved Joint Fact Finding of various kinds.","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Engineering","Social Sciences"],"topics":["Engineering","Environmental Engineering","Environmental Management","Environmental Policy","Public Administration","Science and Technology Policy","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Lecture Videos"],"term":"Fall 2003","instructors":["Dr. Herman Karl","Prof. Lawrence Susskind"],"url":"https://ocw.mit.edu/courses/11-941-use-of-joint-fact-finding-in-science-intensive-policy-disputes-part-i-fall-2003/","views":1380},{"id":"12.086+fall_2014","numbers":["12.086","12.586"],"title":"Modeling Environmental Complexity","summary":"This course provides an introduction to the study of environmental phenomena that exhibit both organized structure and wide variability—i.e., complexity. Through focused study of a variety of physical, biological, and chemical problems in conjunction with theoretical models, we learn a series of lessons with wide applicability to understanding the structure and organization of the natural world. Students also learn how to construct minimal mathematical, physical, and computational models that provide informative answers to precise questions.\n\nThis course is appropriate for advanced undergraduates. Beginning graduate students are encouraged to register for 12.586 (graduate version of 12.086). Students taking the graduate version complete different assignments.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Computational Modeling and Simulation","Earth Science","Engineering","Environmental Science","Science","Systems Engineering"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2014","instructors":["Prof. Daniel Rothman"],"url":"https://ocw.mit.edu/courses/12-086-modeling-environmental-complexity-fall-2014/","views":1379},{"id":"21G.502+spring_2020","numbers":["21G.502","21G.552"],"title":"Japanese II","summary":"This course covers Genki I Lessons 7 through 12 that will enhance the basic skills for conversation, reading, and writing in Japenese. The program emphasizes active command of the language rather than passive knowledge. By the end of the semester, you will be able to carry on a conversation in Japanese. You will also learn approximately 90 kanji characters.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","Japanese","Language"],"levels":["Undergraduate"],"features":["Exams","Instructor Insights"],"term":"Spring 2020","instructors":["Dr. Takako Aikawa","Masami Ikeda-Lamm","Wakana Maekawa","Emiko Rafique"],"url":"https://ocw.mit.edu/courses/21g-502-japanese-ii-spring-2020/","views":1376},{"id":"12.757+spring_2005","numbers":["12.757"],"title":"Science and Communication","summary":"This seminar is intended to help students in the MIT/Woods Hole Oceanographic Institution Joint Program develop a broader perspective on their thesis research by considering some aspects of science in the large. The first part of the course challenges students to develop a thoughtful view towards major questions in science that can be incorporated in their own research process, and that will help them articulate research findings. The second part of the course emphasizes science as a social process and the important roles of written and oral communication.\n\nThis course is offered through The MIT/WHOI Joint Program. The MIT/WHOI Joint Program is one of the premier marine science graduate programs in the world. It draws on the complementary strengths and approaches of two great institutions: the Massachusetts Institute of Technology (MIT) and the Woods Hole Oceanographic Institution (WHOI).","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Humanities","Science & Math","Social Sciences"],"topics":["Academic Writing","Communication","Humanities","Literature","Science","Social Science"],"levels":["Graduate"],"features":[],"term":"Spring 2005","instructors":["Dr. James F. Price"],"url":"https://ocw.mit.edu/courses/12-757-science-and-communication-spring-2005/","views":1374},{"id":"21M.302+spring_2005","numbers":["21M.302"],"title":"Harmony and Counterpoint II","summary":"In this subject, we explore the harmonic, melodic, and formal practices of western music, principally the so-called “Classical” idiom of central Europe, ca. 1750-1825. Topics include a quick review of material covered in 21M.301, chromatic harmony (viio7, bII6, and chords of the augmented sixth), and chromatic modulation; lecture study and discussion are complemented by work in the keyboard laboratory and sight-singing laboratory. All areas of study will be integrated in a semester-long project of composing a theme and two variations in Classical style.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History","Music Performance","Music Theory"],"levels":["Undergraduate"],"features":["Exams","Problem Sets","Projects with Examples"],"term":"Spring 2005","instructors":["Prof. Brian Robison"],"url":"https://ocw.mit.edu/courses/21m-302-harmony-and-counterpoint-ii-spring-2005/","views":1373},{"id":"21M.235+fall_2013","numbers":["21M.235"],"title":"Monteverdi to Mozart: 1600-1800","summary":"This course surveys seven Baroque and Classical genres: opera, oratorio, cantata, sonata, concerto, quartet, symphony, and includes work by composers Bach, Handel, Haydn, Monteverdi, Mozart, Purcell, Schütz and Vivaldi. Course work is based on live performances as well as listening and reading assignments.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History"],"levels":["Undergraduate"],"features":["Activity Assignments","Demonstration Videos","Instructor Insights","Lecture Notes","Written Assignments"],"term":"Fall 2013","instructors":["Teresa M. Neff"],"url":"https://ocw.mit.edu/courses/21m-235-monteverdi-to-mozart-1600-1800-fall-2013/","views":1373},{"id":"6.883+spring_2006","numbers":["6.883"],"title":"Pervasive Human Centric Computing (SMA 5508)","summary":"This course is broad, covering a wide range of topics that have to do with the post-pc era of computing. It is a hands-on project course that also includes some foundational subjects. Students will program iPAQ handheld computers, cell phones (series 60 phones), speech processing, vision, Cricket location systems, GPS, and more. Most of the programming will be using Python®, but Python® can be learned and mastered during the course.\n\nThis course was also taught as part of the Singapore-MIT Alliance (SMA) programme as course number SMA 5508 (Pervasive Computing).","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Engineering","Human-Computer Interfaces","Programming Languages","Theory of Computation"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Spring 2006","instructors":["Dr. Larry Rudolph"],"url":"https://ocw.mit.edu/courses/6-883-pervasive-human-centric-computing-sma-5508-spring-2006/","views":1373},{"id":"1.061+fall_2008","numbers":["1.061","1.61"],"title":"Transport Processes in the Environment","summary":"This class serves as an introduction to mass transport in environmental flows, with emphasis given to river and lake systems. The class will cover the derivation and solutions to the differential form of mass conservation equations. Class topics to be covered will include: molecular and turbulent diffusion, boundary layers, dissolution, bed-water exchange, air-water exchange and particle transport.","departments":["Civil and Environmental Engineering"],"areas":["Engineering"],"topics":["Aquatic Sciences and Water Quality Control","Chemical Engineering","Engineering","Environmental Engineering","Hydrology and Water Resource Systems","Transport Processes"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets","Simulation Videos"],"term":"Fall 2008","instructors":["Prof. Heidi Nepf"],"url":"https://ocw.mit.edu/courses/1-061-transport-processes-in-the-environment-fall-2008/","views":1372},{"id":"21M.S53+spring_2014","numbers":["21M.S53"],"title":"Chinese Popular Musics in Dialogue","summary":"This course provides an introduction to the major popular music cultures of the Chinese-speaking world. We will consider a wide variety of genres, from Shanghainese shidaiqu to Cantopop to Taiwanese rap, with the goal of listening beyond the notion of a monolithic “Chinese popular music” to something more dynamic, multivocal, and translocal. We will ask: What, if anything, is so “Chinese” about Chinese popular music? How does popular music participate in the formation of identities for artists and audiences in these areas? How does it enable the articulation of diverging social and political values while also facilitating meaningful connections among disparate communities? We will approach these questions through a diverse array of source materials, including sound recordings, music videos, films, and online multimedia.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Asian Studies","Cultural Anthropology","Fine Arts","Music","Music History","Social Science","Society"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments"],"term":"Spring 2014","instructors":["Dr. Meredith Schweig"],"url":"https://ocw.mit.edu/courses/21m-s53-chinese-popular-musics-in-dialogue-spring-2014/","views":1371},{"id":"21L.704+spring_2006","numbers":["21L.704"],"title":"Studies in Poetry: From the Sonneteers to the Metaphysicals","summary":"This course introduces students to some of the most important practitioners of poetry in sixteenth- and seventeenth-century England, locating them in their historical and social contexts. We will be emphasizing love poetry or amatory verse, by combining close reading of selected poems with an investigation of the contexts of English verse.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Humanities","Literature","Poetry"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments with Examples"],"term":"Spring 2006","instructors":["Prof. Shankar Raman"],"url":"https://ocw.mit.edu/courses/21l-704-studies-in-poetry-from-the-sonneteers-to-the-metaphysicals-spring-2006/","views":1371},{"id":"STS.427+spring_2015","numbers":["STS.427","21H.205","STS.027"],"title":"The Civil War and the Emergence of Modern America, 1861-1890","summary":"Using the American Civil War as a baseline, the course considers what it means to become “modern” by exploring the war’s material and manpower needs, associated key technologies, and how both influenced the United States’ entrance into the age of “Big Business.” Readings include material on steam transportation, telegraphic communications, arms production, naval innovation, food processing, medicine, public health, management methods, and the mass production of everything from underwear to uniforms—all essential ingredients of modernity. Students taking the graduate version must complete additional assignments.","departments":["History","Science, Technology, and Society"],"areas":["Humanities"],"topics":["American History","Historiography","History","History of Science and Technology","Humanities"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2015","instructors":["Prof. Merritt Roe Smith"],"url":"https://ocw.mit.edu/courses/sts-427-the-civil-war-and-the-emergence-of-modern-america-1861-1890-spring-2015/","views":1371},{"id":"4.696+spring_2008","numbers":["4.696"],"title":"A Global History of Architecture Writing Seminar","summary":"This course will study the question of Global Architecture from the point of view of producing a set of lectures on that subject. The course will be run in the form of a writing seminar, except that students will be asked to prepare for the final class an hour-long lecture for an undergraduate survey course. During the semester, students will study the debates about where to locate “the global” and do some comparative analysis of various textbooks. The topic of the final lecture will be worked on during the semester. For that lecture, students will be asked to identify the themes of the survey course, and hand in the bibliography and reading list for their lecture.","departments":["Architecture"],"areas":["Art, Design & Architecture","Education & Teaching","Humanities"],"topics":["Academic Writing","Architectural History and Criticism","Architecture","Curriculum and Teaching","Fine Arts","Humanities","Literature","Teaching and Education"],"levels":["Graduate"],"features":["Other Video","Projects with Examples"],"term":"Spring 2008","instructors":["Prof. Mark Jarzombek"],"url":"https://ocw.mit.edu/courses/4-696-a-global-history-of-architecture-writing-seminar-spring-2008/","views":1370},{"id":"CMS.S63+fall_2019","numbers":["CMS.S63","CMS.S99"],"title":"Playful Augmented Reality Audio Design Exploration","summary":"Students explore augmented reality audio through the design and evaluation of prototypes. Participants will probe design space and illuminate creative possibilities. This includes productive, playful, and social applications, as well as the intersection between games and music. The course builds understanding of the limitations and strengths of iterative design and rapid prototyping as research methods, familiarizes students with the theoretical foundations of design exploration, and practices working with physical and digital materials.","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Fine Arts","Game Design","Game Theory","Media Studies","Social Science"],"levels":["Undergraduate"],"features":["Demonstration Videos","Design Assignments","Lecture Videos"],"term":"Fall 2019","instructors":["Mikael Jakobsson","Philip B. Tan"],"url":"https://ocw.mit.edu/courses/cms-s63-playful-augmented-reality-audio-design-exploration-fall-2019/","views":1369},{"id":"21L.512+spring_2003","numbers":["21L.512","WGS.517"],"title":"American Authors: American Women Authors","summary":"This subject, cross-listed in Literature and Women’s Studies, examines a range of American women authors from the seventeenth century to the present. It aims to introduce a number of literary genres and styles- the captivity narrative, slave novel, sensational, sentimental, realistic, and postmodern fiction- and also to address significant historical events in American women’s history: Puritanism, the American Revolution, industrialization and urbanization in the nineteenth century, the Harlem Renaissance, World War II, the 60s civil rights movements. A primary focus will be themes studied and understood through the lens of gender: war, violence, and sexual exploitation (Keller, Rowlandson, Rowson); the relationship between women and religion (Rowlandson, Rowson, Stowe); labor, poverty, and working conditions for women (Fern, Davis, Wharton); captivity and slavery (Rowlandson, Jacobs); class struggle (Fern, Davis, Wharton, Larsen); race and identity (Keller, Jacobs, Larsen, Morrison); feminist revisions of history (Stowe, Morrison, Keller); and the myth of the fallen woman (take your pick). Essays and in-class reports will focus more particularly on specific writers and themes and will stress the skills of close reading, annotation, research, and uses of multimedia where appropriate.","departments":["Literature","Women's and Gender Studies"],"areas":["Humanities","Social Sciences"],"topics":["American Literature","Criticism","Gender Studies","Humanities","Literature","Society","Women's Studies"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2003","instructors":["Dr. Wyn Kelley"],"url":"https://ocw.mit.edu/courses/21l-512-american-authors-american-women-authors-spring-2003/","views":1368},{"id":"11.237+spring_2016","numbers":["11.237"],"title":"Practice of Participatory Action Research (PAR)","summary":"This course introduces students to the techniques of participatory action research (PAR) and the practice of case study research. PAR processes are place or case-specific, place a premium on local ways of knowing, and gauge the success of research in terms of what partner-communities do with the knowledge that is co-produced. The objective of PAR is to generate the ideas, information, and understandings that ought to inform efforts to promote social change. By focusing on ways of co-producing knowledge using various forms of data collection and analysis, students will learn how the people and communities who are often university partners in applied social science research can use findings or results from PAR case studies to address the challenges they confront in their communities.\n\nLearn more about Participatory Action Research at MIT.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Public Administration","Public Policy","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Spring 2016","instructors":["Prof. Lawrence Susskind","Dayna Cunningham, Esq."],"url":"https://ocw.mit.edu/courses/11-237-practice-of-participatory-action-research-par-spring-2016/","views":1368},{"id":"16.322+fall_2004","numbers":["16.322"],"title":"Stochastic Estimation and Control","summary":"The major themes of this course are estimation and control of dynamic systems. Preliminary topics begin with reviews of probability and random variables. Next, classical and state-space descriptions of random processes and their propagation through linear systems are introduced, followed by frequency domain design of filters and compensators. From there, the Kalman filter is employed to estimate the states of dynamic systems. Concluding topics include conditions for stability of the filter equations.","departments":["Aeronautics and Astronautics"],"areas":["Engineering","Science & Math"],"topics":["Aerospace Engineering","Engineering","Guidance and Control Systems","Mathematics","Probability and Statistics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Wallace Vander Velde"],"url":"https://ocw.mit.edu/courses/16-322-stochastic-estimation-and-control-fall-2004/","views":1368},{"id":"12.803+fall_2009","numbers":["12.803"],"title":"Quasi-Balanced Circulations in Oceans and Atmospheres","summary":"This course introduces the students to dynamics of large-scale circulations in oceans and atmospheres. Basic concepts include mass and momentum conservation, hydrostatic and geostrophic balance, and pressure and other vertical coordinates. It covers the topics of fundamental conservation and balance principles for large-scale flow, generation and dissipation of quasi-balanced eddies, as well as equilibrated quasi-balanced systems. Examples of oceanic and atmospheric quasi-balanced flows, computational models, and rotating tank experiments can be found in the accompaniment laboratory course 12.804, Large-scale Flow Dynamics Lab.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Atmospheric Science","Earth Science","Engineering","Geophysics","Hydrodynamics","Ocean Engineering","Oceanography","Physics","Science","Thermodynamics"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2009","instructors":["Prof. Kerry Emanuel"],"url":"https://ocw.mit.edu/courses/12-803-quasi-balanced-circulations-in-oceans-and-atmospheres-fall-2009/","views":1367},{"id":"16.A47+fall_2009","numbers":["16.A47"],"title":"The Engineer of 2020","summary":"Numerous recent studies have shown that the U.S. has relatively low percentages of students who enter science and engineering and a high drop-out rate. Some other countries are producing many more scientists and engineers per capita than the U.S. What does this mean for the future of the U.S. and the global economy?\n\nIn this readings and discussion-based seminar you will meet weekly with the Dean of Undergraduate Education to explore the kind of education MIT and other institutions are and should be giving. Based on data from National Academy and other reports, along with what pundits have been saying, we’ll see if we can decide how much the U.S. may or may not be at risk.","departments":["Aeronautics and Astronautics"],"areas":["Business & Management","Education & Teaching","Social Sciences"],"topics":["Business","Curriculum and Teaching","Education Policy","Globalization","Higher Education","Teaching and Education"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2009","instructors":["Prof. Daniel Hastings"],"url":"https://ocw.mit.edu/courses/16-a47-the-engineer-of-2020-fall-2009/","views":1364},{"id":"4.511+spring_2006","numbers":["4.511"],"title":"Digital Mock-Up Workshop","summary":"This is an advanced subject in computer modeling and CAD CAM fabrication, with a focus on building large-scale prototypes and digital mock-ups within a classroom setting. Prototypes and mock-ups are developed with the aid of outside designers, consultants, and fabricators. Field trips and in-depth relationships with building fabricators demonstrate new methods for building design. The class analyzes complex shapes, shape relationships, and curved surfaces fabrication at a macro scale leading to new architectural languages, based on methods of construction.","departments":["Architecture"],"areas":["Art, Design & Architecture","Engineering"],"topics":["Architectural Design","Architecture","Computational Modeling and Simulation","Engineering","Fine Arts","Systems Engineering"],"levels":["Graduate"],"features":["Design Assignments","Presentation Assignments"],"term":"Spring 2006","instructors":["Prof. Lawrence Sass"],"url":"https://ocw.mit.edu/courses/4-511-digital-mock-up-workshop-spring-2006/","views":1363},{"id":"24.954+fall_2006","numbers":["24.954"],"title":"Pragmatics in Linguistic Theory","summary":"The course introduces formal theories of context-dependency, presupposition, implicature, context-change, focus and topic. Special emphasis is on the division of labor between semantics and pragmatics. It also covers applications to the analysis of quantification, definiteness, presupposition projection, conditionals and modality, anaphora, questions and answers.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics","Semantics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2006","instructors":["Prof. Daniel Fox","Prof. Paula Menéndez-Benito"],"url":"https://ocw.mit.edu/courses/24-954-pragmatics-in-linguistic-theory-fall-2006/","views":1362},{"id":"18.307+spring_2006","numbers":["18.307"],"title":"Integral Equations","summary":"This course emphasizes concepts and techniques for solving integral equations from an applied mathematics perspective. Material is selected from the following topics: Volterra and Fredholm equations, Fredholm theory, the Hilbert-Schmidt theorem; Wiener-Hopf Method; Wiener-Hopf Method and partial differential equations; the Hilbert Problem and singular integral equations of Cauchy type; inverse scattering transform; and group theory. Examples are taken from fluid and solid mechanics, acoustics, quantum mechanics, and other applications.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Applied Mathematics","Calculus","Differential Equations","Mathematical Analysis","Mathematics","Physics","Science","Theoretical Physics"],"levels":["Graduate"],"features":["Problem Set Solutions","Problem Sets"],"term":"Spring 2006","instructors":["Dr. Dionisios Margetis"],"url":"https://ocw.mit.edu/courses/18-307-integral-equations-spring-2006/","views":1361},{"id":"9.63+fall_2009","numbers":["9.63"],"title":"Laboratory in Visual Cognition","summary":"9.63 teaches principles of experimental methods in human perception and cognition, including design and statistical analysis. The course combines lectures and hands-on experimental exercises and requires an independent experimental project. Some experience in programming is desirable. To foster improved writing and presentation skills in conducting and critiquing research in cognitive science, students are required to provide reports and give oral presentations of three team experiments. A fourth individually conducted experiment includes a proposal with revision, and concluding written and oral reports.","departments":["Brain and Cognitive Sciences"],"areas":["Health & Medicine","Science & Math"],"topics":["Cognitive Science","Health and Medicine","Science","Sensory-Neural Systems"],"levels":["Undergraduate"],"features":["Exams","Lecture Notes","Written Assignments"],"term":"Fall 2009","instructors":["Prof. Aude Oliva"],"url":"https://ocw.mit.edu/courses/9-63-laboratory-in-visual-cognition-fall-2009/","views":1361},{"id":"18.353J+fall_2012","numbers":["18.353J","2.050J","12.006J"],"title":"Nonlinear Dynamics I: Chaos","summary":"This course provides an introduction to nonlinear dynamics and chaos in dissipative systems. The content is structured to be of general interest to undergraduates in engineering and science.","departments":["Earth, Atmospheric, and Planetary Sciences","Mathematics","Mechanical Engineering"],"areas":["Science & Math"],"topics":["Computation","Differential Equations","Linear Algebra","Mathematics"],"levels":["Undergraduate"],"features":["Exams","Problem Sets","Programming Assignments with Examples"],"term":"Fall 2012","instructors":["Lyubov Chumakova"],"url":"https://ocw.mit.edu/courses/18-353j-nonlinear-dynamics-i-chaos-fall-2012/","views":1361},{"id":"17.537+spring_2009","numbers":["17.537","17.538"],"title":"Politics and Policy in Contemporary Japan","summary":"This subject is designed for upper level undergraduates and graduate students as an introduction to politics and the policy process in modern Japan. The semester is divided into two parts. After a two-week general introduction to Japan and to the dominant approaches to the study of Japanese history, politics and society, we will begin exploring five aspects of Japanese politics: party politics, electoral politics, interest group politics, bureaucratic politics, and policy, which will be broken up into seven additional sections. We will try to understand the ways in which the actors and institutions identified in the first part of the semester affect the policy process across a variety of issues areas.","departments":["Political Science"],"areas":["Humanities","Social Sciences"],"topics":["Asian History","Asian Studies","History","Humanities","Political Science","Public Administration","Public Policy","Social Science","Society"],"levels":["Undergraduate","Graduate"],"features":["Projects with Examples","Written Assignments with Examples"],"term":"Spring 2009","instructors":["Prof. Richard J. Samuels"],"url":"https://ocw.mit.edu/courses/17-537-politics-and-policy-in-contemporary-japan-spring-2009/","views":1360},{"id":"12.009J+spring_2015","numbers":["12.009J","18.352J"],"title":"Theoretical Environmental Analysis","summary":"This course analyzes cooperative processes that shape the natural environment, now and in the geologic past. It emphasizes the development of theoretical models that relate the physical and biological worlds, the comparison of theory to observational data, and associated mathematical methods.","departments":["Earth, Atmospheric, and Planetary Sciences","Mathematics"],"areas":["Energy, Climate & Sustainability","Science & Math"],"topics":["Atmospheric Science","Biology","Climate Studies","Earth Science","Ecology","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2015","instructors":["Prof. Daniel Rothman"],"url":"https://ocw.mit.edu/courses/12-009j-theoretical-environmental-analysis-spring-2015/","views":1357},{"id":"21L.325+fall_2010","numbers":["21L.325"],"title":"Small Wonders: Media, Modernity, and the Moment: Experiments in Time","summary":"The “small wonders” to which our course will attend are moments of present time, depicted in the verbal and visual media of the modern age: newspapers, novels and stories, poems, photographs, films, etc. We will move between visual and verbal media across a considerable span of time, from eighteenth-century poetry and prose fiction to twenty-first century social networking and microblogging sites, and from sculpture to photography, film, and digital visual media. With help from philosophers, contemporary cultural historians, and others, we will begin to think about a media practice largely taken for granted in our own moment.","departments":["Literature"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Comparative Literature","Fiction","Film and Video","Fine Arts","Humanities","Literature","Media Studies","Periodic Literature","Visual Arts"],"levels":["Undergraduate"],"features":["Presentation Assignments with Examples","Written Assignments with Examples"],"term":"Fall 2010","instructors":["Prof. Noel Jackson"],"url":"https://ocw.mit.edu/courses/21l-325-small-wonders-media-modernity-and-the-moment-experiments-in-time-fall-2010/","views":1355},{"id":"HST.502+spring_2003","numbers":["HST.502"],"title":"Survival Skills for Researchers: The Responsible Conduct of Research","summary":"This course is designed to provide graduate students and postdoctoral associates with techniques that enhance both validity and responsible conduct in scientific practice. Lectures present practical steps for developing skills in scientific research and are combined with discussion of cases. The course covers study design, preparation of proposals and manuscripts, peer review, authorship, use of humans and non-human animals in research, allegations of misconduct, and intellectual property. Also discussed are mentoring relationships and career options. Aspects of responsible research conduct are integrated into lectures and case discussion as appropriate to the specific topic. This course also satisfies the training grant requirements of the NIH for education in the responsible conduct of research.\n\nBeginning in Spring 2004, this course will be titled “Survival Skills for Researchers: The Responsible Conduct of Research.”","departments":["Health Sciences and Technology"],"areas":["Humanities"],"topics":["Academic Writing","Ethics","Humanities","Literature","Philosophy"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2003","instructors":["Prof. Elizabeth R. Myers","Prof. Stephanie J. Bird"],"url":"https://ocw.mit.edu/courses/hst-502-survival-skills-for-researchers-the-responsible-conduct-of-research-spring-2003/","views":1354},{"id":"RES.SolveX+summer_2021","numbers":["RES.SolveX"],"title":"Business and Impact Planning for Social Enterprises (0.SolveX)","summary":"People in every corner of the world are innovating to solve social and environmental problems in their communities. In the past decade, new programs like MIT Solve have emerged to support those social entrepreneurs and drive partnerships to accelerate their impact. However, many startups find it difficult to develop business plans that clearly communicate their work and impact.\n\nThe main focus of this course is to help early-stage social impact startups define key aspects of their business by examining case studies from leading social entrepreneurs and both nonprofit and for-profit enterprises around the world.\n\nThe course was created by MIT Solve for MITx, and is now archived on the Open Learning Library (OLL), which is free to use. You have the option to sign up and enroll in each module if you want to track your progress, or you can view and use all the materials without enrolling.","departments":[],"areas":["Business & Management","Innovation & Entrepreneurship"],"topics":["Business","Entrepreneurship","Management"],"levels":["Non-Credit"],"features":[],"term":"Summer 2021","instructors":["Dr. Anjali Sastry"],"url":"https://ocw.mit.edu/courses/res-solvex-business-and-impact-planning-for-social-enterprises-0-solvex-summer-2021/","views":1353},{"id":"21T.1001+spring_2008","numbers":["21T.1001","WGS.595"],"title":"Theater and Cultural Diversity in the U.S.","summary":"This course explores contemporary American theatrical expression as it may be organized around issues of gender and cultural identity. This exploration will include the analysis of performances, scripts, and video documentation, as well as the invention of original documents of theatrical expression. Class lectures and discussions will analyze samples of Native American, Chicano, African American, and Asian American theater, taking into consideration the historical and political context for the creation of these works. Performance exercises will help students identify theatrical forms and techniques used by these theaters, and how these techniques contribute to the overall goals of specific theatrical expressions.","departments":["Theater Arts","Women's and Gender Studies"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Creative Writing","Criticism","Drama","Ethnography","Fine Arts","Humanities","Literature","Performance Arts","Social Science","Theater"],"levels":["Undergraduate"],"features":["Projects with Examples","Written Assignments"],"term":"Spring 2008","instructors":["Prof. Thomas DeFrantz"],"url":"https://ocw.mit.edu/courses/21m-621-theater-and-cultural-diversity-in-the-u-s-spring-2008/","views":1352},{"id":"9.57J+fall_2001","numbers":["9.57J","24.904J"],"title":"Language Acquisition","summary":"Covers the major results in the study of first language acquisition concentrating on the development of linguistic structure, including sentence structure and morphology. Universal aspects of development are discussed, as well as a variety of cross-linguistic phenomena. Theories of language learning are considered, including parameter-setting and maturation.","departments":["Brain and Cognitive Sciences","Linguistics and Philosophy"],"areas":["Humanities","Science & Math"],"topics":["Cognitive Science","Humanities","Linguistics","Science"],"levels":["Undergraduate"],"features":["Problem Set Solutions","Problem Sets"],"term":"Fall 2001","instructors":["Prof. Ken Wexler"],"url":"https://ocw.mit.edu/courses/9-57j-language-acquisition-fall-2001/","views":1350},{"id":"21T.1002+spring_2008","numbers":["21T.1002","WGS.591J"],"title":"Traditions in American Concert Dance: Gender and Autobiography","summary":"This course explores the forms, contents, and context of world traditions in dance that played a crucial role in shaping American concert dance. For example, we will identify dances from an African American vernacular tradition that were transferred from the social space to the concert stage. We will explore the artistic lives of such American dance artists as Katherine Dunham, Pearl Primus, and Alvin Ailey along with Isadora Duncan, Martha Graham, George Balanchine, and Merce Cunningham as American dance innovators. Of particular importance to our investigation will be the construction of gender and autobiography that lie at the heart of concert dance practice, and the ways in which these qualities have been choreographed by American artists.","departments":["Theater Arts","Women's and Gender Studies"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["African American Studies","Anthropology","Dance","Ethnography","Fine Arts","Gender Studies","Performance Arts","Social Science","Society","Women's Studies"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments with Examples"],"term":"Spring 2008","instructors":["Melissa Blanco"],"url":"https://ocw.mit.edu/courses/21m-670-traditions-in-american-concert-dance-gender-and-autobiography-spring-2008/","views":1350},{"id":"CMS.840+fall_2013","numbers":["CMS.840","21L.435"],"title":"At the Limit: Violence in Contemporary Representation","summary":"This course focuses on novels and films from the last twenty-five years (nominally 1985–2010) marked by their relationship to extreme violence and transgression. Our texts will focus on serial killers, torture, rape, and brutality, but they also explore notions of American history, gender and sexuality, and reality television—sometimes, they delve into love or time or the redemptive role of art in late modernity. Our works are a motley assortment, with origins in the U.S., France, Spain, Belgium, Austria, Japan and South Korea. The broad global era marked by this period is one of acceleration, fragmentation, and late capitalism; however, we will also consider national specificities of violent representation, including particulars like the history of racism in the United States, the role of politeness in bourgeois Austrian culture, and the effect of Japanese manga on vividly graphic contemporary Asian cinema.\n\nWe will explore the politics and aesthetics of the extreme; affective questions about sensation, fear, disgust, and shock; and problems of torture, pain, and the unrepresentable. We will ask whether these texts help us understand violence, or whether they frame violence as something that resists comprehension; we will consider whether form mitigates or colludes with violence. Finally, we will continually press on the central term in the title of this course: what, specifically, is violence? (Can we only speak of plural “violences”?) Is violence the same as force? Do we know violence when we see it? Is it something knowable or does it resist or even destroy knowledge? Is violence a matter for a text’s content—who does what, how, and to whom—or is it a problem of form: shock, boredom, repetition, indeterminacy, blankness? Can we speak of an aesthetic of violence? A politics or ethics of violence? Note the question that titles our last week: Is it the case that we are what we see? If so, what does our obsession with ultraviolence mean, and how does contemporary representation turn an accusing gaze back at us?","departments":["Comparative Media Studies/Writing","Literature"],"areas":["Art, Design & Architecture","Humanities"],"topics":["American Literature","Film and Video","Fine Arts","Humanities","Literature","Media Studies","Visual Arts"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2013","instructors":["Prof. Eugenie Brinkema"],"url":"https://ocw.mit.edu/courses/cms-840-at-the-limit-violence-in-contemporary-representation-fall-2013/","views":1349},{"id":"7.22+fall_2005","numbers":["7.22","7.72"],"title":"Developmental Biology","summary":"This graduate and advanced undergraduate level lecture and literature discussion course covers the current understanding of the molecular mechanisms that regulate animal development. Evolutionary mechanisms are emphasized as well as the discussion of relevant diseases. Vertebrate (mouse, chick, frog, fish) and invertebrate (fly, worm) models are covered. Specific topics include formation of early body plan, cell type determination, organogenesis, morphogenesis, stem cells, cloning, and issues in human development.","departments":["Biology"],"areas":["Science & Math"],"topics":["Biology","Developmental Biology","Science"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2005","instructors":["Prof. Hazel Sive","Prof. Martha Constantine-Paton"],"url":"https://ocw.mit.edu/courses/7-22-developmental-biology-fall-2005/","views":1349},{"id":"17.269+spring_2017","numbers":["17.269"],"title":"Race, Ethnicity, and American Politics","summary":"This course explores the role of race and ethnicity in modern American politics. It focuses on social science approaches to measuring the effects of race, both at the individual level and more broadly. Topics include race and representation, measurement of racial and ethnic identities, voting rights and electoral districting, protest and other forms of political participation, and the meaning and measurement of racial attitudes.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["African American Studies","American Politics","Political Science","Social Science","Society"],"levels":["Undergraduate"],"features":["Exams","Instructor Insights","Written Assignments with Examples"],"term":"Spring 2017","instructors":["Prof. Ariel White"],"url":"https://ocw.mit.edu/courses/17-269-race-ethnicity-and-american-politics-spring-2017/","views":1349},{"id":"21L.004+spring_2018","numbers":["21L.004"],"title":"Reading Poetry","summary":"How do you read a poem? Intuition is not the only answer. In this class, we will investigate some of the formal tools poets use—meter, sound, syntax, word-choice, and other properties of language—as well as exploring a range of approaches to reading poetry, from the old (memorization and reading out loud) to the new (digitally enabled visualization and annotation). We will use readings available online via the generosity of the Poetry Foundation and the Academy of American Poets. We will also think collectively about how to approach difficult poems.","departments":["Literature"],"areas":["Humanities"],"topics":["American Literature","Criticism","Humanities","Literature","Poetry"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2018","instructors":["Prof. Mary Fuller"],"url":"https://ocw.mit.edu/courses/21l-004-reading-poetry-spring-2018/","views":1349},{"id":"17.914+january-iap_2005","numbers":["17.914"],"title":"International Politics in the New Century - via Simulation, Interactive Gaming, and  'Edutainment'","summary":"This workshop is designed to introduce students to different perspectives on politics and the state of the world through new visualization techniques and approaches to interactive political gaming (and selective ’edutainment’). Specifically, we shall explore applications of interactive tools (such as video and web-based games, blogs or simulations) to examine critical challenges in international politics of the 21C century focusing specifically on general insights and specific understandings generated by operational uses of core concepts in political science.","departments":["Political Science"],"areas":["Art, Design & Architecture","Data Science, Analytics & Computer Technology","Engineering","Social Sciences"],"topics":["Computational Modeling and Simulation","Computer Science","Engineering","Fine Arts","Game Design","Graphics and Visualization","International Relations","Political Science","Social Science","Systems Engineering"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"January IAP 2005","instructors":["Prof. Nazli Choucri"],"url":"https://ocw.mit.edu/courses/17-914-international-politics-in-the-new-century-via-simulation-interactive-gaming-and-edutainment-january-iap-2005/","views":1348},{"id":"21H.105+spring_2006","numbers":["21H.105"],"title":"American Classics","summary":"This subject is devoted to reading and discussing basic American historical texts that are often cited but often remain unread, understanding their meaning, and assessing their continuing significance in American culture. Since it is a “Communications Intensive” subject, 21H.105 is also dedicated to improving students’ capacities to write and speak well. It requires a substantial amount of writing, participation in discussions, and individual presentations to the class.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["American History","Anthropology","Classics","Cultural Anthropology","History","Humanities","Literature","Social Anthropology","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2006","instructors":["Prof. Pauline Maier"],"url":"https://ocw.mit.edu/courses/21h-105-american-classics-spring-2006/","views":1347},{"id":"1.782+fall_2007","numbers":["1.782"],"title":"Environmental Engineering Masters of Engineering Project","summary":"This class is one of the core requirements for the Environmental Masters of Engineering program, in conjunction with 1.133 Masters of Engineering Concepts of Engineering Practice. It is designed to teach about environmental engineering through the use of case studies, computer software tools, and seminars from industrial experts. Case studies provide the basis for group projects as well as individual theses. Recent 1.782 projects include the MMR Superfund site on Cape Cod, appropriate wastewater treatment technology for Brazil and Honduras, point-of-use water treatment and safe storage procedures for Nepal and Ghana, Brownfields Development in Providence, RI, and water resource planning for the island of Cyprus and refugee settlements in Thailand. This class spans the entire academic year; students must register for the Fall and Spring terms.","departments":["Civil and Environmental Engineering"],"areas":["Engineering"],"topics":["Aquatic Sciences and Water Quality Control","Engineering","Environmental Engineering","Hydrology and Water Resource Systems"],"levels":["Graduate"],"features":["Projects","Written Assignments"],"term":"Fall 2007","instructors":["Dr. Eric Adams","Dr. Peter Shanahan","Susan Murcott"],"url":"https://ocw.mit.edu/courses/1-782-environmental-engineering-masters-of-engineering-project-fall-2007-spring-2008/","views":1346},{"id":"6.973+spring_2003","numbers":["6.973"],"title":"Organic Optoelectronics","summary":"The course examines optical and electronic processes in organic molecules and polymers that govern the behavior of practical organic optoelectronic devices. Electronic structure of a single organic molecule is used as a guide to the electronic behavior of organic aggregate structures. Emphasis is placed on the use of organic thin films in active organic devices including organic LEDs, solar cells, photodetectors, transistors, chemical sensors, memory cells, electrochromic devices, as well as xerography and organic non-linear optics. How to reach the ultimate miniaturization limit of molecular electronics and related nanoscale patterning techniques of organic materials will also be discussed. The class encompasses three laboratory sessions during which the students will practice the use of select vacuum and non-vacuum organic deposition techniques by making their own active organic devices.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering"],"topics":["Biological Engineering","Biotechnology","Electrical Engineering","Engineering","Mechanical Engineering","Microtechnology","Nanotechnology"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2003","instructors":["Prof. Vladimir Bulovic"],"url":"https://ocw.mit.edu/courses/6-973-organic-optoelectronics-spring-2003/","views":1346},{"id":"22.812J+spring_2004","numbers":["22.812J","ESD.163J"],"title":"Managing Nuclear Technology","summary":"An examination of current economic and policy issues in the electric power industry, focusing on nuclear power and its fuel cycle. Introduces techniques for analyzing private and public policy alternatives, including discounted cash flow methods and other techniques in engineering economics. Application to specific problem areas, including nuclear waste management and weapons proliferation. Other topics include deregulation and restructuring in the electric power industry.","departments":["Engineering Systems Division","Nuclear Science and Engineering"],"areas":["Business & Management","Energy, Climate & Sustainability","Engineering","Social Sciences"],"topics":["Business","Electricity","Energy","Engineering","Management","Nuclear Energy","Nuclear Engineering","Nuclear Systems, Policy, and Economics","Public Administration","Science and Technology Policy","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2004","instructors":["Prof. Richard Lester"],"url":"https://ocw.mit.edu/courses/22-812j-managing-nuclear-technology-spring-2004/","views":1342},{"id":"21H.181+spring_2014","numbers":["21H.181"],"title":"Libertarianism in History","summary":"This course explores the history of the ideal of personal freedom with an eye towards contemporary debates over the pros and cons of the regulatory state. The first part of the course surveys the sociological and theological sources of the concepts of freedom and civil society, and introduces liberty’s leading relatives or competitors: property, equality, community, and republicanism. The second part consists of a series of case studies in the rise of modern liberty and libertarianism: the abolition of slavery, the struggle for religious freedom, and the twentieth-century American civil liberties movement. In the last part of the course, we take up debates over the role of libertarianism vs. the regulatory state in a variety of contexts: counter-terrorism, health care, the financial markets, and the Internet.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["American History","American Politics","History","Humanities","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Problem Sets","Written Assignments"],"term":"Spring 2014","instructors":["Prof. Malick Ghachem"],"url":"https://ocw.mit.edu/courses/21h-181-libertarianism-in-history-spring-2014/","views":1340},{"id":"21H.319+fall_2014","numbers":["21H.319"],"title":"Race, Crime, and Citizenship in American Law","summary":"This seminar looks at key issues in the historical development and current state of modern American criminal justice, with an emphasis on its relationship to citizenship, nationhood, and race/ethnicity. We begin with a range of perspectives on the rise of what is often called “mass incarceration”: how did our current system of criminal punishment take shape, and what role did race play in that process? Part Two takes up a series of case studies, including racial disparities in the administration of the death penalty, enforcement of the drug laws, and the regulation of police investigations. The third and final part of the seminar looks at national security policing: the development of a constitutional law governing the intersection of ethnicity, religion, and counter-terrorism, and the impact of counter-terrorism policy on domestic police practices.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["African American Studies","American History","American Politics","History","Humanities","Legal Studies","Modern History","Political Science","Public Administration","Public Policy","Security Studies","Social Justice","Social Science","Society","Sociology"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments with Examples"],"term":"Fall 2014","instructors":["Prof. Malick Ghachem"],"url":"https://ocw.mit.edu/courses/21h-319-race-crime-and-citizenship-in-american-law-fall-2014/","views":1340},{"id":"11.481J+spring_2009","numbers":["11.481J","1.284J","ESD.192J"],"title":"Analyzing and Accounting for Regional Economic Growth","summary":"This course focuses on alternative ways in which the issues of growth, restructuring, innovation, knowledge, learning, and accounting and measurements can be examined, covering both industrialized and emerging countries. We give special emphasis to recent transformations in regional economies throughout the world and to the implications these changes have for the theories and research methods used in spatial economic analyses. Readings will relate mainly to the United States, but we cover pertinent material on foreign countries in lectures.","departments":["Civil and Environmental Engineering","Engineering Systems Division","Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Economics","Macroeconomics","Political Economy","Regional Planning","Social Science","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Projects with Examples"],"term":"Spring 2009","instructors":["Prof. Karen R. Polenske"],"url":"https://ocw.mit.edu/courses/11-481j-analyzing-and-accounting-for-regional-economic-growth-spring-2009/","views":1339},{"id":"STS.067+spring_2005","numbers":["STS.067"],"title":"Scientific Visualization across Disciplines: A Critical Introduction","summary":"This subject exposes students to a variety of visualization techniques so that they learn to understand the work involved in producing them and to critically assess the power and limits of each. Students concentrate on areas where visualizations are crucial for meaning making and data production. Drawing on scholarship in science and technology studies on visualization, critical art theory, and core discussions in science and engineering, students work through a series of case studies in order to become better readers and producers of visualizations.","departments":["Science, Technology, and Society"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Social Sciences"],"topics":["Communication","Computer Science","Engineering","Graphics and Visualization","Social Science"],"levels":["Undergraduate"],"features":["Presentation Assignments","Problem Sets","Projects"],"term":"Spring 2005","instructors":["Prof. Joseph Dumit"],"url":"https://ocw.mit.edu/courses/sts-067-scientific-visualization-across-disciplines-a-critical-introduction-spring-2005/","views":1339},{"id":"11.487+fall_2004","numbers":["11.487"],"title":"Urban Public Finance in Developing Countries","summary":"This readings-based course analyzes the structure and operation of government systems in developing countries, with particular emphasis on regional and local governments. Major topics include: the role of decentralization in national economic reform programs, the potential impact of decentralized governments on local economic development, determination of optimal arrangements for sharing fiscal responsibilities among levels of government, evaluation of local revenue and expenditure decisions, and assessment of prospects and options for intergovernmental fiscal reform. Emphasis is on basic economic concerns, with consideration given to political, institutional, and cultural factors.","departments":["Urban Studies and Planning"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Developmental Economics","Economics","Finance","Public Administration","Public Economics","Public Policy","Social Science","Urban Studies"],"levels":["Graduate"],"features":["Presentation Assignments","Problem Set Solutions","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Annette M. Kim"],"url":"https://ocw.mit.edu/courses/11-487-urban-public-finance-in-developing-countries-fall-2004/","views":1339},{"id":"4.614+fall_2002","numbers":["4.614"],"title":"Religious Architecture and Islamic Cultures","summary":"This course introduces the history of Islamic cultures through their most vibrant material signs: the religious architecture that spans fourteen centuries and three continents — Asia, Africa, and Europe. The course presents Islamic architecture both as a historical tradition and as a cultural catalyst that influenced and was influenced by the civilizations with which it came in contact.","departments":["Architecture"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Architectural History and Criticism","Architecture","Fine Arts","Middle Eastern Studies","Religious Architecture","Society"],"levels":["Undergraduate"],"features":["Image Gallery"],"term":"Fall 2002","instructors":["Prof. Nasser Rabbat"],"url":"https://ocw.mit.edu/courses/4-614-religious-architecture-and-islamic-cultures-fall-2002/","views":1338},{"id":"21L.485+fall_2015","numbers":["21L.485"],"title":"Modern Fiction","summary":"Tradition and innovation in representative fiction of the early modern period. Recurring themes include the role of the artist in the modern period; the representation of psychological and sexual experience; and the virtues (and defects) of the aggressively experimental character. Works by Conrad, Kipling, Babel, Kafka, James, Lawrence, Mann, Ford Madox Ford, Joyce, Woolf, Faulkner, and Nabokov.","departments":["Literature"],"areas":["Humanities"],"topics":["Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2015","instructors":["Prof. James Buzard"],"url":"https://ocw.mit.edu/courses/21l-485-modern-fiction-fall-2015/","views":1337},{"id":"17.484+fall_2004","numbers":["17.484"],"title":"Comparative Grand Strategy and Military Doctrine","summary":"This course will conduct a comparative study of the grand strategies of the great powers (Britain, France, Germany and Russia) competing for mastery of Europe from the late nineteenth to the mid-twentieth century. Grand strategy is the collection of political and military means and ends with which a state attempts to achieve security. We will examine strategic developments in the years preceding World Wars I and II, and how those developments played themselves out in these wars. The following questions will guide the inquiry: What is grand strategy and what are its critical aspects? What recurring factors have exerted the greatest influence on the strategies of the states selected for study? How may the quality of a grand strategy be judged? What consequences seem to follow from grand strategies of different types? A second theme of the course is methodological. We will pay close attention to how comparative historical case studies are conducted.","departments":["Political Science"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["Business","Comparative History","History","Humanities","International Relations","Military History","Military Studies","Organizational Behavior","Political Science","Public Administration","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2004","instructors":["Prof. Barry Posen"],"url":"https://ocw.mit.edu/courses/17-484-comparative-grand-strategy-and-military-doctrine-fall-2004/","views":1336},{"id":"MAS.962+spring_2003","numbers":["MAS.962"],"title":"The Nature of Constructionist Learning","summary":"This course examines the philosophical and theoretical foundations of constructionism as a paradigm for formulating and evaluating new theories for learning and approaches to education. One of the goals of this course is to help new learning researchers situate their work within the constructionist framework through readings and projects that will focus on the rich interplay between the process of knowledge construction and the development and co-evolution of ideas, learners, tools, and contexts.","departments":["Media Arts and Sciences"],"areas":["Education & Teaching","Humanities"],"topics":["Curriculum and Teaching","Humanities","Philosophy","Teaching and Education"],"levels":["Graduate"],"features":["Projects with Examples"],"term":"Spring 2003","instructors":["Prof. Bakhtiar Mikhak"],"url":"https://ocw.mit.edu/courses/mas-962-the-nature-of-constructionist-learning-spring-2003/","views":1336},{"id":"CMS.801+fall_2012","numbers":["CMS.801"],"title":"Media in Transition","summary":"This course centers on historical eras in which the form and function of media technologies were radically transformed. It includes consideration of the “Gutenberg Revolution,” the rise of modern mass media, and the “digital revolution,” among other case studies of media transformation and cultural change. Readings are in cultural and social history and historiographic method.","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","History","Humanities","Media Studies"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2012","instructors":["Prof. Jeffrey S. Ravel"],"url":"https://ocw.mit.edu/courses/cms-801-media-in-transition-fall-2012/","views":1335},{"id":"4.125+fall_2002","numbers":["4.125"],"title":"Architecture Studio: Building in Landscapes","summary":"4.125 is the third undergraduate design studio. This subject introduces skills needed to build within a landscape establishing continuities between the built and natural world. Students learn to build appropriately through analysis of landscape and climate for a chosen site, and to conceptualize design decisions through drawings and models.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architecture","Environmental Design","Fine Arts"],"levels":["Undergraduate"],"features":["Design Assignments with Examples","Lecture Videos","Projects with Examples"],"term":"Fall 2002","instructors":["Prof. Jan Wampler"],"url":"https://ocw.mit.edu/courses/4-125-architecture-studio-building-in-landscapes-fall-2002/","views":1333},{"id":"RES.ENV-003+fall_2019","numbers":["RES.ENV-003"],"title":"EarthDNA's Climate 101","summary":"The Climate 101 presentation was developed by Brandon Leshchinskiy in collaboration with Professor Dava Newman, MIT Portugal, and EarthDNA in an effort to mobilize young people as educators on the issue of climate change. The presentation addresses not only the science but also the economics and civics of climate change, incorporating a negotiation activity that brings key concepts to life.\n\nThis resource includes the slides and instructions for the presentation, along with an introductory video from Prof. Newman, a video of Leshchinskiy actually delivering the presentation to a classroom full of students, and extensive supporting materials that will help users to become climate ambassadors and deliver the Climate 101 presentation themselves.","departments":[],"areas":["Energy, Climate & Sustainability","Science & Math"],"topics":["Climate Studies","Earth Science","Environmental Science","Science"],"levels":["Non-Credit"],"features":["Editable Files","Instructor Insights","Other Video","Podcasts"],"term":"Fall 2019","instructors":["Brandon Leshchinskiy","Dava Newman"],"url":"https://ocw.mit.edu/courses/res-env-003-earthdnas-climate-101-fall-2019/","views":1333},{"id":"4.001J+spring_2007","numbers":["4.001J","11.004J"],"title":"CityScope: New Orleans","summary":"Do you want to think about ways to help solve New Orleans’ problems? CityScope is a project-based introduction to the contemporary city. “Problem solving in complex (urban) environments” is different than “solving complex problems.” As a member of a team, you will learn to assess scenarios for the purpose of formulating social, economic and design strategies to provide humane and sustainable solutions. A visit to New Orleans is planned for spring break 2007.","departments":["Architecture","Urban Studies and Planning"],"areas":["Art, Design & Architecture","Engineering","Social Sciences"],"topics":["Architectural Engineering","Architecture","Civil Engineering","Engineering","Fine Arts","Social Science","Urban Studies"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2007","instructors":["Cherie Miot Abbanat","Prof. J. Phillip Thompson","Prof. John Fernandez"],"url":"https://ocw.mit.edu/courses/4-001j-cityscope-new-orleans-spring-2007/","views":1332},{"id":"6.895+fall_2003","numbers":["6.895"],"title":"Theory of Parallel Systems (SMA 5509)","summary":"6.895 covers theoretical foundations of general-purpose parallel computing systems, from languages to architecture. The focus is on the algorithmic underpinnings of parallel systems. The topics for the class will vary depending on student interest, but will likely include multithreading, synchronization, race detection, load balancing, memory consistency, routing networks, message-routing algorithms, and VLSI layout theory. The class will emphasize randomized algorithms and probabilistic analysis, including high-probability arguments.\n\nThis course was also taught as part of the Singapore-MIT Alliance (SMA) programme as course number SMA 5509 (Theory of Parallel Systems).","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Algorithms and Data Structures","Computer Science","Engineering","Theory of Computation"],"levels":["Graduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Fall 2003","instructors":["Dr. Bradley Kuszmaul","Prof. Charles Leiserson","Prof. Hsu Wen Jing","Prof. Michael Bender"],"url":"https://ocw.mit.edu/courses/6-895-theory-of-parallel-systems-sma-5509-fall-2003/","views":1332},{"id":"HST.935+january-iap_2007","numbers":["HST.935"],"title":"Narrative Ethics: Literary Texts and Moral Issues in Medicine","summary":"This eight-session course, designed for a mixed group of first, second, third and fourth-year medical students, uses literary narratives and poetry to study ethical issues in medicine. This methodology emphasizes the importance of context, contingency, and circumstances in recognizing, evaluating, and resolving moral problems. The seminar will focus on developing the skills of critical and reflective reading that increase effectiveness in clinical medicine. Texts will include short fiction and poetry by authors such as Woolf, Chekhov, Carver, Kafka, Hurston, Marquez and Tolstoy. The instructor will provide necessary philosophic and literary context at the beginning of each session, the balance devoted to class discussion. During the course, students will keep a reading journal that examines the meanings of illness, the moral role of the physician, and the relevance of emotions, culture, faith, values, social realities, and life histories to patient care.","departments":["Health Sciences and Technology"],"areas":["Health & Medicine","Humanities"],"topics":["Ethics","Health and Medicine","Humanities","Literature","Philosophy"],"levels":["Graduate"],"features":[],"term":"January IAP 2007","instructors":["Prof. Martha Montello"],"url":"https://ocw.mit.edu/courses/hst-935-narrative-ethics-literary-texts-and-moral-issues-in-medicine-january-iap-2007/","views":1331},{"id":"22.920+january-iap_1997","numbers":["22.920"],"title":"A Hands-On Introduction to Nuclear Magnetic Resonance","summary":"Hands-on introduction to NMR presenting background in classical theory and instrumentation. Each lecture is followed by lab experiments to demonstrate ideas presented during the lecture and to familiarize students with state-of-the-art NMR instrumentation. Experiments cover topics ranging from spin dynamics to spectroscopy, and include imaging.","departments":["Nuclear Science and Engineering"],"areas":["Health & Medicine","Science & Math"],"topics":["Biomedical Instrumentation","Biomedical Signal and Image Processing","Health and Medicine","Medical Imaging","Nuclear Physics","Physics","Science","Spectroscopy"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Simulation Videos"],"term":"January IAP 1997","instructors":["Prof. David Cory"],"url":"https://ocw.mit.edu/courses/22-920-a-hands-on-introduction-to-nuclear-magnetic-resonance-january-iap-1997/","views":1330},{"id":"17.447+fall_2011","numbers":["17.447","17.448"],"title":"Cyberpolitics in International Relations: Theory, Methods, Policy","summary":"This course focuses on cyberspace and its implications for private and public, sub-national, national, and international actors and entities.","departments":["Political Science"],"areas":["Art, Design & Architecture","Business & Management","Social Sciences"],"topics":["Business","Digital Media","Fine Arts","Globalization","International Relations","Media Studies","Political Science","Public Administration","Science and Technology Policy","Social Science"],"levels":["Undergraduate"],"features":["Exams"],"term":"Fall 2011","instructors":["Prof. Nazli Choucri","Prof. Stuart Madnick","Dr. David D. Clark"],"url":"https://ocw.mit.edu/courses/17-447-cyberpolitics-in-international-relations-theory-methods-policy-fall-2011/","views":1330},{"id":"17.148+spring_2006","numbers":["17.148"],"title":"Political Economy of Globalization","summary":"This is a graduate seminar for students who already have some familiarity with issues in political economy and/or European politics. The objective is to examine the ways in which changes in the international economy and the regimes that regulate it interact with domestic politics, policy-making, and the institutional structures of the political economy in industrialized democracies.","departments":["Political Science"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Globalization","International Economics","Political Economy","Political Science","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2006","instructors":["Prof. Suzanne Berger"],"url":"https://ocw.mit.edu/courses/17-148-political-economy-of-globalization-spring-2006/","views":1329},{"id":"18.034+spring_2004","numbers":["18.034"],"title":"Honors Differential Equations","summary":"This course covers the same material as 18.03 with more emphasis on theory. Topics include first order equations, separation, initial value problems, systems, linear equations, independence of solutions, undetermined coefficients, and singular points and periodic orbits for planar systems.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Differential Equations","Linear Algebra","Mathematics"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2004","instructors":["Prof. Jason Starr"],"url":"https://ocw.mit.edu/courses/18-034-honors-differential-equations-spring-2004/","views":1328},{"id":"4.297+fall_2000","numbers":["4.297"],"title":"Special Problems in Architecture Studies","summary":"The course investigates e-Learning systems from a business, policy, technical and legal perspective. The issues presented will be tackled by discussion of the design and structure of the various example systems. The connection between information architectures and the physical workplace of the users will also be examined. The course will be comprised of readings, discussions, guest speakers and group design sessions. Laboratory sessions will be focused on implementation tools and opportunities to create one’s own working prototypes. Students will learn to describe information architectures using the Unified Modeling Language (used to specify, design and structure web applications) and XML (to designate meaningful content).","departments":["Architecture"],"areas":["Art, Design & Architecture","Education & Teaching"],"topics":["Architecture","Digital Media","Educational Technology","Environmental Design","Fine Arts","Media Studies","Teaching and Education"],"levels":["Graduate"],"features":[],"term":"Fall 2000","instructors":["Daniel Greenwood","Prof. William Mitchell"],"url":"https://ocw.mit.edu/courses/4-297-special-problems-in-architecture-studies-fall-2000/","views":1326},{"id":"12.307+spring_2009","numbers":["12.307"],"title":"Weather and Climate Laboratory","summary":"Course 12.307 is an undergraduate course intended to illustrate, by means of ‘hands on’ projects, the basic dynamical and physical principles that govern the general circulation of the atmosphere and ocean and the day to day sequence of weather events. The course parallels the content of the new undergraduate textbook Atmosphere, Ocean and Climate Dynamics by John Marshall and R. Alan Plumb.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Energy, Climate & Sustainability","Science & Math"],"topics":["Atmospheric Science","Climate Studies","Earth Science","Oceanography","Science"],"levels":["Undergraduate"],"features":["Activity Assignments","Projects"],"term":"Spring 2009","instructors":["Prof. John Marshall","Dr. Lodovica Illari"],"url":"https://ocw.mit.edu/courses/12-307-weather-and-climate-laboratory-spring-2009/","views":1325},{"id":"CMS.950+fall_2005","numbers":["CMS.950"],"title":"Workshop I","summary":"This course fulfills the first half of the Comparative Media Studies workshop sequence requirement for entering graduate students. The workshop sequence provides an opportunity for a creative, hands-on project development experience and emphasizes intellectual growth as well as the acquisition of technical skills. The course is designed to provide practical, hands-on experience to complement students’ theoretical studies.","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture"],"topics":["Fine Arts","Media Studies"],"levels":["Graduate"],"features":["Media Assignments"],"term":"Fall 2005","instructors":["Dr. Edward C. Barrett"],"url":"https://ocw.mit.edu/courses/cms-950-workshop-i-fall-2005/","views":1323},{"id":"21L.002+fall_2002","numbers":["21L.002"],"title":"Foundations of Western Culture II","summary":"Complementary to 21L.001. A broad survey of texts - literary, philosophical, and sociological - studied to trace the growth of secular humanism, the loss of a supernatural perspective upon human events, and changing conceptions of individual, social, and communal purpose. Stresses appreciation and analysis of texts that came to represent the common cultural possession of our time. Enrollment limited. HASS-D, CI.\n\nReadings this semester ranging from political theory and oratory to autobiography, poetry, and science fiction reflect on war, motives for war, reconciliation and memory. The readings are largely organized around three historical moments: the Renaissance and first contacts between Europe and America (Machiavelli, Cortés, Sahagún); the European age of revolutions (Voltaire, Blake, Williams); the American Civil War and the abolition of slavery (Stowe, Whitman, Lincoln). Readings from the twentieth-century include poetry by Lowell and Walcott and fiction by Ondaatje and O.S. Card.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","History","Humanities","Intellectual History","International Literature","Literature","Philosophy","Political Philosophy"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2002","instructors":["Prof. Mary Fuller"],"url":"https://ocw.mit.edu/courses/21l-002-foundations-of-western-culture-ii-fall-2002/","views":1322},{"id":"21L.423J+fall_2005","numbers":["21L.423J","21M.223J"],"title":"Introduction to Anglo-American Folk Music","summary":"This course examines the production, transmission, preservation and qualities of folk music in the British Isles and North America from the 18th century to the folk revival of the 1960s and the present. There is a special emphasis on balladry, fiddle styles, and African-American influences. The class sings ballads and folk songs from the Child and Lomax collections as well as other sources as we examine them from literary, historical, and musical points of view. Readings supply critical and background materials from a number of sources. Visitors and films bring additional perspectives.","departments":["Literature","Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History","Performance Arts"],"levels":["Undergraduate"],"features":["Activity Assignments","Written Assignments"],"term":"Fall 2005","instructors":["Prof. George Ruckert","Prof. Ruth Perry"],"url":"https://ocw.mit.edu/courses/21l-423j-introduction-to-anglo-american-folk-music-fall-2005/","views":1321},{"id":"ESD.70J+fall_2009","numbers":["ESD.70J","1.145J"],"title":"Engineering Economy Module","summary":"This intensive micro-subject provides the necessary skills in Microsoft® Excel spreadsheet modeling for ESD.71 Engineering Systems Analysis for Design. Its purpose is to bring entering students up to speed on some of the advanced techniques that we routinely use in analysis. It is motivated by our experience that many students only have an introductory knowledge of Excel, and thus waste a lot of time thrashing about unproductively. Many people think they know Excel, but overlook many efficient tools, such as Data Table and Goal Seek. It is also useful for a variety of other subjects.","departments":["Civil and Environmental Engineering","Engineering Systems Division"],"areas":["Engineering","Science & Math"],"topics":["Applied Mathematics","Computational Modeling and Simulation","Engineering","Mathematics","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2009","instructors":["Michel-Alexandre Cardin","Prof. Richard de Neufville"],"url":"https://ocw.mit.edu/courses/esd-70j-engineering-economy-module-fall-2009/","views":1319},{"id":"STS.050+spring_2016","numbers":["STS.050"],"title":"The History of MIT","summary":"To study MIT is to study the modern world. In 2016, MIT celebrated the 100th anniversary of the move from Boston to Cambridge; therefore, this course examines the history of the Institute through the lens of the history of science and technology, and vice-versa. It is about discovery, exploration, adventure, learning, creative thinking, and the synthesis of big ideas. Additionally, this course is about the importance of the research university, what it has been in the past and what it will be in the future. The course includes guest lecturers and field trips to the Institute Archives and the MIT Museum.\n\nThe most important prerequisite for this class is curiosity, a desire to think deeply about MIT, and a willingness to communicate your thoughts and ideas. The ultimate aim is to fascinate you as much as to help you improve your skills synthesizing information from diverse sources about science, technology, and culture.","departments":["Science, Technology, and Society"],"areas":["Humanities"],"topics":["American History","History","History of Science and Technology","Humanities","Modern History"],"levels":["Undergraduate"],"features":["Activity Assignments","Written Assignments"],"term":"Spring 2016","instructors":["Deborah Douglas"],"url":"https://ocw.mit.edu/courses/sts-050-the-history-of-mit-spring-2016/","views":1319},{"id":"6.896+spring_2004","numbers":["6.896"],"title":"Theory of Parallel Hardware (SMA 5511)","summary":"6.896 covers mathematical foundations of parallel hardware, from computer arithmetic to physical design, focusing on algorithmic underpinnings. Topics covered include: arithmetic circuits, parallel prefix, systolic arrays, retiming, clocking methodologies, boolean logic, sorting networks, interconnection networks, hypercubic networks, P-completeness, VLSI layout theory, reconfigurable wiring, fat-trees, and area-time complexity.\n\nThis course was also taught as part of the Singapore-MIT Alliance (SMA) programme as course number SMA 5511 (Theory of Parallel Hardware).","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Algorithms and Data Structures","Computer Design and Engineering","Computer Science","Engineering","Theory of Computation"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2004","instructors":["Dr. Bradley Kuszmaul","Prof. Charles Leiserson","Prof. Michael Bender"],"url":"https://ocw.mit.edu/courses/6-896-theory-of-parallel-hardware-sma-5511-spring-2004/","views":1315},{"id":"11.S948+spring_2018","numbers":["11.S948"],"title":"Seeing the City Afresh","summary":"This course explores the city through writing—listening to the voices of poets, short story writers, novelists, journalists, critics, historians, ethnographers, urbanists, musicians, filmmakers, and visual artists. Through extensive reading that informs their work on a longform story, students will join the chorus of storytellers to richly represent the variegated city. Our focus is on three nonfiction forms—essay, memoir, literary narrative—with special emphasis on the writer-editor relationship and on revision as a heuristic to better thinking.","departments":["Urban Studies and Planning"],"areas":["Humanities"],"topics":["Creative Writing","Humanities","Literature","Nonfiction Prose","Poetry"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2018","instructors":["Garnette Cadogan"],"url":"https://ocw.mit.edu/courses/11-s948-seeing-the-city-afresh-spring-2018/","views":1313},{"id":"21L.310+spring_2010","numbers":["21L.310"],"title":"Bestsellers: The Memoir","summary":"What is a “life” when it’s written down? How does memory inform the present? Why are memoirs so popular? This course will address these questions and others, considering the relationship between biography, autobiography, and memoir and between personal and social themes. We will closely examine some recent memoirs: Tobias Wolff’s This Boy’s Life, Barack Obama’s Dreams From My Father, Edwidge Danticat’s Brother, I’m Dying, Ayaan Hirsi Ali’s Infidel, and Alison Bechdel’s Fun Home. Students will write two brief papers: a critical essay and an experiment in memoir.\n\nAs a “Sampling,” this class offers 6 units, with a strong emphasis on close reading, group discussion, focused writing, and research and presentation skills.","departments":["Literature"],"areas":["Humanities"],"topics":["Biography","Criticism","Humanities","Literature","Nonfiction Prose"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2010","instructors":["Dr. Wyn Kelley"],"url":"https://ocw.mit.edu/courses/21l-310-bestsellers-the-memoir-spring-2010/","views":1311},{"id":"11.384+spring_2018","numbers":["11.384","11.385","11.386"],"title":"Malaysia Sustainable Cities Practicum","summary":"The Malaysia Sustainable Cities Practicum is an intensive field-based course that brings 15 graduate students to Malaysia to learn about and analyze sustainable city development in five cities in Malaysia. The students in the Practicum will help determine the extent to which these efforts have been successful. They will identify specific projects or policy-making efforts that the following year’s cohort of International Visiting Scholars can examine more closely.\n\nLead Faculty\n\nProfessor Larry Susskind\n\nTeaching Assistants\n\nJessica Gordon\n\nYasmin Zaerpoor\n\nAdministrative Staff\n\nTakeo Kuwabara\n\nSelmah Goldberg","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Humanities","Social Sciences"],"topics":["Asian History","Community Development","Environmental Policy","Geography","Global Poverty","History","Housing Development","Humanities","International Relations","Political Science","Public Administration","Regional Planning","Social Science","Society","Sociology","The Developing World","Transportation Planning","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Instructor Insights","Other Video","Written Assignments with Examples"],"term":"Spring 2018","instructors":["Prof. Lawrence Susskind"],"url":"https://ocw.mit.edu/courses/11-384-malaysia-sustainable-cities-practicum-spring-2018/","views":1310},{"id":"21H.447+fall_2004","numbers":["21H.447"],"title":"Nazi Germany and the Holocaust","summary":"The rise and fall of National Socialism is one of the most intensively-studied topics in European history. Nevertheless, after more than half a century, popular views of Nazism in the media and among the public remain simplistic-essentialized by equal parts fascination and horror. Adolf Hitler, for instance, is often portrayed as an evil genius of supernatural ability; while the Nazi state is similarly imagined to have held absolute power over every aspect of its subjects’ lives. Such characterizations allow ordinary Germans to be portrayed as helpless victims of Nazism, ensnared or coerced into submission by forces beyond their control. Another popular characterization is that German culture itself is fundamentally flawed - that all Germans were basically Nazis at heart. This schema conveniently erases the manifestations of fascism in other Western nations, and allows Americans and other Westerners to reassure themselves that the horrors of Nazism could never emerge in their own enlightened national cultures.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","European History","History","Humanities","Modern History","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. David Ciarlo"],"url":"https://ocw.mit.edu/courses/21h-447-nazi-germany-and-the-holocaust-fall-2004/","views":1309},{"id":"3.094+spring_2004","numbers":["3.094"],"title":"Materials in Human Experience","summary":"This course examines the ways in which people in ancient and contemporary societies have selected, evaluated, and used materials of nature, transforming them to objects of material culture. Some examples are: glass in ancient Egypt and Rome; sounds and colors of powerful metals in Mesoamerica; cloth and fiber technologies in the Inca empire. It also explores ideological and aesthetic criteria often influential in materials development. Laboratory/workshop sessions provide hands-on experience with materials discussed in class. This course complements 3.091.","departments":["Materials Science and Engineering"],"areas":["Engineering","Humanities"],"topics":["Ancient History","Engineering","History","History of Science and Technology","Humanities","Materials Science and Engineering","Metallurgical Engineering"],"levels":["Undergraduate"],"features":[],"term":"Spring 2004","instructors":["Prof. Heather Lechtman"],"url":"https://ocw.mit.edu/courses/3-094-materials-in-human-experience-spring-2004/","views":1307},{"id":"18.385J+fall_2004","numbers":["18.385J","2.036J"],"title":"Nonlinear Dynamics and Chaos","summary":"This graduate level course focuses on nonlinear dynamics with applications. It takes an intuitive approach with emphasis on geometric thinking, computational and analytical methods and makes extensive use of demonstration software.","departments":["Mathematics","Mechanical Engineering"],"areas":["Science & Math"],"topics":["Applied Mathematics","Differential Equations","Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Rodolfo Rosales"],"url":"https://ocw.mit.edu/courses/18-385j-nonlinear-dynamics-and-chaos-fall-2004/","views":1307},{"id":"21H.421+spring_2011","numbers":["21H.421","21H.185"],"title":"Introduction to Environmental History","summary":"Focusing primarily on the period since 1500, explores the influence of climate, topography, plants, animals, and microorganisms on human history and the reciprocal influence of people on the environment. Topics include the European encounter with the Americas, the impact of modern technology, and the historical roots of the current environmental crisis.","departments":["History"],"areas":["Energy, Climate & Sustainability","Humanities","Science & Math"],"topics":["Biology","Climate Studies","Earth Science","Ecology","Environmental Science","History","Humanities","Modern History","Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2011","instructors":["Prof. Harriet Ritvo"],"url":"https://ocw.mit.edu/courses/21h-421-introduction-to-environmental-history-spring-2011/","views":1304},{"id":"10.492-2+fall_2004","numbers":["10.492-2"],"title":"Integrated Chemical Engineering Topics I: Introduction to Biocatalysis","summary":"This course provides a brief introduction to the field of biocatalysis in the context of process design. Fundamental topics include why and when one may choose to use biological systems for chemical conversion, considerations for using free enzymes versus whole cells, and issues related to design and development of bioconversion processes. Biological and engineering problems are discussed as well as how one may arrive at both biological and engineering solutions.","departments":["Chemical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Biochemistry","Biological Engineering","Biology","Biomaterials","Chemical Engineering","Chemistry","Engineering","Organic Chemistry","Process Control Systems","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Kristala L. Jones Prather"],"url":"https://ocw.mit.edu/courses/10-492-2-integrated-chemical-engineering-topics-i-introduction-to-biocatalysis-fall-2004/","views":1300},{"id":"17.445+fall_2015","numbers":["17.445","17.446"],"title":"International Relations Theory in the Cyber Age","summary":"This course examines cyber dynamics and processes in international relations from different theoretical perspectives. It considers alternative theoretical and empirical frameworks consistent with characteristic features of cyberspace and emergent transformations at all levels of international interaction. Theories examined include realism and neorealism, institutionalism and liberalism, constructivism, and systems theory and lateral pressure. The course also highlights relevant features and proposes customized international relations theory for the cyber age.\n\nStudents taking the graduate version are expected to pursue the subject in greater depth through reading and individual research.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["International Relations","Political Science","Social Science"],"levels":["Undergraduate","Graduate"],"features":["Instructor Insights","Written Assignments with Examples"],"term":"Fall 2015","instructors":["Prof. Nazli Choucri"],"url":"https://ocw.mit.edu/courses/17-445-international-relations-theory-in-the-cyber-age-fall-2015/","views":1300},{"id":"18.409+fall_2009","numbers":["18.409"],"title":"Topics in Theoretical Computer Science: An Algorithmist's Toolkit","summary":"This course covers a collection of geometric techniques that apply broadly in modern algorithm design.","departments":["Mathematics"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Algorithms and Data Structures","Applied Mathematics","Computer Science","Engineering","Linear Algebra","Mathematics","Theory of Computation","Topology and Geometry"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2009","instructors":["Prof. Jonathan Kelner"],"url":"https://ocw.mit.edu/courses/18-409-topics-in-theoretical-computer-science-an-algorithmists-toolkit-fall-2009/","views":1300},{"id":"21L.004+fall_2005","numbers":["21L.004"],"title":"Major Poets","summary":"This subject is an introduction to poetry as a genre; most of our texts are originally written in English. We read poems from the Renaissance through the 17th and 18th centuries, Romanticism, and Modernism. Focus will be on analytic reading, on literary history, and on the development of the genre and its forms; in writing we attend to techniques of persuasion and of honest evidenced sequential argumentation. Poets to be read will include William Shakespeare, Queen Elizabeth, William Wordsworth, John Keats, T.S. Eliot, Langston Hughes, Sylvia Plath, Elizabeth Bishop, and some contemporary writers.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Humanities","Literature","Poetry"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2005","instructors":["Prof. Stephen Tapscott"],"url":"https://ocw.mit.edu/courses/21l-004-major-poets-fall-2005/","views":1298},{"id":"12.005+spring_2006","numbers":["12.005"],"title":"Applications of Continuum Mechanics to Earth, Atmospheric, and Planetary Sciences","summary":"This course focuses on the practical applications of the continuum concept for deformation of solids and fluids, emphasizing force balance. Topics include stress tensor, infinitesimal and finite strain, and rotation tensors. Constitutive relations applicable to geological materials, including elastic, viscous, brittle, and plastic deformation are studied.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Atmospheric Science","Earth Science","Engineering","Fluid Mechanics","Geology","Mechanical Engineering","Planetary Science","Science","Solid Mechanics"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2006","instructors":["Prof. Bradford Hager"],"url":"https://ocw.mit.edu/courses/12-005-applications-of-continuum-mechanics-to-earth-atmospheric-and-planetary-sciences-spring-2006/","views":1296},{"id":"21H.154+fall_2022","numbers":["21H.154","21G.554"],"title":"Inventing the Samurai","summary":"This course explores the historical origins of the Japanese warrior class as well as its reinvention throughout the archipelago’s history, with a special focus on the pre-modern era (200–1600 CE). It highlights key historical contexts including the rise of the imperial court, interactions with the broader world, and the establishment of a warrior-dominated state. It also considers the modern imaginations and uses of the warrior figure.\n\nNote: This course is taught in English with a project that requires research in Japanese.","departments":["Global Studies and Languages","History"],"areas":["Humanities"],"topics":["Ancient History","Asian History","History","Humanities"],"levels":["Undergraduate"],"features":["Lecture Notes","Readings","Written Assignments"],"term":"Fall 2022","instructors":["Prof. Hiromu Nagahara"],"url":"https://ocw.mit.edu/courses/21h-154-inventing-the-samurai-fall-2022/","views":1295},{"id":"18.318+spring_2006","numbers":["18.318"],"title":"Topics in Algebraic Combinatorics","summary":"The course consists of a sampling of topics from algebraic combinatorics. The topics include the matrix-tree theorem and other applications of linear algebra, applications of commutative and exterior algebra to counting faces of simplicial complexes, and applications of algebra to tilings.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Discrete Mathematics","Linear Algebra","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2006","instructors":["Prof. Richard Stanley"],"url":"https://ocw.mit.edu/courses/18-318-topics-in-algebraic-combinatorics-spring-2006/","views":1294},{"id":"7.18+fall_2005","numbers":["7.18"],"title":"Topics in Experimental Biology","summary":"This independent experimental study course is designed to allow students with a strong interest in independent research to fulfill the project laboratory requirement for the Biology Department Program in the context of a research laboratory at MIT. The research should be a continuation of a previous project under the direction of a member of the Biology Department faculty.\n\nThis course provides instruction and practice in written and oral communication. Journal club discussions are used to help students evaluate and write scientific papers.","departments":["Biology"],"areas":["Science & Math"],"topics":["Biology","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Presentation Assignments","Written Assignments"],"term":"Fall 2005","instructors":["Dr. Karen Pepper","Dr. Leslie Ann Roldan","Prof. Paul T. Matsudaira","Prof. Anthony Sinskey"],"url":"https://ocw.mit.edu/courses/7-18-topics-in-experimental-biology-fall-2005/","views":1294},{"id":"21G.056+fall_2003","numbers":["21G.056"],"title":"Visual  Histories: German Cinema 1945 to Present","summary":"This course is an invitation to German film-making since the end of the Second World War. We investigate how German cinema captured the atmosphere of the immediate post-war years and discuss extensively major works of the “New German Cinema” of the Sixties and Seventies. We also look at examples of East Germany’s film production and finally observe the very different roads German cinema has been taking from the 1990’s into the present.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["European History","European and Russian Studies","Film and Video","Fine Arts","History","Humanities","Society","Visual Arts"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2003","instructors":["Prof. Bernd Widdig"],"url":"https://ocw.mit.edu/courses/21g-056-visual-histories-german-cinema-1945-to-present-fall-2003/","views":1292},{"id":"21A.215+spring_2012","numbers":["21A.215"],"title":"Disease and Health: Culture, Society, and Ethics","summary":"This course examines how medicine is practiced cross-culturally, with particular emphasis on Western biomedicine. Students analyze medical practice as a cultural system, focusing on the human, as opposed to the biological, side of things. Also considered is how people in different cultures think of disease, health, body, and mind.","departments":["Anthropology"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Ethics","History","History of Science and Technology","Humanities","Philosophy","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2012","instructors":["Prof. Jean Jackson"],"url":"https://ocw.mit.edu/courses/21a-215-disease-and-health-culture-society-and-ethics-spring-2012/","views":1289},{"id":"22.68J+spring_2003","numbers":["22.68J","2.64J"],"title":"Superconducting Magnets","summary":"This course focuses on one important engineering application of superconductors – the generation of large-scale and intense magnetic fields. It includes a review of electromagnetic theory; detailed treatment of magnet design and operational issues, including “usable” superconductors, field and stress analyses, magnet instabilities, ac losses and mechanical disturbances, quench and protection, experimental techniques, and cryogenics. The course also examines new high-temperature superconductors for magnets, as well as design and operational issues at high temperatures.","departments":["Mechanical Engineering","Nuclear Science and Engineering"],"areas":["Science & Math"],"topics":["Condensed Matter Physics","Electromagnetism","Physics","Quantum Mechanics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2003","instructors":["Dr. Joseph Minervini","Res. Prof. Yukikazu Iwasa"],"url":"https://ocw.mit.edu/courses/22-68j-superconducting-magnets-spring-2003/","views":1289},{"id":"21G.043J+fall_2013","numbers":["21G.043J","21H.107J"],"title":"Introduction to Asian American Studies: Literature, Culture, and Historical Experience","summary":"This course provides an overview of Asian American history and its relevance for contemporary issues. It covers the first wave of Asian immigration in the 19th century, the rise of anti-Asian movements, the experiences of Asian Americans during WWII, the emergence of the Asian American movement in the 1960s, and the new wave of post–1965 Asian immigration. The class examines the role these experiences played in the formation of Asian American ethnicity. The course addresses key societal issues such as racial stereotyping, media racism, affirmative action, the glass ceiling, the “model minority” syndrome, and anti-Asian harassment or violence. The course is taught in English.","departments":["Global Studies and Languages","History"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Asian History","Asian Studies","Cultural Anthropology","History","Humanities","Social Science","Society"],"levels":["Undergraduate"],"features":["Activity Assignments","Written Assignments"],"term":"Fall 2013","instructors":["Prof. Emma J. Teng"],"url":"https://ocw.mit.edu/courses/21g-043j-introduction-to-asian-american-studies-literature-culture-and-historical-experience-fall-2013/","views":1287},{"id":"18.034+spring_2009","numbers":["18.034"],"title":"Honors Differential Equations","summary":"This course covers the same material as Differential Equations (18.03) with more emphasis on theory. In addition, it treats mathematical aspects of ordinary differential equations such as existence theorems.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Differential Equations","Linear Algebra","Mathematics"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets","Projects with Examples"],"term":"Spring 2009","instructors":["Dr. Vera Mikyoung Hur"],"url":"https://ocw.mit.edu/courses/18-034-honors-differential-equations-spring-2009/","views":1284},{"id":"21G.S55+fall_2022","numbers":["21G.S55"],"title":"Japanese V","summary":"This is an experimental version of 21G.505, which offers a combination of in-person and synchronous remote instruction. It aims to achieve simultaneous progression of four skills—listening, speaking, reading, and writing. It immerses students in various aspects of Japanese culture through authentic everyday Japanese media.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","Japanese","Language"],"levels":["Undergraduate"],"features":["Editable Files","Instructor Insights","Lecture Notes","Videos"],"term":"Fall 2022","instructors":["Dr. Takako Aikawa"],"url":"https://ocw.mit.edu/courses/21g-s55-japanese-v-fall-2022/","views":1284},{"id":"3.60+fall_2005","numbers":["3.60"],"title":"Symmetry, Structure, and Tensor Properties of Materials","summary":"This course covers the derivation of symmetry theory; lattices, point groups, space groups, and their properties; use of symmetry in tensor representation of crystal properties, including anisotropy and representation surfaces; and applications to piezoelectricity and elasticity.","departments":["Materials Science and Engineering"],"areas":["Engineering"],"topics":["Engineering","Materials Science and Engineering","Mechanical Engineering","Solid Mechanics"],"levels":["Graduate"],"features":["Lecture Videos","Problem Sets"],"term":"Fall 2005","instructors":["Prof. Bernhardt Wuensch"],"url":"https://ocw.mit.edu/courses/3-60-symmetry-structure-and-tensor-properties-of-materials-fall-2005/","views":1284},{"id":"18.997+spring_2004","numbers":["18.997"],"title":"Topics in Combinatorial Optimization","summary":"In this graduate-level course, we will be covering advanced topics in combinatorial optimization. We will start with non-bipartite matchings and cover many results extending the fundamental results of matchings, flows and matroids. The emphasis is on the derivation of purely combinatorial results, including min-max relations, and not so much on the corresponding algorithmic questions of how to find such objects. The intended audience consists of Ph.D. students interested in optimization, combinatorics, or combinatorial algorithms.","departments":["Mathematics"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Applied Mathematics","Computation","Computer Science","Engineering","Mathematics","Systems Engineering","Systems Optimization","Theory of Computation"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2004","instructors":["Prof. Michel Goemans"],"url":"https://ocw.mit.edu/courses/18-997-topics-in-combinatorial-optimization-spring-2004/","views":1284},{"id":"WGS.640+fall_2007","numbers":["WGS.640"],"title":"Studies in Women's Life Narratives: Interrogating Marriage: Case Studies in American Law and Culture","summary":"Is marriage a patriarchal institution? Much feminist scholarship has characterized it that way, but now in the context of the recent Massachusetts Supreme Court decision legalizing gay marriage, the meaning of marriage itself demands serious re-examination. This course will discuss history, literature, film, and legal scholarship, making use of cross-cultural, sociological, anthropological, and many other theoretical approaches to the marriage question from 1630 to the present. As it turns out, sex, marriage, and the family have never been stable institutions; to the contrary, they have continued to function as flash points for the very social and cultural questions that are central to gender studies scholarship.","departments":["Women's and Gender Studies"],"areas":["Social Sciences"],"topics":["Gender Studies","Legal Studies","Social Science","Society","Women's Studies"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Fall 2007","instructors":["Prof. Leonard Buckle","Prof. Renee Bergland","Prof. Suzann Thomas-Buckle"],"url":"https://ocw.mit.edu/courses/wgs-640-studies-in-womens-life-narratives-interrogating-marriage-case-studies-in-american-law-and-culture-fall-2007/","views":1283},{"id":"20.330J+spring_2007","numbers":["20.330J","2.793J","6.023J"],"title":"Fields, Forces and Flows in Biological Systems","summary":"This course introduces the basic driving forces for electric current, fluid flow, and mass transport, plus their application to a variety of biological systems. Basic mathematical and engineering tools will be introduced, in the context of biology and physiology. Various electrokinetic phenomena are also considered as an example of coupled nature of chemical-electro-mechanical driving forces. Applications include transport in biological tissues and across membranes, manipulation of cells and biomolecules, and microfluidics.","departments":["Biological Engineering","Electrical Engineering and Computer Science","Mechanical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Biology","Biophysics","Chemical Engineering","Computation and Systems Biology","Engineering","Fluid Mechanics","Mechanical Engineering","Molecular Biology","Science","Transport Processes"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2007","instructors":["Prof. Jongyoon Han","Prof. Scott Manalis"],"url":"https://ocw.mit.edu/courses/20-330j-fields-forces-and-flows-in-biological-systems-spring-2007/","views":1281},{"id":"18.112+fall_2008","numbers":["18.112"],"title":"Functions of a Complex Variable","summary":"This is an advanced undergraduate course dealing with calculus in one complex variable with geometric emphasis. Since the course Analysis I (18.100B) is a prerequisite, topological notions like compactness, connectedness, and related properties of continuous functions are taken for granted.\n\nThis course offers biweekly problem sets with solutions, two term tests and a final exam, all with solutions.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Calculus","Mathematical Analysis","Mathematics","Topology and Geometry"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2008","instructors":["Prof. Sigurdur Helgason"],"url":"https://ocw.mit.edu/courses/18-112-functions-of-a-complex-variable-fall-2008/","views":1281},{"id":"11.027+spring_2017","numbers":["11.027"],"title":"Global Cityscope - Disaster Planning and Post-Disaster Rebuilding and Recovery","summary":"This class is designed to expose you to the cycles of disasters, the roots of emergency planning in the U.S., how to understand and map vulnerabilities, and expose you to the disaster planning in different contexts, including in developing countries.","departments":["Urban Studies and Planning"],"areas":["Data Science, Analytics & Computer Technology","Energy, Climate & Sustainability","Engineering","Science & Math","Social Sciences"],"topics":["Civil Engineering","Climate","Energy","Engineering","Environmental Engineering","Housing Development","Regional Planning","Social Science","Technology","Urban Planning","Urban Studies"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2017","instructors":["Cherie Miot Abbanat"],"url":"https://ocw.mit.edu/courses/11-027-global-cityscope-disaster-planning-and-post-disaster-rebuilding-and-recovery-spring-2017/","views":1281},{"id":"RES.CMS-504+spring_2021","numbers":["RES.CMS-504"],"title":"Sorting Truth From Fiction: Civic Online Reasoning","summary":"With educators from around the world and faculty from MIT and Stanford University, you will learn quick and effective practices for evaluating online information that you can bring back to your classroom. The Stanford History Education Group has distilled these practices from observations with professional fact-checkers from the nation’s most prestigious media outlets from across the political spectrum. Using a combination of readings, classroom practice lessons, and assignments, you will learn how to teach the critical thinking skills needed for making wise judgments about web sources.\n\nAt the end of the course, you will be better able to help students find reliable sources at a time when we need it most.\n\nThis course is part of the Open Learning Library, which is free to use. You have the option to sign up and enroll in the course if you want to track your progress, or you can view and use all the materials without enrolling.","departments":["Comparative Media Studies/Writing"],"areas":["Education & Teaching"],"topics":["Teaching and Education"],"levels":["Non-Credit"],"features":[],"term":"Spring 2021","instructors":["Prof. Justin Reich","Prof. Sam Wineburg"],"url":"https://ocw.mit.edu/courses/res-cms-504-sorting-truth-from-fiction-civic-online-reasoning-spring-2021/","views":1280},{"id":"1.725J+fall_2004","numbers":["1.725J"],"title":"Chemicals in the Environment: Fate and Transport","summary":"This core class in the Environmental M.Eng. program is for all students interested in the behavior of chemicals in the environment. The emphasis is on man-made chemicals; their movement through water, air, and soil; and their eventual fate. Physical transport, as well as chemical and biological sources and sinks, are discussed. Linkages to health effects, sources and control, and policy aspects are discussed and debated.","departments":["Civil and Environmental Engineering"],"areas":["Engineering","Science & Math"],"topics":["Chemical Engineering","Chemistry","Earth Science","Engineering","Environmental Engineering","Environmental Science","Hydrology and Water Resource Systems","Science","Transport Processes"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Harold Hemond","Janet Chuang"],"url":"https://ocw.mit.edu/courses/1-725j-chemicals-in-the-environment-fate-and-transport-fall-2004/","views":1279},{"id":"4.580+fall_2006","numbers":["4.580"],"title":"Inquiry into Computation and Design","summary":"This subject explores the varied nature and practice of computation in design. We will view computation and design broadly. Computation will include both work done on the computer (digital computing) and by-hand. Design will include both the process of making designs and artifacts, as well as the designs and artifacts themselves. The aim of the course is to develop a view of computation and design beyond the specifics of techniques and tools, and a critical, self-awareness of our own approaches and metaphors for computation and design.","departments":["Architecture"],"areas":["Art, Design & Architecture","Engineering"],"topics":["Architectural Design","Architecture","Computational Science and Engineering","Engineering","Fine Arts","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2006","instructors":["Prof. Terry Knight"],"url":"https://ocw.mit.edu/courses/4-580-inquiry-into-computation-and-design-fall-2006/","views":1279},{"id":"11.484+spring_2005","numbers":["11.484"],"title":"Project Appraisal in Developing Countries","summary":"This course covers techniques of financial analysis of investment expenditures as well as the economic and distributive appraisal of those projects. The course gives special consideration to cases in the developing world. Students will engage in a critical analysis of these tools and their role in the political economy of international development. The course will cover topics such as alternative planning strategies for conditions of uncertainty; organizations and project cycle management; the political environment; and interactions of clients and advisers, engineers, planners, policy analysts, and other professionals.\n\nIntroductory micro-economics is a pre-requisite for this course.","departments":["Urban Studies and Planning"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Finance","Financial Economics","International Development","Social Science","Society","The Developing World"],"levels":["Graduate"],"features":["Problem Sets","Written Assignments"],"term":"Spring 2005","instructors":["Prof. Annette M. Kim"],"url":"https://ocw.mit.edu/courses/11-484-project-appraisal-in-developing-countries-spring-2005/","views":1276},{"id":"12.520+fall_2006","numbers":["12.520"],"title":"Geodynamics","summary":"This course deals with mechanics of deformation of the crust and mantle, with emphasis on the importance of different rheological descriptions: brittle, elastic, linear and nonlinear fluids, and viscoelastic.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geology","Geophysics","Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2006","instructors":["Prof. Bradford Hager"],"url":"https://ocw.mit.edu/courses/12-520-geodynamics-fall-2006/","views":1272},{"id":"21G.820+fall_2016","numbers":["21G.820"],"title":"The Beat of Brazil: Brazilian Society Through Its Music","summary":"This course will present students with an overview of Brazilian popular music, from the late nineteenth century to the present day. Considered an advanced course, it aims to build vocabulary competence and improve oral communication through the study and discussion of topics about cultural aspects and current issues in Brazil. It is designed to give students extensive experience in Portuguese and emphasizes skill development and refinement in the area of critical reading and writing in Portuguese.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Fine Arts","History","Humanities","Language","Latin American History","Latin and Caribbean Studies","Music","Music History","Portuguese","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2016","instructors":["Dr. Nilma Dominique"],"url":"https://ocw.mit.edu/courses/21g-820-the-beat-of-brazil-brazilian-society-through-its-music-fall-2016/","views":1272},{"id":"21L.702+fall_2007","numbers":["21L.702"],"title":"Studies in Fiction: Rethinking the American Masterpiece","summary":"What has been said of Moby-Dick—that it’s the greatest novel no one ever reads—could just as well be said of any number of American “classics” like The Scarlet Letter, Uncle Tom’s Cabin, or The Adventures of Huckleberry Finn. This course reconsiders a small number of nineteenth-century American novels by presenting each in a surprising context.","departments":["Literature"],"areas":["Humanities"],"topics":["American Literature","Criticism","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2007","instructors":["Dr. Wyn Kelley"],"url":"https://ocw.mit.edu/courses/21l-702-studies-in-fiction-rethinking-the-american-masterpiece-fall-2007/","views":1271},{"id":"21G.711+spring_2014","numbers":["21G.711"],"title":"Advanced Spanish Conversation and Composition","summary":"En este curso el estudiante perfeccionará su comunicación oral y escrita mediante el estudio y la discusión de temas relacionados al impacto social y cultural de la ciencia y la tecnología en ciertas sociedades hispanas. Algunos de los temas a tratar son los efectos de los cambios tecnológicos en la estructura familiar y comunitaria, en las relaciones entre los sexos, en la identidad personal y cultural, en el mundo natural y en los sistemas de valores, la religión, la educación y el trabajo. También se examinan y discuten diversas actitudes hacia la innovación tecnológica y científica así como las ramificaciones éticas de las decisiones tecnológicas.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["Communication","European and Russian Studies","Humanities","Language","Social Science","Society","Spanish"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments"],"term":"Spring 2014","instructors":["Margarita Ribas Groeger"],"url":"https://ocw.mit.edu/courses/21g-711-advanced-spanish-conversation-and-composition-spring-2014/","views":1269},{"id":"11.020+fall_2003","numbers":["11.020"],"title":"Poverty, Public Policy and Controversy","summary":"This course covers topics and questions such as: What is poverty? How is it defined and measured in the United States and other countries? What are the different program designs that countries use to relieve poverty? To answer these questions, the course examines the main public policy frames that guide theory, research, policy, and practice. How do the definition and policies to deal with poverty change over time? What are the economic, political, and social forces that contribute to the persistence of poverty and its periodic reframing? Can social science to help to resolve the public policy debates that make poverty and its relief so controversial?","departments":["Urban Studies and Planning"],"areas":["Humanities","Social Sciences"],"topics":["Economics","Global Poverty","Humanities","Philosophy","Political Economy","Political Philosophy","Public Administration","Public Policy","Social Science","Society","Sociology"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2003","instructors":["Prof. Martin Rein"],"url":"https://ocw.mit.edu/courses/11-020-poverty-public-policy-and-controversy-fall-2003/","views":1269},{"id":"17.588+fall_2013","numbers":["17.588"],"title":"Field Seminar in Comparative Politics","summary":"This course provides an introduction to the field of comparative politics. Readings include both classic and recent materials. Discussions include research design and research methods, in addition to topics such as political culture, social cleavages, the state, and democratic institutions. The emphasis on each issue depends in part on the interests of the students.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Comparative Politics","Political Science","Social Science"],"levels":["Graduate"],"features":["Instructor Insights","Written Assignments"],"term":"Fall 2013","instructors":["Prof. Chappell Lawson"],"url":"https://ocw.mit.edu/courses/17-588-field-seminar-in-comparative-politics-fall-2013/","views":1265},{"id":"4.S33+spring_2015","numbers":["4.S33"],"title":"Unmanageability: Pathless Realities and Approaches","summary":"Over the last 40 years, new managerial technologies in Western democratic societies have emerged to dominate our perceived and lived reality. Demands for autonomy and a creative life, which have been the touchstones for artistic endeavors, have been readily absorbed into management philosophies, becoming normative values for self-management and entrepreneurial innovation. Is this art’s triumph or demise? Can we imagine other worlds beyond our managed reality and propose forms of living not yet captured by the rationality of network capitalism? We will explore the “creative” figure and how it can shape renewed critical expressions in fields such as technology, design, science, philosophy, etc.","departments":["Architecture"],"areas":["Art, Design & Architecture","Business & Management","Education & Teaching","Humanities","Social Sciences"],"topics":["American History","Business","Fine Arts","History","History of Science and Technology","Humanities","Innovation","Media Studies","Modern History","Organizational Behavior","Philosophy","Social Science","Sociology","Teaching and Education"],"levels":["Graduate"],"features":["Presentation Assignments"],"term":"Spring 2015","instructors":["Gabriel Kahan","Howard Chen"],"url":"https://ocw.mit.edu/courses/4-s33-unmanageability-pathless-realities-and-approaches-spring-2015/","views":1263},{"id":"WGS.700+spring_2017","numbers":["WGS.700"],"title":"Changing Life: Reading the Intersections of Gender, Race, Biology, and Literature","summary":"In this course, students will develop their abilities to expose ways that scientific knowledge has been shaped in contexts that are gendered, racialized, economically exploitative, and hetero-normative. This happens through a sequence of four projects that concern:\n\n• Interpretation of the cultural dimension of sciences\n• Climate change futures\n• Genomic citizenry\n• Students’ plans for ongoing practice\n\nThe course uses a Project-Based Learning format that allows students to shape their own directions of inquiry in each project, development of skills, and collegial support. Students’ learning will be guided by individualized bibliographies co-constructed with the instructors, the inquiries of the other students, and a set of tools and processes for literary analysis, inquiry, reflection, and support.\n\nAcknowledgement\n\nProfessor Peter Taylor spent several years crafting the unique structure of the course, which is crucial to the way it was taught.\n\nThe Consortium for Graduate Studies in Gender, Culture, Women, and Sexuality\n\nThis course was taught as part of the Consortium for Graduate Studies in Gender, Culture, Women, and Sexuality (GCWS) at MIT. The GCWS brings together scholars and teachers at nine degree-granting institutions in the Boston area who are devoted to graduate teaching and research in Women’s Studies and to advance interdisciplinary Women’s Studies scholarship.","departments":["Women's and Gender Studies"],"areas":["Energy, Climate & Sustainability","Science & Math","Social Sciences"],"topics":["African American Studies","Biology","Climate Studies","Earth Science","Environmental Science","Gender Studies","Genetics","Science","Society"],"levels":["Graduate"],"features":["Projects"],"term":"Spring 2017","instructors":["Prof. Mary Baine Campbell","Prof. Peter Taylor"],"url":"https://ocw.mit.edu/courses/wgs-700-changing-life-reading-the-intersections-of-gender-race-biology-and-literature-spring-2017/","views":1262},{"id":"WGS.640+spring_2014","numbers":["WGS.640"],"title":"Screen Women: Body Narratives in Popular American Film","summary":"Using film and related popular media as our texts, this course will examine how screen “embodiments” of the woman visualize ideologies of discipline and desire in a culture in which her body has become a representation of the ability to control appetites, size and shape while investing personal and social capital in its rehabilitation as a project of endless reconstruction, redesign and maintenance. Throughout the course we will draw from feminist film theory, clinical psychology, as well as women’s, gender, and cultural studies, to better understand how filmic representations of the woman’s body first emerge from contemporary psychosocial contexts and then in turn shape the body ideals and internalizations, as well as the behavioral practices of the film spectator.\n\nThe Graduate Consortium in Women’s Studies (GCWS)\n\nThis course is part of the Graduate Consortium in Women’s Studies. The GCWS at MIT brings together scholars and teachers at nine degree-granting institutions in the Boston area who are devoted to graduate teaching and research in Women’s Studies and to advancing interdisciplinary Women’s Studies scholarship. Learn more about the GCWS.","departments":["Women's and Gender Studies"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Criticism","Film and Video","Fine Arts","Gender Studies","Humanities","Literature","Society","Visual Arts","Women's Studies"],"levels":["Graduate"],"features":["Instructor Insights","Presentation Assignments","Written Assignments with Examples"],"term":"Spring 2014","instructors":["Dr. Emily Fox-Kales","Dr. Suzanne Leonard"],"url":"https://ocw.mit.edu/courses/wgs-640-screen-women-body-narratives-in-popular-american-film-spring-2014/","views":1262},{"id":"RES.EC-001+spring_2020","numbers":["RES.EC-001"],"title":"Exploring Fairness in Machine Learning for International Development","summary":"In an effort to build the capacity of the students and faculty on the topics of bias and fairness in machine learning (ML) and appropriate use of ML, the MIT CITE team developed capacity-building activities and material. This material covers content through four modules that an be integrated into existing courses over a one to two week period.","departments":["Edgerton Center"],"areas":["Data Science, Analytics & Computer Technology","Education & Teaching","Engineering"],"topics":["Artificial Intelligence","Computer Science","Curriculum and Teaching","Engineering","Teaching and Education"],"levels":["Non-Credit"],"features":["Lecture Videos"],"term":"Spring 2020","instructors":["Dr. Richard Fletcher","Prof. Daniel Frey","Dr. Mike Teodorescu","Amit Gandhi","Audace Nakeshimana"],"url":"https://ocw.mit.edu/courses/res-ec-001-exploring-fairness-in-machine-learning-for-international-development-spring-2020/","views":1260},{"id":"22.103+fall_2003","numbers":["22.103"],"title":"Microscopic Theory of Transport","summary":"Transport is among the most fundamental and widely studied phenomena in science and engineering. This subject will lay out the essential concepts and current understanding, with emphasis on the molecular view, that cut across all disciplinary boundaries. (Suitable for all students in research.)\n\n• Broad perspectives of transport phenomena\n• From theory and models to computations and simulations\n• Micro/macro coupling\n• Current research insights","departments":["Nuclear Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Chemical Engineering","Chemistry","Engineering","Physical Chemistry","Science","Transport Processes"],"levels":["Undergraduate"],"features":["Exams","Lecture Notes","Problem Sets"],"term":"Fall 2003","instructors":["Prof. Sidney Yip"],"url":"https://ocw.mit.edu/courses/22-103-microscopic-theory-of-transport-fall-2003/","views":1260},{"id":"12.400+spring_2006","numbers":["12.400"],"title":"The Solar System","summary":"This is an introduction to the study of the solar system with emphasis on the latest spacecraft results. The subject covers basic principles rather than detailed mathematical and physical models. Topics include: an overview of the solar system, planetary orbits, rings, planetary formation, meteorites, asteroids, comets, planetary surfaces and cratering, planetary interiors, planetary atmospheres, and life in the solar system.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Astrophysics","Earth Science","Geophysics","Physics","Planetary Science","Science"],"levels":["Undergraduate"],"features":["Problem Sets"],"term":"Spring 2006","instructors":["Prof. Richard Binzel"],"url":"https://ocw.mit.edu/courses/12-400-the-solar-system-spring-2006/","views":1260},{"id":"11.128+spring_2005","numbers":["11.128","11.248","14.49"],"title":"Information Technology and the Labor Market","summary":"This course explores how information technology is reshaping different dimensions of the U.S. labor market: the way work is organized, the mix of occupations, the skills required to perform in an occupation, economy-wide labor productivity, and the distribution of wages.","departments":["Economics","Urban Studies and Planning"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Information Technology","Labor Economics","Public Administration","Science and Technology Policy","Social Science","Sociology"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets","Written Assignments"],"term":"Spring 2005","instructors":["Prof. Frank Levy"],"url":"https://ocw.mit.edu/courses/11-128-information-technology-and-the-labor-market-spring-2005/","views":1259},{"id":"21A.302J+fall_2013","numbers":["21A.302J","WGS.271J"],"title":"Dilemmas in Bio-Medical Ethics: Playing God or Doing Good?","summary":"This course is an introduction to the cross-cultural study of biomedical ethics, examining moral foundations of the science and practice of Western biomedicine through case studies of abortion, contraception, cloning, organ transplantation and other issues. It evaluates challenges that new medical technologies pose to the practice and availability of medical services around the globe, and to cross-cultural ideas of kinship and personhood. Also discussed are critiques of the biomedical tradition from anthropological, feminist, legal, religious, and cross-cultural theorists.","departments":["Anthropology","Women's and Gender Studies"],"areas":["Humanities","Social Sciences"],"topics":["African American Studies","Anthropology","Ethics","Gender Studies","Humanities","Philosophy","Social Science","Society"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2013","instructors":["Prof. Erica James"],"url":"https://ocw.mit.edu/courses/21a-302j-dilemmas-in-bio-medical-ethics-playing-god-or-doing-good-fall-2013/","views":1258},{"id":"PE.710+spring_2007","numbers":["PE.710"],"title":"Tennis","summary":"The goals of this instructional course are to get you started in this wonderful sport and to give you a working knowledge of tennis. It should help you to understand the basics of a sport and how to perform these basics. Most of the course will focus on the basic stroke techniques. Variation to those techniques will be presented, as well as drills and games, so that you can take it to the court. Singles and doubles tactics will be covered as well.","departments":["Athletics, Physical Education and Recreation"],"areas":["Health & Medicine"],"topics":["Health and Medicine","Physical Education and Recreation"],"levels":["Undergraduate"],"features":["Demonstration Videos","Image Gallery"],"term":"Spring 2007","instructors":["Prof. Carol Matsuzaki"],"url":"https://ocw.mit.edu/courses/pe-710-tennis-spring-2007/","views":1258},{"id":"21G.035+fall_2003","numbers":["21G.035","21G.037"],"title":"Topics in Culture and Globalization","summary":"The concept of globalization fosters the understanding of the interconnectedness of cultures and societies geographically wide apart; America, Europe, Asia, and Africa. Subject scans existing debates over globalization around the world. This course explores how globalization impacts everyday life in the First and Third World; how globalization leads to a common cosmopolitan culture; the emergence of a global youth culture; and religious, social, and political movements that challenge globalization. Materials examined include pop music, advertisements, film posters, and political cartoons.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Business & Management","Social Sciences"],"topics":["Anthropology","Business","Cultural Anthropology","Fine Arts","Globalization","Media Studies","Social Science"],"levels":["Undergraduate","Graduate"],"features":["Lecture Notes","Presentation Assignments","Written Assignments"],"term":"Fall 2003","instructors":["Prof. Ian Condry"],"url":"https://ocw.mit.edu/courses/21g-035-topics-in-culture-and-globalization-fall-2003/","views":1258},{"id":"21G.040+spring_2012","numbers":["21G.040"],"title":"A Passage to India: Introduction to Modern Indian Culture and Society","summary":"This course is an introduction to modern Indian culture and society through films, documentaries, short stories, novels, poems, and journalistic writing. The principal focus is on the study of major cultural developments and social debates in the last sixty five years of history through the reading of literature and viewing of film clips. The focus will be on the transformations of gender and class issues, representation of nationhood, the idea of regional identities and the place of the city in individual and communal lives. The cultural and historical background will be provided in class lectures. The idea is to explore the “other Indias” that lurk behind our constructed notion of a homogeneous national culture.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Asian Studies","Cultural Anthropology","Fine Arts","Humanities","International Literature","Literature","Media Studies","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2012","instructors":["Prof. Sunil H. Sharma"],"url":"https://ocw.mit.edu/courses/21g-040-a-passage-to-india-introduction-to-modern-indian-culture-and-society-spring-2012/","views":1257},{"id":"12.570+spring_2005","numbers":["12.570"],"title":"Seminar in Geophysics: Thermal and Chemical Evolution of the Earth","summary":"The main objective of this cross-disciplinary course is to understand the historical development and the current status of ideas and models, to present and question the constraints from the different research fields, and to investigate if and how the different views on mantle flow can be reconciled with the currently available data.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geochemistry","Geology","Geophysics","Physics","Science","Thermodynamics"],"levels":["Graduate"],"features":["Lecture Notes","Presentation Assignments with Examples"],"term":"Spring 2005","instructors":["Prof. Robert Van Der Hilst"],"url":"https://ocw.mit.edu/courses/12-570-seminar-in-geophysics-thermal-and-chemical-evolution-of-the-earth-spring-2005/","views":1257},{"id":"11.208+january-iap_2002","numbers":["11.208"],"title":"Introduction to Computers in Public Management II","summary":"Second of two modules facilitating a basic understanding of computing in planning and public management. Students develop problem-solving skills using computer-based tools for “what-if” analyses. Emphasis on spatial analysis using geographic information systems and database query tools.","departments":["Urban Studies and Planning"],"areas":["Business & Management","Engineering","Social Sciences"],"topics":["Business","Computational Modeling and Simulation","Engineering","Information Technology","Public Administration","Social Science","Systems Engineering","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"January IAP 2002","instructors":["Prof. Joseph Ferreira","Prof. Lorlene Hoyt","Thomas Grayson"],"url":"https://ocw.mit.edu/courses/11-208-introduction-to-computers-in-public-management-ii-january-iap-2002/","views":1255},{"id":"18.712+fall_2010","numbers":["18.712"],"title":"Introduction to Representation Theory","summary":"The goal of this course is to give an undergraduate-level introduction to representation theory (of groups, Lie algebras, and associative algebras). Representation theory is an area of mathematics which, roughly speaking, studies symmetry in linear spaces.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Linear Algebra","Mathematics"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2010","instructors":["Prof. Pavel Etingof"],"url":"https://ocw.mit.edu/courses/18-712-introduction-to-representation-theory-fall-2010/","views":1255},{"id":"3.23+fall_2007","numbers":["3.23"],"title":"Electrical, Optical, and Magnetic Properties of Materials","summary":"This class discusses the origin of electrical, magnetic and optical properties of materials, with a focus on the acquisition of quantum mechanical tools. It begins with an analysis of the properties of materials, presentation of the postulates of quantum mechanics, and close examination of the hydrogen atom, simple molecules and bonds, and the behavior of electrons in solids and energy bands. Introducing the variation principle as a method for the calculation of wavefunctions, the course continues with investigation of how and why materials respond to different electrical, magnetic and electromagnetic fields and probes and study of the conductivity, dielectric function, and magnetic permeability in metals, semiconductors, and insulators. A survey of common devices such as transistors, magnetic storage media, optical fibers concludes the semester.\n\nNote: The Magnetics unit was taught by co-instructor David Paul; that material is not available at this time.","departments":["Materials Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Atomic, Molecular, Optical Physics","Electromagnetism","Engineering","Materials Science and Engineering","Physics","Quantum Mechanics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2007","instructors":["Prof. David Paul","Prof. Nicola Marzari"],"url":"https://ocw.mit.edu/courses/3-23-electrical-optical-and-magnetic-properties-of-materials-fall-2007/","views":1254},{"id":"RES.TLL-010+spring_2025","numbers":["RES.TLL-010"],"title":"Syllabus Checklist to Support Student Belonging & Achievement","summary":"The syllabus informs students’ first impressions of a class, the instructor, and their evaluation of whether they will succeed. Given the important role of the syllabus for students and for instructors’ intentional design of the course, this syllabus checklist is a tool to guide instructors in their construction and revision of course design, assessment descriptions, teaching practices, and policies in their syllabi. Many of the checklist items also apply beyond the syllabus to other communication channels in the course (e.g., Learning Management Systems, course wikis, classroom conversations).\n\nThe checklist is adapted from a comprehensive and detailed rubric developed by members of MIT’s Teaching + Learning Lab.","departments":[],"areas":["Education & Teaching"],"topics":["Curriculum and Teaching","Teaching and Education"],"levels":["Non-Credit"],"features":["Activity Assignments"],"term":"Spring 2025","instructors":["Dr. Ruthann Thomas"],"url":"https://ocw.mit.edu/courses/res-tll-010-syllabus-checklist-to-support-student-belonging-achievement-spring-2025/","views":1253},{"id":"ES.255+spring_2006","numbers":["ES.255"],"title":"Physics of Rock Climbing","summary":"SP.255 is a lecture, discussion, and project based seminar about the physics of rock climbing. Participants are first exposed to the unsolved problems in the climbing community that could be answered by research and then asked to solve a small part of one of these problems. The seminar provides an introduction to engineering problems, an opportunity to practice communication skills, and a brief stab at doing some research. This seminar explicitly does not include climbing instruction nor is climbing/mountaineering experience a prerequisite.","departments":["Experimental Study Group"],"areas":["Engineering","Science & Math"],"topics":["Engineering","Mechanical Engineering","Physics","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Spring 2006","instructors":["David Custer"],"url":"https://ocw.mit.edu/courses/es-255-physics-of-rock-climbing-spring-2006/","views":1252},{"id":"21H.342+fall_2003","numbers":["21H.342"],"title":"The Royal Family","summary":"This course is an an exploration of British culture and politics, focusing on the changing role of the monarchy from the accession of the House of Hanover (later Windsor) in 1714 to the present. The dynasty has encountered a series of crises, in which the personal and the political have been inextricably combined: for example, George III’s mental illness; the scandalous behavior of his son, George IV; Victoria’s withdrawal from public life after the death of Prince Albert; the abdication of Edward VIII; and the public antagonism sparked by sympathy for Diana, Princess of Wales.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","European History","European and Russian Studies","History","Humanities","Political Science","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2003","instructors":["Prof. Harriet Ritvo"],"url":"https://ocw.mit.edu/courses/21h-342-the-royal-family-fall-2003/","views":1246},{"id":"8.08+spring_2005","numbers":["8.08"],"title":"Statistical Physics II","summary":"This course covers probability distributions for classical and quantum systems. Topics include: Microcanonical, canonical, and grand canonical partition-functions and associated thermodynamic potentials. Also discussed are conditions of thermodynamic equilibrium for homogenous and heterogenous systems.\n\nThe course follows 8.044, Statistical Physics I, and is second in this series of undergraduate Statistical Physics courses.","departments":["Physics"],"areas":["Science & Math"],"topics":["Classical Mechanics","Mathematics","Physics","Probability and Statistics","Quantum Mechanics","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2005","instructors":["Prof. Xiao-Gang Wen"],"url":"https://ocw.mit.edu/courses/8-08-statistical-physics-ii-spring-2005/","views":1245},{"id":"21G.010+fall_2006","numbers":["21G.010"],"title":"Introduction to European and Latin American Fiction","summary":"This subject serves as a broad introduction to the field of European and Latin American fiction. It is taught in an historical manner—beginning with the first picaresque novel, Lazarillo de Tormes, and ending with contemporary European fiction. It is designed to help students acquire a general understanding of major fictional modes-from 18th century epistolary fiction, Liaisons dangereuses, to 20th century avant-garde fiction: Cosmicomicsi and Aura. Attention is paid not only to the literary movements these works represent, but also to the subtle interplay of history, geography, language and cultural norms that gave rise to specific literary forms. While the reading load is heavy, the books are compelling.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Fiction","Humanities","International Literature","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2006","instructors":["Prof. Margery Resnick"],"url":"https://ocw.mit.edu/courses/21g-010-introduction-to-european-and-latin-american-fiction-fall-2006/","views":1243},{"id":"6.881+spring_2016","numbers":["6.881"],"title":"Computational Personal Genomics: Making Sense of Complete Genomes","summary":"With the growing availability and lowering costs of genotyping and personal genome sequencing, the focus has shifted from the ability to obtain the sequence to the ability to make sense of the resulting information. This course is aimed at exploring the computational challenges associated with interpreting how sequence differences between individuals lead to phenotypic differences in gene expression, disease predisposition, or response to treatment.","departments":["Electrical Engineering and Computer Science"],"areas":["Science & Math"],"topics":["Biology","Computation and Systems Biology","Genetics","Science"],"levels":["Graduate"],"features":["Laboratory Assignments"],"term":"Spring 2016","instructors":["Prof. Manolis Kellis"],"url":"https://ocw.mit.edu/courses/6-881-computational-personal-genomics-making-sense-of-complete-genomes-spring-2016/","views":1240},{"id":"21W.777+spring_2017","numbers":["21W.777"],"title":"Science Writing in Contemporary Society","summary":"This class addresses the craft of writing about science in and for contemporary society, both its pleasures and its challenges. We will read essays, reportage, op-eds, and web-based articles on a variety of topics concerning science, technology, medicine and nature. Readings by contemporary writers such as Elizabeth Kolbert, Atul Gawande, and Michael Pollan will serve as examples of the craft and sources of ideas for our own writing.","departments":["Comparative Media Studies/Writing"],"areas":["Humanities"],"topics":["Academic Writing","Creative Writing","Criticism","Humanities","Literature","Nonfiction Prose"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2017","instructors":["Karen Boiko"],"url":"https://ocw.mit.edu/courses/21w-777-science-writing-in-contemporary-society-spring-2017/","views":1240},{"id":"2.000+spring_2002","numbers":["2.000"],"title":"How and Why Machines Work","summary":"Subject studies how and why machines work, how they are conceived, how they are developed (drawn), and how they are utilized. Students learn from the hands-on experiences of taking things apart mentally and physically, drawing (sketching, 3D CAD) what they envision and observe, taking occasional field trips, and completing an individual term project (concept, creation, and presentation). Emphasis on understanding the physics and history of machines.","departments":["Mechanical Engineering"],"areas":["Engineering"],"topics":["Engineering","Mechanical Design","Mechanical Engineering"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2002","instructors":["Prof. Joseph Smith","Prof. Martin Culpepper"],"url":"https://ocw.mit.edu/courses/2-000-how-and-why-machines-work-spring-2002/","views":1239},{"id":"RES.8-009+summer_2017","numbers":["RES.8-009"],"title":"Introduction to Oscillations and Waves","summary":"Introduction to Oscillations and Waves covers the basic mathematics and physics of oscillatory and wave phenomena. By the end of the course, students should be able to explain why oscillations appear in many near equilibrium systems, the various mathematical properties of those oscillations in various contexts, how oscillations and waves are related, and the basic mathematical description and properties of a wave.\n\nThis course was offered as part of MITES Summer, a six-week, residential STEM experience for rising high school seniors. MIT Introduction to Technology, Engineering, and Science (MITES) provides transformative experiences that bolster confidence, create lifelong community, and build an exciting, challenging foundation in STEM for highly motivated 7th–12th grade students from diverse and underrepresented backgrounds.","departments":["Physics"],"areas":["Science & Math"],"topics":["Atomic, Molecular, Optical Physics","Classical Mechanics","Electromagnetism","Physics","Science"],"levels":["High School"],"features":["Exam Solutions","Exams","Instructor Insights","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Summer 2017","instructors":["Dr. Mobolaji Williams"],"url":"https://ocw.mit.edu/courses/res-8-009-introduction-to-oscillations-and-waves-summer-2017/","views":1238},{"id":"7.16+spring_2005","numbers":["7.16"],"title":"Experimental Molecular Biology: Biotechnology II","summary":"The course applies molecular biology and reverse genetics approaches to the study of apoptosis, or programmed cell death (PCD), in Drosophila cells. RNA interference (RNAi), or double stranded RNA-mediated gene silencing, will be used to inhibit expression of candidate apoptosis-related genes in cultured Drosophila cells. Teams of 2 or 3 students will design and carry out experiments to address questions about the genes involved in the regulation and execution of PCD in this system. Some projects involve the use of DNA damaging agents or other cytotoxic chemicals or drugs to help understand the pathways that control a cell’s decision to undergo apoptosis. Instruction and practice in written and oral communication are provided.","departments":["Biology"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Biotechnology","Engineering","Molecular Biology","Science"],"levels":["Undergraduate"],"features":["Demonstration Videos","Written Assignments with Examples"],"term":"Spring 2005","instructors":["Prof. Christopher Burge","Prof. David Sabatini","Dr. Marilee Ogren-Balkema","Dr. Alice Rushforth"],"url":"https://ocw.mit.edu/courses/7-16-experimental-molecular-biology-biotechnology-ii-spring-2005/","views":1236},{"id":"21H.112+spring_2006","numbers":["21H.112"],"title":"The American Revolution","summary":"This course is concerned primarily with the revolutionary origins of American government. Topics covered include: English and American backgrounds of the Revolution; issues and arguments in the Anglo-American conflict; colonial resistance and the beginnings of republicanism; the Revolutionary War; constitution writing for the states and nation; and effects of the American Revolution. Readings emphasize documents from the period–pamphlets, correspondence, the minutes or resolutions of resistance organizations, constitutional documents and debates.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["American History","American Politics","History","Humanities","Philosophy","Political Philosophy","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2006","instructors":["Prof. Pauline Maier"],"url":"https://ocw.mit.edu/courses/21h-112-the-american-revolution-spring-2006/","views":1235},{"id":"6.827+fall_2002","numbers":["6.827"],"title":"Multithreaded Parallelism: Languages and Compilers","summary":"The topics covered in this course include:\n\n• Languages and compilers to exploit multithreaded parallelism\n• Implicit parallel programming using functional languages and their extensions\n• Higher-order functions, non-strictness, and polymorphism\n• Explicit parallel programming and nondeterminism\n• The lambda calculus and its variants\n• Term rewriting and operational semantics\n• Compiling multithreaded code for symmetric multiprocessors and clusters\n• Static analysis and compiler optimizations\n\nThis course is worth 4 Engineering Design Points.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Engineering","Programming Languages","Software Design and Engineering","Theory of Computation"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Programming Assignments","Projects"],"term":"Fall 2002","instructors":["Prof. Arvind"],"url":"https://ocw.mit.edu/courses/6-827-multithreaded-parallelism-languages-and-compilers-fall-2002/","views":1234},{"id":"9.56J+fall_2004","numbers":["9.56J","24.907J"],"title":"Abnormal Language","summary":"Introduction to the linguistic study of language pathology, concentrating on experimental approaches and theoretical explanations. Discussion of Specific Language Impairment, autism, Down syndrome, Williams syndrome, normal aging, Parkinson’s disease, Alzheimer’s disease, hemispherectomy and aphasia. Focuses on the comparison of linguistic abilities among these syndromes, while drawing clear comparisons with first and second language acquisition. Topics include the lexicon, morphology, syntax, semantics and pragmatics. Relates the lost linguistic abilities in these syndromes to properties of the brain.","departments":["Brain and Cognitive Sciences","Linguistics and Philosophy"],"areas":["Health & Medicine","Humanities","Science & Math"],"topics":["Cognitive Science","Health and Medicine","Humanities","Linguistics","Science","Speech Pathology"],"levels":["Undergraduate"],"features":["Problem Sets","Written Assignments"],"term":"Fall 2004","instructors":["Mr. Christopher Hirsch","Prof. Ken Wexler"],"url":"https://ocw.mit.edu/courses/9-56j-abnormal-language-fall-2004/","views":1233},{"id":"21G.820+fall_2014","numbers":["21G.820"],"title":"Portuguese Advanced Conversation and Composition","summary":"This is an advanced course that aims to build vocabulary competence and improve oral communication through the study and discussion of topics related to cultural aspects in Lusophone societies, primarily from current issues in Brazil. It is designed to give students extensive experience in Portuguese and emphasizes skill development and refinement in the area of critical reading and writing in Portuguese.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["European and Russian Studies","Humanities","Language","Latin and Caribbean Studies","Portuguese","Society"],"levels":["Undergraduate"],"features":["Instructor Insights","Presentation Assignments","Problem Sets","Written Assignments"],"term":"Fall 2014","instructors":["Dr. Nilma Dominique"],"url":"https://ocw.mit.edu/courses/21g-820-portuguese-advanced-conversation-and-composition-fall-2014/","views":1231},{"id":"12.103+spring_2010","numbers":["12.103"],"title":"Science and Policy of Natural Hazards","summary":"This course examines the science of natural catastrophes such as earthquakes and hurricanes and explores the relationships between the science of and policy toward such hazards. It presents the causes and effects of these phenomena, discusses their predictability, and examines how this knowledge influences policy making. This course includes intensive practice in the writing and presentation of scientific research and summaries for policy makers.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Energy, Climate & Sustainability","Science & Math","Social Sciences"],"topics":["Atmospheric Science","Earth Science","Environmental Policy","Environmental Science","Public Administration","Science","Science and Technology Policy","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2010","instructors":["Prof. Kerry Emanuel","Prof. Stephane Rondenay","Jane Connor"],"url":"https://ocw.mit.edu/courses/12-103-science-and-policy-of-natural-hazards-spring-2010/","views":1231},{"id":"4.196+spring_2004","numbers":["4.196","4.132"],"title":"Architecture Design, Level II: Cuba Studio","summary":"This architectural studio will have one main project for the semester: to explore the issues surrounding the redesign of an area in Havana, Cuba. It is a typical area about the size of a Law of Indies block that presently has a mix of housing, work, and shopping, in buildings that need to be replaced and others that need to be rehabilitated. There is also vacant land, and buildings that are unused. Part of the blocks front on the Malecon, the street next to the water. The other edge fronts onto a typical neighborhood. The intention is to study the culture through an understanding of one area of Havana and then design an “echo” in architectural form. The design will include public space as well as a mix of buildings: some new, some rehabilitated.","departments":["Architecture"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Anthropology","Architectural Design","Architecture","Cultural Anthropology","Environmental Design","Fine Arts","Social Science"],"levels":["Graduate"],"features":["Image Gallery","Video Materials"],"term":"Spring 2004","instructors":["Prof. Jan Wampler"],"url":"https://ocw.mit.edu/courses/4-196-architecture-design-level-ii-cuba-studio-spring-2004/","views":1230},{"id":"9.93+january-iap_2007","numbers":["9.93"],"title":"Marathon Moral Reasoning Laboratory","summary":"This seminar focuses on the cognitive science of moral reasoning. Philosophers debate how we decide which moral actions are permissible. Is it permissible to take one human life in order to save others? We have powerful and surprisingly rich and subtle intuitions to such questions.\n\nIn this class, you will learn how intuitions can be studied using formal analytical paradigms and behavioral experiments. Thursday evening, meet to learn about recent advances in theories of moral reasoning. Overnight, formulate a hypothesis about the structure of moral reasoning and design a questionnaire-based experiment to test this. Friday, present and select 1-2 proposals and collect data; we will then reconvene to analyze and discuss results and implications for the structure of the moral mind.\n\nThis course is offered during the Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month.","departments":["Brain and Cognitive Sciences"],"areas":["Humanities","Science & Math","Social Sciences"],"topics":["Cognitive Science","Ethics","Humanities","Philosophy","Psychology","Science","Social Science"],"levels":["Undergraduate"],"features":[],"term":"January IAP 2007","instructors":["Prof. John Mikhail","Prof. Joshua Tenenbaum","Prof. Rebecca Saxe"],"url":"https://ocw.mit.edu/courses/9-93-marathon-moral-reasoning-laboratory-january-iap-2007/","views":1230},{"id":"ESD.342+spring_2010","numbers":["ESD.342"],"title":"Network Representations of Complex Engineering Systems","summary":"This course provides a deep understanding of engineering systems at a level intended for research on complex engineering systems. It provides a review and extension of what is known about system architecture and complexity from a theoretical point of view while examining the origins of and recent developments in the field. The class considers how and where the theory has been applied, and uses key analytical methods proposed. Students examine the level of observational (qualitative and quantitative) understanding necessary for successful use of the theoretical framework for a specific engineering system. Case studies apply the theory and principles to engineering systems.","departments":["Engineering Systems Division"],"areas":["Engineering"],"topics":["Computational Modeling and Simulation","Engineering","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Projects"],"term":"Spring 2010","instructors":["Dr. Christopher L. Magee","Dr. Daniel E. Whitney","Prof. Joel Moses"],"url":"https://ocw.mit.edu/courses/esd-342-network-representations-of-complex-engineering-systems-spring-2010/","views":1229},{"id":"21H.952J+fall_2003","numbers":["21H.952J","STS.410J"],"title":"Readings in American History Since 1877","summary":"This seminar aims to develop a teaching knowledge of the field through extensive reading and discussion of major works. The reading covers a broad range of topics - political, economic, social, and cultural - and represents a variety of historical methods.","departments":["History","Science, Technology, and Society"],"areas":["Humanities"],"topics":["American History","Comparative History","Historical Methods","History","Humanities","Modern History"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2003","instructors":["Prof. Meg Jacobs"],"url":"https://ocw.mit.edu/courses/21h-952j-readings-in-american-history-since-1877-fall-2003/","views":1228},{"id":"9.52-B+spring_2001","numbers":["9.52-B"],"title":"Topics in Brain and Cognitive Sciences Human Ethology","summary":"Survey and special topics designed for students in Brain and Cognitive Sciences. Emphasizes ethological studies of natural behavior patterns and their analysis in laboratory work, with contributions from field biology (mammology, primatology), sociobiology, and comparative psychology. Stresses human behavior but also includes major contributions from studies of other animals.","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math","Social Sciences"],"topics":["Cognitive Science","Psychology","Science","Social Science"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Spring 2001","instructors":["Prof. Gerald E. Schneider"],"url":"https://ocw.mit.edu/courses/9-52-b-topics-in-brain-and-cognitive-sciences-human-ethology-spring-2001/","views":1228},{"id":"21W.015+fall_2013","numbers":["21W.015"],"title":"Writing and Rhetoric: Writing about Sports","summary":"“Sports, not religion, is the opiate of the people.” So says David Remnick, editor of the New Yorker and a former sportswriter. Many of our heroes are sports heroes, and for many of us, sports were an important part of our childhood years. Sports are big business, even on college campuses, and they are the subject of many classic movies. In this introductory writing class we consider the role of sports in our own lives and explore the cultural meanings of sports in America. Sports have produced a large body of excellent descriptive and analytic writing; we’ll read writers as diverse as Hank Aaron, John Updike, David Foster Wallace, and Malcolm Gladwell on the joys and conundrums of baseball, boxing, football, tennis, and running.\n\nThe primary work of the class is improving students’ communication skills. We’ll write and revise 3 essays, including an investigative essay, and we’ll also give one short oral report. Revision is an important part of the class; all essays will be revised at least once.","departments":["Comparative Media Studies/Writing"],"areas":["Humanities"],"topics":["Humanities","Literature","Nonfiction Prose","Periodic Literature","Rhetoric"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments"],"term":"Fall 2013","instructors":["Karen Boiko"],"url":"https://ocw.mit.edu/courses/21w-015-writing-and-rhetoric-writing-about-sports-fall-2013/","views":1226},{"id":"21A.470J+spring_2010","numbers":["21A.470J","WGS.274J"],"title":"Gender and Representation of Asian Women","summary":"This course explores stereotypes associated with Asian women in colonial, nationalist, state-authoritarian, and global/diasporic narratives about gender and power. Students will read ethnography, cultural studies, and history, and view films to examine the politics and circumstances that create and perpetuate the representation of Asian women as dragon ladies, lotus blossoms, despotic tyrants, desexualized servants, and docile subordinates. Students are introduced to the debates about Orientalism, gender, and power.","departments":["Anthropology","Women's and Gender Studies"],"areas":["Social Sciences"],"topics":["Anthropology","Asian Studies","Cultural Anthropology","Ethnography","Gender Studies","Social Science","Society","Women's Studies"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2010","instructors":["Prof. Manduhai Buyandelger"],"url":"https://ocw.mit.edu/courses/21a-470j-gender-and-representation-of-asian-women-spring-2010/","views":1225},{"id":"17.581+spring_2013","numbers":["17.581"],"title":"Riots, Rebellions, Revolutions","summary":"This course examines different types of violent political conflict. It compares and contrasts several social science approaches (psychological, sociological, and political) and analyzes their ability to explain variation in outbreak, duration and outcome of conflict. Incidents such as riots in the U.S. during the 1960’s, riots in India, the Yugoslav wars, and the Russian Revolution, as well as current international events are discussed.","departments":["Political Science"],"areas":["Humanities","Social Sciences"],"topics":["History","Humanities","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Exams","Problem Sets"],"term":"Spring 2013","instructors":["Prof. Roger Petersen"],"url":"https://ocw.mit.edu/courses/17-581-riots-rebellions-revolutions-spring-2013/","views":1225},{"id":"12.820+spring_2006","numbers":["12.820","12.822"],"title":"Turbulence in the Ocean and Atmosphere","summary":"This course presents the phenomena, theory, and modeling of turbulence in the Earth’s oceans and atmosphere. The scope ranges from centimeter to planetary scale motions. The regimes of turbulence include homogeneous isotropic three dimensional turbulence, convection, boundary layer turbulence, internal waves, two dimensional turbulence, quasi-geostrophic turbulence, and macrotrubulence in the ocean and atmosphere.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Atmospheric Science","Earth Science","Engineering","Fluid Mechanics","Hydrodynamics","Mechanical Engineering","Ocean Engineering","Oceanography","Planetary Science","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2006","instructors":["Prof. Glenn Flierl","Prof. Raffaele Ferrari"],"url":"https://ocw.mit.edu/courses/12-820-turbulence-in-the-ocean-and-atmosphere-spring-2006/","views":1224},{"id":"21L.463+fall_2008","numbers":["21L.463"],"title":"Renaissance Literature","summary":"The Renaissance has justly become both famous and notorious as an age of discovery, and its voyages took place in many realms. This semester, we will read several history making narratives of early modern travel: first-hand accounts of discovery, captivity, conquest, or cultural encounter. As Europeans came to acquire experience of unfamiliar places, literary texts of the period began to assimilate this experience by describing imagined voyages across real or fantastic landscapes. Finally, voyages of exploration served Renaissance writers as a metaphor: for intellectual inquiry, for spiritual development, or for the pursuit of love. Among the literary genres sampled this semester will be sonnets, plays, prose narratives, utopias, and chivalric romance. Authors and travellers will include Francis Petrarch, Amerigo Vespucci, Thomas More, Christopher Marlowe, Edmund Spenser, Hernán Cortés, John Donne, Francis Drake, Mary Rowlandson, Francis Bacon.","departments":["Literature"],"areas":["Humanities"],"topics":["History","Humanities","Intellectual History","Literature"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2008","instructors":["Prof. Mary Fuller"],"url":"https://ocw.mit.edu/courses/21l-463-renaissance-literature-fall-2008/","views":1222},{"id":"22.616+fall_2003","numbers":["22.616"],"title":"Plasma Transport Theory","summary":"This course describes the processes by which mass, momentum, and energy are transported in plasmas, with special reference to magnetic confinement fusion applications.\n\nThe Fokker-Planck collision operator and its limiting forms, as well as collisional relaxation and equilibrium, are considered in detail. Special applications include a Lorentz gas, Brownian motion, alpha particles, and runaway electrons.\n\nThe Braginskii formulation of classical collisional transport in general geometry based on the Fokker-Planck equation is presented.\n\nNeoclassical transport in tokamaks, which is sensitive to the details of the magnetic geometry, is considered in the high (Pfirsch-Schluter), low (banana) and intermediate (plateau) regimes of collisionality.","departments":["Nuclear Science and Engineering"],"areas":["Engineering","Science & Math"],"topics":["Chemical Engineering","Chemistry","Engineering","High Energy Physics","Nuclear Physics","Physical Chemistry","Physics","Science","Transport Processes"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Lecture Notes","Problem Sets"],"term":"Fall 2003","instructors":["Prof. Kim Molvig"],"url":"https://ocw.mit.edu/courses/22-616-plasma-transport-theory-fall-2003/","views":1221},{"id":"21T.424+spring_2018","numbers":["21T.424"],"title":"Topics in Performance Studies: Comedy Across Media","summary":"This multidisciplinary lecture / workshop engages students in a variety of approaches to the study and practice of performance as an area of aesthetic and social interaction. Special attention is paid to the use of diverse media in performance. Interdisciplinary approaches to study encourage students to seek out material histories of performance and practice.","departments":["Theater Arts"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Comedy","Digital Media","Fine Arts","Humanities","Literature","Media Studies","Performance Arts","Theater"],"levels":["Undergraduate"],"features":[],"term":"Spring 2018","instructors":["James Stanley"],"url":"https://ocw.mit.edu/courses/21m-846-topics-in-performance-studies-comedy-across-media-spring-2018/","views":1220},{"id":"CC.S10+fall_2011","numbers":["CC.S10"],"title":"History and Philosophy of Mechanics: Newton's Principia Mathematica","summary":"This course focuses on an in-depth reading of Principia Mathematica Philosophiae Naturalis by Isaac Newton, as well as several related commentaries and historical philosophical texts.","departments":["Concourse"],"areas":["Humanities"],"topics":["History","History of Science and Technology","Humanities","Intellectual History","Philosophy"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2011","instructors":["Adam Schulman"],"url":"https://ocw.mit.edu/courses/cc-s10-history-and-philosophy-of-mechanics-newtons-principia-mathematica-fall-2011/","views":1219},{"id":"9.71+fall_2007","numbers":["9.71"],"title":"Functional MRI of High-Level Vision","summary":"We are now at an unprecedented point in the field of neuroscience: We can watch the human brain in action as it sees, thinks, decides, reads, and remembers. Functional magnetic resonance imaging (fMRI) is the only method that enables us to monitor local neural activity in the normal human brain in a noninvasive fashion and with good spatial resolution. A large number of far-reaching and fundamental questions about the human mind and brain can now be answered using straightforward applications of this technology. This is particularly true in the area of high-level vision, the study of how we interpret and use visual information including object recognition, mental imagery, visual attention, perceptual awareness, visually guided action, and visual memory.\n\nThe goals of this course are to help students become savvy and critical readers of the current neuroimaging literature, to understand the strengths and weaknesses of the technique, and to design their own cutting-edge, theoretically motivated studies. Students will read, present to the class, and critique recently published neuroimaging articles, as well as write detailed proposals for experiments of their own. Lectures will cover the theoretical background on some of the major areas in high-level vision, as well as an overview of what fMRI has taught us and can in future teach us about each of these topics. Lectures and discussions will also cover fMRI methods and experimental design. A prior course in statistics and at least one course in perception or cognition are required.","departments":["Brain and Cognitive Sciences"],"areas":["Health & Medicine","Science & Math"],"topics":["Biology","Biomedical Instrumentation","Biomedical Signal and Image Processing","Health and Medicine","Medical Imaging","Neuroscience","Science"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments with Examples"],"term":"Fall 2007","instructors":["Prof. Nancy Kanwisher"],"url":"https://ocw.mit.edu/courses/9-71-functional-mri-of-high-level-vision-fall-2007/","views":1218},{"id":"18.755+spring_2024","numbers":["18.755"],"title":"Lie Groups and Lie Algebras II","summary":"This course is the second half of the year-long introductory graduate sequence Lie Groups and Lie Algebras I & Lie Groups and Lie Algebras II. Topics include classical groups, Haar measure on locally compact groups, the representation-theoretic understanding of the hydrogen atom, representations of compact (in particular, finite) groups, the Peter-Weyl theorem with proof, maximal tori, Cartan and Iwasawa decompositions, classification of real reductive Lie groups, topology of Lie groups, proof of the third fundamental theorem of Lie theory, Levi decomposition, Ado’s theorem, Borel subgroups, and flag manifolds.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes","Open Textbooks","Problem Sets"],"term":"Spring 2024","instructors":["Prof. Pavel Etingof"],"url":"https://ocw.mit.edu/courses/18-755-lie-groups-and-lie-algebras-ii-spring-2024/","views":1216},{"id":"18.965+fall_2004","numbers":["18.965"],"title":"Geometry of Manifolds","summary":"Geometry of Manifolds analyzes topics such as the differentiable manifolds and vector fields and forms. It also makes an introduction to Lie groups, the de Rham theorem, and Riemannian manifolds.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Differential Equations","Linear Algebra","Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Tomasz Mrowka"],"url":"https://ocw.mit.edu/courses/18-965-geometry-of-manifolds-fall-2004/","views":1215},{"id":"16.459+fall_2011","numbers":["16.459"],"title":"Bioengineering Journal Article Seminar","summary":"Each term, the class selects a new set of professional journal articles on bioengineering topics of current research interest. Some papers are chosen because of particular content, others are selected because they illustrate important points of methodology. Each week, one student leads the discussion, evaluating the strengths, weaknesses, and importance of each paper. Subject may be repeated for credit a maximum of four terms. Letter grade given in the last term applies to all accumulated units of 16.459.","departments":["Aeronautics and Astronautics"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Aerospace Engineering","Bioastronautics","Computer Science","Engineering","Human-Computer Interfaces"],"levels":["Graduate"],"features":["Activity Assignments","Presentation Assignments"],"term":"Fall 2011","instructors":["Dr. Charles M. Oman","Dr. Laurence R. Young","Dr. Alan Natapoff"],"url":"https://ocw.mit.edu/courses/16-459-bioengineering-journal-article-seminar-fall-2011/","views":1213},{"id":"11.364+fall_2010","numbers":["11.364"],"title":"International Environmental Negotiation","summary":"This seminar will explore the difficulties of getting agreement on global definitions of sustainability; in particularly building international support for efforts to combat climate change created by greenhouse gas emissions as well as other international resource management efforts. We will focus on possible changes in the way global environmental agreements are formulated and implemented, especially on ways of shifting from the current “pollution control” approach to combating climate change to a more comprehensive strategy for taking advantage of sustainable development opportunities.","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math","Social Sciences"],"topics":["Earth Science","Engineering","Environmental Engineering","Environmental Management","Environmental Policy","International Relations","Political Science","Public Administration","Science","Social Science","Sustainability","Urban Studies"],"levels":["Graduate"],"features":["Activity Assignments","Presentation Assignments","Written Assignments"],"term":"Fall 2010","instructors":["Prof. William Moomaw","Prof. Lawrence Susskind"],"url":"https://ocw.mit.edu/courses/11-364-international-environmental-negotiation-fall-2010/","views":1212},{"id":"21G.312+spring_2011","numbers":["21G.312"],"title":"Basic Themes in French Literature and Culture","summary":"Childhood is a source of fascination in most Western cultures. It is both a major inspiration for artistic creation and a political ideal, which aims at protecting future generations. Which role does it play in French society and in other francophone areas? Why is the French national anthem (“La Marseillaise”) addressed to its “children”? This course will study the transformation of childhood since the 18th century and the development of sentimentality within the family. We will examine various representations of childhood in literature (e.g. Pagnol, Proust, Sarraute, Laye, Morgièvre), movies (e.g. Truffaut), and songs (e.g. Brel, Barbara). Course taught in French.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","French","Humanities","International Literature","Language","Literature","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2011","instructors":["Prof. Bruno Perreau"],"url":"https://ocw.mit.edu/courses/21g-312-basic-themes-in-french-literature-and-culture-spring-2011/","views":1211},{"id":"11.363+spring_2005","numbers":["11.363"],"title":"Civil Society and the Environment","summary":"This graduate seminar examines civic engagement in international, national and local environmental governance. We will consider theories pertaining to civil society development, social movement mobilization, and the relations that nongovernmental organizations (NGOs) have with governments and corporations. During the course of the semester, particular attention will be given to the legitimacy and accountability of NGOs. Case studies of NGO and community responses to specific environmental issues will be used to illustrate theoretical issues and assess the impacts that these actors have on environmental policy and planning.","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Engineering","Social Sciences"],"topics":["Engineering","Environmental Engineering","Environmental Management","Environmental Policy","International Relations","Political Science","Public Administration","Public Policy","Social Science"],"levels":["Graduate"],"features":["Projects","Written Assignments with Examples"],"term":"Spring 2005","instructors":["Prof. JoAnn Carmin"],"url":"https://ocw.mit.edu/courses/11-363-civil-society-and-the-environment-spring-2005/","views":1211},{"id":"12.524+fall_2005","numbers":["12.524"],"title":"Mechanical Properties of Rocks","summary":"12.524 is a survey of the mechanical behavior of rocks in natural geologic situations. Topics will include a brief survey of field evidence of rock deformation, physics of plastic deformation in minerals, brittle fracture and sliding, and pressure-solution processes. We will compare results of field petrologic and structural studies to data from experimental structural geology.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geology","Geophysics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2005","instructors":["Prof. J. Evans"],"url":"https://ocw.mit.edu/courses/12-524-mechanical-properties-of-rocks-fall-2005/","views":1211},{"id":"4.665+spring_2002","numbers":["4.665"],"title":"Contemporary Architecture and Critical Debate","summary":"This class, required of all Master of Architecture students, presents a critical review of works, theories, and polemics in architecture in the aftermath of World War II. The aim is to present a historical understanding of the period, and to develop a meaningful framework to assess contemporary issues in architecture. Special attention will be paid to historiographic questions of how architects construe the terms of their “present.”","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural History and Criticism","Architecture","Fine Arts"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2002","instructors":["Prof. Arindam Dutta"],"url":"https://ocw.mit.edu/courses/4-665-contemporary-architecture-and-critical-debate-spring-2002/","views":1210},{"id":"18.S190+january-iap_2023","numbers":["18.S190"],"title":"Introduction to Metric Spaces","summary":"This course provides a basic introduction to metric spaces. It covers metrics, open and closed sets, continuous functions (in the topological sense), function spaces, completeness, and compactness.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Mathematical Analysis","Mathematics"],"levels":["Undergraduate"],"features":["Editable Files","Instructor Insights","Lecture Notes","Lecture Videos","Problem Sets"],"term":"January IAP 2023","instructors":["Paige Bright"],"url":"https://ocw.mit.edu/courses/18-s190-introduction-to-metric-spaces-january-iap-2023/","views":1209},{"id":"WGS.645+spring_2019","numbers":["WGS.645"],"title":"Gendering U.S. Immigration Policy: Sociopolitical, Theological and Feminist Perspectives","summary":"This course uses theories of gender to explore sociopolitical, ethical and theological perspectives on immigration policy, with a focus on the U.S. The course begins with an overview of global developments in the feminization of migration and ethical and policy dilemmas that are specific to the current era.","departments":["Women's and Gender Studies"],"areas":["Social Sciences"],"topics":["American Politics","Gender Studies","Political Science","Public Administration","Public Policy","Social Science","Society","Women's Studies"],"levels":["Graduate"],"features":["Presentation Assignments","Written Assignments with Examples"],"term":"Spring 2019","instructors":["Dr. Choi Hee An","Dr. Philip Kretsedemas"],"url":"https://ocw.mit.edu/courses/wgs-645-gendering-u-s-immigration-policy-sociopolitical-theological-and-feminist-perspectives-spring-2019/","views":1208},{"id":"17.559+fall_2004","numbers":["17.559","17.560"],"title":"Comparative Security and Sustainability","summary":"This course focuses on the complexities associated with security and sustainability of states in international relations. Covering aspects of theory, methods and empirical analysis, the course is in three parts, and each consists of seminar sessions focusing on specific topics.","departments":["Political Science"],"areas":["Energy, Climate & Sustainability","Science & Math","Social Sciences"],"topics":["Comparative Politics","Earth Science","International Relations","Political Science","Public Administration","Science","Security Studies","Social Science","Sustainability"],"levels":["Undergraduate","Graduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. Nazli Choucri"],"url":"https://ocw.mit.edu/courses/17-559-comparative-security-and-sustainability-fall-2004/","views":1207},{"id":"11.007+spring_2005","numbers":["11.007"],"title":"Resolving Public Disputes","summary":"This course is an introduction to real-world dynamics of public policy controversies. Topics to be considered include national, state, and local policy disputes, such as smoking, hazardous waste, abortion, gun control, and education. Using a case study approach, students study whether and how those disputes get resolved. Students conduct debates and simulations in addition to writing a series of short essays.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Political Science","Public Administration","Public Policy","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2005","instructors":["Prof. Judith Layzer"],"url":"https://ocw.mit.edu/courses/11-007-resolving-public-disputes-spring-2005/","views":1206},{"id":"6.852J+fall_2009","numbers":["6.852J","18.437J"],"title":"Distributed Algorithms","summary":"Distributed algorithms are algorithms designed to run on multiple processors, without tight centralized control. In general, they are harder to design and harder to understand than single-processor sequential algorithms. Distributed algorithms are used in many practical systems, ranging from large computer networks to multiprocessor shared-memory systems. They also have a rich theory, which forms the subject matter for this course.\n\nThe core of the material will consist of basic distributed algorithms and impossibility results, as covered in Prof. Lynch’s book Distributed Algorithms. This will be supplemented by some updated material on topics such as self-stabilization, wait-free computability, and failure detectors, and some new material on scalable shared-memory concurrent programming.","departments":["Electrical Engineering and Computer Science","Mathematics"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Algorithms and Data Structures","Computer Science","Engineering","Theory of Computation"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2009","instructors":["Prof. Nancy Lynch"],"url":"https://ocw.mit.edu/courses/6-852j-distributed-algorithms-fall-2009/","views":1203},{"id":"21L.709+spring_2017","numbers":["21L.709"],"title":"Ethnic Literature in America","summary":"Although this class starts by critically examining the term “ethnic” as it defines a wide range of cultural forms over time, we will focus mostly on contemporary writers. Questions to consider will include: How has ethnic writing changed American culture and renovated forms of literary expression? What are the varieties and nuances of what we might call an ethnic subjectivity? What could it mean to harbor fugitives within the self: transgressive thoughts or a “foreign” identity? And what is the future of “ethnic” literature in a global space?","departments":["Literature"],"areas":["Humanities"],"topics":["American Literature","Comparative Literature","Creative Writing","Criticism","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2017","instructors":["Dr. Wyn Kelley"],"url":"https://ocw.mit.edu/courses/21l-709-ethnic-literature-in-america-spring-2017/","views":1203},{"id":"6.820+fall_2015","numbers":["6.820"],"title":"Fundamentals of Program Analysis","summary":"This course offers a comprehensive introduction to the field of program analysis. It covers some of the major forms of program analysis including Type Checking, Abstract Interpretation and Model Checking. For each of these, the course covers the underlying theories as well as modern techniques and applications.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Engineering","Software Design and Engineering"],"levels":["Undergraduate"],"features":["Lecture Notes","Programming Assignments"],"term":"Fall 2015","instructors":["Prof. Armando Solar-Lezama"],"url":"https://ocw.mit.edu/courses/6-820-fundamentals-of-program-analysis-fall-2015/","views":1203},{"id":"11.947+spring_2007","numbers":["11.947"],"title":"History and Theory of Historic Preservation","summary":"This class examines the history and theory of historic preservation, focusing on the United States, but with reference to traditions and practices in other countries. The class is designed to examine the largely untold history of the historic preservation movement in this country, and explore how laws, public policies and cultural attitudes shape how we preserve or do not preserve the built environment. The class will give students a grounding in the history, theory and practice of historic preservation, but is not an applied, technical course.","departments":["Urban Studies and Planning"],"areas":["Humanities","Social Sciences"],"topics":["History","Humanities","Social Science","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2007","instructors":["Prof. Max Page"],"url":"https://ocw.mit.edu/courses/11-947-history-and-theory-of-historic-preservation-spring-2007/","views":1203},{"id":"6.972+spring_2006","numbers":["6.972"],"title":"Algebraic Techniques and Semidefinite Optimization","summary":"This research-oriented course will focus on algebraic and computational techniques for optimization problems involving polynomial equations and inequalities with particular emphasis on the connections with semidefinite optimization. The course will develop in a parallel fashion several algebraic and numerical approaches to polynomial systems, with a view towards methods that simultaneously incorporate both elements. We will study both the complex and real cases, developing techniques of general applicability, and stressing convexity-based ideas, complexity results, and efficient implementations. Although we will use examples from several engineering areas, particular emphasis will be given to those arising from systems and control applications.","departments":["Electrical Engineering and Computer Science"],"areas":["Business & Management","Engineering","Science & Math"],"topics":["Algebra and Number Theory","Computation","Engineering","Mathematics","Systems Engineering","Systems Optimization"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2006","instructors":["Prof. Pablo Parrilo"],"url":"https://ocw.mit.edu/courses/6-972-algebraic-techniques-and-semidefinite-optimization-spring-2006/","views":1202},{"id":"11.312+spring_2020","numbers":["11.312"],"title":"Engaging Community: Models and Methods for Designers and Planners","summary":"This course proposes that most cities have neither the infrastructure nor the processes in place to support the demographically complex public in fulfilling its role in democracy. Through this course, participants will learn a set of design principles for creating public engagement practices necessary for building inclusive civic infrastructure in cities. Participants will also have the opportunity to review and practice strategies, techniques, and methods for engaging communities in demographically complex settings.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Social Justice","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Instructor Insights","Podcasts"],"term":"Spring 2020","instructors":["Prof. Ceasar McDowell"],"url":"https://ocw.mit.edu/courses/11-312-engaging-community-models-and-methods-for-designers-and-planners-spring-2020/","views":1202},{"id":"STS.025J+fall_2009","numbers":["STS.025J","21H.913J"],"title":"Making the Modern World: The Industrial Revolution in Global Perspective","summary":"This class is a global survey of the great transformation in history known as the “Industrial Revolution.” Topics include origins of mechanized production, the factory system, steam propulsion, electrification, mass communications, mass production and automation. Emphasis on the transfer of technology and its many adaptations around the world. Countries treated include Great Britain, France, Germany, the US, Sweden, Russia, Japan, China, and India. Includes brief reflection papers and a final paper.","departments":["History","Science, Technology, and Society"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["Business","Globalization","History","History of Science and Technology","Humanities","Modern History","World History"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2009","instructors":["Prof. Merritt Roe Smith"],"url":"https://ocw.mit.edu/courses/sts-025j-making-the-modern-world-the-industrial-revolution-in-global-perspective-fall-2009/","views":1202},{"id":"14.128+spring_2003","numbers":["14.128"],"title":"Dynamic Optimization & Economic Applications (Recursive Methods)","summary":"The unifying theme of this course is best captured by the title of our main reference book: “Recursive Methods in Economic Dynamics”. We start by covering deterministic and stochastic dynamic optimization using dynamic programming analysis. We then study the properties of the resulting dynamic systems. Finally, we will go over a recursive method for repeated games that has proven useful in contract theory and macroeconomics. We shall stress applications and examples of all these techniques throughout the course.","departments":["Economics"],"areas":["Business & Management","Engineering","Social Sciences"],"topics":["Economics","Engineering","Game Theory","Macroeconomics","Social Science","Systems Engineering","Systems Optimization"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Spring 2003","instructors":["Prof. Iván Werning"],"url":"https://ocw.mit.edu/courses/14-128-dynamic-optimization-economic-applications-recursive-methods-spring-2003/","views":1201},{"id":"18.04+fall_1999","numbers":["18.04"],"title":"Complex Variables with Applications","summary":"The following topics are covered in the course: complex algebra and functions; analyticity; contour integration, Cauchy’s theorem; singularities, Taylor and Laurent series; residues, evaluation of integrals; multivalued functions, potential theory in two dimensions; Fourier analysis and Laplace transforms.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Calculus","Mathematical Analysis","Mathematics"],"levels":["Undergraduate"],"features":["Exam Solutions","Exams","Problem Set Solutions","Problem Sets"],"term":"Fall 1999","instructors":["Prof. R. Rosales"],"url":"https://ocw.mit.edu/courses/18-04-complex-variables-with-applications-fall-1999/","views":1200},{"id":"11.S196+spring_2011","numbers":["11.S196","11.191"],"title":"Global Freshwater Crisis","summary":"For the first time in history, the global demand for freshwater is overtaking its supply in many parts of the world. The U.N. predicts that by 2025, more than half of the countries in the world will be experiencing water stress or outright shortages. Lack of water can cause disease, food shortages, starvation, migrations, political conflict, and even lead to war. Models of cooperation, both historic and contemporary, show the way forward. The first half of the course details the multiple facets of the water crisis. Topics include water systems, water transfers, dams, pollution, climate change, scarcity, water conflict/cooperation, food security, and agriculture. The second half of the course describes innovative solutions: Adaptive technologies and adaptation through policy, planning, management, economic tools, and finally, human behaviors required to preserve this precious and imperiled resource. Several field trips to water/wastewater/biosolids reuse and water-energy sites will help us to better comprehend both local and international challenges and solutions.","departments":["Urban Studies and Planning"],"areas":["Engineering","Social Sciences"],"topics":["Aquatic Sciences and Water Quality Control","Economics","Engineering","Environmental Engineering","Environmental Management","Hydrodynamics and Coastal Engineering","International Development","Social Science"],"levels":["Undergraduate"],"features":["Projects","Written Assignments"],"term":"Spring 2011","instructors":["Susan Murcott"],"url":"https://ocw.mit.edu/courses/11-s196-global-freshwater-crisis-spring-2011/","views":1200},{"id":"18.305+fall_2004","numbers":["18.305"],"title":"Advanced Analytic Methods in Science and Engineering","summary":"Advanced Analytic Methods in Science and Engineering is a comprehensive treatment of the advanced methods of applied mathematics. It was designed to strengthen the mathematical abilities of graduate students and train them to think on their own.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Applied Mathematics","Differential Equations","Mathematical Analysis","Mathematics"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Hung Cheng"],"url":"https://ocw.mit.edu/courses/18-305-advanced-analytic-methods-in-science-and-engineering-fall-2004/","views":1198},{"id":"11.S943+fall_2017","numbers":["11.S943"],"title":"Development, Planning, and Implementation: The Dialectic of Theory and Practice","summary":"This is an advanced graduate-level seminar that will analyze the effectiveness of development and planning theories from the perspective of practitioners who implement projects and policies based on such theories. The course will be organized around 12 implementation puzzles, which should be considered for re-theorizing both developmental and planning processes.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Public Administration","Public Policy","Social Science","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2017","instructors":["Prof. Bishwapriya Sanyal","Cauam Ferreira Cardoso"],"url":"https://ocw.mit.edu/courses/11-s943-development-planning-and-implementation-the-dialectic-of-theory-and-practice-fall-2017/","views":1198},{"id":"2.674+spring_2016","numbers":["2.674","2.675"],"title":"Micro/Nano Engineering Laboratory","summary":"This course encourages creative thinking through hands-on experience via building, observing and manipulating micro-and nano-scale structures. Students learn about underlying science and engineering principles and possible applications.","departments":["Mechanical Engineering"],"areas":["Engineering"],"topics":["Engineering","Mechanical Engineering","Microtechnology"],"levels":["Undergraduate"],"features":["Lecture Notes"],"term":"Spring 2016","instructors":["Prof. Sang-Gook Kim","Prof. Rohit Karnik","Prof. Jeehwan Kim","Prof. Mathias Kolle","Dr. Benita Comeau","Daniel C Herrick"],"url":"https://ocw.mit.edu/courses/2-674-micro-nano-engineering-laboratory-spring-2016/","views":1198},{"id":"16.430J+spring_2012","numbers":["16.430J","HST.514J"],"title":"Sensory-Neural Systems: Spatial Orientation from End Organs to Behavior and Adaptation","summary":"This course introduces sensory systems and multi-sensory fusion using the vestibular and spatial orientation systems as a model. Topics range from end organ dynamics to neural responses, to sensory integration, to behavior, and adaptation, with particular application to balance, posture and locomotion under normal gravity and space conditions. Depending upon the background and interests of the students, advanced term project topics might include motion sickness, astronaut adaptation, artificial gravity, lunar surface locomotion, vestibulo-cardiovascular responses, vestibular neural prostheses, or other topics of interest.","departments":["Aeronautics and Astronautics","Health Sciences and Technology"],"areas":["Engineering","Science & Math"],"topics":["Aerospace Engineering","Bioastronautics","Biology","Engineering","Neurobiology","Neuroscience","Science"],"levels":["Graduate"],"features":["Presentation Assignments"],"term":"Spring 2012","instructors":["Dr. Charles M. Oman","Dr. Laurence R. Young","Dr. Daniel M. Merfeld","Dr. Kathleen Cullen"],"url":"https://ocw.mit.edu/courses/16-430j-sensory-neural-systems-spatial-orientation-from-end-organs-to-behavior-and-adaptation-spring-2012/","views":1198},{"id":"12.571+fall_2009","numbers":["12.571"],"title":"Near-Surface Geophysical Imaging","summary":"This graduate level course presents theories, methodologies, and applications of seismic imaging for solving the shallow near-surface (0 - 500 m) effects on the seismic data processing for oil and gas exploration on land. It introduces both conventional and advanced imaging technologies that have been developed in academia and the seismic industry.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Computer Science","Data Mining","Earth Science","Engineering","Geology","Geophysics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Fall 2009","instructors":["Prof. Jie Zhang"],"url":"https://ocw.mit.edu/courses/12-571-near-surface-geophysical-imaging-fall-2009/","views":1197},{"id":"15.S50+january-iap_2016","numbers":["15.S50"],"title":"How to Win at Texas Hold'em Poker","summary":"Offered during MIT’s Independent Activites Period (IAP), this short course covers the poker concepts, math concepts, and general concepts needed to play the game of Texas Hold’em on a professional level.\n\nIAP is a special 4-week term in January that provides members of the MIT community including students, faculty, staff, and alums with an opportunity to organize, sponsor and participate in a wide variety of activities and topics that are often outside of the regular MIT curriculum.\n\nFaculty Advisor: Paul Mende","departments":["Sloan School of Management"],"areas":["Science & Math"],"topics":["Mathematics","Probability and Statistics"],"levels":["Graduate"],"features":["Lecture Notes","Lecture Videos","Problem Set Solutions","Problem Sets"],"term":"January IAP 2016","instructors":["Will Ma"],"url":"https://ocw.mit.edu/courses/15-s50-how-to-win-at-texas-holdem-poker-january-iap-2016/","views":1194},{"id":"18.S997+fall_2011","numbers":["18.S997"],"title":"Introduction To MATLAB Programming","summary":"This course is intended to assist undergraduates with learning the basics of programming in general and programming MATLAB® in particular.","departments":["Mathematics"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Applied Mathematics","Computational Modeling and Simulation","Computer Science","Engineering","Mathematics","Programming Languages","Systems Engineering"],"levels":["Undergraduate"],"features":["Lecture Videos","Problem Sets","Programming Assignments with Examples"],"term":"Fall 2011","instructors":["Yossi Farjoun"],"url":"https://ocw.mit.edu/courses/18-s997-introduction-to-matlab-programming-fall-2011/","views":1194},{"id":"20.442+fall_2005","numbers":["20.442","20.342"],"title":"Molecular Structure of Biological Materials (BE.442)","summary":"This course, intended for both graduate and upper level undergraduate students, will focus on understanding of the basic molecular structural principles of biological materials. It will address the molecular structures of various materials of biological origin, such as several types of collagen, silk, spider silk, wool, hair, bones, shells, protein adhesives, GFP, and self-assembling peptides. It will also address molecular design of new biological materials applying the molecular structural principles. The long-term goal of this course is to teach molecular design of new biological materials for a broad range of applications. A brief history of biological materials and its future perspective as well as its impact to the society will also be discussed. Several experts will be invited to give guest lectures.","departments":["Biological Engineering"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Biomaterials","Biotechnology","Engineering","Molecular Biology","Nanotechnology","Science","Structural Biology"],"levels":["Graduate"],"features":["Lecture Notes","Presentation Assignments with Examples","Written Assignments with Examples"],"term":"Fall 2005","instructors":["Prof. Shuguang Zhang"],"url":"https://ocw.mit.edu/courses/20-442-molecular-structure-of-biological-materials-be-442-fall-2005/","views":1193},{"id":"17.262+spring_2023","numbers":["17.262"],"title":"Congress and the American Political System II","summary":"This course analyzes the development of the US Congress by focusing on the competing theoretical lenses through which legislatures have been studied. In particular, it compares sociological and economic models of legislative behavior, applying those models to floor decision-making, committee behavior, political parties, relations with other branches of the Federal government, and elections.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","Political Science","Social Science"],"levels":["Graduate"],"features":["Readings","Written Assignments"],"term":"Spring 2023","instructors":["Prof. Charles Stewart"],"url":"https://ocw.mit.edu/courses/17-262-congress-and-the-american-political-system-ii-spring-2023/","views":1191},{"id":"EC.S11+fall_2005","numbers":["EC.S11"],"title":"Engineering Capacity in Community-Based Healthcare","summary":"This multidisciplinary seminar addresses fundamental issues in global health faced by community-based healthcare programs in developing countries. Students will broadly explore topics with expert lecturers and guided readings. Topics will be further illuminated with case studies from healthcare programs in urban centers of Zambia. Multidisciplinary teams will be formed to develop feasible solutions to specific health challenges posed in the case studies and encouraged to pursue their ideas beyond the seminar. Possible global health topics include community-based AIDS/HIV management, maternity care, health diagnostics, and information technology in patient management and tracking. Students from Medicine, Public Health, Engineering, Management, and Social Sciences are encouraged to enroll. No specific background experience is expected, but students should have some relevant skills or experiences.","departments":["Edgerton Center"],"areas":["Business & Management","Health & Medicine","Social Sciences"],"topics":["Biomedical Enterprise","Business","Health Care Management","Health and Medicine","Public Health","Society","The Developing World"],"levels":["Graduate"],"features":["Projects","Written Assignments with Examples"],"term":"Fall 2005","instructors":["Ms. Christina DeFilippo","Mr. Eric Soller","Ms. Kathie Dionisio","Ms. MaryAnn Dakkak","Mr. Peter J. Mack","Mr. Sankey Chibale","Mr. Will DelHagen"],"url":"https://ocw.mit.edu/courses/ec-s11-engineering-capacity-in-community-based-healthcare-fall-2005/","views":1189},{"id":"MAS.963+spring_2002","numbers":["MAS.963"],"title":"Techno-identity: Who we are and how we perceive ourselves and others","summary":"The nature of human identity - how we think of ourselves, how we perceive others - is a mutable concept, changing with the rise and fall of religious beliefs, social mores, philosophical theories. Today, we live in a world in which science and technology are among the most powerful forces reshaping our culture - and thus our definitions and perceptions of identity. In this seminar, we will examine the impact of science and technology on identity.\n\nThe instructor’s course page may be viewed at http://smg.media.mit.edu/classes/IdentitySeminar/","departments":["Media Arts and Sciences"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Fine Arts","Humanities","Media Studies","Philosophy","Social Anthropology","Social Science"],"levels":["Graduate"],"features":[],"term":"Spring 2002","instructors":["Prof. Judith Donath"],"url":"https://ocw.mit.edu/courses/mas-963-techno-identity-who-we-are-and-how-we-perceive-ourselves-and-others-spring-2002/","views":1185},{"id":"HST.584J+spring_2006","numbers":["HST.584J","22.561J"],"title":"Magnetic Resonance Analytic, Biochemical, and Imaging Techniques","summary":"This course is an introduction to basic NMR theory. Examples of biochemical data obtained using NMR are summarized along with other related experiments. Students participate in detailed study of NMR imaging techniques, including discussions of basic cross-sectional image reconstruction, image contrast, flow and real-time imaging, and hardware design considerations. Exposure to laboratory NMR spectroscopic and imaging equipment is included.","departments":["Health Sciences and Technology","Nuclear Science and Engineering"],"areas":["Health & Medicine","Science & Math"],"topics":["Biochemistry","Biology","Biomedical Instrumentation","Biomedical Signal and Image Processing","Health and Medicine","Medical Imaging","Science","Spectroscopy"],"levels":["Graduate"],"features":["Exam Solutions","Exams","Problem Set Solutions","Problem Sets","Projects with Examples"],"term":"Spring 2006","instructors":["Prof. Bruce Rosen","Prof. Lawrence Wald"],"url":"https://ocw.mit.edu/courses/hst-584j-magnetic-resonance-analytic-biochemical-and-imaging-techniques-spring-2006/","views":1183},{"id":"STS.428+fall_2004","numbers":["STS.428"],"title":"Technology and Change in Rural America","summary":"This course considers the historical dimensions of rural production from subsistence to industrialization, both in America and in an international context, with an emphasis on the role of science and technology. Topics include changing notions of progress; emergence of genetics and its complex applications to food production; mechanization of both farm practices and the food industry; role of migrant labor; management theory and its impact on farm practice; role of federal governments and NGOs in production systems; women in food production systems; and the green revolution.","departments":["Science, Technology, and Society"],"areas":["Humanities","Social Sciences"],"topics":["American History","Anthropology","History","History of Science and Technology","Humanities","Modern History","Social Anthropology","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. Deborah Fitzgerald"],"url":"https://ocw.mit.edu/courses/sts-428-technology-and-change-in-rural-america-fall-2004/","views":1181},{"id":"15.968+spring_2005","numbers":["15.968"],"title":"The Sociology of Strategy","summary":"This seminar provides an introduction to scholarship in a growing research community: the sociologists and sociologically-inclined organization theorists who study issues that relate, at least in a broad sense, to the interdisciplinary field of inquiry that is known as “strategy” or “strategic management” research. The course is not designed to survey the field of strategy. Rather, the focus is on getting a closer understanding of the recent work by sociologists and sociologically-oriented organization theorists that investigates central questions in strategic management. In particular, we will be concerned with identifying and assessing sociological work that aims to shed light on: (a) relative firm performance; (b) the nature of competition and market interaction; (c) organizational capabilities; (d) the beginnings of industries and firms; (e) the diffusion or transfer of ideas and practices across firms; and (f) strategic change.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Industrial Organization","Management","Organizational Behavior","Social Science","Sociology"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2005","instructors":["Prof. Ezra Zuckerman"],"url":"https://ocw.mit.edu/courses/15-968-the-sociology-of-strategy-spring-2005/","views":1181},{"id":"17.586+spring_2009","numbers":["17.586"],"title":"Warlords, Terrorists, and Militias: Theorizing on Violent Non-State Actors","summary":"This course is a general overview of the recent political science literature on violent non-state actors. Its aim is to examine why non-state actors (such as warlords, terrorists, militias, etc.) resort to violence, what means and tactics they use, and what can be done to counter that violence. In that regard, the class will cover works pertaining to the production side of non-state violence (i.e. the objectives and organization of insurgents/terrorists/militias/warlords, their mobilization strategies and support base, how they coerce opponents, etc.); as well as the response that violence elicits from governments or other actors (i.e. counter-insurgency or counter-terrorism strategies, among others). Apart from introducing the basic variables and theoretical and empirical findings in the literature, this course will also grapple with questions of definition, operationalization of variables, and general methodology relevant to conducting research in this area of violent conflict. Though thematically-driven, this course will also reference cases from the contemporary battlefields of insurgency and terrorism (be it Afghanistan, Iraq, Pakistan, the West Bank and Gaza, Colombia, etc.) as they relate to the pertinent themes.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Anthropology","Military Studies","Political Science","Public Administration","Security Studies","Social Anthropology","Social Science"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Spring 2009","instructors":["Prof. Fotini Christia"],"url":"https://ocw.mit.edu/courses/17-586-warlords-terrorists-and-militias-theorizing-on-violent-non-state-actors-spring-2009/","views":1181},{"id":"24.962+spring_2005","numbers":["24.962"],"title":"Advanced Phonology","summary":"This course focuses on phonological phenomena that are sensitive to morphological structure, including base-reduplicant identity, cyclicity, level ordering, derived environment effects, opaque rule interactions, and morpheme structure constraints. In the recent OT literature, it has been claimed that all of these phenomena can be analyzed with a single theoretical device: correspondence constraints, which regulate the similarity of lexically related forms (such as input and output, base and derivative, base and reduplicant).","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics","Phonology"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2005","instructors":["Prof. Donca Steriade","Prof. Adam Albright"],"url":"https://ocw.mit.edu/courses/24-962-advanced-phonology-spring-2005/","views":1180},{"id":"8.511+fall_2004","numbers":["8.511"],"title":"Theory of Solids I","summary":"This is the first term of a theoretical treatment of the physics of solids. Topics covered include crystal structure and band theory, density functional theory, a survey of properties of metals and semiconductors, quantum Hall effect, phonons, electron phonon interaction and superconductivity.","departments":["Physics"],"areas":["Engineering","Science & Math"],"topics":["Atomic, Molecular, Optical Physics","Condensed Matter Physics","Engineering","Mechanical Engineering","Physics","Science","Solid Mechanics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Patrick Lee"],"url":"https://ocw.mit.edu/courses/8-511-theory-of-solids-i-fall-2004/","views":1180},{"id":"15.575+spring_2004","numbers":["15.575"],"title":"Research Seminar in IT and Organizations: Economic Perspectives","summary":"Business organizations and markets use a bewildering variety of structures to coordinate the productive activities of their stakeholders. Dramatic changes in information technology and the nature of economic competition are forcing firms to come up with new ways of organizing work. This course uses economic theory to investigate the roles of information and technology in the existing diversity of organizations and markets and in enabling the creating of new organizational forms.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Industrial Organization","Information Technology","Operations Management","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2004","instructors":["Prof. Erik Brynjolfsson"],"url":"https://ocw.mit.edu/courses/15-575-research-seminar-in-it-and-organizations-economic-perspectives-spring-2004/","views":1178},{"id":"21L.422+fall_2002","numbers":["21L.422"],"title":"Tragedy","summary":"“Tragedy” is a name originally applied to a particular kind of dramatic art and subsequently to other literary forms; it has also been applied to particular events, often implying thereby a particular view of life. Throughout the history of Western literature it has sustained this double reference. Uniquely and insistently, the realm of the tragic encompasses both literature and life.\n\nThrough careful, critical reading of literary texts, this subject will examine three aspects of the tragic experience:\n\n• the scapegoat\n• the tragic hero\n• the ethical crisis\n\nThese aspects of the tragic will be pursued in readings that range in the reference of their materials from the warfare of the ancient world to the experience of the modern extermination camps.","departments":["Literature"],"areas":["Humanities"],"topics":["Classics","Criticism","Drama","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":[],"term":"Fall 2002","instructors":["Prof. Alvin Kibel"],"url":"https://ocw.mit.edu/courses/21l-422-tragedy-fall-2002/","views":1177},{"id":"RES.2-002+spring_2010","numbers":["RES.2-002"],"title":"Finite Element Procedures for Solids and Structures","summary":"Finite element analysis is now widely used for solving complex static and dynamic problems encountered in engineering and the sciences. In these two video courses, Professor K. J. Bathe, a researcher of world renown in the field of finite element analysis, teaches the basic principles used for effective finite element analysis, describes the general assumptions, and discusses the implementation of finite element procedures for linear and nonlinear analyses.\n\nThese videos were produced in 1982 and 1986 by the MIT Center for Advanced Engineering Study.","departments":["Mechanical Engineering"],"areas":["Engineering"],"topics":["Computational Modeling and Simulation","Engineering","Mechanical Engineering","Numerical Simulation","Solid Mechanics","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Videos"],"term":"Spring 2010","instructors":["Klaus-Jürgen Bathe"],"url":"https://ocw.mit.edu/courses/res-2-002-finite-element-procedures-for-solids-and-structures-spring-2010/","views":1174},{"id":"RES.ENV-005","numbers":["RES.ENV-005"],"title":"Climate Science, Risk & Solutions: A Climate Primer","summary":"The goal of the Climate Primer website is to summarize the most important lines of evidence for human-caused climate change. It confronts the stickier questions about uncertainty in our projections, engages in a discussion of risk and risk managment, and concludes by presenting different options for taking action. We hope that the facts prepare you for more effective conversations with your community about values, trade-offs, politics, and actions.\n\nIn March 2024, the MIT Environmental Solutions Initiative launched the first major update to the Climate Primer. The updated Primer includes more precise estimates of future global warming and its effects on global temperatures and extreme weather events, important advances in climate modeling, new actions taken around the world to adapt to the impacts of climate change, and the latest data about the pace at which clean energy and other critical climate solutions are being deployed. Read more about the update on the MIT Environmental Solutions website.","departments":[],"areas":["Data Science, Analytics & Computer Technology","Energy, Climate & Sustainability","Science & Math"],"topics":["Climate","Climate Studies","Earth Science","Energy","Science","Sustainability","Technology"],"levels":["Non-Credit"],"features":["Other Audio","Other Video"],"term":"","instructors":["Prof. Kerry Emanuel"],"url":"https://ocw.mit.edu/courses/res-env-005-climate-science-risk-solutions-a-climate-primer/","views":1172},{"id":"ESD.69+fall_2010","numbers":["ESD.69","HST.926J"],"title":"Seminar on Health Care Systems Innovation","summary":"This seminar applies a systems perspective to understand health care delivery today, its stakeholders and problems as well as opportunities. Students are introduced to the ‘systems perspective’ that has been used successfully in other industries, and will address the introduction of new processes, technologies and strategies to improve overall health outcomes. Students are assigned to teams to work on a semester‐long group project, in collaboration with staff of a nearby Boston hospital.","departments":["Engineering Systems Division","Health Sciences and Technology"],"areas":["Business & Management","Engineering","Health & Medicine"],"topics":["Biomedical Enterprise","Business","Engineering","Health Care Management","Health and Medicine","Innovation","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Fall 2010","instructors":["Stan Finkelstein, MD","Prof. Joseph Coughlin","Prof. Joel Moses"],"url":"https://ocw.mit.edu/courses/esd-69-seminar-on-health-care-systems-innovation-fall-2010/","views":1172},{"id":"24.941J+spring_2007","numbers":["24.941J","6.543J","9.587J","HST.727J"],"title":"The Lexicon and Its Features","summary":"This course provides an overview of the distinctive features which distinguish sound categories of languages of the world. Theories which relate these categories to their acoustic and articulatory correlates, both universally and in particular languages, are covered. Models of word recognition by listeners, features, and phonological structure are also discussed. In addition, the course offers a variety of perspectives on these issues, drawn from Electrical Engineering, Linguistics and Cognitive Science.","departments":["Brain and Cognitive Sciences","Electrical Engineering and Computer Science","Health Sciences and Technology","Linguistics and Philosophy"],"areas":["Humanities","Science & Math"],"topics":["Cognitive Science","Humanities","Linguistics","Phonology","Science"],"levels":["Graduate"],"features":["Lecture Notes","Projects"],"term":"Spring 2007","instructors":["Dr. David Gow","Prof. Donca Steriade","Prof. Edward Flemming","Prof. Kenneth Stevens","Dr. Stefanie Shattuck-Hufnagel"],"url":"https://ocw.mit.edu/courses/24-941j-the-lexicon-and-its-features-spring-2007/","views":1172},{"id":"1.259J+fall_2006","numbers":["1.259J","11.542J","ESD.227J"],"title":"Transit Management","summary":"This course discusses management methods of relevance to public transportation systems. Topics include strategic planning management, labor relations, maintenance planning and administration, financing, marketing and fare policy, and management information and decision support systems. The course shows how these general management tasks are dealt with in the transit industry and presents alternative strategies. It also identifies alternative arrangements for service provision, including different ways of involving the private sector in public transportation.","departments":["Civil and Environmental Engineering","Engineering Systems Division","Urban Studies and Planning"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Operations Management","Social Science","Transportation Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2006","instructors":["Prof. Nigel Wilson"],"url":"https://ocw.mit.edu/courses/1-259j-transit-management-fall-2006/","views":1172},{"id":"17.263+fall_2020","numbers":["17.263"],"title":"American Elections","summary":"This course provides an overview of electoral politics in the United States, covering presidential, congressional, state, and local elections. It covers the development of American elections over time, electoral rules and institutions, the macro-structural forces shaping electoral outcomes, the key organizations involved in elections (parties, etc.), candidates’ calculations and campaign strategies, and the role of ordinary citizens in the electoral process, as well as potential reforms to the U.S. electoral system.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","Political Science","Public Administration","Public Policy","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2020","instructors":["Prof. Devin Caughey"],"url":"https://ocw.mit.edu/courses/17-263-american-elections-fall-2020/","views":1171},{"id":"21H.968J+spring_2010","numbers":["21H.968J","STS.415J"],"title":"Nature, Environment, and Empire","summary":"This class examines the relationship between the study of natural history, both domestic and exotic, by Europeans and Americans, and exploration and exploitation of the natural world, focusing on the eighteenth and nineteenth centuries.","departments":["History","Science, Technology, and Society"],"areas":["Humanities","Science & Math"],"topics":["Biology","Earth Science","Ecology","Environmental Science","History","Humanities","Intellectual History","Modern History","Science"],"levels":["Graduate"],"features":["Image Gallery","Written Assignments"],"term":"Spring 2010","instructors":["Prof. Harriet Ritvo"],"url":"https://ocw.mit.edu/courses/21h-968j-nature-environment-and-empire-spring-2010/","views":1171},{"id":"7.60+spring_2010","numbers":["7.60"],"title":"Cell Biology: Structure and Functions of the Nucleus","summary":"The goal of this course is to teach both the fundamentals of nuclear cell biology as well as the methodological and experimental approaches upon which they are based. Lectures and class discussions will cover the background and fundamental findings in a particular area of nuclear cell biology. The assigned readings will provide concrete examples of the experimental approaches and logic used to establish these findings. Some examples of topics include genome and systems biology, transcription, and gene expression.","departments":["Biology"],"areas":["Science & Math"],"topics":["Biology","Cell Biology","Science"],"levels":["Graduate"],"features":[],"term":"Spring 2010","instructors":["Prof. Phillip Sharp","Prof. Richard Young"],"url":"https://ocw.mit.edu/courses/7-60-cell-biology-structure-and-functions-of-the-nucleus-spring-2010/","views":1169},{"id":"21L.021+spring_2022","numbers":["21L.021"],"title":"Comedy","summary":"Comedy, that most elastic literary and performance mode, skewers artifice, topples authority, and reverses expectations, not with the fatal outcomes of tragedy but with laughter and festivity. This class examines both deep roots and current forms of comedy, with a particular focus on comic insubordination. And food.\n\nWe will revel in Greek, Roman, and Shakespearean drama; explore Aphra Behn’s eighteenth-century feminist rakes and sexual adventurers in The Rover; investigate social satire in Jane Austen, Herman Melville, and Oscar Wilde; peek under the covers of small-town family life in Alison Bechdel’s Fun Home; and probe the uneasy relationship between farce and romantic love, violence and redemptive humor, satire and festivity in comic art. Discussion will draw on examples of popular and contemporary forms, including film and sketch comedy.","departments":["Literature"],"areas":["Humanities"],"topics":["Comedy","Humanities","Literature"],"levels":["Undergraduate"],"features":["Editable Files","Instructor Insights","Readings","Written Assignments"],"term":"Spring 2022","instructors":["Dr. Wyn Kelley"],"url":"https://ocw.mit.edu/courses/21l-021-comedy-spring-2022/","views":1169},{"id":"8.324+fall_2010","numbers":["8.324"],"title":"Relativistic Quantum Field Theory II","summary":"This course is the second course of the quantum field theory trimester sequence beginning with Relativistic Quantum Field Theory I (8.323) and ending with Relativistic Quantum Field Theory III (8.325). It develops in depth some of the topics discussed in 8.323 and introduces some advanced material.","departments":["Physics"],"areas":["Science & Math"],"topics":["Condensed Matter Physics","Particle Physics","Physics","Quantum Mechanics","Relativity","Science","Theoretical Physics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2010","instructors":["Prof. Hong Liu"],"url":"https://ocw.mit.edu/courses/8-324-relativistic-quantum-field-theory-ii-fall-2010/","views":1169},{"id":"17.506+spring_2007","numbers":["17.506"],"title":"Ethnic Politics II","summary":"This course is designed mainly for political science graduate students conducting or considering conducting research on identity politics. While 17.504 Ethnic Politics I is designed as a primarily theoretical course, Ethnic Politics II switches the focus to methods. It aims to familiarize the student with the current conventional approaches as well as major challenges to them. The course discusses definition and measurement issues as well as briefly addressing survey techniques and modeling.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Anthropology","Ethnography","Political Science","Social Anthropology","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2007","instructors":["Prof. Roger Petersen"],"url":"https://ocw.mit.edu/courses/17-506-ethnic-politics-ii-spring-2007/","views":1166},{"id":"8.13-14+fall_2016","numbers":["8.13-14"],"title":"Experimental Physics I & II \"Junior Lab\"","summary":"Junior Lab consists of two undergraduate courses in experimental physics. The course sequence is usually taken by Juniors (hence the name). Officially, the courses are called Experimental Physics I and II and are numbered 8.13 for the first half, given in the fall semester, and 8.14 for the second half, given in the spring.\n\nEach term, students do experiments on phenomena whose discoveries led to major advances in physics. In the process, they deepen their understanding of the relations between experiment and theory, mostly in atomic and nuclear physics.","departments":["Physics"],"areas":["Science & Math"],"topics":["Atomic, Molecular, Optical Physics","Physics","Science"],"levels":["Undergraduate"],"features":["Instructor Insights"],"term":"Fall 2016","instructors":["Physics Department Faculty, Lecturers, and Technical Staff"],"url":"https://ocw.mit.edu/courses/8-13-14-experimental-physics-i-ii-junior-lab-fall-2016-spring-2017/","views":1165},{"id":"15.ES718+spring_2015","numbers":["15.ES718"],"title":"Global Health Innovation: Delivering Targeted Advice to an Organization in the Field","summary":"In this three-day workshop, students will get a broad introduction to global health issues. We will look at one particular non-governmental organization in India that works to improve health across the lifespan by empowering existing community resources to provide appropriate physical, psychological and social therapies, focusing on child development, adolescent and youth health, mental health, and chronic disease. This workshop equips student to explore novel ideas and technologies with an inspiring and ground-breaking Indian NGO.\n\nFulfills the Sloan Innovation Period (SIP) elective requirement. SIP occurs at the midpoint of each semester providing students with an intensive week of experiential leadership learning, as well as exposure to groundbreaking faculty work. It allows students to engage in intellectual exploration outside the classroom. SIP degree requirements include core courses in ethics and leadership as well as electives.","departments":["Sloan School of Management"],"areas":["Business & Management","Health & Medicine"],"topics":["Business","Health Care Management","Innovation","Management","Organizational Behavior"],"levels":["Graduate"],"features":["Instructor Insights","Lecture Notes","Presentation Assignments","Written Assignments with Examples"],"term":"Spring 2015","instructors":["Dr. Anjali Sastry"],"url":"https://ocw.mit.edu/courses/15-es718-global-health-innovation-delivering-targeted-advice-to-an-organization-in-the-field-spring-2015/","views":1165},{"id":"4.210+fall_2012","numbers":["4.210"],"title":"Precedents in Critical Practice","summary":"This course provides students with the opportunity to develop a map of contemporary architectural practice and discourse. The seminar examines six themes in terms of their recent history: city and global economy, urban plan and map of operations, program and performance, drawing and scripting, image and surface, and utopia and projection. Students will study buildings and read relevant texts in order to place recent architectural projects in disciplinary and cultural context.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architectural History and Criticism","Architecture","Fine Arts"],"levels":["Graduate"],"features":["Presentation Assignments with Examples"],"term":"Fall 2012","instructors":["Prof. Ana Miljački"],"url":"https://ocw.mit.edu/courses/4-210-precedents-in-critical-practice-fall-2012/","views":1165},{"id":"21L.455+fall_2004","numbers":["21L.455"],"title":"Classical Literature: The Golden Age of Augustan Rome","summary":"Roman Literature of the Golden Age of Augustus Caesar, produced during the transition from Republican to Imperial forms of government, was to have a profound and defining influence on Western European and American societies. These writings ultimately established lasting models of aesthetic refinement, philosophical aspiration, and political ambition that continue to shape modern cultures. This class will be exploring the Golden Age of Latin Literature from an historical perspective in order to provide an intensive examination of the cultural contexts in which these monumental works of classical art were first produced. Readings will emphasize the transition from a Republican form of government to an Empire under the rule of Augustus Caesar and the diversity of responses among individual authors to the profound structural changes that Roman society was undergoing at this time. Particular attention will be devoted to the reorganization of society and the self through textuality, the changing dimensions of the public and the private, the roles of class and gender, and the relationship between art and pleasure. Writings covering a wide variety of literary genres will include the works of Caesar, Cicero, Catullus, Livy, Virgil, Horace, and Ovid, with additional readings from Cassius Dio for background.","departments":["Literature"],"areas":["Humanities"],"topics":["Ancient History","Classics","History","Humanities","Intellectual History","Literature","Philosophy","Political Philosophy"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2004","instructors":["Prof. James Cain"],"url":"https://ocw.mit.edu/courses/21l-455-classical-literature-the-golden-age-of-augustan-rome-fall-2004/","views":1164},{"id":"16.622+fall_2003","numbers":["16.622"],"title":"Experimental Projects II","summary":"The Experimental Project Lab in the Department of Aeronautics and Astronautics is a two-semester course sequence: 16.621 Experimental Projects I and 16.622 Experimental Projects II (this course). Students in 16.622 gain practical insight and improved understanding of engineering experimentation through design and execution of “project” experiments. Building upon work in course 16.621, students construct and test equipment, make systematic experimental measurements of phenomena, analyze data, and compare theoretical predictions with results. Deliverables comprise a written final project report and formal oral presentations. Instructions on oral presentations and multi-section reporting are given. Experimental Projects I and II provide a valuable link between theory (16.621) and practice (16.622).","departments":["Aeronautics and Astronautics"],"areas":["Business & Management","Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Aerospace Engineering","Computer Science","Data Mining","Engineering","Science","Systems Design","Systems Engineering"],"levels":["Undergraduate"],"features":["Projects with Examples"],"term":"Fall 2003","instructors":["Prof. Edward Greitzer","Prof. Jennifer L. Craig","Prof. John Deyst"],"url":"https://ocw.mit.edu/courses/16-622-experimental-projects-ii-fall-2003/","views":1164},{"id":"21L.701+fall_2003","numbers":["21L.701"],"title":"Literary Interpretation: Interpreting Poetry","summary":"This seminar offers a course of readings in lyric poetry. It aims to enhance the student’s capacity to understand the nature of poetic language and the enjoyment of poetic texts by treating poems as messages to be deciphered.\n\nThe seminar will briefly touch upon the history of theories of figurative language since Aristotle and it will attend to the development of those theories during the last thirty years, noting the manner in which they tended to consider figures of speech distinct from normative or literal expression, and it will devote particular attention to the rise of theories that quarrel with this distinction.\n\nThe seminar also aims to communicate a rough sense of the history of English-speaking poetry since the early modern period. Some attention will be paid as well to the use of metaphor in science.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Humanities","Literature","Philosophy","Philosophy of Language","Poetry"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2003","instructors":["Prof. Alvin Kibel"],"url":"https://ocw.mit.edu/courses/21l-701-literary-interpretation-interpreting-poetry-fall-2003/","views":1164},{"id":"6.897+spring_2004","numbers":["6.897"],"title":"Selected Topics in Cryptography","summary":"This course covers a number of advanced “selected topics” in the field of cryptography. The first part of the course tackles the foundational question of how to define security of cryptographic protocols in a way that is appropriate for modern computer networks, and how to construct protocols that satisfy these security definitions. For this purpose, the framework of “universally composable security” is studied and used. The second part of the course concentrates on the many challenges involved in building secure electronic voting systems, from both theoretical and practical points of view. In the third part, an introduction to cryptographic constructions based on bilinear pairings is given.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computer Science","Cryptography","Engineering","Theory of Computation"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2004","instructors":["Prof. Ran Canetti"],"url":"https://ocw.mit.edu/courses/6-897-selected-topics-in-cryptography-spring-2004/","views":1163},{"id":"17.199J+fall_2005","numbers":["17.199J","21G.098J"],"title":"Working in a Global Economy","summary":"The course introduces the main debates about the “new” global economy and their implications for practice and policy. Experts from academia and business will share their findings about, and direct experiences with, different aspects of globalization.","departments":["Global Studies and Languages","Political Science"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Globalization","International Economics","Political Science","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2005","instructors":["Dr. Serenella Sferza","Prof. Suzanne Berger"],"url":"https://ocw.mit.edu/courses/17-199j-working-in-a-global-economy-fall-2005/","views":1163},{"id":"21G.221+spring_2019","numbers":["21G.221"],"title":"Communicating in American Culture(s)","summary":"In Communicating in American Culture(s), bilingual students examine how various aspects of American culture—history, geography, institutions, traditions, values—have shaped dominant Anglo-American communication norms and responses to critical events in the world. In addition, you can expect to practice and strengthen your analytical and communication skills in a carefully scaffolded manner, starting with frequent short writing and speaking tasks and progressing to longer, more formal tasks.","departments":["Global Studies and Languages"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Communication","Cultural Anthropology","English as a Second Language","Humanities","Language","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2019","instructors":["Jane Dunphy"],"url":"https://ocw.mit.edu/courses/21g-221-communicating-in-american-culture-s-spring-2019/","views":1162},{"id":"RES.21H-001+spring_2021","numbers":["RES.21H-001"],"title":"Visualizing the Birth of Modern Tokyo","summary":"This course shows the emergence of modern Tokyo through artist renderings of its neighborhoods, daily life and nightlife, nested between its recurring destruction by natural disasters and war. Students will learn about the tradition of the “100 views,” and through these composite depictions of the city, will witness the excitement and loss of change. Kiyochika Kobayashi’s woodblock prints of Tokyo in the late 1870s convey a moody view on the cusp of change as the new capital, formerly Edo, begins modernization with Western influences. Koizumi Kishio’s depictions of the “Imperial Capital” in the 1930s show the lively cosmopolitanism and move toward ultranationalism that placed the emperor at its center.\n\nThis course is part of the Open Learning Library, which is free to use. You have the option to sign up and enroll in the course if you want to track your progress, or you can view and use all the materials without enrolling.","departments":["History"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Asian History","Fine Arts","History","Humanities","Modern History","Visual Arts"],"levels":["Undergraduate"],"features":[],"term":"Spring 2021","instructors":["Prof. Shigeru Miyagawa"],"url":"https://ocw.mit.edu/courses/res-21h-001-visualizing-the-birth-of-modern-tokyo-spring-2021/","views":1161},{"id":"15.341+fall_2006","numbers":["15.341"],"title":"Individuals, Groups, and Organizations","summary":"This class develops basic concepts for understanding individual, group, and organizational behavior through the critical analysis of important works in the field. Among the areas covered are: individual affect and cognition; group process and performance; and organizational culture and adaptation. The class also emphasizes the use of behavioral science concepts for stimulating new and useful organizational behavior research.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Organizational Behavior","Psychology","Social Science","Sociology"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2006","instructors":["Prof. John Carroll"],"url":"https://ocw.mit.edu/courses/15-341-individuals-groups-and-organizations-fall-2006/","views":1160},{"id":"21L.488+spring_2018","numbers":["21L.488"],"title":"Contemporary Literature: Street Haunting in the Global City","summary":"In this class we will focus on the connections between urban exploration and reading, attending to such shared concerns as pacing, legibility, transgression, attention and distraction, tracing and retracing, and memory. This idea of re-reading cities will be both a theme centering our discussions and a guiding principle of the course design, as we continuously loop back, returning to haunt texts we left behind earlier in the semester.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2018","instructors":["Dr. Anna J. Abramson"],"url":"https://ocw.mit.edu/courses/21l-488-contemporary-literature-street-haunting-in-the-global-city-spring-2018/","views":1159},{"id":"21H.234J+spring_2005","numbers":["21H.234J","11.339J","11.026J"],"title":"Downtown","summary":"This seminar focuses on downtowns in U.S. cities from the late nineteenth century to the late twentieth century. Emphasis will be placed on downtown as an idea, place, and cluster of interests; on the changing character of downtown; and on recent efforts to rebuild it. Subjects to be considered will include subways, skyscrapers, highways, urban renewal, and retail centers. The focus will be on readings, discussions, and individual research projects.","departments":["History","Urban Studies and Planning"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["American History","Architecture","Environmental Design","Fine Arts","History","Humanities","Social Science","Urban Studies"],"levels":["Undergraduate","Graduate"],"features":["Written Assignments with Examples"],"term":"Spring 2005","instructors":["Prof. Bernard Frieden","Prof. Robert Fogelson"],"url":"https://ocw.mit.edu/courses/21h-234j-downtown-spring-2005/","views":1159},{"id":"12.119+spring_2011","numbers":["12.119"],"title":"Analytical Techniques for Studying Environmental and Geologic Samples","summary":"This is a laboratory course supplemented by lectures that focus on selected analytical facilities that are commonly used to determine the mineralogy, elemental abundance and isotopic ratios of Sr and Pb in rocks, soils, sediments and water.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Analytical Chemistry","Chemistry","Earth Science","Environmental Science","Geochemistry","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2011","instructors":["Prof. Samuel Bowring","Prof. Edward Boyle","Dr. Nilanjan Chatterjee","Dr. Francis Dudas"],"url":"https://ocw.mit.edu/courses/12-119-analytical-techniques-for-studying-environmental-and-geologic-samples-spring-2011/","views":1155},{"id":"RES.6-010+spring_2013","numbers":["RES.6-010"],"title":"Electronic Feedback Systems","summary":"Feedback control is an important technique that is used in many modern electronic and electromechanical systems. The successful inclusion of this technique improves performance, reliability, and cost effectiveness of many designs. In this series of lectures we introduce the analytical concepts that underlie classical feedback system design. The application of these concepts is illustrated by a variety of experiments and demonstration systems. The diversity of the demonstration systems reinforces the value of the analytic methods.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering"],"topics":["Electrical Engineering","Electronics","Engineering"],"levels":["Undergraduate"],"features":["Lecture Videos","Open Textbooks","Problem Set Solutions","Problem Sets"],"term":"Spring 2013","instructors":["James Roberge"],"url":"https://ocw.mit.edu/courses/res-6-010-electronic-feedback-systems-spring-2013/","views":1155},{"id":"21W.034+fall_2016","numbers":["21W.034"],"title":"Science Writing and New Media: Perspectives on Medicine and Public Health","summary":"Like other scientists, medical researchers and clinicians must be capable of presenting their work to an audience of professional peers. Unlike many scientists, however, physicians must routinely translate their sophisticated knowledge into lay terms for their own patients and for the education of the public at large. A surprising number of physicians write for less utilitarian reasons as well, choosing the narrative essay as a means of exploring the non-technical issues that emerge in their clinical practice. Over the course of the semester, we will explore the full range of writings by physicians and other health practitioners.","departments":["Comparative Media Studies/Writing"],"areas":["Health & Medicine","Humanities"],"topics":["Academic Writing","Health and Medicine","Humanities","Literature","Nonfiction Prose","Public Health"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2016","instructors":["Dr. Cynthia Taft"],"url":"https://ocw.mit.edu/courses/21w-034-science-writing-and-new-media-perspectives-on-medicine-and-public-health-fall-2016/","views":1155},{"id":"21W.775+spring_2017","numbers":["21W.775"],"title":"Writing about Nature and Environmental Issues","summary":"In this course we will read and write about works that explore symbolic encounters in the American landscape. Some of the assigned works look at uneasy encounters between ordinary individuals and animals—wolves, eagles, sandhill cranes—that Americans have invested with symbolic significance; others explore conflicts between the pragmatic American impulse to impose order on unruly nature and the equally American inclination to enshrine the unaltered landscape.","departments":["Comparative Media Studies/Writing"],"areas":["Humanities"],"topics":["American Literature","Creative Writing","History","Humanities","Literature","Nonfiction Prose"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments with Examples"],"term":"Spring 2017","instructors":["Dr. Cynthia Taft"],"url":"https://ocw.mit.edu/courses/21w-775-writing-about-nature-and-environmental-issues-spring-2017/","views":1155},{"id":"MAS.S63+fall_2013","numbers":["MAS.S63"],"title":"Engineering Health: Towards the Tricorder","summary":"Students will learn to fabricate, remix, and design detection and monitoring devices for health following the core focus of the Tricorder: a portable, handheld diagnostic device which can brings health solutions to consumers at home or in remote parts of the world. Inspired by the Tricorder X-Prize (with a purse of $10 million), students will aim to create specific component technologies that integrate into a comprehensive Tricorder mechanism capable of reading vital signs and specific disease biomarker detection. Component areas will include optical, electric, biochemical, and molecular diagnostics.","departments":["Media Arts and Sciences"],"areas":["Health & Medicine"],"topics":["Biomedical Enterprise","Biomedical Instrumentation","Biomedical Signal and Image Processing","Health and Medicine"],"levels":["Graduate"],"features":[],"term":"Fall 2013","instructors":["Prof. Ramesh Raskar","Jose Gomez-Marquez","Anna Young"],"url":"https://ocw.mit.edu/courses/mas-s63-engineering-health-towards-the-tricorder-fall-2013/","views":1154},{"id":"17.951+spring_2009","numbers":["17.951"],"title":"Nuclear Weapons in International Politics: Past, Present and Future","summary":"This course will expose students to tools and methods of analysis for use in assessing the challenges and dangers associated with nuclear weapons in international politics. The first two weeks of the course will look at the technology and design of nuclear weapons and their means of production. The next five weeks will look at the role they played in the Cold War, the organizations that managed them, the technologies that were developed to deliver them, and the methods used to analyze nuclear force structures and model nuclear exchanges. The last six weeks of the course will look at theories and cases of nuclear decision making beyond the original five weapon states, and will look particularly at why states pursue or forego nuclear weapons, the role that individuals and institutions play, and the potential for both new sources of proliferation and new consequences.","departments":["Political Science"],"areas":["Humanities","Social Sciences"],"topics":["History","Humanities","International Relations","Military History","Military Studies","Political Science","Public Administration","Security Studies","Social Science"],"levels":["Graduate"],"features":["Projects"],"term":"Spring 2009","instructors":["Prof. Owen Cote","Dr. James Walsh"],"url":"https://ocw.mit.edu/courses/17-951-nuclear-weapons-in-international-politics-past-present-and-future-spring-2009/","views":1154},{"id":"21G.041+fall_2004","numbers":["21G.041"],"title":"Topics in South Asian Literature and Culture","summary":"This subject aims to provide an overview of contemporary texts in regional languages in South Asian Literature and Cinema. We will cover major authors and film makers, writing from Bangladesh, India, Nepal, Pakistan and Sri Lanka. Within India, we will look at authors and directors working in different regional languages and as we examine their different socio-cultural, political and historical contexts we will attempt to understand what it means to study them under the all-unifying category of “South Asian Literature and Culture”. Some of the major issues we shall explore include caste, gender, globalization and social change. We will end with exploring some of the newer, younger writers and directors and try to analyze some of the thematic and formal shifts in their work. Authors include Ashapurna Devi, Manto, Vijayan, Premchand, Mohanty, and Nasreen and film makers will include Adoor Gopalakrishnan, Satyajit Ray, Shyam Benegal, Aparna Sen and Rituporno Ghosh.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Asian Studies","Cultural Anthropology","Fine Arts","Humanities","International Literature","Literature","Media Studies","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2004","instructors":["Arundhati Banerjee"],"url":"https://ocw.mit.edu/courses/21g-041-topics-in-south-asian-literature-and-culture-fall-2004/","views":1154},{"id":"18.906+spring_2020","numbers":["18.906"],"title":"Algebraic Topology II","summary":"This is the second part of the two-course series on algebraic topology. Topics include basic homotopy theory, obstruction theory, classifying spaces, spectral sequences, characteristic classes, and Steenrod operations.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2020","instructors":["Prof. Haynes Miller"],"url":"https://ocw.mit.edu/courses/18-906-algebraic-topology-ii-spring-2020/","views":1153},{"id":"4.125A+fall_2005","numbers":["4.125A"],"title":"Architecture Studio: Building in Landscapes","summary":"This subject introduces skills needed to build within a landscape establishing continuities between the built and natural world. Students learn to build appropriately through analysis of landscape and climate for a chosen site, and to conceptualize design decisions through drawings and models.\n\nThis class was taught concurrently with 4.125B. Some of the assignments are the same, some are different, and the sites for the final project are different. But since they were taught in tandem, it would be useful to look at both together.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Architectural Design","Architecture","Environmental Design","Fine Arts"],"levels":["Undergraduate"],"features":["Design Assignments with Examples","Image Gallery"],"term":"Fall 2005","instructors":["Prof. Alan Joslin"],"url":"https://ocw.mit.edu/courses/4-125a-architecture-studio-building-in-landscapes-fall-2005/","views":1151},{"id":"8.811+fall_2005","numbers":["8.811"],"title":"Particle Physics II","summary":"8.811, Particle Physics II, describes essential research in High Energy Physics. We derive the Standard Model (SM) first using a bottom up method based on Unitarity, in addition to the usual top down method using SU3xSU2xU1. We describe and analyze several classical experiments, which established the SM, as examples on how to design experiments. Further topics include heavy flavor physics, high-precision tests of the Standard Model, neutrino oscillations, searches for new phenomena (compositeness, supersymmetry, technical color, and GUTs), and discussion of expectations from future accelerators (B factory, LHC, large electron-positron linear colliders, etc). The term paper requires the students to have constant discussions with the instructor throughout the semester on theories, physics, measurables, signatures, detectors, resolution, background identification and elimination, signal to noise and statistical analysis.","departments":["Physics"],"areas":["Science & Math"],"topics":["High Energy Physics","Particle Physics","Physics","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets"],"term":"Fall 2005","instructors":["Prof. Min Chen"],"url":"https://ocw.mit.edu/courses/8-811-particle-physics-ii-fall-2005/","views":1150},{"id":"RES.LL-002+spring_2010","numbers":["RES.LL-002"],"title":"Adaptive Antennas and Phased Arrays","summary":"The 16 lectures in this course cover the topics of adaptive antennas and phased arrays. Both theory and experiments are covered in the lectures. Part one (lectures 1 to 7) covers adaptive antennas. Part two (lectures 8 to 16) covers phased arrays. Parts one and two can be studied independently (in either order). The intended audience for this course is primarily practicing engineers and students in electrical engineering. This course is presented by Dr. Alan J. Fenn, senior staff member at MIT Lincoln Laboratory.\n\nOnline Publication","departments":[],"areas":["Engineering","Science & Math"],"topics":["Electrical Engineering","Electromagnetism","Electronics","Engineering","Physics","Science","Signal Processing"],"levels":["Undergraduate"],"features":[],"term":"Spring 2010","instructors":["Alan J. Fenn"],"url":"https://ocw.mit.edu/courses/res-ll-002-adaptive-antennas-and-phased-arrays-spring-2010/","views":1145},{"id":"7.13+fall_2008","numbers":["7.13"],"title":"Experimental Microbial Genetics","summary":"In this class, students engage in independent research projects to probe various aspects of the physiology of the bacterium Pseudomonas aeruginosa PA14, an opportunistic pathogen isolated from the lungs of cystic fibrosis patients. Students use molecular genetics to examine survival in stationary phase, antibiotic resistance, phase variation, toxin production, and secondary metabolite production.\n\nProjects aim to discover the molecular basis for these processes using both classical and cutting-edge techniques. These include plasmid manipulation, genetic complementation, mutagenesis, PCR, DNA sequencing, enzyme assays, and gene expression studies. Instruction and practice in written and oral communication are also emphasized.\n\nWARNING NOTICE\n\nThe experiments described in these materials are potentially hazardous and require a high level of safety training, special facilities and equipment, and supervision by appropriate individuals. You bear the sole responsibility, liability, and risk for the implementation of such safety procedures and measures. MIT shall have no responsibility, liability, or risk for the content or implementation of any of the material presented.\n\nLegal Notice","departments":["Biology"],"areas":["Science & Math"],"topics":["Biology","Genetics","Microbiology","Science"],"levels":["Undergraduate"],"features":["Problem Sets","Projects","Written Assignments"],"term":"Fall 2008","instructors":["Prof. Dianne Newman","Dr. Janis Melvold","Dr. Laura Croal","Prof. Michael Laub"],"url":"https://ocw.mit.edu/courses/7-13-experimental-microbial-genetics-fall-2008/","views":1145},{"id":"21H.907+fall_2000","numbers":["21H.907"],"title":"Trials in History","summary":"This seminar examines a number of famous trials in European and American history. It considers the salient issues (political, social, cultural) of several trials, the ways in which each trial was constructed and covered in public discussions at the time, the ways in which legal reasoning and storytelling interacted in each trial and in the later retellings of the trial, and the ways in which trials serve as both spectacle and a forum for moral and political reasoning. Students have an opportunity to study one trial in depth and present their findings to the class.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["American History","European History","History","Humanities","Legal Studies","Social Justice","Social Science","Sociology"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2000","instructors":["Prof. Elizabeth A. Wood"],"url":"https://ocw.mit.edu/courses/21h-907-trials-in-history-fall-2000/","views":1141},{"id":"15.224+spring_2003","numbers":["15.224"],"title":"Global Markets, National Politics and the Competitive Advantage of Firms","summary":"This course examines the opportunities and risks firms face in today’s global world. The course provides conceptual tools for analyzing how governments and a variety of social and economic institutions influence competition among firms embedded in different national settings. Public policies and institutions that shape competitive outcomes are examined through cases and analytic readings on different companies and industries operating in both developed and emerging markets. In addition to traditional case/class discussions, this course will include some presentations by various guest speakers. The hope is that greater exposure to/interaction with these real-world practitioners will “bring to life” some of the issues discussed in the readings/cases. Whenever possible, informal dinners and/or coffees will be organized for small groups of students interested in meeting with our guest speakers.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Globalization","Industrial Organization","International Economics","Public Administration","Public Policy","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2003","instructors":["Prof. Richard Locke"],"url":"https://ocw.mit.edu/courses/15-224-global-markets-national-politics-and-the-competitive-advantage-of-firms-spring-2003/","views":1140},{"id":"11.201+fall_2010","numbers":["11.201"],"title":"Gateway to the Profession of Planning","summary":"The purpose of the course is to cultivate the sensibilities necessary for effective planning practice. This objective rests on one key assumption: that a set of key sensibilities creates the right mindset for practice.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Social Science","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2010","instructors":["Prof. Bishwapriya Sanyal"],"url":"https://ocw.mit.edu/courses/11-201-gateway-to-the-profession-of-planning-fall-2010/","views":1137},{"id":"12.802+spring_2008","numbers":["12.802"],"title":"Wave Motion in the Ocean and the Atmosphere","summary":"This course is an introduction to basic ideas of geophysical wave motion in rotating, stratified, and rotating-stratified fluids. Subject begins with general wave concepts of phase and group velocity. It also covers the dynamics and kinematics of gravity waves with a focus on dispersion, energy flux, initial value problems, etc.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Atmospheric Science","Earth Science","Engineering","Environmental Engineering","Fluid Mechanics","Geophysics","Hydrodynamics","Hydrodynamics and Coastal Engineering","Mechanical Engineering","Ocean Engineering","Oceanography","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2008","instructors":["Prof. Paola Rizzoli"],"url":"https://ocw.mit.edu/courses/12-802-wave-motion-in-the-ocean-and-the-atmosphere-spring-2008/","views":1135},{"id":"9.63+fall_2002","numbers":["9.63"],"title":"Laboratory in Cognitive Science","summary":"Teaches principles of experimental methods in human perception and cognition, including design and statistical analysis. Combines lectures and hands-on experimental exercises; requires an independent experimental project. Some experience in programming desirable. To foster improved writing and presentation skills in conducting and critiquing research in cognitive science, students are required to provide reports and give oral presentations of three team experiments; a fourth individually conducted experiment includes a proposal with revision, and concluding written and oral reports.","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math"],"topics":["Cognitive Science","Science"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2002","instructors":["Prof. Pawan Sinha"],"url":"https://ocw.mit.edu/courses/9-63-laboratory-in-cognitive-science-fall-2002/","views":1134},{"id":"18.S997+fall_2012","numbers":["18.S997"],"title":"The Polynomial Method","summary":"This course offers an introduction to the polynomial method as applied to solving problems in combinatorics in the last decade. The course also explores the connections between the polynomial method as used in these problems to the polynomial method in other fields, including computer science, number theory, and analysis.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Discrete Mathematics","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2012","instructors":["Prof. Lawrence D Guth"],"url":"https://ocw.mit.edu/courses/18-s997-the-polynomial-method-fall-2012/","views":1132},{"id":"11.013J+spring_2010","numbers":["11.013J","21H.231J"],"title":"American Urban History I","summary":"This course is a seminar on the history of institutions and institutional change in American cities from roughly 1850 to the present. Among the institutions to be looked at are political machines, police departments, courts, schools, prisons, public authorities, and universities. The focus of the course is on readings and discussions.","departments":["History","Urban Studies and Planning"],"areas":["Humanities","Social Sciences"],"topics":["American History","History","Humanities","Public Administration","Social Science","Urban Studies"],"levels":["Undergraduate"],"features":["Projects with Examples"],"term":"Spring 2010","instructors":["Prof. Robert Fogelson"],"url":"https://ocw.mit.edu/courses/11-013j-american-urban-history-i-spring-2010/","views":1129},{"id":"STS.032+spring_2018","numbers":["STS.032"],"title":"Energy, Environment, and Society: Global Politics, Technologies, and Ecologies of the Water-Energy-Food Crises","summary":"With increasing public awareness of the multiple effects of global environmental change, the terms water, energy, and food crisis have become widely used in scientific and political debates on sustainable development and environmental policy. Although each of these crises has distinct drivers and consequences, providing sustainable supplies of water, energy, and food are deeply interrelated challenges and require a profound understanding of the political, socioeconomic, and cultural factors that have historically shaped these interrelations at a local and global scale.","departments":["Science, Technology, and Society"],"areas":["Energy, Climate & Sustainability","Social Sciences"],"topics":["Environmental Policy","Global Poverty","Public Administration","Social Science","Society","The Developing World"],"levels":["Undergraduate"],"features":["Projects","Written Assignments"],"term":"Spring 2018","instructors":["Dr. William San Martin Aedo"],"url":"https://ocw.mit.edu/courses/sts-032-energy-environment-and-society-global-politics-technologies-and-ecologies-of-the-water-energy-food-crises-spring-2018/","views":1129},{"id":"15.566+spring_2003","numbers":["15.566"],"title":"Information Technology as an Integrating Force in Manufacturing","summary":"In virtually every industry and every firm, information technology is driving change, creating opportunities and challenges. Leaders who don’t understand at least the fundamentals of information systems will be at a strategic disadvantage. This course provides broad coverage of technology concepts and trends underlying current and future developments in information technology, and fundamental principles for the effective use of computer-based information systems. There will be a special emphasis on manufacturing. Information Systems topics that will be covered include networks and distributed computing, including the World Wide Web, hardware and operating systems, software development tools and processes, relational databases, security and cryptography, enterprise applications, B2B, the semantic web and electronic commerce. Sloan LFM students with an interest in Information Systems are encouraged to register for this course.","departments":["Sloan School of Management"],"areas":["Business & Management"],"topics":["Business","Information Technology","Operations Management"],"levels":["Graduate"],"features":["Lecture Notes","Lecture Videos","Written Assignments"],"term":"Spring 2003","instructors":["Prof. Brian Subirana"],"url":"https://ocw.mit.edu/courses/15-566-information-technology-as-an-integrating-force-in-manufacturing-spring-2003/","views":1129},{"id":"18.782+fall_2013","numbers":["18.782"],"title":"Introduction to Arithmetic Geometry","summary":"This course is an introduction to arithmetic geometry, a subject that lies at the intersection of algebraic geometry and number theory. Its primary motivation is the study of classical Diophantine problems from the modern perspective of algebraic geometry.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics","Topology and Geometry"],"levels":["Undergraduate"],"features":["Instructor Insights","Lecture Notes","Problem Sets"],"term":"Fall 2013","instructors":["Andrew V. Sutherland"],"url":"https://ocw.mit.edu/courses/18-782-introduction-to-arithmetic-geometry-fall-2013/","views":1128},{"id":"21H.235+fall_2009","numbers":["21H.235"],"title":"Metropolis: History of New York City","summary":"Hitherto it had gone by the original Indian name Manna-hatta, or as some still have it, ‘The Manhattoes’; but this was now decried as savage and heathenish… At length, when the council was almost in despair, a burgher, remarkable for the size and squareness of his head, proposed that they should call it New-Amsterdam. The proposition took every body by surprise; it was so striking, so apposite, so ingenious. The name was adopted by acclamation, and New-Amsterdam the metropolis was thenceforth called.\n\n—Washington Irving, 1808\n\nIn less tongue-in-cheek style, this course examines the evolution of New York City from 1607 to the present. The readings focus on the city’s social and physical histories, and the class discussions compare New York’s development to patterns in other cities.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["American History","Anthropology","Cultural Anthropology","History","Humanities","Social Science","Urban Studies"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2009","instructors":["Prof. Craig Wilder"],"url":"https://ocw.mit.edu/courses/21h-235-metropolis-history-of-new-york-city-fall-2009/","views":1128},{"id":"CC.111+spring_2013","numbers":["CC.111"],"title":"Modern Conceptions of Freedom","summary":"This course examines the modern definition of freedom, and the obligations that people accept in honoring it. It investigates how these obligations are captured in the principles of our political associations. This course also studies how the centrality of freedom plays out in the political thought of such authors as Hobbes, Locke, Rousseau, Burke and Montesquieu, as well as debating which notions of freedom inspire and sustain the American experiment by careful reading of the documents and arguments of the founding of the United States.\n\nThis course is part of the Concourse program at MIT.","departments":["Concourse"],"areas":["Humanities"],"topics":["Humanities","Philosophy","Political Philosophy"],"levels":["Undergraduate"],"features":[],"term":"Spring 2013","instructors":["Dr. Linda Rabieh"],"url":"https://ocw.mit.edu/courses/cc-111-modern-conceptions-of-freedom-spring-2013/","views":1125},{"id":"8.S271+spring_2022","numbers":["8.S271"],"title":"Nuclear Weapons – History and Future Prospects","summary":"This course was designed to educate students about how nuclear weapons came into being, the physics of these weapons, how they are structured, how they have evolved over the past several decades, efforts to control them and limit the threats that they represent, and what the possibilities for the future are. Many people in our country and other countries are not aware of what an existential threat nuclear weapons represent, and this lack of awareness is an important part of the overall threat.\n\nThe course was taught by an MIT Iterdisciplinary team coordinated by Robert P. Redwine, Professor of Physics Emeritus. The full list of instructors is listed on the course page.","departments":["Physics"],"areas":["Energy, Climate & Sustainability","Humanities","Science & Math","Social Sciences"],"topics":["Atomic, Molecular, Optical Physics","Energy","History","History of Science and Technology","Humanities","Military Studies","Nuclear Energy","Physics","Public Administration","Public Policy","Science","Social Science"],"levels":["Undergraduate"],"features":[],"term":"Spring 2022","instructors":["MIT Interdisciplinary Team: Robert P. Redwine, Professor of Physics Emeritus (Coordinator)"],"url":"https://ocw.mit.edu/courses/8-s271-nuclear-weapons-history-and-future-prospects-spring-2022/","views":1124},{"id":"21L.512+fall_2013","numbers":["21L.512"],"title":"American Authors: Autobiography and Memoir","summary":"What is a “life” when it’s written down? How does memory inform the present? Why are autobiographies and memoirs so popular? This course will address these questions among others, considering the relationship between biography, autobiography, and memoir and between personal and social themes. We will examine classic authors such as Mary Rowlandson, Benjamin Franklin, Frederick Douglass, Harriet Jacobs, and Mark Twain; then more recent examples like Tobias Wolff, Art Spiegelman, Sherman Alexie, Shirley Geok-lin Lim, Edwidge Danticat, and Alison Bechdel.","departments":["Literature"],"areas":["Humanities"],"topics":["American Literature","Criticism","Humanities","Literature"],"levels":["Undergraduate"],"features":["Instructor Insights","Written Assignments"],"term":"Fall 2013","instructors":["Dr. Wyn Kelley"],"url":"https://ocw.mit.edu/courses/21l-512-american-authors-autobiography-and-memoir-fall-2013/","views":1123},{"id":"RES.15-003+spring_2016","numbers":["RES.15-003"],"title":"Shaping the Future of Work (15.662x)","summary":"The goal of this course is to explore and develop plans of action for improving the job and career opportunities for today and tomorrow’s workforce. If we take the right actions we can shape the future of work in ways that meet the needs of workers, families, and their economies and societies. To do so we first have to understand how the world of work is changing, how firms can compete and prosper and support good jobs and careers, and how to update the policies and practices governing the world of work.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Industrial Organization","Industrial Relations and Human Resource Management","Labor Economics","Public Administration","Social Science","Social Welfare"],"levels":["Graduate"],"features":["Instructor Insights","Lecture Videos"],"term":"Spring 2016","instructors":["Prof. Thomas A. Kochan"],"url":"https://ocw.mit.edu/courses/res-15-003-shaping-the-future-of-work-15-662x-spring-2016/","views":1121},{"id":"11.945+spring_2004","numbers":["11.945"],"title":"Springfield Studio","summary":"The Springfield Studio is a practicum design course that focuses on the physical, programmatic, and social renewal of an urban community in Springfield, Massachusetts by combining classroom work with an applied class project. The course content covers the areas of physical design/urban design and the related analysis and planning tools used to understand and assess urban conditions from a design and development perspective. Urban design issues are investigated in the context of social and economic challenges within the community. Thus, the course has dual goals:\n\n• analyze physical conditions in the community, assess community need, propose physical design interventions; and\n• assess community capacity and programmatic needs.\n\nThe ultimate goal is to explore the integration of social, programmatic and physical development interventions in ways that reinforce community revitalization efforts, and to apply this knowledge through the development of a formal neighborhood revitalization plan that addresses community needs.","departments":["Urban Studies and Planning"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Architecture","Community Development","Environmental Design","Fine Arts","Regional Planning","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Activity Assignments","Image Gallery","Projects with Examples"],"term":"Spring 2004","instructors":["Prof. Ceasar McDowell","Prof. Susan Silberberg"],"url":"https://ocw.mit.edu/courses/11-945-springfield-studio-spring-2004/","views":1121},{"id":"24.914+spring_2019","numbers":["24.914"],"title":"Language Variation and Change","summary":"All languages vary across geographic space and between social groups, and languages are always changing. It makes sense to study these phenomena together because they are intimately related: language change is the basic source of language variation. So studying language change can help us to understand variation, and the nature of linguistic variation provides evidence as to how language changes. Both illuminate the nature of grammar. The course will focus largely on variation and change in phonetics and phonology, and most case studies will be drawn from the English language.","departments":["Linguistics and Philosophy"],"areas":["Humanities"],"topics":["Humanities","Linguistics","Phonology","Syntax"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2019","instructors":["Prof. Edward Flemming"],"url":"https://ocw.mit.edu/courses/24-914-language-variation-and-change-spring-2019/","views":1120},{"id":"15.310+spring_2003","numbers":["15.310","15.301"],"title":"Managerial Psychology Laboratory","summary":"Surveys social psychology and organization theory interpreted in the context of the managerial environment. Shares lectures with 15.301, with a separate recitation required. 15.301 is intended primarily for non-Sloan students, both graduate and undergraduate. Deals with a number of diverse subjects, including motivation and reward systems for engineers and scientists in industry; the aging of technical groups; the management of R&D matrix organizations; and the architecture of R&D laboratories and its effect on communication patterns in the organization.\n\n15.301 is a core subject for students majoring in management science. A laboratory is a required element of the course for these students. It involves projects of an applied nature in behavioral science. Emphasizes use of behavioral science research methods to test hypotheses concerning organizational behavior. Instruction and practice in communication include report writing, team decision-making, and oral and visual presentation.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Management","Organizational Behavior","Psychology","Social Science"],"levels":["Graduate"],"features":["Activity Assignments","Lecture Notes","Presentation Assignments","Projects","Written Assignments"],"term":"Spring 2003","instructors":["Prof. Dan Ariely","Prof. Tom Allen"],"url":"https://ocw.mit.edu/courses/15-310-managerial-psychology-laboratory-spring-2003/","views":1119},{"id":"4.366+spring_2004","numbers":["4.366"],"title":"Advanced Projects in the Visual Arts: Personal Narrative","summary":"This advanced video class serves goes into greater depth on the topics covered in 4.351 Introduction to Video. It also will explore the nature and function of narrative in cinema and video through exercises and screenings culminating in a final project. Starting with a brief introduction to the basic principles of classical narrative cinema, we will proceed to explore strategies designed to test the elements of narrative: story trajectory, character development, verisimilitude, time-space continuity, viewer identification, suspension of disbelief, and closure.","departments":["Architecture"],"areas":["Art, Design & Architecture"],"topics":["Digital Media","Film and Video","Fine Arts","Media Studies","Visual Arts"],"levels":["Undergraduate"],"features":["Media Assignments","Projects with Examples"],"term":"Spring 2004","instructors":["Prof. Joe Gibbons"],"url":"https://ocw.mit.edu/courses/4-366-advanced-projects-in-the-visual-arts-personal-narrative-spring-2004/","views":1117},{"id":"8.325+spring_2007","numbers":["8.325"],"title":"Relativistic Quantum Field Theory III","summary":"This course is the third and last term of the quantum field theory sequence. Its aim is the proper theoretical discussion of the physics of the standard model. Topics include: quantum chromodynamics; the Higgs phenomenon and a description of the standard model; deep-inelastic scattering and structure functions; basics of lattice gauge theory; operator products and effective theories; detailed structure of the standard model; spontaneously broken gauge theory and its quantization; instantons and theta-vacua; topological defects; introduction to supersymmetry.","departments":["Physics"],"areas":["Science & Math"],"topics":["Particle Physics","Physics","Quantum Mechanics","Relativity","Science","Theoretical Physics"],"levels":["Graduate"],"features":["Problem Sets"],"term":"Spring 2007","instructors":["Prof. Iain Stewart"],"url":"https://ocw.mit.edu/courses/8-325-relativistic-quantum-field-theory-iii-spring-2007/","views":1116},{"id":"17.951+fall_2005","numbers":["17.951"],"title":"Special Graduate Topic in Political Science: Political Behavior","summary":"This graduate seminar provides an examination of mass and elite political behavior in the United States, with an emphasis on political participation, political inequality, elections, voting behavior, and political organizations.","departments":["Political Science"],"areas":["Humanities","Social Sciences"],"topics":["American Politics","Humanities","Philosophy","Political Philosophy","Political Science","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2005","instructors":["Prof. Andrea Campbell","Prof. Barry Burden"],"url":"https://ocw.mit.edu/courses/17-951-special-graduate-topic-in-political-science-political-behavior-fall-2005/","views":1116},{"id":"21W.036+spring_2022","numbers":["21W.036"],"title":"Science Writing and New Media: Writing and the Environment","summary":"Environmentalists have traditionally relied upon the power of their prose to transform the thoughts and behavior of their contemporaries. In 1963, Rachel Carson, a marine biologist with a penchant for writing, described a world without wildlife in Silent Spring and altered the way Americans understood their impact on the landscape. Like other writers we will encounter this semester, Carson realized that she could alter the perceptions of her contemporaries only if she was able to transmit her knowledge in engaging and accessible language. We will do our best to follow in her footsteps.","departments":["Comparative Media Studies/Writing"],"areas":["Humanities","Science & Math","Social Sciences"],"topics":["Academic Writing","Communication","Earth Science","Environmental Science","Humanities","Literature","Nonfiction Prose","Science","Social Science"],"levels":["Undergraduate"],"features":["Editable Files","Readings","Written Assignments"],"term":"Spring 2022","instructors":["Dr. Cynthia Taft"],"url":"https://ocw.mit.edu/courses/21w-036-science-writing-and-new-media-writing-and-the-environment-spring-2022/","views":1110},{"id":"12.491+fall_2005","numbers":["12.491"],"title":"Advanced Seminar in Geology and Geochemistry: Organic Geochemistry","summary":"12.491 is a seminar focusing on problems of current interest in geology and geochemistry. For Fall 2005, the topic is organic geochemistry. Lectures and readings cover recent research in the development and properties of organic matter.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Biochemistry","Biology","Chemistry","Earth Science","Geobiology","Geochemistry","Geology","Organic Chemistry","Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2005","instructors":["Prof. Roger Summons"],"url":"https://ocw.mit.edu/courses/12-491-advanced-seminar-in-geology-and-geochemistry-organic-geochemistry-fall-2005/","views":1109},{"id":"ES.114+fall_2018","numbers":["ES.114"],"title":"Non-violence as a Way of Life","summary":"This course addresses the philosophical question of what a non-violent life entails. It investigates its ethical dimensions and challenges, and considers whether we can derive a comprehensive moral theory from the principle of non-violence. In addition, it discusses the issues of lying, the duty to forgive, non-violent communication, the ethics of our relationship to anger, the possibility of loving enemies, and the ethics of punishment and rehabilitation. Readings are included from primary exponents of non-violence, such as Tolstoy, Gandhi, and King.\n\nThis course is part of the Experimental Study Group at MIT.","departments":["Experimental Study Group"],"areas":["Humanities"],"topics":["Classics","Ethics","Humanities","Literature","Philosophy"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2018","instructors":["Dr. Lee Perlman"],"url":"https://ocw.mit.edu/courses/es-114-non-violence-as-a-way-of-life-fall-2018/","views":1107},{"id":"21A.101J (formerly 21A.218J)+spring_2010","numbers":["21A.101J (formerly 21A.218J)","WGS.170J"],"title":"Identity and Difference","summary":"This course explores how identities, whether of individuals or groups, are produced, maintained, and transformed. Students will be introduced to various theoretical perspectives that deal with identity formation, including constructions of “the normal.” We will explore the utility of these perspectives for understanding identity components such as gender, sexual orientation, race, ethnicity, religion, language, social class, and bodily difference. By semester’s end students will understand better how an individual can be at once cause and consequence of society, a unique agent of social action as well as a social product.","departments":["Anthropology","Women's and Gender Studies"],"areas":["Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Ethnography","Gender Studies","Social Anthropology","Social Science","Society"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2010","instructors":["Prof. Jean Jackson"],"url":"https://ocw.mit.edu/courses/21a-218j-identity-and-difference-spring-2010/","views":1106},{"id":"12.110+spring_2007","numbers":["12.110"],"title":"Sedimentary Geology","summary":"Survey of the important aspects of modern sediments and ancient sedimentary rocks. Emphasis is on fundamental materials, features, and processes. Textures of siliciclastic sediments and sedimentary rocks: particle size, particle shape, and particle packing. Mechanics of sediment transport. Survey of siliciclastic sedimentary rocks: sandstones, conglomerates, and shales. Carbonate sediments and sedimentary rocks; cherts; evaporites. Siliciclastic and carbonate diagenesis. Paleontology, with special reference to fossils in sedimentary rocks. Modern and ancient depositional environments. Stratigraphy. Sedimentary basins. Fossil fuels: coal, petroleum.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geochemistry","Geology","Geophysics","Oceanography","Science"],"levels":["Undergraduate"],"features":["Activity Assignments with Examples","Lecture Notes"],"term":"Spring 2007","instructors":["Prof. John Southard"],"url":"https://ocw.mit.edu/courses/12-110-sedimentary-geology-spring-2007/","views":1103},{"id":"17.317+spring_2006","numbers":["17.317"],"title":"U.S. Social Policy","summary":"This subject examines the historical development and contemporary politics of social policy in the United States. We will discuss the kinds of risks individuals face over a lifetime and why some are ameliorated by social policy while others are not (and how the U.S. is similar or different from other countries in this regard). We will examine the policymaking process in the U.S., why some alternatives are implemented and others abandoned, why some interests are privileged over others, and how the designs of policies can feed back and shape politics in a given policy area. Along the way we will examine interactions among political institutions, policy elites, the media, and the mass public.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","Political Science","Public Administration","Public Policy","Social Science","Social Welfare"],"levels":["Undergraduate"],"features":[],"term":"Spring 2006","instructors":["Prof. Andrea Campbell"],"url":"https://ocw.mit.edu/courses/17-317-u-s-social-policy-spring-2006/","views":1103},{"id":"RES.6-015+spring_2026","numbers":["RES.6-015"],"title":"Discrete-Time Signals and Systems: An Operator Approach","summary":"This online textbook introduces a powerful analytical framework for designing systems across engineering disciplines, from electronics to mechanical and thermal applications. Derived from MIT’s foundational Signals and Systems course (6.003), it takes a modern perspective. While traditional courses emphasize continuous-time analog circuits, today’s engineers rely primarily on digital technology and discrete-time simulation.","departments":["Electrical Engineering and Computer Science"],"areas":["Engineering"],"topics":["Digital Systems","Electrical Engineering","Engineering","Signal Processing"],"levels":[],"features":["Open Textbooks"],"term":"Spring 2026","instructors":["Sanjoy Mahajan","Prof. Dennis Freeman"],"url":"https://ocw.mit.edu/courses/res-6-015-discrete-time-signals-and-systems-an-operator-approach/","views":1102},{"id":"6.186+january-iap_2005","numbers":["6.186"],"title":"Mobile Autonomous Systems Laboratory","summary":"MASLab (Mobile Autonomous System Laboratory), also known as 6.186, is a robotics contest. The contest takes place during MIT’s Independent Activities Period and participants earn 6 units of P/F credit and 6 Engineering Design Points. Teams of three to four students have less than a month to build and program sophisticated robots which must explore an unknown playing field and perform a series of tasks.\n\nMASLab provides a significantly more difficult robotics problem than many other university-level robotics contests. Although students know the general size, shape, and color of the floors and walls, the students do not know the exact layout of the playing field. In addition, MASLab robots are completely autonomous, or in other words, the robots operate, calculate, and plan without human intervention. Finally, MASLab is one of the few robotics contests in the country to use a vision based robotics problem.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Artificial Intelligence","Computer Science","Electrical Engineering","Engineering","Mechanical Engineering","Robotics and Control Systems"],"levels":["Undergraduate"],"features":["Lecture Notes"],"term":"January IAP 2005","instructors":["No Faculty","Prof. Leslie Kaelbling"],"url":"https://ocw.mit.edu/courses/6-186-mobile-autonomous-systems-laboratory-january-iap-2005/","views":1102},{"id":"15.229+spring_2012","numbers":["15.229"],"title":"Managing Global Integration","summary":"This course on global integration brings together matters of global markets and institutions, global strategy, organization, and leadership. Global integration, the process by which an organization with units around the world becomes united, will be presented as a link to entrepreneurship and general management. The seminar is offered only to those enrolled in the MIT Sloan Fellows Program and challenges the participants to draw upon their past managerial experiences, especially those affiliated with multinational companies.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Globalization","Management","Organizational Behavior"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2012","instructors":["Prof. José Santos"],"url":"https://ocw.mit.edu/courses/15-229-managing-global-integration-spring-2012/","views":1101},{"id":"24.236+fall_2014","numbers":["24.236","24.636"],"title":"Topics in Social Theory and Practice: Race and Racism","summary":"Courses in the Topics in Social Theory and Practice series feature in-depth considerations of such topics with reflections on their implications for social change.\n\nThe topic for Fall 2014 is race and racism. We will consider a variety of arguments for and against the biological and / or social “reality” of race—taking into account purported races other than those defined by the black / white binary and the intersection of race with other social categories. We will then consider a number of accounts of racism, contemporary manifestations of racism, and potential counter-measures.","departments":["Linguistics and Philosophy"],"areas":["Humanities","Social Sciences"],"topics":["African American Studies","American History","Gender Studies","History","Humanities","Philosophy","Social Science","Society","Sociology"],"levels":["Undergraduate","Graduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Fall 2014","instructors":["Prof. Sally Haslanger"],"url":"https://ocw.mit.edu/courses/24-236-topics-in-social-theory-and-practice-race-and-racism-fall-2014/","views":1101},{"id":"18.786+spring_2006","numbers":["18.786"],"title":"Topics in Algebraic Number Theory","summary":"This course is a first course in algebraic number theory. Topics to be covered include number fields, class numbers, Dirichlet’s units theorem, cyclotomic fields, local fields, valuations, decomposition and inertia groups, ramification, basic analytic methods, and basic class field theory. An additional theme running throughout the course will be the use of computer algebra to investigate number-theoretic questions; this theme will appear primarily in the problem sets.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics"],"levels":["Graduate"],"features":["Exams","Problem Sets"],"term":"Spring 2006","instructors":["Prof. Kiran Kedlaya"],"url":"https://ocw.mit.edu/courses/18-786-topics-in-algebraic-number-theory-spring-2006/","views":1099},{"id":"17.407+spring_2009","numbers":["17.407","17.408"],"title":"Chinese Foreign Policy: International Relations and Strategy","summary":"China’s rise as a great power raises important questions about how that power might be used in its relations with other states. Nowhere are such questions more salient than in the future trajectory of China’s conflict behavior, including its approach to deterrence, crisis management and the use of force. To explore these important questions in China’s international relations, this seminar examines the evolution of Chinese strategic thought, in primary sources as well as its reflection in the interactions among Chinese states and between China and other states.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Asian Studies","International Relations","Political Science","Public Administration","Public Policy","Social Science","Society"],"levels":["Undergraduate"],"features":[],"term":"Spring 2009","instructors":["Prof. M. Taylor Fravel"],"url":"https://ocw.mit.edu/courses/17-407-chinese-foreign-policy-international-relations-and-strategy-spring-2009/","views":1097},{"id":"21H.382+fall_2016","numbers":["21H.382"],"title":"Capitalism in the Age of Revolution","summary":"The decades leading up to the Atlantic revolutions of the late eighteenth century were formative moments in the rise of capitalism. The novel instruments of credit, debt, and investment fashioned during this period proved to be enduring sources of financial innovation, but they also generated a great deal of political conflict, particularly during the revolutionary era itself. This seminar examines the debates surrounding large-scale financial and trading corporations and considers the eighteenth century as a period of recurring financial crisis in which corporate power came into sustained and direct contact with emerging republican norms. The seminar ends with a look at the relationship between slavery and the rise of “modern” or “industrial” capitalism in the nineteenth century, as well as some of the critiques of capitalism that emerged out of that experience.","departments":["History"],"areas":["Humanities"],"topics":["American History","European History","History","Humanities","World History"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2016","instructors":["Prof. Malick Ghachem"],"url":"https://ocw.mit.edu/courses/21h-382-capitalism-in-the-age-of-revolution-fall-2016/","views":1096},{"id":"17.55J+fall_2006","numbers":["17.55J","21A.130J (formerly 21A.430J)","21G.084J"],"title":"Introduction to Latin American Studies","summary":"Interdisciplinary introduction to contemporary Latin America, drawing on films, literature, popular press accounts, and scholarly research. Topics include economic development, ethnic and racial identity, religion, revolution, democracy, transitional justice, and the rule of law. Examples draw on a range of countries in the region, especially Mexico, Chile, and Brazil. Includes a heavy oral participation component, with regular breakout groups, formal class presentations on pressing social issues (such as criminal justice and land tenure), and a structured class debate.","departments":["Anthropology","Global Studies and Languages","Political Science"],"areas":["Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Latin and Caribbean Studies","Political Science","Social Science","Society","The Developing World"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2006","instructors":["Prof. Chappell Lawson"],"url":"https://ocw.mit.edu/courses/17-55j-introduction-to-latin-american-studies-fall-2006/","views":1096},{"id":"9.15+fall_2007","numbers":["9.15","9.150"],"title":"Biochemistry and Pharmacology of Synaptic Transmission","summary":"This course considers the process of neurotransmission, especially chemicals used in the brain and elsewhere to carry signals from nerve terminals to the structures they innervate. We focus on monoamine transmitters (acetylcholine; serotonin; dopamine and norepinephrine); we also examine amino acid and peptide transmitters and neuromodulators like adenosine. Macromolecules that mediate neurotransmitter synthesis, release, inactivation and receptor-mediated actions are discussed, as well as factors that regulate their activity and the second-messenger systems and ion fluxes that they control. The involvement of particular neurotransmitters in human diseases is considered.","departments":["Brain and Cognitive Sciences"],"areas":["Health & Medicine","Science & Math"],"topics":["Biochemistry","Biology","Cognitive Science","Health and Medicine","Neurobiology","Pharmacology and Toxicology","Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2007","instructors":["Prof. Richard Wurtman"],"url":"https://ocw.mit.edu/courses/9-15-biochemistry-and-pharmacology-of-synaptic-transmission-fall-2007/","views":1095},{"id":"18.783+spring_2021","numbers":["18.783","18.7831"],"title":"Elliptic Curves","summary":"This course is a computationally focused introduction to elliptic curves, with applications to number theory and cryptography. While this is an introductory course, we will (gently) work our way up to some fairly advanced material, including an overview of the proof of Fermat’s last theorem.","departments":["Mathematics"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Algebra and Number Theory","Computation","Computer Science","Engineering","Mathematics"],"levels":["Undergraduate"],"features":["Editable Files","Instructor Insights","Lecture Notes","Problem Sets"],"term":"Spring 2021","instructors":["Andrew V. Sutherland"],"url":"https://ocw.mit.edu/courses/18-783-elliptic-curves-spring-2021/","views":1094},{"id":"6.881+spring_2005","numbers":["6.881"],"title":"Representation and Modeling for Image Analysis","summary":"Most algorithms in computer vision and image analysis can be understood in terms of two important components: a representation and a modeling/estimation algorithm. The representation defines what information is important about the objects and is used to describe them. The modeling techniques extract the information from images to instantiate the representation for the particular objects present in the scene. In this seminar, we will discuss popular representations (such as contours, level sets, deformation fields) and useful methods that allow us to extract and manipulate image information, including manifold fitting, markov random fields, expectation maximization, clustering and others.\n\nFor each concept – a new representation or an estimation algorithm – a lecture on the mathematical foundations of the concept will be followed by a discussion of two or three relevant research papers in computer vision, medical and biological imaging, that use the concept in different ways. We will aim to understand the fundamental techniques and to recognize situations in which these techniques promise to improve the quality of the analysis.","departments":["Electrical Engineering and Computer Science"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Computational Modeling and Simulation","Computer Science","Electrical Engineering","Engineering","Graphics and Visualization","Signal Processing","Systems Engineering"],"levels":["Graduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Spring 2005","instructors":["Prof. Polina Golland"],"url":"https://ocw.mit.edu/courses/6-881-representation-and-modeling-for-image-analysis-spring-2005/","views":1093},{"id":"EC.721+spring_2009","numbers":["EC.721"],"title":"Wheelchair Design in Developing Countries","summary":"According to the United States Agency for International Development, 20 million people in developing countries require wheelchairs, and the United Nations Development Programme estimates below 1% of their need is being met in Africa by local production. Wheelchair Design in Developing Countries (WDDC) gives students the chance to better the lives of others by improving wheelchairs and tricycles made in the developing world. Lectures will focus on understanding local factors, such as operating environments, social stigmas against the disabled, and manufacturing constraints, and then applying sound scientific/engineering knowledge to develop appropriate technical solutions. Multidisciplinary student teams will conduct term-long projects on topics such as hardware design, manufacturing optimization, biomechanics modeling, and business plan development. Theory will further be connected to real-world implementation during guest lectures by MIT faculty, Third-World community partners, and U.S. wheelchair organizations.\n\nThis class is made possible by an MIT Alumni Sponsored Funding Opportunities grant with additional support from the National Collegiate Inventors and Innovators Alliance (now VentureWell), the MIT Public Service Center, and the MIT Edgerton Center; special thanks to CustomInk.com.","departments":["Edgerton Center"],"areas":["Engineering","Health & Medicine","Social Sciences"],"topics":["Engineering","Health and Medicine","Mechanical Design","Mechanical Engineering","Public Health","Society","The Developing World"],"levels":["Undergraduate"],"features":["Demonstration Videos","Image Gallery","Lecture Notes","Projects with Examples"],"term":"Spring 2009","instructors":["Mr. Amos G. Winter","Amy J. Smith"],"url":"https://ocw.mit.edu/courses/ec-721-wheelchair-design-in-developing-countries-spring-2009/","views":1086},{"id":"21L.448J+fall_2010","numbers":["21L.448J","21W.739J"],"title":"Darwin and Design","summary":"Humans are social animals; social demands, both cooperative and competitive, structure our development, our brain and our mind. This course covers social development, social behaviour, social cognition and social neuroscience, in both human and non-human social animals. Topics include altruism, empathy, communication, theory of mind, aggression, power, groups, mating, and morality. Methods include evolutionary biology, neuroscience, cognitive science, social psychology and anthropology.","departments":["Literature"],"areas":["Humanities","Science & Math"],"topics":["Cognitive Science","History","Humanities","Intellectual History","Literature","Metaphysics","Philosophy","Science"],"levels":["Undergraduate"],"features":["Lecture Videos","Written Assignments"],"term":"Fall 2010","instructors":["Prof. James Paradis"],"url":"https://ocw.mit.edu/courses/21l-448j-darwin-and-design-fall-2010/","views":1082},{"id":"21H.237+fall_2014","numbers":["21H.237"],"title":"The City of Athens in the Age of Pericles","summary":"This course investigates the relationship between urban architecture and political, social, and cultural history of Athens in the 5th and 4th centuries BC. It surveys and analyzes archeological and literary evidence, including the sanctuary of Athena on the Acropolis, the Agora, Greek houses, the histories of Herodotus and Thucydides, plays of Sophocles and Aristophanes, and the panhellenic sanctuaries of Delphi and Olympia.","departments":["History"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Ancient History","Architectural Design","Architecture","Classics","European History","Fine Arts","History","Humanities","Literature"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2014","instructors":["Prof. William Broadhead"],"url":"https://ocw.mit.edu/courses/21h-237-the-city-of-athens-in-the-age-of-pericles-fall-2014/","views":1081},{"id":"11.952+spring_2005","numbers":["11.952"],"title":"Gaoming Studio - China","summary":"The studio will focus on the district of Gaoming, located in the northwest of the Pearl River Delta (PRD) - the fastest growing and most productive region of China. The District has recently completed a planning effort in which several design institutes and a Hong Kong planning firm prepared ideas for a new central area near the river. The class will complement these efforts by focusing on planning and design options on the waterfront of the proposed new district and ways of integrating water/hydrological factors into all aspects and land uses of a modern city (residential, commercial, industrial) - including watershed and natural ecosystem protection, economic and recreational activities, transportation, and tourism.","departments":["Urban Studies and Planning"],"areas":["Art, Design & Architecture","Engineering","Social Sciences"],"topics":["Architecture","Developmental Economics","Economics","Engineering","Environmental Design","Environmental Engineering","Fine Arts","Hydrology and Water Resource Systems","Social Science","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Projects with Examples"],"term":"Spring 2005","instructors":["Prof. Eran Ben-Joseph","Prof. Tunney Lee"],"url":"https://ocw.mit.edu/courses/11-952-gaoming-studio-china-spring-2005/","views":1079},{"id":"PE.920+spring_2005","numbers":["PE.920"],"title":"PE for ME","summary":"The sensing, thinking, moving body is the basis of our experience in the world; it is the very foundation on which cognitive intelligence is built. Physical Intelligence, then, is the inherent ability of the human organism to function in extraordinary accord with its physical environment. This class–a joint offering from the Department of Athletics, Physical Education and Recreation (DAPER) and Department of Mechanical Engineering (ME) for both PE and academic credit–uses the MIT gymnastics gym as a laboratory to explore Physical Intelligence as applied to Mechanical Engineering and design. Readings, discussions and experiential learning introduce various dimensions of Physical Intelligence which students then apply to the design of innovative exercise equipment.","departments":["Athletics, Physical Education and Recreation"],"areas":["Engineering","Health & Medicine"],"topics":["Engineering","Health and Medicine","Mechanical Engineering","Physical Education and Recreation"],"levels":["Undergraduate"],"features":["Projects with Examples"],"term":"Spring 2005","instructors":["Noah Riskin","Prof. Alex Slocum","Aline Newton"],"url":"https://ocw.mit.edu/courses/pe-920-pe-for-me-spring-2005/","views":1077},{"id":"ES.260+spring_2006","numbers":["ES.260"],"title":"Women's Novels: A Weekly Book Club","summary":"This pass/fail seminar should be a fun setting where we can all enjoy a love of good books together. Students will read approximately one novel every two weeks, and the class will discuss each novel in a relaxed and interactive setting, with attention to whatever themes and issues interest them most about each book. We will read a wide mixture of classic and contemporary novels written by women, including: Edith Wharton, The House of Mirth; Toni Morrison, Jazz; Virginia Woolf, Mrs. Dalloway; Alice Walker, The Color Purple; Charlotte Brontë, Jane Eyre; Sheri Reynolds, The Rapture of Canaan; Jane Austen, Pride and Prejudice; and Sylvia Plath, The Bell Jar. Recurrent issues likely to be discussed include: gender, race, and class; romance, love, and marriage; depression and suicide; and conception, childbirth, and parenthood.","departments":["Experimental Study Group"],"areas":["Humanities","Social Sciences"],"topics":["Fiction","Gender Studies","Humanities","Literature","Society","Women's Studies"],"levels":["Undergraduate"],"features":[],"term":"Spring 2006","instructors":["Faye Kasemset","Dr. Holly Sweet","Jocelyn Rodal"],"url":"https://ocw.mit.edu/courses/es-260-womens-novels-a-weekly-book-club-spring-2006/","views":1077},{"id":"WGS.615+fall_2012","numbers":["WGS.615"],"title":"Feminist Inquiry: Strategies for Effective Scholarship","summary":"This course investigates theories and practices of feminist inquiry across a range of disciplines. Feminist research involves rethinking disciplinary assumptions and methodologies, developing new understandings of what counts as knowledge, seeking alternative ways of understanding the origins of problems/issues, formulating new ways of asking questions and redefining the relationship between subjects and objects of study.\n\nWhat makes research distinctively feminist lies in the complex connections between epistemologies, methodologies and research methods. This course explores how these connections are formed in the traditional disciplines and raise questions about why they are inadequate and/or problematic for feminist inquiry and what, specifically, are the feminist critiques of these intersections.\n\nThis course is part of the Graduate Consortium in Women’s Studies at MIT.","departments":["Women's and Gender Studies"],"areas":["Social Sciences"],"topics":["Gender Studies","Society"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2012","instructors":["Prof. Renee Bergland","Prof. Frinde Maher"],"url":"https://ocw.mit.edu/courses/wgs-615-feminist-inquiry-strategies-for-effective-scholarship-fall-2012/","views":1073},{"id":"12.479+spring_2013","numbers":["12.479"],"title":"Trace-Element Geochemistry","summary":"The emphasis of this course is to use Trace Element Geochemistry to understand the origin and evolution of igneous rocks. The approach is to discuss the parameters that control partitioning of trace elements between phases and to develop models for the partitioning of trace elements between phases in igneous systems, especially between minerals and melt. Subsequently, published papers that are examples of utilizing Trace Element Geochemistry are read and discussed.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Analytical Chemistry","Chemistry","Earth Science","Geochemistry","Geology","Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2013","instructors":["Prof. Frederick Frey"],"url":"https://ocw.mit.edu/courses/12-479-trace-element-geochemistry-spring-2013/","views":1073},{"id":"HST.410J+spring_2007","numbers":["HST.410J","6.07J"],"title":"Projects in Microscale Engineering for the Life Sciences","summary":"This course is a project-based introduction to manipulating and characterizing cells and biological molecules using microfabricated tools. It is designed for first year undergraduate students. In the first half of the term, students perform laboratory exercises designed to introduce (1) the design, manufacture, and use of microfluidic channels, (2) techniques for sorting and manipulating cells and biomolecules, and (3) making quantitative measurements using optical detection and fluorescent labeling. In the second half of the term, students work in small groups to design and test a microfluidic device to solve a real-world problem of their choosing. Includes exercises in written and oral communication and team building.","departments":["Electrical Engineering and Computer Science","Health Sciences and Technology"],"areas":["Engineering"],"topics":["Biological Engineering","Biomaterials","Cell and Tissue Engineering","Engineering","Mechanical Engineering","Microtechnology","Nanotechnology"],"levels":["Undergraduate"],"features":["Image Gallery","Lecture Notes","Presentation Assignments","Problem Sets","Written Assignments"],"term":"Spring 2007","instructors":["Prof. Dennis Freeman","Prof. Martha Gray","Prof. Alexander Aranyosi"],"url":"https://ocw.mit.edu/courses/hst-410j-projects-in-microscale-engineering-for-the-life-sciences-spring-2007/","views":1071},{"id":"15.269B+fall_2002","numbers":["15.269B"],"title":"Literature, Ethics and Authority","summary":"Our subject is the ethics of leadership, an examination of the principles appealed to by executive authority when questions arise about its sources and its legitimacy. Most treatments of this subject resort to case-studies in order to illustrate the application of ethical principles to business situations, but our primary emphasis will be upon classic works of imaginative literature, which convey more directly than case-studies the ethical pressures of decision-making. Readings will include works by Shakespeare, Sophocles, Shaw, E.M. Forster, Joseph Conrad, George Orwell, Fyodor Dostoyevsky, and Henrik Ibsen, among others. Topics to be discussed include the sources of authority, the management of consensus, the ideal of vocation, the ethics of deception, the morality of expediency, the requirements of hierarchy, the virtues and vices of loyalty, the relevance of ethical principles in extreme situations.","departments":["Sloan School of Management"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["Anthropology","Business","Ethics","Humanities","Leadership","Literature","Philosophy","Social Anthropology","Social Science"],"levels":["Graduate"],"features":[],"term":"Fall 2002","instructors":["Prof. Alvin Kibel"],"url":"https://ocw.mit.edu/courses/15-269b-literature-ethics-and-authority-fall-2002/","views":1067},{"id":"21H.357+spring_2018","numbers":["21H.357"],"title":"South Asian Migrations","summary":"This course provides a global history of South Asians and introduces students to the cultural, social, economic, and political experiences of immigrants who traveled across the world. It studies how and why South Asians, who have migrated to America, Europe, Africa, the Caribbean and the Middle East, are considered a model minority in some countries and unwanted strangers in others. Through literature, memoirs, films, music, and historical writing, it follows South Asian migrants as they discovered the world beyond India, Pakistan, and Bangladesh.","departments":["History"],"areas":["Humanities"],"topics":["American History","Asian History","History","Humanities","Modern History","World History"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2018","instructors":["Prof. Sana Aiyar"],"url":"https://ocw.mit.edu/courses/21h-357-south-asian-migrations-spring-2018/","views":1067},{"id":"21L.701+fall_2006","numbers":["21L.701"],"title":"Literary Interpretation: Beyond the Limits of the Lyric","summary":"In this seminar we’ll read individual poems closely within a set of questions about the moral and political position of poetry – and of intellectuals – in different cultural contexts. Of course, part of the divergence in the social positions of poetry [and of ’the aesthetic’] depends on the dominant paradigm of the social, political and literary culture; part of the divergence derives from the momentum of literary development in the culture [how did the culture experience modernism?, for instance], and part depends on the different attitudes toward traditional form. We read poets from North America (Whitman, Williams, Lowell, Plath, Bishop), from South America (Neruda), from Western Europe (Yeats), and Eastern Europe (Akhmatova, Szymborska); we conclude with a month dedicated to the work of the Polish poet Czeslaw Milosz, who won the Nobel Prize for literature (the first to win from a position of exile) in 1980.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Humanities","International Literature","Literature","Poetry"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2006","instructors":["Prof. Stephen Tapscott"],"url":"https://ocw.mit.edu/courses/21l-701-literary-interpretation-beyond-the-limits-of-the-lyric-fall-2006/","views":1066},{"id":"21G.504+spring_2020","numbers":["21G.504"],"title":"Japanese IV","summary":"The main objective of this course is to build up basic skills of communication in Japanese using appropriate speech levels in both writing and speaking for various social settings. This course covers Lessons 19 through 23 in the textbook Genki: An Integrated Course in Elementary Japanese II.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","Japanese","Language"],"levels":["Undergraduate"],"features":["Exams","Instructor Insights","Written Assignments"],"term":"Spring 2020","instructors":["Dr. Takako Aikawa","Masami Ikeda-Lamm","Wakana Maekawa","Emiko Rafique"],"url":"https://ocw.mit.edu/courses/21g-504-japanese-iv-spring-2020/","views":1065},{"id":"11.800+spring_2007","numbers":["11.800"],"title":"Doctoral Research Seminar: Knowledge in the Public Arena","summary":"This is a course about how research knowledge and other types of knowledge come to be actionable and influential in the world — or not. The course explores ways to make research knowledge more accessible, credible, and useful in the realm of public policy and practice, a project in which the course faculty collectively bring decades of professional experience, in both academic and non-academic roles.\n\nThe course addresses the politics of the policymaking process, the power of framing and agenda-setting, fads and paradigms in the design professions and society in general, how knowledge diffuses along knowledge and influence networks, and how varied types of knowledge (rational, craft, other) and deliberation shape decision-making and action. The course engages a number of guests to present case studies of research in use (and abuse) in varied fields, highlighting rich areas for potential research contributions, along with major conflicts in public values, political interests, ethical obligations, and more. The resulting dilemmas confront scholars, policymakers, practitioners, and others as they look to research — sometimes — for useful guidance, influence, or both.","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Communication","Political Science","Public Administration","Public Policy","Social Justice","Social Science","Sociology","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Spring 2007","instructors":["Prof. Frank Levy","Prof. Martin Rein","Prof. Xavier de Souza Briggs"],"url":"https://ocw.mit.edu/courses/11-800-doctoral-research-seminar-knowledge-in-the-public-arena-spring-2007/","views":1062},{"id":"15.220+spring_2012","numbers":["15.220"],"title":"Global Strategy and Organization","summary":"This subject focuses on the specifics of strategy and organization of the multinational company, and provides a framework for formulating successful and adaptive strategies in an increasingly complex world economy. Topics include the globalization of industries, the continuing role of country factors in competition, organization of multinational enterprises, and building global networks. This particular version of the subject is taught and tailored specifically to those enrolled in the MIT Sloan Fellows Program.","departments":["Sloan School of Management"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Globalization","Management","Operations Management","Organizational Behavior"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2012","instructors":["Prof. José Santos"],"url":"https://ocw.mit.edu/courses/15-220-global-strategy-and-organization-spring-2012/","views":1062},{"id":"RES.21W-01+fall_2015","numbers":["RES.21W-01"],"title":"Angles","summary":"Angles is an annual online magazine of exemplary writing by MIT students. All of the works published in Angles since its first edition in 2008 were written by students in the introductory writing courses. These courses, designated as CI-HW (Communications-Intensive Humanities Writing) subjects, bring together students who love to write, students who struggle with writing, students who thrive in seminar-style classes, and students who just want a chance to develop their English skills. These students prosper together and produce some remarkable work. Angles has provided them with a public outlet for that work. It also provides the CI-HW instructors with material that inspires and guides their current students.\n\nIn these classes, students learn to read more critically, to address specific audiences for particular purposes, to construct effective arguments and narratives, and to use and cite source material properly. Students in these courses write a great deal; they prewrite, write, revise, and edit their work for content, clarity, tone, and grammar and receive detailed feedback from instructors and classmates. Assigned readings are related to the thematic focus of each course, and are used as demonstrations of writing techniques. The pieces in Angles may be used as teaching tools and practical examples for other students and self-learners to emulate.\n\nYou can find Angles Online.","departments":["Comparative Media Studies/Writing"],"areas":["Humanities","Social Sciences"],"topics":["Academic Writing","Communication","Creative Writing","Humanities","Literature","Nonfiction Prose","Social Science"],"levels":["Non-Credit"],"features":[],"term":"Fall 2015","instructors":["Jared David Berezin","Louise Harrison Lepera","Lucy Marx","Karen Boiko","Dr. Cynthia Taft","Dr. Andrea Walsh","Jane Kokernak"],"url":"https://ocw.mit.edu/courses/res-21w-01-angles-fall-2015/","views":1060},{"id":"21H.443+spring_2006","numbers":["21H.443"],"title":"European Imperialism in the 19th and 20th Centuries","summary":"From pineapples grown in Hawaii to English-speaking call centers outsourced to India, the legacy of the “Age of Imperialism” appears everywhere in our modern world. This class explores the history of European imperialism in its political, economic, and cultural dimensions from the 1840s through the 1960s.","departments":["History"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["Business","European History","Globalization","History","Humanities","Modern History","Philosophy","Political Philosophy"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2006","instructors":["Prof. David Ciarlo"],"url":"https://ocw.mit.edu/courses/21h-443-european-imperialism-in-the-19th-and-20th-centuries-spring-2006/","views":1060},{"id":"17.524+fall_2004","numbers":["17.524"],"title":"Nationalism","summary":"This course provides a broad overview of the theories of and approaches to the study of nationalist thought and practice. It also explores the related phenomena termed nationalism: national consciousness and identity, nations, nation-states, and nationalist ideologies and nationalist movements. The course analyzes nationalism’s emergence and endurance as a factor in modern politics and society. Topics include: nationalism and state-building, nationalism and economic modernization, nationalism and democratization, and nationalism and religious conflict.","departments":["Political Science"],"areas":["Humanities","Social Sciences"],"topics":["Humanities","Philosophy","Political Philosophy","Political Science","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. Melissa Nobles"],"url":"https://ocw.mit.edu/courses/17-524-nationalism-fall-2004/","views":1059},{"id":"ESD.86+spring_2007","numbers":["ESD.86"],"title":"Models, Data and Inference for Socio-Technical Systems","summary":"In this class, students use data and systems knowledge to build models of complex socio-technical systems for improved system design and decision-making. Students will enhance their model-building skills, through review and extension of functions of random variables, Poisson processes, and Markov processes; move from applied probability to statistics via Chi-squared t and f tests, derived as functions of random variables; and review classical statistics, hypothesis tests, regression, correlation and causation, simple data mining techniques, and Bayesian vs. classical statistics. A class project is required.","departments":["Engineering Systems Division"],"areas":["Data Science, Analytics & Computer Technology","Engineering","Science & Math"],"topics":["Computational Modeling and Simulation","Computer Science","Data Mining","Engineering","Mathematics","Probability and Statistics","Systems Engineering"],"levels":["Graduate"],"features":["Exams","Lecture Notes","Problem Set Solutions","Problem Sets","Written Assignments with Examples"],"term":"Spring 2007","instructors":["Prof. Daniel Frey","Richard C. Larson"],"url":"https://ocw.mit.edu/courses/esd-86-models-data-and-inference-for-socio-technical-systems-spring-2007/","views":1057},{"id":"21H.580+fall_2003","numbers":["21H.580"],"title":"From the Silk Road to the Great Game: China, Russia, and Central Eurasia","summary":"This subject examines interactions across the Eurasian continent between Russians, Chinese, Mongolian nomads, and Turkic oasis dwellers during the last millennium and a half. As empires rose and fell, religions, trade, and war flowed back and forth continuously across this vast space. Today, the fall of the Soviet Union and China’s reforms have opened up new opportunities for cultural interaction.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["Ancient History","Asian History","Asian Studies","European and Russian Studies","History","Humanities","Society"],"levels":["Undergraduate"],"features":["Lecture Notes"],"term":"Fall 2003","instructors":["Prof. Peter C. Perdue"],"url":"https://ocw.mit.edu/courses/21h-580-from-the-silk-road-to-the-great-game-china-russia-and-central-eurasia-fall-2003/","views":1053},{"id":"16.682+spring_2006","numbers":["16.682"],"title":"Prototyping Avionics","summary":"In the past building prototypes of electronic components for new projects/products was limited to using protoboards and wirewrap. Manufacturing a printed-circuit-board was limited to final production, where mistakes in the implementation meant physically cutting traces on the board and adding wire jumpers - the final products would have these fixes on them! Today that is no longer the case, while you will still cut traces and use jumpers when debugging a board, manufacturing a new final version without the errors is a simple and relatively inexpensive task. For that matter, manufacturing a prototype printed circuit board which you know is likely to have errors but which will get the design substantially closer to the final product than a protoboard setup is not only possible, but desirable. In this class, you’ll learn to design, build, and debug printed-circuit-boards.","departments":["Aeronautics and Astronautics"],"areas":["Engineering"],"topics":["Aerospace Engineering","Avionics","Electrical Engineering","Engineering"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2006","instructors":["Dr. Alvar Saenz-Otero"],"url":"https://ocw.mit.edu/courses/16-682-prototyping-avionics-spring-2006/","views":1053},{"id":"11.967+january-iap_2007","numbers":["11.967"],"title":"Special Studies in Urban Studies and Planning: Economic Development Planning Skills","summary":"This intensive and brief 4-day seminar, taught during MIT’s Independent Activities Period in January, uses a case set in Hartford, Vermont to introduce economic development planning skills to students in the Master in City Planning (MCP) Degree Program. It introduces analytical tools that are used to assess local economic development conditions, issues, and opportunities as part of formulating economic development plans. The course is designed to provide MCP students with skills needed for applied economic development planning work in other courses, particularly Economic Development Planning (11.438) and Revitalizing Urban Main Streets (11.439).","departments":["Urban Studies and Planning"],"areas":["Social Sciences"],"topics":["Community Development","Developmental Economics","Economics","Social Science","Sociology","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets","Projects with Examples","Written Assignments"],"term":"January IAP 2007","instructors":["Prof. Karl Seidman"],"url":"https://ocw.mit.edu/courses/11-967-special-studies-in-urban-studies-and-planning-economic-development-planning-skills-january-iap-2007/","views":1053},{"id":"WGS.150+spring_2015","numbers":["WGS.150"],"title":"Gender, Power, Leadership and the Workplace","summary":"The course will focus primarily on contemporary discourses concerning gender inequality. Most of the readings assigned will be recent articles published in U.S. and British media capturing the latest thinking and research on gender inequality in the workplace. The class will be highly interactive combining case studies, videos, debates, guest speakers, and in-class simulations.","departments":["Women's and Gender Studies"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Gender Studies","Leadership","Organizational Behavior","Society","Women's Studies"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Spring 2015","instructors":["Dr. Elena Mendez Escobar"],"url":"https://ocw.mit.edu/courses/wgs-150-gender-power-leadership-and-the-workplace-spring-2015/","views":1052},{"id":"17.523+fall_2005","numbers":["17.523"],"title":"Ethnicity and Race in World Politics","summary":"Discerning the ethnic and racial dimensions of politics is considered by some indispensable to understanding contemporary world politics. This course seeks to answer fundamental questions about racial and ethnic politics. To begin, what are the bases of ethnic and racial identities? What accounts for political mobilization based upon such identities? What are the political claims and goals of such mobilization and is conflict between groups and/or with government forces inevitable? How do ethnic and racial identities intersect with other identities, such as gender and class, which are themselves the sources of social, political, and economic cleavages? Finally, how are domestic ethnic/racial politics connected to international human rights? To answer these questions, the course begins with an introduction to dominant theoretical approaches to racial and ethnic identity. The course then considers these approaches in light of current events in Africa, Asia, Latin America, Europe, and the United States.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Anthropology","Ethnography","Humanities","International Relations","Philosophy","Political Philosophy","Political Science","Social Anthropology","Social Justice","Social Science","Sociology"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Fall 2005","instructors":["Prof. Melissa Nobles"],"url":"https://ocw.mit.edu/courses/17-523-ethnicity-and-race-in-world-politics-fall-2005/","views":1051},{"id":"21L.460+fall_2013","numbers":["21L.460"],"title":"Medieval Literature: Legends of Arthur","summary":"As a quasi-historical, quasi-legendary figure of consistently great popularity, King Arthur has been subject to an extraordinary amount of reinvention and rewriting: as a Christian hero and war-leader; as an ineffective king and pathetic cuckold; and as a tragic figure of noble but doomed intentions. As we trace Arthur’s evolution and that of principal knights, we will ask what underlies the appeal of this figure whose consistent reappearance in western culture has performed the medieval prophecy that he would be rex quondam et futurus: the once and future king.","departments":["Literature"],"areas":["Humanities"],"topics":["Comparative Literature","Criticism","History","Humanities","Literature","Medieval History"],"levels":["Undergraduate"],"features":["Instructor Insights","Projects with Examples"],"term":"Fall 2013","instructors":["Prof. Arthur Bahr"],"url":"https://ocw.mit.edu/courses/21l-460-medieval-literature-legends-of-arthur-fall-2013/","views":1048},{"id":"21H.207+fall_2010","numbers":["21H.207"],"title":"The Energy Crisis: Past and Present","summary":"This course will explore how Americans have confronted energy challenges since the end of World War II. Beginning in the 1970s, Americans worried about the supply of energy. As American production of oil declined, would the US be able to secure enough fuel to sustain their high consumption lifestyles? At the same time, Americans also began to fear the environmental side affects of energy use. Even if the US had enough fossil fuel, would its consumption be detrimental to health and safety? This class examines how Americans thought about these questions in the last half-century. We will consider the political, diplomatic, economic, cultural, and technological aspects of the energy crisis. Topics include nuclear power, suburbanization and the new car culture, the environmental movement and the challenges of clean energy, the Middle East and supply of oil, the energy crisis of the 1970s, and global warming.","departments":["History"],"areas":["Energy, Climate & Sustainability","Humanities","Social Sciences"],"topics":["American History","Energy","Environmental Policy","Fossil Fuels","History","Humanities","Modern History","Public Administration","Science and Technology Policy","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2010","instructors":["Prof. Meg Jacobs"],"url":"https://ocw.mit.edu/courses/21h-207-the-energy-crisis-past-and-present-fall-2010/","views":1048},{"id":"21L.432+spring_2003","numbers":["21L.432"],"title":"Understanding Television","summary":"The subtitle of this course for the spring 2003 term is “American Television: A Cultural History.” The class takes a cultural approach to television’s evolution as a technology and system of representation, considering television as a system of storytelling and myth-making, and as a cultural practice, studied from anthropological, literary, and cinematic perspectives. The course focuses on prime-time commercial broadcasting, the medium’s technological and economic history, and theoretical perspectives. There is much required viewing as well as readings in media theory and cultural interpretation.","departments":["Literature"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Drama","Film and Video","Fine Arts","Humanities","Literature","Media Studies","Social Science","Visual Arts"],"levels":["Undergraduate"],"features":["Lecture Videos","Written Assignments"],"term":"Spring 2003","instructors":["Prof. David Thorburn"],"url":"https://ocw.mit.edu/courses/21l-432-understanding-television-spring-2003/","views":1047},{"id":"11.947+fall_1998","numbers":["11.947"],"title":"Imaging the City: The Place of Media in City Design and Development","summary":"Kevin Lynch’s landmark volume, The Image of the City (1960), emphasized the perceptual characteristics of the urban environment, stressing the ways that individuals mentally organize their own sensory experience of cities. Increasingly, however, city imaging is supplemented and constructed by exposure to visual media, rather than by direct sense experience of urban realms. City images are not static, but subject to constant revision and manipulation by a variety of media-savvy individuals and institutions. In recent years, urban designers (and others) have used the idea of city image proactively – seeking innovative ways to alter perceptions of urban, suburban, and regional areas. City imaging, in this sense, is the process of constructing visually-based narratives about the potential of places.","departments":["Urban Studies and Planning"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Architecture","Digital Media","Environmental Design","Fine Arts","Media Studies","Social Science","Urban Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 1998","instructors":["Prof. Lawrence Vale","Prof. Sam Warner"],"url":"https://ocw.mit.edu/courses/11-947-imaging-the-city-the-place-of-media-in-city-design-and-development-fall-1998/","views":1045},{"id":"21L.017+spring_2008","numbers":["21L.017"],"title":"The Art of the Probable: Literature and Probability","summary":"“The Art of the Probable” addresses the history of scientific ideas, in particular the emergence and development of mathematical probability. But it is neither meant to be a history of the exact sciences per se nor an annex to, say, the Course 6 curriculum in probability and statistics. Rather, our objective is to focus on the formal, thematic, and rhetorical features that imaginative literature shares with texts in the history of probability. These shared issues include (but are not limited to): the attempt to quantify or otherwise explain the presence of chance, risk, and contingency in everyday life; the deduction of causes for phenomena that are knowable only in their effects; and, above all, the question of what it means to think and act rationally in an uncertain world.\n\nOur course therefore aims to broaden students’ appreciation for and understanding of how literature interacts with – both reflecting upon and contributing to – the scientific understanding of the world. We are just as centrally committed to encouraging students to regard imaginative literature as a unique contribution to knowledge in its own right, and to see literary works of art as objects that demand and richly repay close critical analysis. It is our hope that the course will serve students well if they elect to pursue further work in Literature or other discipline in SHASS, and also enrich or complement their understanding of probability and statistics in other scientific and engineering subjects they elect to take.","departments":["Literature"],"areas":["Humanities","Science & Math"],"topics":["Comparative Literature","Criticism","History","History of Science and Technology","Humanities","Intellectual History","Literature","Mathematics","Probability and Statistics"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments with Examples"],"term":"Spring 2008","instructors":["Prof. Noel Jackson","Prof. Shankar Raman","Prof. Alvin Kibel"],"url":"https://ocw.mit.edu/courses/21l-017-the-art-of-the-probable-literature-and-probability-spring-2008/","views":1042},{"id":"ES.259+spring_2006","numbers":["ES.259"],"title":"Information and Communication Technology in Africa","summary":"This is a discussion-based, interactive seminar on the development of information and communication technology in Sub-Saharan Africa. The students will seek to understand the issues surrounding designing and instituting policy, and explore the possible ways in which they can make an impact on information and communication technology in Africa.","departments":["Experimental Study Group"],"areas":["Business & Management","Engineering","Social Sciences"],"topics":["Business","Electrical Engineering","Engineering","Information Technology","Society","Telecommunications","The Developing World"],"levels":["Undergraduate"],"features":["Projects with Examples"],"term":"Spring 2006","instructors":["Raja Bobbili","Prof. Shigeru Miyagawa"],"url":"https://ocw.mit.edu/courses/es-259-information-and-communication-technology-in-africa-spring-2006/","views":1041},{"id":"9.12+fall_2006","numbers":["9.12"],"title":"Experimental Molecular Neurobiology","summary":"Designed for students without previous experience in techniques of cellular and molecular biology, this class teaches basic experimental techniques in cellular and molecular neurobiology. Experimental approaches covered include tissue culture of neuronal cell lines, dissection and culture of brain cells, DNA manipulation, synaptic protein analysis, immunocytochemistry, and fluorescent microscopy.","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math"],"topics":["Biology","Cognitive Science","Molecular Biology","Neurobiology","Science"],"levels":["Undergraduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Fall 2006","instructors":["Prof. Carlos Lois","Prof. Yasunori Hayashi"],"url":"https://ocw.mit.edu/courses/9-12-experimental-molecular-neurobiology-fall-2006/","views":1034},{"id":"21H.134J+spring_2012","numbers":["21H.134J","14.70J"],"title":"Medieval Economic History in Comparative Perspective","summary":"This course will survey the conditions of material life and changing social and economic conditions in medieval Europe with reference to the comparative context of contemporary Islamic, Chinese, and central Asian experiences. Subject covers the emergence and decline of feudal institutions, the transformation of peasant agriculture, living standards and the course of epidemic disease, and the ebb and flow of long-distance trade across the Eurasian system. Particular emphasis will be placed on the study of those factors, both institutional and technological, which have contributed to the emergence of capitalist organization and economic growth in Western Europe in contrast to the trajectories followed by the other major medieval economies.","departments":["Economics","History"],"areas":["Humanities"],"topics":["Asian History","Comparative History","European History","History","Humanities","Medieval History"],"levels":["Undergraduate"],"features":["Instructor Insights","Presentation Assignments","Written Assignments"],"term":"Spring 2012","instructors":["Prof. Anne McCants"],"url":"https://ocw.mit.edu/courses/21h-134j-medieval-economic-history-in-comparative-perspective-spring-2012/","views":1031},{"id":"21L.704+fall_2005","numbers":["21L.704"],"title":"Studies in Poetry: \"What's the Use of Beauty?\"","summary":"This course explores variations on the proposition that an adequate recognition of beauty could, however indirectly, make you a more humane person. Readings extend widely across literary and non-literary genres, including lyric poetry and the novel, philosophical prose and essays.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Humanities","Literature","Philosophy","Poetry"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2005","instructors":["Prof. Noel Jackson"],"url":"https://ocw.mit.edu/courses/21l-704-studies-in-poetry-whats-the-use-of-beauty-fall-2005/","views":1031},{"id":"17.480+spring_2017","numbers":["17.480"],"title":"Understanding Military Operations","summary":"This course examines selected past, current, and future sea, air, space, and land battlefields and looks at the interaction in each of these warfare areas between existing military doctrine and weapons, sensors, communications, and information processing technologies. It also explores how technological development, whether innovative or stagnant, is influenced in each warfare area by military doctrine.","departments":["Political Science"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Military Studies","Organizational Behavior","Public Administration","Science and Technology Policy","Security Studies","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2017","instructors":["Prof. Owen Cote"],"url":"https://ocw.mit.edu/courses/17-480-understanding-military-operations-spring-2017/","views":1030},{"id":"17.504+fall_2003","numbers":["17.504"],"title":"Ethnic Politics I","summary":"This course is designed to provide students with a broad overview of the major theories on the relationship between ethnicity and politics. The course is divided into three sections. The first covers general theory and discusses the social construction of ethnicity as well as the limits of construction. The second section discusses ethnicity as a dependent variable. This section studies the forces that shape the development of ethnic identities and their motivating power. The third section addresses ethnicity as an independent variable. In other words, it focuses on how ethnicity operates to affect important political and economic outcomes.\n\nThis course is the first semester of a year-long sequence on ethnic politics. However, each semester is self-contained and students may take the course in either or both semesters. Ethnic Politics I aims for breadth over depth. It covers many works in the “canon” of texts on ethnic politics as well as addressing many major topics (modernization, entrepreneurship, prejudice, ethnic party formation, etc.) in one week sessions. Ethnic Politics II covers some of these topics in greater depth and also requires a major research paper.","departments":["Political Science"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Ethnography","Humanities","Philosophy","Political Philosophy","Political Science","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2003","instructors":["Prof. Roger Petersen"],"url":"https://ocw.mit.edu/courses/17-504-ethnic-politics-i-fall-2003/","views":1029},{"id":"WGS.645+fall_2005","numbers":["WGS.645"],"title":"Issues of Representation: Women, Representation, and Music in Selected Folk Traditions of the British Isles and North America","summary":"This subject investigates the special relation of women to several musical folk traditions in the British Isles and North America. Throughout, we will be examining the implications of gender in the creation, transmission, and performance of music. Because virtually all societies operate to some extent on a gendered division of labor (and of expressive roles) the music of these societies is marked by the gendering of musical repertoires, traditions of instrumentation, performance settings, and styles. This seminar will examine the gendered dimensions of the music - the song texts, the performance styles, processes of dissemination (collection, literary representation) and issues of historiography - with respect to selected traditions within the folk musics of North America and the British Isles, with the aim of analyzing the special contributions of women to these traditions. In addition to telling stories about women’s musical lives, and studying elements of female identity and subjectivity in song texts and music, we will investigate the ways in which women’s work and women’s cultural roles have affected the folk traditions of these several countries.","departments":["Women's and Gender Studies"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Fine Arts","Gender Studies","Music","Music History","Social Science","Society","Women's Studies"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2005","instructors":["Prof. Judith Tick","Prof. Ruth Perry"],"url":"https://ocw.mit.edu/courses/wgs-645-issues-of-representation-women-representation-and-music-in-selected-folk-traditions-of-the-british-isles-and-north-america-fall-2005/","views":1028},{"id":"21T.355+spring_2012","numbers":["21T.355"],"title":"Playwrights' Workshop","summary":"This course provides continued work in the development of play scripts for the theater. Writers work on sustained pieces in weekly workshop meetings, individual consultation with the instructor, and in collaboration with student actors, directors, and designers. Fully developed scripts are eligible for inclusion in the Playwrights’ Workshop Production.","departments":["Theater Arts"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Creative Writing","Drama","Fine Arts","Humanities","Literature","Performance Arts","Theater"],"levels":["Undergraduate"],"features":["Projects with Examples"],"term":"Spring 2012","instructors":["Prof. Alan Brody"],"url":"https://ocw.mit.edu/courses/21m-785-playwrights-workshop-spring-2012/","views":1027},{"id":"21L.501+spring_2013","numbers":["21L.501"],"title":"The American Novel: Stranger and Stranger","summary":"This course covers works by major American novelists, beginning with the late 18th century and concluding with a contemporary novelist. The class places major emphasis on reading novels as literary texts, but attention is paid to historical, intellectual, and political contexts as well. The syllabus varies from term to term, but many of the following writers are represented: Rowson, Hawthorne, Melville, Twain, Wharton, James, and Toni Morrison. Previously taught topics include The American Revolution and Makeovers (i.e. adaptations and reinterpretation of novels traditionally considered as American “Classics”). May be repeated for credit with instructor’s permission so long as the content differs.","departments":["Literature"],"areas":["Humanities"],"topics":["American Literature","Classics","Humanities","Literature"],"levels":["Undergraduate"],"features":["Activity Assignments","Instructor Insights","Presentation Assignments","Written Assignments with Examples"],"term":"Spring 2013","instructors":["Dr. Wyn Kelley"],"url":"https://ocw.mit.edu/courses/21l-501-the-american-novel-stranger-and-stranger-spring-2013/","views":1026},{"id":"12.490+fall_2005","numbers":["12.490"],"title":"Advanced Igneous Petrology","summary":"Advanced Igneous Petrology covers the history of and recent developments in the study of igneous rocks. Students review the chemistry and structure of igneous rock-forming minerals and proceed to study how these minerals occur and interact in igneous rocks. The course focuses on igneous processes and how we have learned about them through studying a number of significant sites worldwide.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geochemistry","Geology","Geophysics","Science"],"levels":["Graduate"],"features":[],"term":"Fall 2005","instructors":["Prof. Timothy Grove"],"url":"https://ocw.mit.edu/courses/12-490-advanced-igneous-petrology-fall-2005/","views":1023},{"id":"21G.061+spring_2004","numbers":["21G.061"],"title":"Advanced Topics: Plotting Terror in European Culture","summary":"This interdisciplinary course surveys modern European culture to disclose the alignment of literature, opposition, and revolution. Reaching back to the foundational representations of anarchism in nineteenth-century Europe (Kleist, Conrad) the curriculum extends through the literary and media representations of militant organizations in the 1970s and 80s (Italy’s Red Brigade, Germany’s Red Army Faction, and the Real Irish Republican Army). In the middle of the term students will have the opportunity to hear a lecture by Margarethe von Trotta, one of the most important filmmakers who has worked on terrorism. The course concludes with a critical examination of the ways that certain segments of European popular media have returned to the “radical chic” that many perceive to have exhausted itself more than two decades ago.","departments":["Global Studies and Languages"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","European History","European and Russian Studies","Fine Arts","History","Humanities","International Literature","Literature","Media Studies","Social Science","Society"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2004","instructors":["Prof. Charity Scribner"],"url":"https://ocw.mit.edu/courses/21g-061-advanced-topics-plotting-terror-in-european-culture-spring-2004/","views":1023},{"id":"21H.931+spring_2002","numbers":["21H.931"],"title":"Seminar in Historical Methods","summary":"This course is designed to introduce students to fundamental issues and debates in the writing of history. It will feature innovative historical accounts written in recent years. The class will consider such questions as the words historians use, their language, sources, methods, organization, framing, and style. How does the choice of each of these affect the historian’s work? How does the author choose, analyze, and present evidence? How effective are different methodologies?","departments":["History"],"areas":["Humanities"],"topics":["Comparative History","Historical Methods","Historiography","History","Humanities"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2002","instructors":["Prof. Elizabeth A. Wood"],"url":"https://ocw.mit.edu/courses/21h-931-seminar-in-historical-methods-spring-2002/","views":1023},{"id":"12.097+january-iap_2006","numbers":["12.097"],"title":"Chemical Investigations of Boston Harbor","summary":"This is an undergraduate introductory laboratory subject in ocean chemistry and measurement. There are three main elements to the course: oceanic chemical sampling and analysis, instrumentation development for the ocean environment, and the larger field of ocean science.\n\nThis course is offered through The MIT/WHOI Joint Program. The MIT/WHOI Joint Program is one of the premier marine science graduate programs in the world. It draws on the complementary strengths and approaches of two great institutions: the Massachusetts Institute of Technology (MIT) and the Woods Hole Oceanographic Institution (WHOI).","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Analytical Chemistry","Aquatic Sciences and Water Quality Control","Chemistry","Earth Science","Engineering","Environmental Engineering","Geochemistry","Oceanography","Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Problem Sets"],"term":"January IAP 2006","instructors":["Dr. Elizabeth Kujawinski","Prof. Franz Hover","Dr. Sheri White"],"url":"https://ocw.mit.edu/courses/12-097-chemical-investigations-of-boston-harbor-january-iap-2006/","views":1022},{"id":"9.036+spring_2005","numbers":["9.036"],"title":"The Visual System","summary":"This comprehensive course on the visual system is designed to ground future researchers in the field of visual science and to provide scientists with an excellent basis for using the visual system as a model in research. In this graduate seminar, anatomical, neurophysiological, imaging and behavioral research is examined in an attempt to gain a better understanding of how information is processed in the primate visual system.","departments":["Brain and Cognitive Sciences"],"areas":["Health & Medicine","Science & Math"],"topics":["Anatomy and Physiology","Biology","Health and Medicine","Neurobiology","Neuroscience","Science","Sensory-Neural Systems"],"levels":["Graduate"],"features":["Presentation Assignments","Written Assignments"],"term":"Spring 2005","instructors":["Prof. Peter H. Schiller"],"url":"https://ocw.mit.edu/courses/9-036-the-visual-system-spring-2005/","views":1019},{"id":"9.912+fall_2001","numbers":["9.912"],"title":"Special Topics in Brain and Cognitive Sciences","summary":"Memory is not a unitary faculty, but rather consists of multiple forms of learning that differ in their operating characteristics and neurobiological substrates. This seminar will consider current debates regarding the cognitive and neural architectures of memory, specifically focusing on recent efforts to address these controversies through application of functional neuroimaging (primarily fMRI and PET).","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math"],"topics":["Biology","Cognitive Science","Neurobiology","Neuroscience","Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Fall 2001","instructors":["Prof. Anthony Wagner"],"url":"https://ocw.mit.edu/courses/9-912-special-topics-in-brain-and-cognitive-sciences-fall-2001/","views":1018},{"id":"21H.802+spring_2005","numbers":["21H.802"],"title":"Modern Latin America, 1808-Present: Revolution, Dictatorship, Democracy","summary":"This class is a selective survey of Latin American history from the beginning of the twentieth century to the present. Issues studied include Latin America in the global economy, relations between Latin America and the U.S., dictatorships and democracies in the twentieth century, African and Indigenous cultures, feminism and gender, cultural politics, revolution in Mexico, Cuba, and Central America, and Latin American identity.","departments":["History"],"areas":["Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","History","Humanities","Latin American History","Latin and Caribbean Studies","Modern History","Social Science","Society"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Spring 2005","instructors":["Prof. Jeffrey S. Ravel"],"url":"https://ocw.mit.edu/courses/21h-802-modern-latin-america-1808-present-revolution-dictatorship-democracy-spring-2005/","views":1017},{"id":"ESD.932+spring_2005","numbers":["ESD.932"],"title":"Technology Policy Organizations","summary":"Technology Policy Organizations and its sequel, ESD.933, Technology Policy Negotiations and Dispute Resolution, form a sequence on Organizational Processes in Technology Policy. This course features an overall framework for understanding the increasingly networked, flat, flexible and diverse nature of organizations, as well as a close look at the many relevant types of organizations, including regulatory, entrepreneurial, multi-national, and non-governmental non-profit. Key organizational processes, including individual motivation, teamwork, and systems change are featured. The core assignment features a series of industry studies in which students conduct field interviews (in phone or in person) of key stakeholders on a pressing policy challenge in that industry and analyze the impact of organizational factors on policy success.","departments":["Engineering Systems Division"],"areas":["Business & Management"],"topics":["Business","Organizational Behavior"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2005","instructors":["Prof. Joel Cutcher-Gershenfeld"],"url":"https://ocw.mit.edu/courses/esd-932-technology-policy-organizations-spring-2005/","views":1017},{"id":"11.368+fall_2004","numbers":["11.368"],"title":"Environmental Justice","summary":"This class explores the foundations of the environmental justice movement, current and emerging issues, and the application of environmental justice analysis to environmental policy and planning. It examines claims made by diverse groups along with the policy and civil society responses that address perceived inequity and injustice. While focused mainly on the United States, international issues and perspectives are also considered.","departments":["Urban Studies and Planning"],"areas":["Energy, Climate & Sustainability","Humanities","Social Sciences"],"topics":["Environmental Policy","Humanities","Philosophy","Political Philosophy","Political Science","Public Administration","Social Justice","Social Science","Sociology"],"levels":["Graduate"],"features":["Written Assignments with Examples"],"term":"Fall 2004","instructors":["Prof. JoAnn Carmin"],"url":"https://ocw.mit.edu/courses/11-368-environmental-justice-fall-2004/","views":1015},{"id":"CMS.360+fall_2012","numbers":["CMS.360","CMS.860"],"title":"Introduction to Civic Media","summary":"This course examines civic media in comparative, transnational and historical perspectives through the use of various theoretical tools, research approaches, and project design methods.","departments":["Comparative Media Studies/Writing"],"areas":["Art, Design & Architecture","Social Sciences"],"topics":["Communication","Fine Arts","Media Studies","Social Science"],"levels":["Undergraduate"],"features":["Lecture Notes","Projects with Examples","Written Assignments with Examples"],"term":"Fall 2012","instructors":["Prof. Sasha Costanza-Chock","Rebecca Hurwitz"],"url":"https://ocw.mit.edu/courses/cms-360-introduction-to-civic-media-fall-2012/","views":1015},{"id":"8.821+fall_2008","numbers":["8.821"],"title":"String Theory","summary":"This is a one-semester class about gauge/gravity duality (often called AdS/CFT) and its applications.","departments":["Physics"],"areas":["Science & Math"],"topics":["Particle Physics","Physics","Quantum Mechanics","Science","Theoretical Physics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Set Solutions","Problem Sets","Projects"],"term":"Fall 2008","instructors":["Prof. John McGreevy"],"url":"https://ocw.mit.edu/courses/8-821-string-theory-fall-2008/","views":1015},{"id":"21W.742J+fall_2008","numbers":["21W.742J","WGS.231J"],"title":"Writing About Race: Narratives of Multiraciality","summary":"In this course we will read essays, novels, memoirs, and graphic texts, and view documentary and experimental films and videos which explore race from the standpoint of the multiracial. Examining the varied work of multiracial authors and filmmakers such as Danzy Senna, Ruth Ozeki, Kip Fulbeck, James McBride and others, we will focus not on how multiracial people are seen or imagined by the dominant culture, but instead on how they represent themselves. How do these authors approach issues of family, community, nation, language and history? What can their work tell us about the complex interconnections between race, gender, class, sexuality, and citizenship? Is there a relationship between their experiences of multiraciality and a willingness to experiment with form and genre? In addressing these and other questions, we will endeavor to think and write more critically and creatively about race as a social category and a lived experience.","departments":["Comparative Media Studies/Writing","Women's and Gender Studies"],"areas":["Art, Design & Architecture","Humanities","Social Sciences"],"topics":["Anthropology","Creative Writing","Ethnography","Fiction","Fine Arts","Humanities","Literature","Media Studies","Nonfiction Prose","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2008","instructors":["Dr. Kym L. Ragusa"],"url":"https://ocw.mit.edu/courses/21w-742j-writing-about-race-narratives-of-multiraciality-fall-2008/","views":1015},{"id":"21L.003-1+spring_2007","numbers":["21L.003-1"],"title":"Reading Fiction: Dysfunctional Families","summary":"This course explores the form, content, and historical context of various works of fiction specifically through the thematic lens of “dysfunctional families.” We will focus primarily on questions pertaining to the structure, language, story, and characters of these fictional works.","departments":["Literature"],"areas":["Humanities"],"topics":["Criticism","Fiction","Humanities","Literature"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Spring 2007","instructors":["Prof. Sandy Alexandre"],"url":"https://ocw.mit.edu/courses/21l-003-1-reading-fiction-dysfunctional-families-spring-2007/","views":1014},{"id":"3.A26+fall_2005","numbers":["3.A26"],"title":"Freshman Seminar: The Nature of Engineering","summary":"Are you interested in investigating how nature engineers itself? How engineers copy the shapes found in nature (“biomimetics”)? This Freshman Seminar investigates why similar shapes occur in so many natural things and how physics changes the shape of nature. Why are things in nature shaped the way they are? How do birds fly? Why do bird nests look the way they do? How do woodpeckers peck? Why can’t trees grow taller than they are? Why is grass skinny and hollow? What is the wood science behind musical instruments? Questions such as these are the subject of biomimetic research and they have been the focus of investigation in this course for the past three years.","departments":["Materials Science and Engineering"],"areas":["Engineering"],"topics":["Biological Engineering","Biomaterials","Biomechanics","Engineering","Materials Science and Engineering"],"levels":["Undergraduate"],"features":[],"term":"Fall 2005","instructors":["Lorna Gibson"],"url":"https://ocw.mit.edu/courses/3-a26-freshman-seminar-the-nature-of-engineering-fall-2005/","views":1011},{"id":"MAS.964+fall_2002","numbers":["MAS.964"],"title":"Common Sense Reasoning for Interactive Applications","summary":"This course will explore the state of the art in common sense knowledge, and class projects will design and build interfaces that can exploit this knowledge to make more usable and helpful interfaces.\n\nCourse requirements will consist of critiques of class readings (about 2 papers/week), and a final project (paper or computer implementation project). Grades will be based primarily on the projects, as well as a small component for class and online participation","departments":["Media Arts and Sciences"],"areas":["Data Science, Analytics & Computer Technology","Engineering"],"topics":["Artificial Intelligence","Computer Science","Engineering","Human-Computer Interfaces","Software Design and Engineering"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2002","instructors":["Prof. Henry Lieberman"],"url":"https://ocw.mit.edu/courses/mas-964-common-sense-reasoning-for-interactive-applications-fall-2002/","views":1010},{"id":"24.912+spring_2017","numbers":["24.912","WGS.190","21H.106","21L.008","21W.741","21A.125"],"title":"Black Matters: Introduction to Black Studies","summary":"Interdisciplinary survey of people of African descent that draws on the overlapping approaches of history, literature, anthropology, legal studies, media studies, performance, linguistics, and creative writing. This course connects the experiences of African-Americans and of other American minorities, focusing on social, political, and cultural histories, and on linguistic patterns.","departments":["Anthropology","Comparative Media Studies/Writing","History","Linguistics and Philosophy","Literature","Women's and Gender Studies"],"areas":["Humanities","Social Sciences"],"topics":["African American Studies","Humanities","Language","Literature","Philosophy","Society"],"levels":["Undergraduate"],"features":["Instructor Insights","Lecture Videos","Presentation Assignments with Examples","Written Assignments"],"term":"Spring 2017","instructors":["Prof. Michel DeGraff"],"url":"https://ocw.mit.edu/courses/24-912-black-matters-introduction-to-black-studies-spring-2017/","views":1008},{"id":"11.965+january-iap_2007","numbers":["11.965"],"title":"Reflective Practice: An Approach for Expanding Your Learning Frontiers","summary":"The course is an introduction to the approach of Reflective Practice developed by Donald Schön. It is an approach that enables professionals to understand how they use their knowledge in practical situations and how they can combine practice and learning in a more effective way. Through greater awareness of how they deploy their knowledge in practical situations, professionals can increase their capacities of learning in a more timely way. Understanding how they frame situations and ideas helps professionals to achieve greater flexibility and increase their capacity of conceptual innovation.\n\nThe objective of the course is to introduce students to the approach and methods of reflective practice by raising their awareness about their own cognitive resources and how they use them in their practice. The course will introduce theories of learning, knowledge generation, framing and reframing, theories of action, reflection-in-practice, and conceptual innovation, and provide students with opportunities to experiment with these theories in real life through practical exercises in which they reflect on real situations that they have faced in their past professional experience. Through these practical exercises, students will have the opportunity to reflect on their thinking capacities in the context of their practice.","departments":["Urban Studies and Planning"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Innovation","Psychology","Social Science"],"levels":["Graduate"],"features":["Lecture Notes","Lecture Videos","Written Assignments"],"term":"January IAP 2007","instructors":["Prof. Ceasar McDowell","Claudia Canepa","Sebastiao Ferriera"],"url":"https://ocw.mit.edu/courses/11-965-reflective-practice-an-approach-for-expanding-your-learning-frontiers-january-iap-2007/","views":1008},{"id":"RES.17-002+spring_2023","numbers":["RES.17-002"],"title":"MIT Governance Lab","summary":"The MIT Governance Lab (MIT GOV/LAB) is an applied research group and ideas incubator that aims to improve democracy and governance by changing practice around corruption, government accountability, and citizen voice. Our model combines behavioral political science, experimental social science, design thinking, and evaluation to iterate on governance solutions that support people’s ability to hold the government to account.\n\nWe partner with in-country practitioners, including government, civil society, and social enterprises, at every stage of the research and learning process, from theory building to theory testing, to critical reflections and adaptations in real time, with the goal of contributing to a solid evidence base to strengthen the overall field of practice for participatory governance.\n\nTo learn more about our work, check out our latest updates, tools, guides, and other resources, as well as published research, or be in touch mitgovlab@mit.edu.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["Political Science","Social Science"],"levels":["Non-Credit"],"features":[],"term":"Spring 2023","instructors":["MIT Governance Lab"],"url":"https://ocw.mit.edu/courses/res-17-002-mit-governance-lab-spring-2023/","views":1007},{"id":"4.540+fall_2018","numbers":["4.540"],"title":"Introduction to Shape Grammars I","summary":"Shape grammars are systems of visual rules by which one shape may be transformed into another. By applying these rules recursively, a simple shape can be elaborated into a complex pattern. This course offers an in-depth introduction to shape grammars and their applications in architecture and related areas of design. More specifically, it involves manipulation of shapes in the algebras Uij, in the algebras Vij and Wij incorporating labels and weights, and in algebras formed as composites of these. Discussions center on rules and computations, shape and structure, and designs.","departments":["Architecture"],"areas":["Art, Design & Architecture","Science & Math"],"topics":["Architectural Design","Architecture","Fine Arts","Mathematics","Topology and Geometry"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2018","instructors":["Prof. George Stiny"],"url":"https://ocw.mit.edu/courses/4-540-introduction-to-shape-grammars-i-fall-2018/","views":1004},{"id":"17.196+fall_2005","numbers":["17.196","17.195"],"title":"Globalization","summary":"This seminar explores changes in the international economy and their effects on domestic politics, economy, and society. Is globalization really a new phenomenon? Is it irreversible? What are effects on wages and inequality, on social safety nets, on production, and innovation? How does it affect relations between developed countries and developing countries? How globalization affects democracy? These are some of the key issues that will be examined.","departments":["Political Science"],"areas":["Business & Management","Social Sciences"],"topics":["Business","Economics","Globalization","International Economics","Political Economy","Social Justice","Social Science","Sociology"],"levels":["Graduate","Undergraduate"],"features":["Written Assignments"],"term":"Fall 2005","instructors":["Prof. Suzanne Berger"],"url":"https://ocw.mit.edu/courses/17-196-globalization-fall-2005/","views":1003},{"id":"18.S66+spring_2003","numbers":["18.S66"],"title":"The Art of Counting","summary":"The subject of enumerative combinatorics deals with counting the number of elements of a finite set. For instance, the number of ways to write a positive integer n as a sum of positive integers, taking order into account, is 2n-1. We will be concerned primarily with bijective proofs, i.e., showing that two sets have the same number of elements by exhibiting a bijection (one-to-one correspondence) between them. This is a subject which requires little mathematical background to reach the frontiers of current research. Students will therefore have the opportunity to do original research. It might be necessary to limit enrollment.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics"],"levels":["Undergraduate"],"features":["Problem Sets"],"term":"Spring 2003","instructors":["Prof. Richard Stanley"],"url":"https://ocw.mit.edu/courses/18-s66-the-art-of-counting-spring-2003/","views":1003},{"id":"21L.704+fall_2004","numbers":["21L.704"],"title":"Studies in Poetry - British Poetry and the Sciences of the Mind","summary":"Do poems think? Recurrent images of the poet as an inspired lunatic, and of poetry as a fundamentally irrational art, have often fostered an understanding of poets and their work as generally extraneous to the work of the sciences. Yet poets have long reflected upon and have sought to embody in their work the most elementary processes of mind, and have frequently drawn for these representations on the very sciences to which they are thought to stand - and sometimes do genuinely stand - in opposition. Far from representing a mere departure from reason, then, the poem offers an image of the mind at work, an account of how minds work, a tool for eliciting thought in the reader or auditor. Bringing together readings in British poetry of the eighteenth and nineteenth centuries with writings from the emergent sciences of psychology and the physiology of the brain, this interdisciplinary course will explore the ways in which British poets, in years that witnessed the crucial development of these sciences, sought to capture an image of the mind at work. The primary aim of the course is to examine how several prominent genres of British poetry - the lyric, for instance, and the didactic poem - draw from and engage in this period with accounts of cognition within the sciences of psychology, physiology, and medicine. More broadly, the course aims to give undergraduates with some prior experience in the methods and topics of literary study an introduction to interdisciplinary humanistic research.","departments":["Literature"],"areas":["Humanities","Science & Math","Social Sciences"],"topics":["Cognitive Science","Comparative Literature","Criticism","History","Humanities","Intellectual History","Literature","Poetry","Psychology","Science","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments with Examples"],"term":"Fall 2004","instructors":["Prof. Noel Jackson"],"url":"https://ocw.mit.edu/courses/21l-704-studies-in-poetry-british-poetry-and-the-sciences-of-the-mind-fall-2004/","views":1002},{"id":"12.808+fall_2004","numbers":["12.808"],"title":"Introduction to Observational Physical Oceanography","summary":"Observational physical oceanography includes topics such as the physical description of the sea, the physical properties of seawater, methods and measurements, wind-driven ocean circulation, abyssal ocean circulation, boundary processes, and wave motions.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Engineering","Science & Math"],"topics":["Earth Science","Engineering","Geophysics","Hydrodynamics","Ocean Engineering","Oceanography","Science"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Fall 2004","instructors":["Prof. Raffaele Ferrari","Dr. Terrence Joyce"],"url":"https://ocw.mit.edu/courses/12-808-introduction-to-observational-physical-oceanography-fall-2004/","views":1001},{"id":"21M.304+spring_2009","numbers":["21M.304"],"title":"Writing in Tonal Forms II","summary":"This course builds on the composition techniques practiced in 21M.303 Writing in Tonal Forms I. Students undertake further written and analytic exercises in tonal music, including a sonata-form movement for string quartet. Students will also have the opportunity to write short works that experiment with the expanded tonal techniques of the late 19th and early 20th centuries. Musicianship laboratory is required.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History","Music Performance","Music Theory"],"levels":["Undergraduate"],"features":["Lecture Videos","Media Assignments with Examples","Music Audio","Projects with Examples"],"term":"Spring 2009","instructors":["Prof. Charles Shadle"],"url":"https://ocw.mit.edu/courses/21m-304-writing-in-tonal-forms-ii-spring-2009/","views":1001},{"id":"RES.21G-001+fall_2020","numbers":["RES.21G-001"],"title":"The User-friendly Classroom","summary":"The User-friendly Classroom video training series was created specifically for teaching assistants for whom English is a second language and the USA a second culture by A.C. Kemp, a lecturer in MIT Global Languages. These videos focus on developing international teaching assistants’ strategies for successful, student-centered communication in the interactive American classroom. These videos demonstrate best practices through authentic examples of successful teaching scenarios, interviews with undergraduates and advice from international teaching assistants.\n\nThese videos were created for use with the following courses:\n\n21G.232 / 21G.233 Advanced Speaking and Critical Listening (ELS)\n\n21G.217 / 21G.218 Workshop in Strategies for Effective Teaching (ELS)\n\n“Special thanks to my mentor, Jane Dunphy, for her support and advice with this project.”\n\n- A.C. Kemp","departments":["Global Studies and Languages"],"areas":["Education & Teaching","Social Sciences"],"topics":["Curriculum and Teaching","Society","Teaching and Education"],"levels":["Graduate"],"features":["Instructor Insights","Lecture Videos","Written Assignments"],"term":"Fall 2020","instructors":["A. C. Kemp"],"url":"https://ocw.mit.edu/courses/res-21g-001-the-user-friendly-classroom-fall-2020/","views":1000},{"id":"21L.707+fall_2005","numbers":["21L.707"],"title":"Writing Early American Lives: Gender, Race, Nation, Faith","summary":"This course focuses on the period between roughly 1550-1850. American ideas of race had taken on a certain shape by the middle of the nineteenth century, consolidated by legislation, economics, and the institution of chattel slavery. But both race and identity meant very different things three hundred years earlier, both in their dictionary definitions and in their social consequences. How did people constitute their identities in early America, and how did they speak about these identities? Texts will include travel writing, captivity narratives, orations, letters, and poems, by Native American, English, Anglo-American, African, and Afro-American writers.","departments":["Literature"],"areas":["Humanities","Social Sciences"],"topics":["African American Studies","American Literature","Comparative Literature","Criticism","Gender Studies","Humanities","Literature","Society"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2005","instructors":["Prof. Mary Fuller"],"url":"https://ocw.mit.edu/courses/21l-707-writing-early-american-lives-gender-race-nation-faith-fall-2005/","views":998},{"id":"9.916+fall_2009","numbers":["9.916"],"title":"Special Topics: Social Animals","summary":"Humans are social animals; social demands, both cooperative and competitive, structure our development, our brain and our mind. This course covers social development, social behaviour, social cognition and social neuroscience, in both human and non-human social animals. Topics include altruism, empathy, communication, theory of mind, aggression, power, groups, mating, and morality. Methods include evolutionary biology, neuroscience, cognitive science, social psychology and anthropology.","departments":["Brain and Cognitive Sciences"],"areas":["Science & Math","Social Sciences"],"topics":["Biology","Cognitive Science","Neuroscience","Psychology","Science","Social Science"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Fall 2009","instructors":["Prof. Rebecca Saxe"],"url":"https://ocw.mit.edu/courses/9-916-special-topics-social-animals-fall-2009/","views":992},{"id":"RES.8-008+spring_2022","numbers":["RES.8-008"],"title":"Nuclear Weapons Education Project","summary":"The MIT Nuclear Weapons Education Project aims to teach individuals, particularly those who grew up after the end of the Cold War, about what nuclear weapons are and their effects on the world. The project website provides materials for lectures or discussions at introductory course levels.","departments":["Physics"],"areas":["Energy, Climate & Sustainability","Humanities","Science & Math"],"topics":["Atomic, Molecular, Optical Physics","Energy","History","History of Science and Technology","Humanities","Nuclear Energy","Physics","Science"],"levels":["Non-Credit"],"features":["Instructor Insights","Podcasts"],"term":"Spring 2022","instructors":["MIT Interdisciplinary Team: Robert P. Redwine, Professor of Physics Emeritus (Coordinator)"],"url":"https://ocw.mit.edu/courses/res-8-008-nuclear-weapons-education-project-spring-2022/","views":991},{"id":"16.886+spring_2004","numbers":["16.886"],"title":"Air Transportation Systems Architecting","summary":"This course addresses the architecting of air transportation systems. The focus is on the conceptual phase of product definition, including technical, economic, market, environmental, regulatory, legal, manufacturing, and societal factors. It centers on a realistic system case study and includes a number of lectures from industry and government. Past examples include: the Very Large Transport Aircraft, a Supersonic Business Jet, and a Next Generation Cargo System. The course identifies the critical system level issues and analyzes them in depth via student team projects and individual assignments. The overall goal of the semester is to produce a business plan and a system specifications document that can be used to assess candidate systems.","departments":["Aeronautics and Astronautics"],"areas":["Business & Management","Engineering","Social Sciences"],"topics":["Aerospace Engineering","Business","Engineering","Operations Management","Social Science","Systems Engineering","Transportation Planning","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2004","instructors":["Earll Murman","Prof. John Hansman","Prof. John-Paul Clarke"],"url":"https://ocw.mit.edu/courses/16-886-air-transportation-systems-architecting-spring-2004/","views":990},{"id":"3.042+spring_2008","numbers":["3.042"],"title":"Materials Project Laboratory","summary":"As its name implies, the 3.042 Materials Project Laboratory involves working with such operations as investment casting of metals, injection molding of polymers, and sintering of ceramics. After all the abstraction and theory in the lecture part of the DMSE curriculum, many students have found this hands-on experience with materials to be very fun stuff - several have said that 3.042/3.082 was their favorite DMSE subject. The lab is more than operating processing equipment, however. It is intended also to emulate professional practice in materials engineering project management, with aspects of design, analysis, teamwork, literature and patent searching, Web creation and oral presentation, and more.","departments":["Materials Science and Engineering"],"areas":["Business & Management","Engineering"],"topics":["Business","Engineering","Materials Science and Engineering","Project Management"],"levels":["Undergraduate"],"features":["Projects"],"term":"Spring 2008","instructors":["Prof. David Roylance","Prof. Yet-Ming Chiang"],"url":"https://ocw.mit.edu/courses/3-042-materials-project-laboratory-spring-2008/","views":990},{"id":"15.270+spring_2016","numbers":["15.270"],"title":"Ethical Practice: Leading Through Professionalism, Social Responsibility, and System Design","summary":"This course offers an introduction to ethics in business, with a focus on business management. Students explore theoretical concepts in business ethics, and cases representing the challenges they will likely face as managers. There is opportunity to work with guest faculty as well as business and other professional practitioners. Individual class sessions take the form of moderated discussion, with occasional short lectures from the instructor.","departments":["Sloan School of Management"],"areas":["Business & Management"],"topics":["Business","Business Ethics","Management"],"levels":["Graduate"],"features":["Instructor Insights","Written Assignments"],"term":"Spring 2016","instructors":["Prof. Leigh Hafrey"],"url":"https://ocw.mit.edu/courses/15-270-ethical-practice-leading-through-professionalism-social-responsibility-and-system-design-spring-2016/","views":986},{"id":"18.465+spring_2005","numbers":["18.465"],"title":"Topics in Statistics: Nonparametrics and Robustness","summary":"This graduate-level course focuses on one-dimensional nonparametric statistics developed mainly from around 1945 and deals with order statistics and ranks, allowing very general distributions.\n\nFor multidimensional nonparametric statistics, an early approach was to choose a fixed coordinate system and work with order statistics and ranks in each coordinate. A more modern method, to be followed in this course, is to look for rotationally or affine invariant procedures. These can be based on empirical processes as in computer learning theory.\n\nRobustness, which developed mainly from around 1964, provides methods that are resistant to errors or outliers in the data, which can be arbitrarily large. Nonparametric methods tend to be robust.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Mathematics","Probability and Statistics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2005","instructors":["Prof. Richard Dudley"],"url":"https://ocw.mit.edu/courses/18-465-topics-in-statistics-nonparametrics-and-robustness-spring-2005/","views":985},{"id":"STS.460+spring_2015","numbers":["STS.460"],"title":"Histories of Information, Communication, and Computing Technologies","summary":"The histories of information, communication, and computing technologies have attracted attention from scholars across a variety of disciplines. This course introduces students to prominent voices in these topics across fields. Alongside readings introducing students to this broad scholarly terrain, the course offers guidance in research and writing for publication based on the reality that PhD candidates on the job market need to be published authors, and that every term paper has the potential to be a journal article. We work towards publication by reading widely-cited scholarly histories both for their content and for what they can tell us about scholarly craft.","departments":["Science, Technology, and Society"],"areas":["Humanities","Social Sciences"],"topics":["Communication","Historical Methods","History","History of Science and Technology","Humanities","Social Science"],"levels":["Graduate"],"features":["Written Assignments"],"term":"Spring 2015","instructors":["Prof. Jennifer S Light"],"url":"https://ocw.mit.edu/courses/sts-460-histories-of-information-communication-and-computing-technologies-spring-2015/","views":984},{"id":"STS.089+fall_2014","numbers":["STS.089"],"title":"Technology and Innovation in Africa","summary":"What do technology and innovation mean from Africa? This is the central question of this course, which tackles a double absence: Of the meanings and role of technology in African history, on the one hand, and of Africa’s place in the global history of technology, on the other. This course alternates between technologies from outside and technologies from within Africa and their itineraries in everyday life, and it is designed to provide students with grounded understandings of technology in Africa for intellectual and action-oriented purposes.","departments":["Science, Technology, and Society"],"areas":["Business & Management","Humanities","Social Sciences"],"topics":["African History","Anthropology","Business","Ethnography","History","History of Science and Technology","Humanities","Innovation","Social Science","Society","The Developing World"],"levels":["Undergraduate"],"features":["Lecture Notes","Written Assignments"],"term":"Fall 2014","instructors":["Prof. Clapperton Chakanetsa Mavhunga"],"url":"https://ocw.mit.edu/courses/sts-089-technology-and-innovation-in-africa-fall-2014/","views":983},{"id":"3.A27+fall_2007","numbers":["3.A27"],"title":"Case Studies in Forensic Metallurgy","summary":"TV programs such as “Law and Order” show how forensic experts are called upon to give testimony that often determines the outcome of court cases. Engineers are one class of expert who can help display evidence in a new light to solve cases. In this seminar you will be part of the problem-solving process, working through both previously solved and unsolved cases. Each week we will investigate cases, from the facts that make up each side to the potential evidence we can use as engineers to expose culprits. The cases range from disintegrating airplane engines to gas main explosions to Mafia murders. This seminar will be full of discussions about the cases and creative approaches to reaching the solutions. The approach is hands-on so you will have a chance to participate in the process, not simply study it. Some background reading and oral presentation are required.","departments":["Materials Science and Engineering"],"areas":["Engineering","Social Sciences"],"topics":["Engineering","Legal Studies","Materials Science and Engineering","Metallurgical Engineering","Social Science"],"levels":["Undergraduate"],"features":["Image Gallery","Presentation Assignments"],"term":"Fall 2007","instructors":["Prof. Kenneth Russell","Kyra Sedransk"],"url":"https://ocw.mit.edu/courses/3-a27-case-studies-in-forensic-metallurgy-fall-2007/","views":982},{"id":"12.000+fall_2009","numbers":["12.000"],"title":"Solving Complex Problems","summary":"12.000 Solving Complex Problems is designed to provide students the opportunity to work as part of a team to propose solutions to a complex problem that requires an interdisciplinary approach. For the students of the class of 2013, 12.000 will revolve around the issues associated with what we can and must do about the steadily increasing amounts CO2 in Earth’s atmosphere.\n\n12.000 is a core course for the MIT Terrascope freshman learning community. Each year’s class explores a different problem in detail through the study of complementary case histories and the development of creative solution strategies. It includes training in Web site development, effective written and oral communication, and team building. Initially developed with major financial support from the d’Arbeloff Fund for Excellence in Education, 12.000 is designed to enhance the freshman experience by helping students develop contexts for other subjects in the sciences and humanities, and by helping them to establish learning communities that include upperclassmen, faculty, MIT alumni, and professionals in science and engineering fields.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Energy, Climate & Sustainability","Engineering","Science & Math","Social Sciences"],"topics":["Atmospheric Science","Earth Science","Engineering","Environmental Engineering","Environmental Management","Environmental Policy","Environmental Science","Public Administration","Science","Social Science"],"levels":["Undergraduate"],"features":["Projects with Examples","Written Assignments with Examples"],"term":"Fall 2009","instructors":["Prof. Samuel Bowring"],"url":"https://ocw.mit.edu/courses/12-000-solving-complex-problems-fall-2009/","views":982},{"id":"11.941+spring_2005","numbers":["11.941"],"title":"Disaster, Vulnerability and Resilience","summary":"In recent years, the redistribution of risk has created conditions for natural and technological disasters to become more widespread, more difficult to manage, and more discriminatory in their effects. Policy and planning decision-makers frequently focus on the impact that human settlement patterns, land use decisions, and risky technologies can have on vulnerable populations. However, to ensure safety and promote equity, they also must be familiar with the social and political dynamics that are present at each stage of the disaster management cycle. Therefore, this course will provide students with:\n\n• An understanding of the breadth of factors that give rise to disaster vulnerability; and\n• A foundation for assessing and managing the social and political processes associated with disaster policy and planning.","departments":["Urban Studies and Planning"],"areas":["Humanities","Social Sciences"],"topics":["Humanities","Philosophy","Political Philosophy","Political Science","Public Administration","Public Policy","Security Studies","Social Science","Urban Studies"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments with Examples"],"term":"Spring 2005","instructors":["Prof. Jennifer Leaning","Prof. JoAnn Carmin"],"url":"https://ocw.mit.edu/courses/11-941-disaster-vulnerability-and-resilience-spring-2005/","views":981},{"id":"STS.009+spring_2012","numbers":["STS.009"],"title":"Evolution and Society","summary":"This course provides a broad conceptual and historical introduction to scientific theories of evolution and their place in the wider culture. It embraces historical, scientific and anthropological/cultural perspectives grounded in relevant developments in the biological sciences since 1800 that are largely responsible for the development of the modern theory of evolution by natural selection. Students read key texts, analyze key debates (e.g. Darwinian debates in the 19th century, and the creation controversies in the 20th century) and give class presentations.","departments":["Science, Technology, and Society"],"areas":["Humanities"],"topics":["History","History of Science and Technology","Humanities"],"levels":["Undergraduate"],"features":["Lecture Notes","Presentation Assignments","Written Assignments"],"term":"Spring 2012","instructors":["Prof. John Durant","Jeanne Wildman","Michaela Thompson"],"url":"https://ocw.mit.edu/courses/sts-009-evolution-and-society-spring-2012/","views":981},{"id":"17.951+spring_2004","numbers":["17.951"],"title":"Special Graduate Topic in Political Science: Public Opinion","summary":"This course provides an introduction to the vast literature devoted to public opinion. In the next 12 weeks, we will survey the major theoretical approaches and empirical research in the field of political behavior (though we will only tangentially discuss political participation and voting). For the most part we will focus on American public opinion, though some of the work we will read is comparative in nature.","departments":["Political Science"],"areas":["Social Sciences"],"topics":["American Politics","Political Science","Public Administration","Public Policy","Social Science","Sociology"],"levels":["Graduate"],"features":["Activity Assignments"],"term":"Spring 2004","instructors":["Prof. Adam Berinsky"],"url":"https://ocw.mit.edu/courses/17-951-special-graduate-topic-in-political-science-public-opinion-spring-2004/","views":981},{"id":"18.969+spring_2009","numbers":["18.969"],"title":"Topics in Geometry: Mirror Symmetry","summary":"This course will focus on various aspects of mirror symmetry. It is aimed at students who already have some basic knowledge in symplectic and complex geometry (18.966, or equivalent). The geometric concepts needed to formulate various mathematical versions of mirror symmetry will be introduced along the way, in variable levels of detail and rigor.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Linear Algebra","Mathematics","Particle Physics","Physics","Science","Topology and Geometry"],"levels":["Graduate"],"features":["Lecture Notes"],"term":"Spring 2009","instructors":["Prof. Denis Auroux"],"url":"https://ocw.mit.edu/courses/18-969-topics-in-geometry-mirror-symmetry-spring-2009/","views":981},{"id":"21H.931+spring_2004","numbers":["21H.931"],"title":"Seminar in Historical Methods","summary":"This course is designed to acquaint students with a variety of approaches to the past used by historians writing in the twentieth century. The books we read have all made significant contributions to their respective sub-fields and have been selected to give as wide a coverage in both field and methodology as possible in one semester’s worth of reading. We examine how historians conceive of their object of study, how they use primary sources as a basis for their accounts, how they structure the narrative and analytic discussion of their topic, and what are the advantages and drawbacks of their various approaches.","departments":["History"],"areas":["Humanities"],"topics":["Comparative History","Historical Methods","Historiography","History","Humanities"],"levels":["Undergraduate"],"features":["Lecture Videos","Written Assignments with Examples"],"term":"Spring 2004","instructors":["Prof. Anne McCants"],"url":"https://ocw.mit.edu/courses/21h-931-seminar-in-historical-methods-spring-2004/","views":980},{"id":"21M.271+spring_2007","numbers":["21M.271"],"title":"Symphony and Concerto","summary":"This course is a survey of significant orchestral masterworks composed during three centuries. Listening assignments include 34 symphonies and 24 concertos, composed from the 1720s to the 1990s. Class discussion and oral presentations focus on the works in 18 miniature scores; prior score-reading experience is helpful. Each of the three written papers reviews a concert attended during the term. Since this is a participatory subject, each student will give oral presentations concerning composers and their symphonies and/or concertos.","departments":["Music"],"areas":["Art, Design & Architecture","Humanities"],"topics":["Fine Arts","Music","Music History","Music Theory"],"levels":["Undergraduate"],"features":["Exams","Presentation Assignments"],"term":"Spring 2007","instructors":["Prof. Lowell Lindgren"],"url":"https://ocw.mit.edu/courses/21m-271-symphony-and-concerto-spring-2007/","views":980},{"id":"RES.12-003+fall_2025","numbers":["RES.12-003"],"title":"Fluid Motions, Sediment Transport, and Current-Generated Sedimentary Structures","summary":"This course provides a comprehensive examination of the physical processes governing sediment transport in aqueous and aeolian environments. Through four integrated lectures, students develop a quantitative understanding of fluid flow mechanics, sediment transport dynamics, and the generation of sedimentary structures preserved in the stratigraphic record.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geology","Science"],"levels":["Graduate"],"features":["Lecture Videos"],"term":"Fall 2025","instructors":["Prof. John Southard"],"url":"https://ocw.mit.edu/courses/res-12-003-fluid-motions-sediment-transport-and-current-generated-sedimentary-structures-fall-2025/","views":978},{"id":"18.996+spring_2004","numbers":["18.996","16.399"],"title":"Random Matrix Theory and Its Applications","summary":"This course is an introduction to the basics of random matrix theory, motivated by engineering and scientific applications.","departments":["Aeronautics and Astronautics","Mathematics"],"areas":["Science & Math"],"topics":["Applied Mathematics","Calculus","Linear Algebra","Mathematical Analysis","Mathematics","Probability and Statistics"],"levels":["Graduate"],"features":["Lecture Notes","Projects with Examples"],"term":"Spring 2004","instructors":["Prof. Moe Win","Prof. Alan Edelman"],"url":"https://ocw.mit.edu/courses/18-996-random-matrix-theory-and-its-applications-spring-2004/","views":976},{"id":"12.753+spring_2006","numbers":["12.753"],"title":"Geodynamics Seminar","summary":"In this year’s Geodynamics Seminar, we will explore the depth and breadth of scientific research related to Earth’s present and past ice-sheets, glaciers and sea-ice, as well as extraterrestrial planetary ice.\n\nInvited speakers have been chosen from experts in the current frontiers in ice-related research, including planetary ice, climate records from polar and tropical ice cores, the Snowball Earth, subglacial volcanoes, ice rheology, ice sheet modeling, ice microkinetics, glacial erosion and tectonics, subglacial life and polar remote sensing.\n\nA field trip to Iceland in Summer 2006 will allow us to view some of the island’s ice caps and glacial geology, the exposed mid Atlantic Ridge and evidence of ice-volcano interactions.","departments":["Earth, Atmospheric, and Planetary Sciences"],"areas":["Science & Math"],"topics":["Earth Science","Geology","Geophysics","Planetary Science","Science"],"levels":["Graduate"],"features":["Image Gallery","Projects"],"term":"Spring 2006","instructors":["Prof. Karen Bice","Prof. Mark Behn","Prof. Sarah Das"],"url":"https://ocw.mit.edu/courses/12-753-geodynamics-seminar-spring-2006/","views":975},{"id":"21A.S01+fall_2021","numbers":["21A.S01"],"title":"Reparations for Slavery and Colonization: Contemporary Movements for Justice","summary":"This class brings anthropological concepts to bear on contemporary movements for justice for harms committed during European colonization in Africa. Over the course of the semester, we use critical readings on topics such as violence, human rights discourse, narrating and measuring harm, memory, and group identity formation to reflect on and contribute to the work of two groups of practitioners currently engaged in claims for justice and reparations for European colonialism in Africa: in Algeria (France), and in the Congo, Burundi, and Rwanda respectively (Belgium).","departments":["Anthropology"],"areas":["Social Sciences"],"topics":["Anthropology","Social Anthropology","Social Science"],"levels":["Undergraduate"],"features":["Instructor Insights","Podcasts","Readings","Videos","Written Assignments"],"term":"Fall 2021","instructors":["Prof. M. Amah Edoh"],"url":"https://ocw.mit.edu/courses/21a-s01-reparations-for-slavery-and-colonization-contemporary-movements-for-justice-fall-2021/","views":975},{"id":"20.420J+fall_2004","numbers":["20.420J","10.538J"],"title":"Biomolecular Kinetics and Cellular Dynamics (BE.420J)","summary":"This subject deals primarily with kinetic and equilibrium mathematical models of biomolecular interactions, as well as the application of these quantitative analyses to biological problems across a wide range of levels of organization, from individual molecular interactions to populations of cells.","departments":["Biological Engineering","Chemical Engineering"],"areas":["Engineering","Science & Math"],"topics":["Biological Engineering","Biology","Biomechanics","Biophysics","Cell Biology","Computational Biology","Engineering","Molecular Biology","Science"],"levels":["Graduate"],"features":["Problem Sets","Programming Assignments"],"term":"Fall 2004","instructors":["Prof. Bruce Tidor","Prof. Karl Wittrup"],"url":"https://ocw.mit.edu/courses/20-420j-biomolecular-kinetics-and-cellular-dynamics-be-420j-fall-2004/","views":974},{"id":"18.706+spring_2023","numbers":["18.706"],"title":"Noncommutative Algebra","summary":"Noncommutative algebra studies algebraic phenomena involving multiplication for which commutativity law fails, such as product of matrices in linear algebra; such phenomena arise in various disciplines ranging from quantum physics to number theory.","departments":["Mathematics"],"areas":["Science & Math"],"topics":["Algebra and Number Theory","Mathematics"],"levels":["Graduate"],"features":["Lecture Notes","Problem Sets"],"term":"Spring 2023","instructors":["Prof. Roman Bezrukavnikov"],"url":"https://ocw.mit.edu/courses/18-706-noncommutative-algebra-spring-2023/","views":974},{"id":"21A.342+fall_2004","numbers":["21A.342"],"title":"Environmental Struggles","summary":"This class explores the interrelationship between humans and natural environments. It does so by focusing on conflict over access to and use of the environment as well as ideas about “nature” in various parts of the world.","departments":["Anthropology"],"areas":["Energy, Climate & Sustainability","Humanities","Social Sciences"],"topics":["Anthropology","Cultural Anthropology","Environmental Policy","Ethnography","Humanities","Philosophy","Political Philosophy","Public Administration","Social Science"],"levels":["Undergraduate"],"features":["Written Assignments"],"term":"Fall 2004","instructors":["Prof. Christine Walley"],"url":"https://ocw.mit.edu/courses/21a-342-environmental-struggles-fall-2004/","views":968},{"id":"WGS.640+fall_2014","numbers":["WGS.640"],"title":"Gender, Race, and the Construction of the American West","summary":"This course explores how gender shaped the historical experiences and cultural productions in the North American West during the time it was being explored, settled, and imagined. The North American West of the late nineteenth and early twentieth centuries provides a fascinating case study of the shifting meanings of gender, race, citizenship, and power in border societies. As the site of migration, settlement, and displacement, it spawned contests over land, labor disputes, inter-ethnic conflicts and peaceful relations, and many kinds of cultural productions.\n\nThe Graduate Consortium in Women’s Studies (GCWS)\n\nThis course is part of the Graduate Consortium in Women’s Studies. The GCWS at MIT brings together scholars and teachers at nine degree-granting institutions in the Boston area who are devoted to graduate teaching and research in Women’s Studies and to advancing interdisciplinary Women’s Studies scholarship. Learn more about the GCWS.","departments":["Women's and Gender Studies"],"areas":["Humanities","Social Sciences"],"topics":["American History","American Literature","American Politics","Gender Studies","History","Humanities","Literature","Modern History","Political Science","Social Science","Society","Women's Studies"],"levels":["Graduate"],"features":["Instructor Insights","Written Assignments with Examples"],"term":"Fall 2014","instructors":["Prof. Karen V Hansen","Prof. Marilynn S Johnson","Prof. Lois Rudnick"],"url":"https://ocw.mit.edu/courses/wgs-640-gender-race-and-the-construction-of-the-american-west-fall-2014/","views":967},{"id":"RES.21G-506+spring_2021","numbers":["RES.21G-506"],"title":"Kanji Learning Any Time, Any Place for Japanese VI","summary":"This resource aims to enhance students’ learning of kanji by providing a series of video lectures that cover the kanji characters in Tobira lessons 6–10. The video lectures not only teach how to write kanji but also provide stories behind the kanji characters.","departments":["Global Studies and Languages"],"areas":["Humanities"],"topics":["Humanities","Japanese","Language"],"levels":["Undergraduate"],"features":["Lecture Videos"],"term":"Spring 2021","instructors":["Dr. Takako Aikawa","Dr. Meghan Perdue"],"url":"https://ocw.mit.edu/courses/res-21g-506-kanji-learning-any-time-any-place-for-japanese-vi-spring-2021/","views":963},{"id":"15.352+spring_2005","numbers":["15.352"],"title":"Managing Innovation: Emerging Trends","summary":"Important emerging trends in innovation are identified, and their implications for innovation management are explored. Major topics to be discussed include the trend to open information (“open source”) rather than protected intellectual property; the distribution of innovation over many independent but collaborating actors; and toolkits that empower users to innovate for themselves.","departments":["Sloan School of Management"],"areas":["Business & Management"],"topics":["Business","Innovation","Management"],"levels":["Graduate"],"features":["Lecture Notes","Written Assignments"],"term":"Spring 2005","instructors":["Prof. Eric von Hippel"],"url":"https://ocw.mit.edu/courses/15-352-managing-innovation-emerging-trends-spring-2005/","views":962}]};
